    def _проверить_прерывание_и_отказ_mutex(сам, ошибка_тела, ошибка_выхода, прерывание):
        м = загрузить_модуль_автоматизации()
        пара = object.__new__(м._ТестовыйВладелецПарыФайловЗамков)
        приём = object.__new__(м._ТестовыйПриёмОпорМоста)
        владелец = м._ТестовыйВладелецПредпросмотра()
