    def test_неизвестный_acquire_не_повторяется(сам):
        м = загрузить_модуль_автоматизации()
        пара = object.__new__(м._ТестовыйВладелецПарыФайловЗамков)
        приём = object.__new__(м._ТестовыйПриёмОпорМоста)
        владелец = м._ТестовыйВладелецПредпросмотра()
        class ЗамокСНеизвестнымЗахватом:
            def __init__(сам):
                сам.попытки = 0
            def acquire(сам, blocking=False):
                сам.попытки += 1
                raise RuntimeError('неизвестно действие acquire')
            def release(сам):
                raise AssertionError('освобождение неизвестного acquire')
        замок = ЗамокСНеизвестнымЗахватом()
        владелец._замок = замок
        пара._приём_опор = приём
        приём._владелец_пары = пара
        приём.состояние, приём.ошибка, приём.попытка = 'передан', None, None
        приём._предпросмотр = (владелец, None)
        приём._фаза_предпросмотра = 'подготовка вызова'
        def предпросмотр():
            return м._выполнить_физический_предпросмотр(
                Path('/private/tmp/отсутствует'), 'Журнал/этап/запрос.md',
                контракт=('fum.test-lock-bridge.1', None, 3, None, 4),
                срок=time.monotonic()+5, владелец=владелец,
                схема=м._ТЕСТОВАЯ_СХЕМА_ЗАПУСКА_С_ИЗОЛЯЦИЕЙ_GIT,
                _ожидаемый_терминал=('00000000-0000-4000-8000-000000000001', b'{}'),
                _закреплённая_пара=пара)
        with сам.assertRaisesRegex(RuntimeError, 'неизвестно действие acquire'):
            предпросмотр()
        with сам.assertRaises(м.ОшибкаОтчёта):
            предпросмотр()
        сам.assertEqual(замок.попытки, 1)
        сам.assertIs(приём._предпросмотр[0], владелец)
        сам.assertEqual((владелец.состояние, приём._фаза_предпросмотра), ('неизвестно', 'неизвестно'))

