    def _сбой_синхронизации_каталога_снимка(сам, этап):
        фикстура = сам._сессия_закрытия_с_метаданными()
        _, _, _, снимок, fd, старый, *_ = фикстура
        выполнить = сам.модуль._ОднократнаяЗаписьСнимкаЗакрытия.выполнить
        синхронизировать, удалить = os.fsync, os.unlink
        владельцы, отказы, удаления = [], [], []
        ошибка = OSError(errno.EIO, 'модель отказа синхронизации каталога снимка')
        def отметить(владелец):
            владельцы.append(владелец)
            return выполнить(владелец)
        def отказ_синхронизации(дескриптор):
            if (владельцы and дескриптор == владельцы[-1].каталог_fd
                and владельцы[-1].попытка == (этап, 'начата')):
                отказы.append(True)
                raise ошибка
            return синхронизировать(дескриптор)
        def отметить_удаление(имя, *аргументы, **ключи):
            if (владельцы and имя == владельцы[-1].имя
                and ключи.get('dir_fd') == владельцы[-1].каталог_fd):
                удаления.append(True)
            return удалить(имя, *аргументы, **ключи)
        with mock.patch.object(сам.модуль._ОднократнаяЗаписьСнимкаЗакрытия, 'выполнить', отметить), \
             mock.patch.object(os, 'fsync', side_effect=отказ_синхронизации), \
             mock.patch.object(os, 'unlink', side_effect=отметить_удаление), \
             mock.patch.object(os, 'replace') as замена:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам._действие_фикстуры('закрытие', сам._закрыть_сессию_фикстуры, фикстура)
        сам.assertEqual(отказы, [True])
        замена.assert_not_called()
        сам.assertEqual(len(владельцы), 1)
        владелец = владельцы[0]
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual(владелец.попытка, (этап, 'начата'))
        сам.assertIs(владелец.ошибка, ошибка)
        число_ссылок = 2 if этап == 'синхронизация публикации снимка' else 1
        сам.assertEqual(os.fstat(владелец.файл_fd).st_nlink, число_ссылок)
        сам.assertEqual((снимок.stat().st_dev, снимок.stat().st_ino), владелец.метка_файла)
        if число_ссылок == 2:
            временный = os.stat(владелец.имя, dir_fd=владелец.каталог_fd, follow_symlinks=False)
            сам.assertEqual((временный.st_dev, временный.st_ino), владелец.метка_файла)
            сам.assertEqual(удаления, [])
        else:
            with сам.assertRaises(FileNotFoundError):
                os.stat(владелец.имя, dir_fd=владелец.каталог_fd, follow_symlinks=False)
            сам.assertEqual(удаления, [True])
        сам.assertEqual(os.pread(fd, len(старый) + 1, 0), старый)
        сам.assertEqual(сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1].состояние, 'неизвестно')
        with mock.patch.object(os, 'fsync') as повтор:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                владелец.выполнить()
        повтор.assert_not_called()
        сам._повтор_закрытия_запрещён(фикстура)

    def test_отказ_синхронизации_после_ссылки_сохраняет_обе_ссылки(сам):
        сам._сбой_синхронизации_каталога_снимка('синхронизация публикации снимка')

