    def _получить_неизвестную_замену(сам, фикстура):
        _, _, отчёт, снимок, fd, старый, *_ = фикстура
        заменить = os.replace
        эффект = []
        ошибка = OSError(errno.EIO, 'потерян результат замены')
        def заменить_и_потерять(*аргументы, **ключи):
            заменить(*аргументы, **ключи)
            эффект.append(True)
            raise ошибка
        with mock.patch.object(os, 'replace', side_effect=заменить_и_потерять) as замена:
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам._действие_фикстуры('закрытие', сам._закрыть_сессию_фикстуры, фикстура)
        замена.assert_called_once()
        сам.assertEqual(эффект, [True])
        сам.assertTrue(снимок.is_file())
        закрытый_маркер = сам.модуль.сформировать_закрытый_маркер(снимок.read_bytes()).encode('utf-8')
        сам.assertIn(закрытый_маркер, отчёт.read_bytes())
        сам.assertEqual(os.pread(fd, len(старый) + 1, 0), старый)
        владелец = сам.модуль._ВладелецЗаменыПредпросмотра._удерживаемые[-1]
        сам.assertTrue(владелец.замена_начата)
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual(сам.удержание['состояние'], 'неизвестно')

