    def test_предпросмотр_v3_v4_отказывает_до_git(сам):
        for версия in ('v3', 'v4'):
            with сам.subTest(версия=версия):
                корень, сессия, отчёт, путь_записи, запись = сам._синтетическая_сессия()
                запись.update({
                    'схема': 'fum.test-run.' + версия,
                    'план': None,
                    'наблюдения': [],
                    'профиль_проверки': {
                        'класс': 'адресная',
                        'отпечаток_снимка': 'sha256:' + '0' * 64,
                        'полные_наборы': [],
                        'основание': None,
                        'идентификатор_отказа': None,
                        'ожидаемое_свидетельство': None,
                    },
                })
                if версия == 'v4':
                    запись.update({'отпечаток_содержимого': 'sha256:' + '1' * 64,
                                   'переход_схемы': None})
                путь_записи.write_text(json.dumps(запись, ensure_ascii=False) + '\n', encoding='utf-8')
                with mock.patch.object(сам.модуль, 'межпроцессная_блокировка',
                                       return_value=contextlib.nullcontext(lambda: None)), \
                     mock.patch.object(сам.модуль, 'текущий_контекст_проверок') as контекст, \
                     mock.patch.object(сам.модуль.subprocess, 'run') as git, \
                     mock.patch.object(сам.модуль.subprocess, 'Popen') as запуск, \
                     mock.patch.object(os, 'replace', wraps=os.replace) as замена:
                    with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'только v1/v2'):
                        сам.модуль.выполнить_предпросмотр(корень, Path(сессия))
                контекст.assert_not_called()
                git.assert_not_called()
                запуск.assert_not_called()
                замена.assert_not_called()
                сам.assertEqual(отчёт.read_bytes(), сам.старый)

    def test_замена_сохраняет_права_и_владельца(self):
        for режим in (0o644, 0o755):
            with self.subTest(режим=режим):
                self.отчёт.write_bytes(self.старый); self.отчёт.chmod(режим)
                до = self.отчёт.stat()
                наблюдения = []
                def проверить():
                    наблюдения.append((self.временный.stat().st_mode & 0o777,
                                       self.временный.read_bytes(), self.отчёт.read_bytes()))
                прежняя = os.umask(0o077)
                try:
                    with mock.patch.object(self.модуль.uuid, 'uuid4', return_value=self.uuid):
                        self.модуль.заменить_управляемый_блок(
                            self.отчёт, self.блок, перед_публикацией=проверить,
                            _сохранить_права=True)
                finally:
                    os.umask(прежняя)
                после = self.отчёт.stat()
                self.assertEqual((после.st_mode & 0o777, после.st_uid, после.st_gid),
                                 (режим, до.st_uid, до.st_gid))
                self.assertEqual(self.отчёт.read_bytes(), self.новый)
                self.assertEqual(наблюдения, [(0o600, self.новый, self.старый),
                                               (режим, self.новый, self.старый)])

