    def test_другой_uid_или_gid_отклоняется_до_записи_временного_отчёта(сам):
        import fcntl
        import stat

        реальный_fstat = os.fstat
        for поле in ('st_uid', 'st_gid'):
            with сам.subTest(поле=поле):
                отчёт = сам.отчёт.parent / (поле + '.md')
                отчёт.write_bytes(сам.старый)
                отчёт.chmod(0o640)
                идентификатор = uuid.uuid4()
                временный = отчёт.parent / f'.{отчёт.name}.{идентификатор}.подготовка' / 'отчёт'
                class ПодменённыеСведения:
                    def __init__(владелец, сведения):
                        владелец.исходные = сведения
                    def __getattr__(владелец, имя):
                        значение = getattr(владелец.исходные, имя)
                        return значение + 1 if имя == поле else значение
                def чужой_владелец(fd):
                    сведения = реальный_fstat(fd)
                    флаги = fcntl.fcntl(fd, fcntl.F_GETFL)
                    if stat.S_ISREG(сведения.st_mode) and флаги & os.O_ACCMODE == os.O_RDWR:
                        return ПодменённыеСведения(сведения)
                    return сведения
                with mock.patch.object(сам.модуль.uuid, 'uuid4', return_value=идентификатор), \
                     mock.patch.object(сам.модуль.os, 'fstat', side_effect=чужой_владелец), \
                     mock.patch.object(сам.модуль.os, 'write', wraps=os.write) as запись, \
                     mock.patch.object(сам.модуль.os, 'replace', wraps=os.replace) as заменить:
                    with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                        сам.модуль.заменить_управляемый_блок(
                            отчёт, сам.блок, _сохранить_права=True)
                    запись.assert_not_called()
                    заменить.assert_not_called()
                сам.assertEqual(отчёт.read_bytes(), сам.старый)
                сам.assertEqual(временный.read_bytes(), b'')
                сам.assertEqual(stat.S_IMODE(временный.stat().st_mode), 0o600)

    def test_опытный_состав_допускает_только_заданный_временный_режим(сам):
        import stat

        сам.отчёт.chmod(0o644)
        каталог = сам.отчёт.parent
        временный = каталог / f'.{сам.отчёт.name}.{сам.uuid}.tmp'
        временный.write_bytes(сам.новый)
        временный.chmod(0o600)
        ожидаемые = {
            сам.отчёт.name: {'режим': stat.S_IFREG | 0o644,
                             'sha256': hashlib.sha256(сам.старый).hexdigest()},
            временный.name: {'режим': stat.S_IFREG | 0o600,
                                 'sha256': hashlib.sha256(сам.новый).hexdigest()},
        }
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'режим'):
            сам.модуль._тестово_снять_физический_состав(
                каталог, time.monotonic()+5, lambda: None, _ожидаемые=ожидаемые)
        результат = сам.модуль._тестово_снять_физический_состав(
            каталог, time.monotonic()+5, lambda: None, _ожидаемые=ожидаемые,
            _временный_отчёт=(временный.name, 0o600))
        сам.assertEqual(результат, ожидаемые)
        другой = каталог / 'посторонний'
        другой.write_bytes(b'other'); другой.chmod(0o600)
        with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
            сам.модуль._тестово_снять_физический_состав(
                каталог, time.monotonic()+5, lambda: None, _ожидаемые=ожидаемые,
                _временный_отчёт=(временный.name, 0o600))

