    def test_системный_конфиг_git_проверяется_на_всём_интервале(сам):
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory() as каталог:
            корень = Path(каталог)
            (корень / 'private' / 'etc').mkdir(parents=True)
            (корень / 'etc').symlink_to('private/etc')
            fd = os.open(корень, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            try:
                with модуль._удержать_системный_конфиг_git(fd) as проверить:
                    сам.assertIsNone(проверить())
                with сам.assertRaisesRegex(RuntimeError, 'только consumer'):
                    with модуль._удержать_системный_конфиг_git(fd):
                        raise RuntimeError('только consumer')
                with сам.assertRaisesRegex(OSError, 'ошибка consumer'):
                    with модуль._удержать_системный_конфиг_git(fd):
                        raise OSError('ошибка consumer')
                штатное_закрытие = os.close
                вызвано = []
                def закрыть_с_ошибкой(номер):
                    штатное_закрытие(номер)
                    if not вызвано:
                        вызвано.append(номер)
                        raise OSError('ошибка закрытия')
                with mock.patch.object(модуль.os, 'close', side_effect=закрыть_с_ошибкой):
                    with сам.assertRaises(модуль._СовокупныйОтказСистемногоGit) as обе:
                        with модуль._удержать_системный_конфиг_git(fd):
                            raise OSError('ошибка consumer')
                сам.assertEqual(str(обе.exception.первичная), 'ошибка consumer')
                сам.assertEqual(str(обе.exception.вторичные[0]), 'ошибка закрытия')
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    with модуль._удержать_системный_конфиг_git(fd) as проверить:
                        сам.assertIsNone(проверить())
                        (корень / 'private' / 'etc' / 'gitconfig').write_bytes(b'[core]\n')
                (корень / 'private' / 'etc' / 'gitconfig').unlink()
                причина = ValueError('существующая причина')
                исходная = RuntimeError('исход consumer')
                исходная.__cause__ = причина
                with сам.assertRaises(модуль._СовокупныйОтказСистемногоGit) as обе:
                    with модуль._удержать_системный_конфиг_git(fd):
                        (корень / 'private' / 'etc' / 'gitconfig').write_bytes(b'[core]\n')
                        raise исходная
                сам.assertIs(обе.exception.первичная, исходная)
                сам.assertIs(исходная.__cause__, причина)
                сам.assertIsInstance(обе.exception.вторичные[0], модуль.ОшибкаОтчёта)
                (корень / 'private' / 'etc' / 'gitconfig').unlink()
                def закрыть_каждый_с_ошибкой(номер):
                    штатное_закрытие(номер)
                    raise OSError('ошибка закрытия')
                with mock.patch.object(модуль.os, 'close', side_effect=закрыть_каждый_с_ошибкой):
                    with сам.assertRaises(модуль._СовокупныйОтказСистемногоGit) as три:
                        with модуль._удержать_системный_конфиг_git(fd):
                            (корень / 'private' / 'etc' / 'gitconfig').write_bytes(b'[core]\n')
                            raise исходная
                сам.assertIs(три.exception.первичная, исходная)
                сам.assertIs(исходная.__cause__, причина)
                сам.assertEqual(len(три.exception.вторичные), 3)
                сам.assertIsInstance(три.exception.вторичные[0], модуль.ОшибкаОтчёта)
                сам.assertTrue(all(isinstance(ошибка, OSError) for ошибка in три.exception.вторичные[1:]))
                (корень / 'private' / 'etc' / 'gitconfig').unlink()
                for тип in (KeyboardInterrupt, SystemExit):
                    прерывание = тип('отмена')
                    сохранено = []
                    with сам.assertRaises(модуль._ПрерванныйОтказСистемногоGit) as одиночное:
                        with модуль._удержать_системный_конфиг_git(fd):
                            raise прерывание
                    with сам.assertRaises(тип) as передано:
                        модуль._передать_прерванный_отказ_системного_git(одиночное.exception, сохранено.append)
                    сам.assertIs(передано.exception, прерывание)
                    сам.assertEqual(сохранено, [одиночное.exception])
                    сохранено.clear()
                    with сам.assertRaises(модуль._ПрерванныйОтказСистемногоGit) as прервано:
                        with модуль._удержать_системный_конфиг_git(fd):
                            (корень / 'private' / 'etc' / 'gitconfig').write_bytes(b'[core]\n')
                            raise прерывание
                    сам.assertIs(прервано.exception.первичная, прерывание)
                    with сам.assertRaises(тип) as передано:
                        модуль._передать_прерванный_отказ_системного_git(прервано.exception, сохранено.append)
                    сам.assertIs(передано.exception, прерывание)
                    сам.assertEqual(сохранено, [прервано.exception])
                    def не_сохранить(_):
                        raise OSError('сохранение UNKNOWN не удалось')
                    with сам.assertRaises(модуль._ПрерванныйОтказСистемногоGit) as не_сохранено:
                        модуль._передать_прерванный_отказ_системного_git(прервано.exception, не_сохранить)
                    сам.assertIs(не_сохранено.exception.первичная, прерывание)
                    сам.assertIsInstance(не_сохранено.exception.вторичные[-1], OSError)
                    (корень / 'private' / 'etc' / 'gitconfig').unlink()
                прерывание_закрытия = KeyboardInterrupt('отмена закрытия')
                def прервать_закрытие(номер):
                    штатное_закрытие(номер)
                    if not вызвано:
                        вызвано.append(номер)
                        raise прерывание_закрытия
                вызвано.clear()
                with mock.patch.object(модуль.os, 'close', side_effect=прервать_закрытие):
                    with сам.assertRaises(модуль._ПрерванныйОтказСистемногоGit) as прервано:
                        with модуль._удержать_системный_конфиг_git(fd):
                            raise RuntimeError('исход consumer')
                сохранено = []
                with сам.assertRaises(KeyboardInterrupt) as передано:
                    модуль._передать_прерванный_отказ_системного_git(прервано.exception, сохранено.append)
                сам.assertIs(передано.exception, прерывание_закрытия)
                сам.assertIsInstance(сохранено[0].первичная, RuntimeError)
                первый, второй = SystemExit('первый'), KeyboardInterrupt('второй')
                вложенный = модуль._составить_отказ_системного_git(первый, (второй,))
                составной = модуль._составить_отказ_системного_git(RuntimeError('consumer'), (вложенный,))
                сохранено = []
                with сам.assertRaises(SystemExit) as передано:
                    модуль._передать_прерванный_отказ_системного_git(составной, сохранено.append)
                сам.assertIs(передано.exception, первый)
                сам.assertIs(сохранено[0].вторичные[0].вторичные[0], второй)
                циклический = модуль._ПрерванныйОтказСистемногоGit(первый, ())
                циклический.первичная = циклический
                сохранено = []
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    модуль._передать_прерванный_отказ_системного_git(циклический, сохранено.append)
                сам.assertEqual(сохранено, [циклический])
                чрезмерный = модуль._ПрерванныйОтказСистемногоGit(первый, (второй,) * 256)
                сохранено = []
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    модуль._передать_прерванный_отказ_системного_git(чрезмерный, сохранено.append)
                сам.assertEqual(сохранено, [чрезмерный])
                класс_группы = getattr(sys.modules['builtins'], 'BaseExceptionGroup', None)
                if класс_группы is not None:
                    группа = класс_группы('две отмены', [первый, второй])
                    составной = модуль._составить_отказ_системного_git(группа, ())
                    сохранено = []
                    with сам.assertRaises(SystemExit) as передано:
                        модуль._передать_прерванный_отказ_системного_git(составной, сохранено.append)
                    сам.assertIs(передано.exception, первый)
                    сам.assertIs(сохранено[0].первичная, группа)
                (корень / 'private' / 'etc').rmdir()
                with mock.patch.object(модуль.os, 'close', side_effect=закрыть_каждый_с_ошибкой):
                    with сам.assertRaises(модуль._СовокупныйОтказСистемногоGit) as вход:
                        with модуль._удержать_системный_конфиг_git(fd):
                            сам.fail('нельзя вызвать consumer')
                сам.assertIsInstance(вход.exception.первичная, OSError)
                сам.assertEqual(len(вход.exception.вторичные), 1)
                (корень / 'private' / 'etc').mkdir()
                (корень / 'etc').unlink()
                (корень / 'etc').symlink_to('other')
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    with модуль._удержать_системный_конфиг_git(fd):
                        сам.fail('нельзя вызвать consumer')
            finally:
                os.close(fd)

    def test_внешний_excludesfile_влияет_на_точный_список_git(сам):
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory() as каталог:
            база = Path(каталог).resolve()
            домашний, репозиторий, дерево = база / 'home', база / 'repo', база / 'work'
            домашний.mkdir()
            окружение = {'PATH': os.defpath, 'HOME': str(домашний), 'LC_ALL': 'C',
                         'GIT_CONFIG_NOSYSTEM': '1', 'GIT_ATTR_NOSYSTEM': '1',
                         'GIT_ALLOW_PROTOCOL': '', 'GIT_OPTIONAL_LOCKS': '0',
                         'GIT_NO_LAZY_FETCH': '1', 'GIT_NO_REPLACE_OBJECTS': '1'}
            def вызвать_git(*аргументы):
                return subprocess.run(['/usr/bin/git', '-c', 'core.hooksPath=/dev/null', *аргументы],
                                      env=окружение, stdin=subprocess.DEVNULL,
                                      stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True, timeout=10)
            вызвать_git('init', '-q', str(репозиторий))
            вызвать_git('-C', str(репозиторий), '-c', 'user.name=fixture', '-c', 'user.email=fixture@invalid',
                        'commit', '-q', '--allow-empty', '-m', 'fixture')
            вызвать_git('-C', str(репозиторий), 'worktree', 'add', '-q', '-b', 'fixture-linked', str(дерево))
            исключения = домашний / 'ignore'
            исключения.write_bytes(b'ignored.tmp\n')
            (домашний / '.gitconfig').write_text('[core]\n\texcludesfile = ' + str(исключения) + '\n')
            глобальный_конфиг = (домашний / '.gitconfig').read_bytes()
            определить = модуль._определить_абсолютное_исключение_git
            выбранный_путь = определить((глобальный_конфиг,))
            сам.assertEqual(выбранный_путь, str(исключения))
            с_кавычками = глобальный_конфиг + b'[difftool "fixture"]\n\tcmd = "tool \\"arg\\""\n'
            сам.assertEqual(определить((с_кавычками,)), str(исключения))
            конфиг_для_git = домашний / 'quoted-config'
            конфиг_для_git.write_bytes(с_кавычками)
            ответ_git = вызвать_git('config', '--no-includes', '--file', str(конфиг_для_git), '--get', 'core.excludesfile')
            сам.assertEqual(ответ_git.stdout, os.fsencode(исключения) + b'\n')
            сам.assertEqual(ответ_git.stderr, b'')
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                определить((глобальный_конфиг, b'[include]\n\tpath = /tmp/unknown\n'))
            for опасный in (b'[includeIf "gitdir:/tmp/"]\n\tpath = /tmp/x\n',
                            b'[core]\n\texcludesfile = ~/ignore\n',
                            b'[core]\n\texcludesfile = /\n',
                            b'[core]\n\texcludesfile = relative\n',
                            b'[core]\n\texcludesfile = /tmp/../ignore\n',
                            b'[core]\n\texcludesfile = "/tmp/ignore"\n',
                            b'[other]\n\tvalue = \x00\n',
                            b'[other]\n\tvalue = "unfinished\n',
                            b'[other]\n\tvalue = invalid\\q\n',
                            b'[core]\n\texcludesfile = /tmp/ignore'):
                with сам.subTest(опасный=опасный), сам.assertRaises(модуль.ОшибкаОтчёта):
                    определить((глобальный_конфиг, опасный))
            (дерево / 'ignored.tmp').write_bytes(b'fixture\n')
            (дерево / 'kept.txt').write_bytes(b'fixture\n')
            def список():
                аргументы = ('/bin/sh', '-c', 'ulimit -SHu 0 && exec "$@"', 'fum-git', '/usr/bin/git',
                             '-C', str(дерево), '--no-pager', '-c', 'core.fsmonitor=false',
                             '--work-tree=' + str(дерево), 'ls-files', '--others', '--exclude-standard', '-z', '--', '.')
                итог = subprocess.run(аргументы, env=окружение, stdin=subprocess.DEVNULL,
                                      stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True, timeout=10)
                сам.assertEqual(итог.stderr, b'')
                return итог.stdout
            with contextlib.ExitStack() as стек:
                каталог_fd = os.open(домашний, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
                стек.callback(os.close, каталог_fd)
                файл_fd = os.open('ignore', os.O_RDONLY | os.O_NOFOLLOW, dir_fd=каталог_fd)
                стек.callback(os.close, файл_fd)
                сверить = модуль._сверить_источник_git_с_fd
                сверить(каталог_fd, 'ignore', файл_fd, b'ignored.tmp\n')
                сверить_путь = модуль._сверить_абсолютный_путь_источника_git
                сверить_путь(выбранный_путь, каталог_fd, файл_fd, b'ignored.tmp\n')
                ссылка = база / 'home-link'
                os.symlink(домашний, ссылка)
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    сверить_путь(str(ссылка / 'ignore'), каталог_fd, файл_fd, b'ignored.tmp\n')
                другой_fd = os.open('.gitconfig', os.O_RDONLY | os.O_NOFOLLOW, dir_fd=каталог_fd)
                стек.callback(os.close, другой_fd)
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    сверить(каталог_fd, 'ignore', другой_fd, b'ignored.tmp\n')
                до = список()
                сверить(каталог_fd, 'ignore', файл_fd, b'ignored.tmp\n')
                сверить_путь(выбранный_путь, каталог_fd, файл_fd, b'ignored.tmp\n')
                сам.assertEqual(до, b'kept.txt\0')
                os.rename(исключения, домашний / 'old-ignore')
                исключения.write_bytes(b'')
                потребитель = mock.Mock(side_effect=AssertionError('потребитель вызван до отказа'))
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    сверить(каталог_fd, 'ignore', файл_fd, b'ignored.tmp\n')
                    потребитель()
                потребитель.assert_not_called()
                новый_fd = os.open('ignore', os.O_RDONLY | os.O_NOFOLLOW, dir_fd=каталог_fd)
                стек.callback(os.close, новый_fd)
                сверить(каталог_fd, 'ignore', новый_fd, b'')
                сверить_путь(выбранный_путь, каталог_fd, новый_fd, b'')
                после = список()
                сверить(каталог_fd, 'ignore', новый_fd, b'')
                сверить_путь(выбранный_путь, каталог_fd, новый_fd, b'')
                сам.assertEqual(после, b'ignored.tmp\0kept.txt\0')
                локальное_исключение = домашний / 'override'
                локальное_исключение.write_bytes(b'kept.txt\n')
                вызвать_git('-C', str(дерево), 'config', '--local', 'core.excludesfile', str(локальное_исключение))
                локальный_конфиг = (репозиторий / '.git/config').read_bytes()
                локальный_путь = определить((глобальный_конфиг, локальный_конфиг))
                сам.assertEqual(локальный_путь, str(локальное_исключение))
                локальный_fd = os.open('override', os.O_RDONLY | os.O_NOFOLLOW, dir_fd=каталог_fd)
                стек.callback(os.close, локальный_fd)
                сверить(каталог_fd, 'override', локальный_fd, b'kept.txt\n')
                сверить_путь(локальный_путь, каталог_fd, локальный_fd, b'kept.txt\n')
                локальный_список = список()
                сверить(каталог_fd, 'override', локальный_fd, b'kept.txt\n')
                сверить_путь(локальный_путь, каталог_fd, локальный_fd, b'kept.txt\n')
                сам.assertEqual(локальный_список, b'ignored.tmp\0')
                print('with_excludes_hex=' + до.hex())
                print('empty_excludes_hex=' + после.hex())
                print('local_override_hex=' + локальный_список.hex())

    def test_формат_git_ref_сверяется_с_git_для_utf8(сам):
        модуль = загрузить_модуль_автоматизации()
        примеры = ('refs/heads/ветка/тест', 'refs/heads/release/1.2', 'refs/heads/a..b',
                    'refs/heads/.hidden', 'refs/heads/a.lock', 'refs/heads/a b',
                    'refs/heads/a@{b', 'refs/heads/ok-name')
        with tempfile.TemporaryDirectory() as каталог:
            окружение = {'PATH': os.defpath, 'HOME': каталог, 'LC_ALL': 'C',
                         'GIT_CONFIG_GLOBAL': '/dev/null', 'GIT_CONFIG_NOSYSTEM': '1'}
            for ссылка in примеры:
                with сам.subTest(ссылка=ссылка):
                    итог = subprocess.run(['/usr/bin/git', '-c', 'core.hooksPath=/dev/null',
                                           'check-ref-format', ссылка], cwd=каталог, env=окружение,
                                          stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                          stderr=subprocess.PIPE, timeout=10, check=False)
                    сам.assertIn(итог.returncode, (0, 1))
                    сам.assertEqual(модуль._допустимая_ссылка_git(ссылка.encode('utf-8')), итог.returncode == 0)
            сам.assertFalse(модуль._допустимая_ссылка_git(b'refs/heads/\xff'))

    def test_неинициализированный_gitlink_и_родительский_diff(сам):
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory() as каталог:
            база = Path(каталог).resolve()
            репозиторий, дерево = база / 'repo', база / 'work'
            окружение = {'PATH': os.defpath, 'HOME': каталог, 'LC_ALL': 'C',
                         'GIT_CONFIG_GLOBAL': '/dev/null', 'GIT_CONFIG_NOSYSTEM': '1',
                         'GIT_ATTR_NOSYSTEM': '1', 'GIT_ALLOW_PROTOCOL': '',
                         'GIT_OPTIONAL_LOCKS': '0', 'GIT_NO_LAZY_FETCH': '1',
                         'GIT_NO_REPLACE_OBJECTS': '1'}
            def вызвать_git(*аргументы):
                return subprocess.run(['/usr/bin/git', '-c', 'core.hooksPath=/dev/null', *аргументы],
                                      env=окружение, stdin=subprocess.DEVNULL,
                                      stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True, timeout=10)
            вызвать_git('init', '-q', str(репозиторий))
            модули = (b'[submodule "module"]\n\tpath = module\n'
                      b'\turl = https://example.invalid/fork\n'
                      b'\tfumUpstream = https://example.invalid/upstream\n')
            (репозиторий / '.gitmodules').write_bytes(модули)
            вызвать_git('-C', str(репозиторий), 'add', '--', '.gitmodules')
            вызвать_git('-C', str(репозиторий), '-c', 'user.name=fixture', '-c', 'user.email=fixture@invalid',
                'commit', '-q', '-m', 'fixture')
            вызвать_git('-C', str(репозиторий), 'config', 'extensions.worktreeConfig', 'true')
            вызвать_git('-C', str(репозиторий), 'worktree', 'add', '-q', '-b', 'fixture-linked', str(дерево))
            вызвать_git('-C', str(дерево), 'config', '--worktree', 'core.autocrlf', 'false')
            вызвать_git('-C', str(репозиторий), 'config', 'remote.origin.url', 'https://example.invalid/repo')
            вызвать_git('-C', str(репозиторий), 'config', 'remote.origin.fetch', '+refs/heads/*:refs/remotes/origin/*')
            вызвать_git('-C', str(репозиторий), 'config', 'branch.fixture.remote', 'origin')
            вызвать_git('-C', str(репозиторий), 'config', 'branch.fixture.merge', 'refs/heads/fixture')
            вызвать_git('-C', str(репозиторий), 'config', 'submodule.obsolete.active', 'true')
            вызвать_git('-C', str(репозиторий), 'config', 'submodule.obsolete.url', 'https://example.invalid/module')
            вызвать_git('-C', str(репозиторий), 'config', 'submodule.module.active', 'true')
            вызвать_git('-C', str(репозиторий), 'config', 'submodule.module.url', 'https://example.invalid/fork')
            вызвать_git('-C', str(дерево), 'config', '--worktree', 'codex.localenvironmentconfigpath', '.codex/local')
            вершина = вызвать_git('-C', str(дерево), 'rev-parse', '--verify', 'HEAD').stdout.strip().decode('ascii')
            вызвать_git('-C', str(дерево), 'update-index', '--add', '--cacheinfo', '160000', вершина, 'module')
            (дерево / 'module').mkdir()
            исключения = ('.', ':(exclude)Журнал/фикстура/отчёт.md',
                          ':(exclude)Журнал/фикстура/материалы/запуски-проверок',
                          ':(exclude)Журнал/фикстура/материалы/запуски-проверок/**',
                          ':(top,exclude,literal)Proyekcii', ':(top,exclude,glob)Proyekcii/**')
            общая = ('/bin/sh', '-c', 'ulimit -SHu 0 && exec "$@"', 'fum-git', '/usr/bin/git',
                     '-C', str(дерево), '--no-pager', '-c', 'core.fsmonitor=false',
                     '--work-tree=' + str(дерево), 'diff', '--binary', '--no-ext-diff',
                     '--no-textconv', '--ignore-submodules=dirty')
            def разница(*параметры):
                итог = subprocess.run((*общая, *параметры, '--', *исключения), env=окружение,
                                      stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                      check=True, timeout=10)
                сам.assertEqual(итог.stderr, b'')
                return итог.stdout
            пустая_разница = разница()
            сам.assertEqual(пустая_разница, b'')
            ожидаемое = (f'diff --git a/module b/module\nnew file mode 160000\n'
                         f'index {"0" * 7}..{вершина[:7]}\n--- /dev/null\n+++ b/module\n'
                         f'@@ -0,0 +1 @@\n+Subproject commit {вершина}\n').encode('ascii')
            индексная_разница = разница('--cached', вершина)
            сам.assertEqual(индексная_разница, ожидаемое)
            print('empty_directory_diff_hex=' + пустая_разница.hex())
            print('cached_diff_hex=' + индексная_разница.hex())
            with contextlib.ExitStack() as стек:
                рабочий = os.open(дерево, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
                стек.callback(os.close, рабочий)
                общий = os.open(репозиторий / '.git', os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
                стек.callback(os.close, общий)
                собрать = модуль._собрать_локальные_конфиги_связанного_git
                параметры = (рабочий, общий, str(дерево), str(репозиторий / '.git'), 'work')
                with mock.patch.object(модуль, '_сверить_url_подмодуля_git',
                                       wraps=модуль._сверить_url_подмодуля_git) as сверка:
                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                        собрать(*параметры)
                    сверка.assert_called_once()
                вызвать_git('-C', str(репозиторий), 'config', 'submodule.module.url', 'https://example.invalid/other')
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'URL подмодуля'):
                    собрать(*параметры)
                for раздел in ('remote.origin', 'branch.fixture', 'submodule.obsolete', 'submodule.module'):
                    вызвать_git('-C', str(репозиторий), 'config', '--remove-section', раздел)
                вызвать_git('-C', str(дерево), 'config', '--worktree', '--remove-section', 'codex')
                сам.assertEqual(len(собрать(*параметры)), 2)
                (дерево / 'module/untracked.txt').write_text('fixture\n')
                непустая_разница = разница()
                print('nonempty_directory_diff_hex=' + непустая_разница.hex())
                сам.assertEqual(непустая_разница, b'')
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    собрать(*параметры)
                (дерево / 'module/untracked.txt').unlink()
                (дерево / 'module').rmdir()
                удаление = (f'diff --git a/module b/module\ndeleted file mode 160000\n'
                            f'index {вершина[:7]}..{"0" * 7}\n--- a/module\n+++ /dev/null\n'
                            f'@@ -1 +0,0 @@\n-Subproject commit {вершина}\n').encode('ascii')
                разница_отсутствующего = разница()
                сам.assertEqual(разница_отсутствующего, удаление)
                print('absent_directory_diff_hex=' + разница_отсутствующего.hex())
                сам.assertEqual(разница('--cached', вершина), ожидаемое)
                сам.assertEqual(len(собрать(*параметры)), 2)
                os.symlink('/tmp', дерево / 'module')
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    собрать(*параметры)
                (дерево / 'module').unlink()
                (дерево / 'module').mkdir()
                (дерево / '.gitmodules').write_bytes(модули + b'# changed\n')
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    собрать(*параметры)
                (дерево / '.gitmodules').write_bytes(модули)
                вызвать_git('init', '-q', str(дерево / 'module'))
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    собрать(*параметры)
                вызвать_git('-C', str(дерево / 'module'), '-c', 'user.name=fixture',
                            '-c', 'user.email=fixture@invalid', 'commit', '-q', '--allow-empty', '-m', 'child')
                вершина_подмодуля = вызвать_git('-C', str(дерево / 'module'), 'rev-parse', '--verify', 'HEAD').stdout.strip().decode('ascii')
                вызвать_git('-C', str(дерево), 'update-index', '--add', '--cacheinfo',
                            '160000', вершина_подмодуля, 'module')
                путь_подмодуля = str(дерево / 'module')
                def статус_подмодуля():
                    аргументы = ('/bin/sh', '-c', 'ulimit -SHu 0 && exec "$@"', 'fum-git', '/usr/bin/git',
                                 '-C', путь_подмодуля, '--no-pager', '-c', 'core.fsmonitor=false',
                                 '--work-tree=' + путь_подмодуля, 'status', '--porcelain=v2', '-z',
                                 '--untracked-files=all', '--ignore-submodules=dirty', '--', '.')
                    итог = subprocess.run(аргументы, env=окружение, stdin=subprocess.DEVNULL,
                                          stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True, timeout=10)
                    сам.assertEqual(итог.stderr, b'')
                    return итог.stdout
                сам.assertEqual(статус_подмодуля(), b'')
                сам.assertEqual(разница(), b'')
                (дерево / 'module/dirty.txt').write_bytes(b'fixture\n')
                грязный_статус = статус_подмодуля()
                разница_с_грязным = разница()
                сам.assertEqual(грязный_статус, b'? dirty.txt\0')
                сам.assertEqual(разница_с_грязным, b'')
                print('initialized_dirty_status_hex=' + грязный_статус.hex())
                print('initialized_dirty_parent_diff_hex=' + разница_с_грязным.hex())

