def загрузить_модуль_автоматизации():
    спецификация = importlib.util.spec_from_file_location(
        "fum_отчёты_о_запусках_проверок_тест",
        сценарий,
    )
    if спецификация is None or спецификация.loader is None:
        raise AssertionError("Не удалось загрузить модуль автоматизации")
    модуль = importlib.util.module_from_spec(спецификация)
    спецификация.loader.exec_module(модуль)
    if hasattr(модуль, "_стандартные_настройки_git_отпечатка"):
        настройки = модуль._НастройкиGitОтпечатка(None, системные_настройки=False)
        модуль._стандартные_настройки_git_отпечатка = lambda: настройки
    return модуль


def дождаться_файла(путь: Path, тайм_аут: float = 5.0) -> None:
    предел = time.monotonic() + тайм_аут
    while time.monotonic() < предел:
        if путь.exists():
            return
        time.sleep(0.01)
    raise AssertionError(f"Файл не появился за {тайм_аут} с: {путь}")


class ФикстураОтчётов:
    def __init__(сам, *, _без_git=False) -> None:
        if type(_без_git) is not bool:
            raise ValueError('неверный режим подготовки фикстуры')
        сам.временный_каталог = tempfile.TemporaryDirectory(dir="/tmp")
        if _без_git:
            сам.временный_каталог._finalizer.detach()
        сам.корень = Path(сам.временный_каталог.name)
        сам.каталог_сессии = сам.корень / "Журнал" / имя_сессии
        сам.каталог_сессии.mkdir(parents=True)
        сам.запрос = сам.каталог_сессии / "запрос.md"
        сам.запрос.write_text(
            "# Исходный запрос 2026-08-04 20:45:26 MSK\n\n"
            "## Текст запроса\n\n````text\nПроверить.\n````\n",
            encoding="utf-8",
        )
        сам.отчёт = сам.каталог_сессии / "отчёт.md"
        сам.отчёт.write_text(
            "# Отчёт 2026-08-04 20:45:26 MSK\n\n"
            "Содержательное введение, которое нельзя менять рендером.\n\n"
            "## Профиль времени выполнения\n\n"
            "### Прямые запуски проверок\n\n"
            f"{открытый_маркер}\n"
            "Запусков пока нет.\n"
            f"{конечный_маркер}\n\n"
            "## Проверки\n\n"
            "Содержательный хвост, который нельзя менять рендером.\n",
            encoding="utf-8",
        )
        сам.каталог_записей = (
            сам.каталог_сессии
            / "материалы"
            / "запуски-проверок"
        )
        if _без_git:
            return
        for команда in (
            ("init", "-q", "--template="),
            ("config", "user.name", "FUM Tests"),
            ("config", "user.email", "fum-tests@example.invalid"),
            ("add", "."),
            ("commit", "-q", "-m", "Исходная фикстура"),
        ):
            subprocess.run(
                ["git", "-C", str(сам.корень), "-c", "core.fsmonitor=false",
                 "-c", "core.hooksPath=/dev/null", "-c", "commit.gpgsign=false", *команда],
                cwd=сам.корень,
                check=True,
                capture_output=True,
                stdin=subprocess.DEVNULL,
                timeout=10,
                env={"PATH": os.defpath, "GIT_OPTIONAL_LOCKS": "0",
                     "GIT_NO_LAZY_FETCH": "1", "GIT_NO_REPLACE_OBJECTS": "1",
                     "GIT_CONFIG_NOSYSTEM": "1", "GIT_CONFIG_GLOBAL": "/dev/null",
                     "GIT_ATTR_NOSYSTEM": "1",
                     "LC_ALL": "C"},
            )

    def очистить(сам) -> None:
        сам.временный_каталог.cleanup()

    def аргументы(сам, команда: str, *дополнения: str) -> list[str]:
        return [
            sys.executable,
            str(сценарий),
            команда,
            "--корень-репозитория",
            str(сам.корень),
            "--запрос",
            путь_запроса,
            *дополнения,
        ]

    def выполнить(
        сам,
        команда: str,
        *дополнения: str,
    ) -> subprocess.CompletedProcess[str]:
        return subprocess.run(
            сам.аргументы(команда, *дополнения),
            cwd=сам.корень,
            check=False,
            capture_output=True,
            text=True,
        )

    def запустить(
        сам,
        идентификатор: str,
        *вызываемая_команда: str,
        название: str = "целевая проверка",
        исполнитель: str = "root",
        тайм_аут: str | None = None,
    ) -> subprocess.CompletedProcess[str]:
        аргументы = [
            "--название",
            название,
            "--исполнитель",
            исполнитель,
            "--идентификатор-запуска",
            идентификатор,
        ]
        if тайм_аут is not None:
            аргументы.extend(["--тайм-аут-секунды", тайм_аут])
        путь_полной_проверки = (
            сам.корень
            / "Инструменты"
            / "fum-kompleksnaya-proverka-repozitoriya"
            / "scripts"
            / "run-smoke-check.py"
        )
        класс_проверки = (
            "полная"
            if len(вызываемая_команда) >= 2
            and Path(вызываемая_команда[1]).resolve()
            == путь_полной_проверки.resolve()
            else "адресная"
        )
        аргументы.extend(["--класс-проверки", класс_проверки, "--обычная-схема-профиля"])
        аргументы.extend(["--", *вызываемая_команда])
        return сам.выполнить("запустить", *аргументы)

    def файлы_записей(сам) -> list[Path]:
        if not сам.каталог_записей.exists():
            return []
        return sorted(
            файл
            for файл in сам.каталог_записей.glob("*.json")
            if файл.name != "снимок.json"
        )

    def записи(сам) -> list[dict[str, object]]:
        return [
            json.loads(файл.read_text(encoding="utf-8"))
            for файл in сам.файлы_записей()
        ]

    def запись(сам, идентификатор: str) -> dict[str, object]:
        совпадения = [
            запись
            for запись in сам.записи()
            if запись["идентификатор"] == идентификатор
        ]
        if len(совпадения) != 1:
            raise AssertionError(
                f"Ожидалась одна запись {идентификатор}, получено {len(совпадения)}"
            )
        return совпадения[0]

    def записать_завершённую_запись(
        сам,
        порядок: int,
        идентификатор: str,
        длительность: int,
        *,
        название: str = "проверка",
        исполнитель: str = "root",
        статус: str = "успешно",
        код: int | None = 0,
        пояснение: str | None = None,
    ) -> Path:
        сам.каталог_записей.mkdir(parents=True, exist_ok=True)
        файл = сам.каталог_записей / f"{порядок}_{идентификатор}.json"
        файл.write_text(
            json.dumps(
                {
                    "схема": "fum.test-run.v1",
                    "идентификатор": идентификатор,
                    "сессия": путь_запроса,
                    "порядок": порядок,
                    "исполнитель": исполнитель,
                    "вызов": название,
                    "состояние": "завершён",
                    "длительность_наносекунды": длительность,
                    "статус": статус,
                    "код_завершения": код,
                    "пояснение": пояснение,
                },
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n",
            encoding="utf-8",
        )
        return файл


class ПроверкаЯвногоЗамкаЗакрытияИВозобновления(unittest.TestCase):
    def setUp(сам):
        сам.модуль = загрузить_модуль_автоматизации()
        # Фикстура принадлежит тесту и сохраняется для разбора при любом исходе.
        сам.фикстура = ФикстураОтчётов(_без_git=True)
        сам.фикстура.записать_завершённую_запись(
            1, '00000000-0000-4000-8000-000000000021', 1000)
        сам.корень = сам.фикстура.корень.resolve()
        сам.снимок = сам.фикстура.каталог_записей / 'снимок.json'
        сам.журнал = сам.фикстура.каталог_записей / имя_журнала_возобновления

    def test_неполная_пара_отклоняется_до_сессии(сам):
        м = сам.модуль
        for операция in (м.выполнить_закрытие, м.выполнить_возобновление):
            for контракт, срок in ((object(), None), (None, 1.0)):
                with сам.subTest(операция=операция.__name__, контракт=контракт is not None), \
                     mock.patch.object(м, 'разрешить_сессию', side_effect=AssertionError('сессия')):
                    with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'контракт.*срок'):
                        операция(сам.корень, Path(путь_запроса),
                                 _контракт_замка=контракт, _срок_замка=срок)

    def test_профили_и_раунды_отклоняются_до_эффекта(сам):
        м = сам.модуль
        исходный = сам.фикстура.отчёт.read_bytes()
        замок = lambda *а, **к: contextlib.nullcontext(lambda: None)
        for операция, чтение in ((м.выполнить_закрытие, 'прочитать_историю_проверок'),
                                 (м.выполнить_возобновление, 'прочитать_записи')):
            for схема in (м.СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА, м.СХЕМА_ЗАПУСКА_С_РАУНДАМИ):
                записи = [(Path('/private/tmp/fixture'), {'схема': схема}, b'')]
                with сам.subTest(операция=операция.__name__, схема=схема), \
                     mock.patch.object(м, '_тестово_выбрать_замок_сессии', side_effect=замок), \
                     mock.patch.object(м, чтение, return_value=записи), \
                     mock.patch.object(м, 'текущий_контекст_проверок', side_effect=AssertionError('контекст Git')), \
                     mock.patch.object(м, 'атомарно_записать_байты', side_effect=AssertionError('запись')):
                    with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'профил|раунд'):
                        операция(сам.корень, Path(путь_запроса),
                                 _контракт_замка=('fixture',), _срок_замка=time.monotonic() + 2.0)
                сам.assertEqual(сам.фикстура.отчёт.read_bytes(), исходный)
                сам.assertFalse(сам.снимок.exists())
                сам.assertFalse(сам.журнал.exists())

    def test_несовместимый_снимок_или_журнал_отклоняется_без_изменений(сам):
        м = сам.модуль
        замок = lambda *а, **к: contextlib.nullcontext(lambda: None)
        случаи = ((м.выполнить_закрытие, 'снимок-профиля'),
                  (м.выполнить_закрытие, 'снимок-раундов'),
                  (м.выполнить_возобновление, 'снимок-профиля'),
                  (м.выполнить_возобновление, 'снимок-раундов'),
                  (м.выполнить_возобновление, 'журнал-профиля'))
        сам.дополнительные_фикстуры = []
        for операция, вид in случаи:
            with сам.subTest(операция=операция.__name__, вид=вид):
                ф = ФикстураОтчётов(_без_git=True)
                сам.дополнительные_фикстуры.append(ф)
                запись = ф.записать_завершённую_запись(
                    1, '00000000-0000-4000-8000-000000000021', 1000)
                файлы = [{'имя': запись.name, 'sha256': hashlib.sha256(запись.read_bytes()).hexdigest()}]
                if вид.startswith('снимок-'):
                    значение = {'схема': (м.СХЕМА_СНИМКА_С_ВЕРДИКТОМ if вид == 'снимок-профиля'
                                           else м.СХЕМА_СНИМКА_С_РАУНДАМИ),
                                'сессия': путь_запроса, 'файлы': файлы,
                                'отпечаток_закрытия': 'sha256:' + '0' * 64}
                    if вид == 'снимок-раундов':
                        значение['отпечаток_содержимого_закрытия'] = 'sha256:' + '1' * 64
                    (ф.каталог_записей / 'снимок.json').write_bytes(м.канонические_машинные_байты(значение))
                else:
                    значение = {'схема': м.СХЕМА_ЖУРНАЛА_ВОЗОБНОВЛЕНИЯ_С_ВЕРДИКТОМ,
                                'сессия': путь_запроса, 'хэш_закрытого_отчёта': '0' * 64,
                                'хэш_открытого_отчёта': '1' * 64, 'хэш_снимка': '2' * 64,
                                'отпечаток_закрытия': 'sha256:' + '3' * 64}
                    (ф.каталог_записей / имя_журнала_возобновления).write_bytes(
                        м.канонические_машинные_байты(значение))
                до = (ф.отчёт.read_bytes(), {п.name: п.read_bytes() for п in ф.каталог_записей.iterdir()})
                with mock.patch.object(м, '_тестово_выбрать_замок_сессии', side_effect=замок), \
                     mock.patch.object(м, 'атомарно_записать_байты', side_effect=AssertionError('запись')), \
                     mock.patch.object(м, 'заменить_управляемый_блок', side_effect=AssertionError('публикация')):
                    with сам.assertRaises(м.ОшибкаОтчёта):
                        операция(ф.корень.resolve(), Path(путь_запроса),
                                 _контракт_замка=('fixture',), _срок_замка=time.monotonic() + 2.0)
                после = (ф.отчёт.read_bytes(), {п.name: п.read_bytes() for п in ф.каталог_записей.iterdir()})
                сам.assertEqual(после, до)

    def test_потеря_явного_замка_отказывает_до_первой_публикации(сам):
        м = сам.модуль
        исходный = сам.фикстура.отчёт.read_bytes()
        def отказ():
            raise м.ОшибкаОтчёта('утрачен замок фикстуры')
        def замок(сверить):
            return lambda *а, **к: contextlib.nullcontext(сверить)
        параметры = {'_контракт_замка': ('fixture',), '_срок_замка': time.monotonic() + 5.0}
        with mock.patch.object(м, '_тестово_выбрать_замок_сессии', side_effect=замок(отказ)):
            with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'утрачен замок'):
                м.выполнить_закрытие(сам.корень, Path(путь_запроса), **параметры)
        сам.assertEqual(сам.фикстура.отчёт.read_bytes(), исходный)
        сам.assertFalse(сам.снимок.exists())
        # Отказ мог оставить непубликуемый временный файл: не повторять эту сессию.
        сам.вторая_фикстура = ФикстураОтчётов(_без_git=True)
        сам.вторая_фикстура.записать_завершённую_запись(
            1, '00000000-0000-4000-8000-000000000021', 1000)
        второй_корень = сам.вторая_фикстура.корень.resolve()
        второй_снимок = сам.вторая_фикстура.каталог_записей / 'снимок.json'
        второй_журнал = сам.вторая_фикстура.каталог_записей / имя_журнала_возобновления
        with mock.patch.object(м, '_тестово_выбрать_замок_сессии', side_effect=замок(lambda: None)):
            сам.assertEqual(м.выполнить_закрытие(второй_корень, Path(путь_запроса), **параметры), 0)
        закрыто = (сам.вторая_фикстура.отчёт.read_bytes(), второй_снимок.read_bytes())
        with mock.patch.object(м, '_тестово_выбрать_замок_сессии', side_effect=замок(отказ)):
            with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'утрачен замок'):
                м.выполнить_возобновление(второй_корень, Path(путь_запроса), **параметры)
        сам.assertEqual((сам.вторая_фикстура.отчёт.read_bytes(), второй_снимок.read_bytes()), закрыто)
        сам.assertFalse(второй_журнал.exists())

    def test_известные_фазы_возобновления_завершаются_под_явным_замком(сам):
        import errno
        м = сам.модуль
        сам.фикстуры_восстановления = []
        for фаза in ('отчёт-закрыт', 'отчёт-открыт'):
            with сам.subTest(фаза=фаза):
                ф = ФикстураОтчётов(_без_git=True)
                сам.фикстуры_восстановления.append(ф)
                ф.записать_завершённую_запись(1, '00000000-0000-4000-8000-000000000021', 1000)
                корень = ф.корень.resolve()
                снимок = ф.каталог_записей / 'снимок.json'
                журнал = ф.каталог_записей / имя_журнала_возобновления
                проверки = []
                def сверить():
                    проверки.append(True)
                def замок(*а, **к):
                    return contextlib.nullcontext(сверить)
                параметры = {'_контракт_замка': ('fixture',), '_срок_замка': time.monotonic() + 5.0}
                with mock.patch.object(м, '_тестово_выбрать_замок_сессии', side_effect=замок), \
                     mock.patch.object(м, 'межпроцессная_блокировка', side_effect=AssertionError('legacy')):
                    сам.assertEqual(м.выполнить_закрытие(корень, Path(путь_запроса), **параметры), 0)
                    закрытый_отчёт, исходный_снимок = ф.отчёт.read_bytes(), снимок.read_bytes()
                    if фаза == 'отчёт-закрыт':
                        вызвать = м._ВладелецЗаменыПредпросмотра._вызвать
                        подмены = []
                        def подменить_после_журнала(владелец, имя, операция, *а, **к):
                            if имя == 'повторная проверка предпросмотра' and not подмены:
                                сам.assertTrue(журнал.is_file())
                                донор = ф.отчёт.with_name('синтетическая-подмена')
                                донор.write_bytes(закрытый_отчёт)
                                os.replace(донор, ф.отчёт)
                                подмены.append(True)
                            return вызвать(владелец, имя, операция, *а, **к)
                        with mock.patch.object(м._ВладелецЗаменыПредпросмотра, '_вызвать',
                                               подменить_после_журнала):
                            with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'отчёт изменился после подготовки журнала'):
                                м.выполнить_возобновление(корень, Path(путь_запроса), **параметры)
                        сам.assertEqual(подмены, [True])
                        сам.assertEqual(ф.отчёт.read_bytes(), закрытый_отчёт)
                    else:
                        настоящий_unlink = os.unlink
                        отказы = []
                        def отказ_до_unlink(путь, *а, **к):
                            fd = к.get('dir_fd')
                            if путь == снимок.name and fd is not None:
                                каталог, открытый = ф.каталог_записей.stat(), os.fstat(fd)
                                if (каталог.st_dev, каталог.st_ino) == (открытый.st_dev, открытый.st_ino):
                                    отказы.append(True)
                                    raise OSError(errno.EIO, 'отказ до unlink снимка')
                            return настоящий_unlink(путь, *а, **к)
                        with mock.patch.object(м.os, 'unlink', side_effect=отказ_до_unlink):
                            with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'снимок и журнал подтверждены'):
                                м.выполнить_возобновление(корень, Path(путь_запроса), **параметры)
                        сам.assertEqual(отказы, [True])
                        сам.assertIn(открытый_маркер.encode(), ф.отчёт.read_bytes())
                    сам.assertEqual(снимок.read_bytes(), исходный_снимок)
                    сам.assertTrue(журнал.is_file())
                    сам.assertGreater(len(проверки), 0)
                    # Фикстурный отказ предшествовал публикации или unlink; готовые фазы сверены выше.
                    сам.assertEqual(м.выполнить_возобновление(корень, Path(путь_запроса), **параметры), 0)
                сам.assertIn(открытый_маркер.encode(), ф.отчёт.read_bytes())
                сам.assertFalse(снимок.exists()); сам.assertFalse(журнал.exists())

    def test_двухкорневой_мост_удерживается_при_закрытии_и_возобновлении(сам):
        м = сам.модуль
        старый, новый = сам.корень / 'old-lock', сам.корень / 'new-lock'
        старый.mkdir(mode=0o700); новый.mkdir(mode=0o700)
        сам.опоры_замков = ([], [])
        флаги = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
        старый_fd = м._приобрести_fd(сам.опоры_замков[0], os.open, старый, флаги)
        новый_fd = м._приобрести_fd(сам.опоры_замков[1], os.open, новый, флаги)
        def селектор(путь, fd):
            с = os.fstat(fd)
            return ('fum.test-lock-root.2', str(путь), с.st_dev, с.st_ino, с.st_uid,
                    с.st_mode & 0o7777, путь_запроса, str(сам.корень))
        а, б = селектор(старый, старый_fd), селектор(новый, новый_fd)
        контракт = ('fum.test-lock-bridge.1', а, старый_fd, б, новый_fd)
        сам.этап_опор = 'удерживаются'
        try:
            with mock.patch.object(м.tempfile, 'gettempdir', side_effect=AssertionError('legacy tempfile')), \
                 mock.patch.object(м.subprocess, 'Popen', side_effect=AssertionError('Git')):
                исходный = сам.фикстура.отчёт.read_bytes()
                with м._тестовый_мост_замков(а, старый_fd, б, новый_fd, сам.корень,
                                              путь_запроса, срок_монотонный=time.monotonic() + 5.0):
                    with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'срок'):
                        м.выполнить_закрытие(сам.корень, Path(путь_запроса),
                            _контракт_замка=контракт, _срок_замка=time.monotonic() + 0.2)
                сам.assertEqual(сам.фикстура.отчёт.read_bytes(), исходный)
                сам.assertFalse(сам.снимок.exists())
                def параметры():
                    return {'_контракт_замка': контракт, '_срок_замка': time.monotonic() + 5.0}
                сам.assertEqual(м.выполнить_закрытие(сам.корень, Path(путь_запроса), **параметры()), 0)
                закрыто = (сам.фикстура.отчёт.read_bytes(), сам.снимок.read_bytes())
                сам.assertEqual(м.выполнить_закрытие(сам.корень, Path(путь_запроса), **параметры()), 0)
                сам.assertEqual((сам.фикстура.отчёт.read_bytes(), сам.снимок.read_bytes()), закрыто)
                with м._тестовый_мост_замков(а, старый_fd, б, новый_fd, сам.корень,
                                              путь_запроса, срок_монотонный=time.monotonic() + 5.0):
                    with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'срок'):
                        м.выполнить_возобновление(сам.корень, Path(путь_запроса),
                            _контракт_замка=контракт, _срок_замка=time.monotonic() + 0.2)
                сам.assertEqual((сам.фикстура.отчёт.read_bytes(), сам.снимок.read_bytes()), закрыто)
                сам.assertFalse(сам.журнал.exists())
                сам.assertEqual(м.выполнить_возобновление(сам.корень, Path(путь_запроса), **параметры()), 0)
                сам.assertIn(открытый_маркер.encode(), сам.фикстура.отчёт.read_bytes())
                сам.assertFalse(сам.снимок.exists()); сам.assertFalse(сам.журнал.exists())
            сам.этап_опор = 'проверка завершена'
        finally:
            if сам.этап_опор == 'проверка завершена':
                for реестр in reversed(сам.опоры_замков):
                    сам.этап_опор = 'закрытие начато'
                    м._отпустить_зарегистрированный_fd(реестр, реестр[0], _точный_исход=True)
                сам.этап_опор = 'опоры закрыты'


class ПроверкаЗамкаПриЗакрытии(unittest.TestCase):
    def setUp(сам):
        сам.модуль = загрузить_модуль_автоматизации()
        сам.фикстура = ФикстураОтчётов(_без_git=True)
        сам.addCleanup(сам.фикстура.очистить)
        сам.фикстура.записать_завершённую_запись(
            1, '00000000-0000-4000-8000-000000000021', 1000)
        сам.исходный_отчёт = сам.фикстура.отчёт.read_bytes()
        сам.снимок = сам.фикстура.каталог_записей / 'снимок.json'

    def закрыть(сам, отказ_на=None):
        вызовы = []
        @contextlib.contextmanager
        def замок(*аргументы, срок_монотонный):
            сам.assertTrue(math.isfinite(срок_монотонный))
            def сверить():
                вызовы.append(True)
                if len(вызовы) == отказ_на:
                    raise сам.модуль.ОшибкаОтчёта('подменён замок фикстуры')
            yield сверить
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', замок):
            сам.модуль.выполнить_закрытие(сам.фикстура.корень, Path(путь_запроса))
        return вызовы

    def test_отказ_перед_публикацией_снимка(сам):
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'подменён замок'):
            сам.закрыть(отказ_на=1)
        сам.assertFalse(сам.снимок.exists())
        сам.assertEqual(сам.фикстура.отчёт.read_bytes(), сам.исходный_отчёт)

    def test_отказ_после_публикации_снимка(сам):
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'подменён замок'):
            сам.закрыть(отказ_на=3)
        сам.assertTrue(сам.снимок.is_file())
        сам.assertEqual(сам.фикстура.отчёт.read_bytes(), сам.исходный_отчёт)

    def test_отказ_при_итоговой_сверке_после_публикации(сам):
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'подменён замок'):
            сам.закрыть(отказ_на=5)
        сам.assertTrue(сам.снимок.is_file())
        сам.assertNotEqual(сам.фикстура.отчёт.read_bytes(), сам.исходный_отчёт)

    def test_отказ_при_дозакрытии_подготовленного_снимка(сам):
        сам.assertEqual(len(сам.закрыть()), 5)
        снимок = сам.снимок.read_bytes()
        сам.фикстура.отчёт.write_bytes(сам.исходный_отчёт)
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'подменён замок'):
            сам.закрыть(отказ_на=1)
        сам.assertEqual(сам.снимок.read_bytes(), снимок)
        сам.assertEqual(сам.фикстура.отчёт.read_bytes(), сам.исходный_отчёт)

    def test_реальная_подмена_inode_замка_до_публикации(сам):
        корень = сам.фикстура.корень.resolve()
        ключ = hashlib.sha256(f'{корень}\0{путь_запроса}'.encode()).hexdigest()
        путь_замка = корень / f'fum-check-runs-{ключ}.lock'
        новый_замок = корень / 'replacement.lock'
        атомарно = сам.модуль._атомарно_сохранить_байты
        подмена = []

        def перехват(путь, временный, байты, режим, **параметры):
            if путь == сам.снимок.resolve():
                сверить = параметры['перед_публикацией']
                def заменить_перед_сверкой():
                    fd = os.open(новый_замок, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                    os.close(fd)
                    os.replace(новый_замок, путь_замка)
                    подмена.append(True)
                    сверить()
                параметры['перед_публикацией'] = заменить_перед_сверкой
            return атомарно(путь, временный, байты, режим, **параметры)

        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(сам.модуль, '_атомарно_сохранить_байты', side_effect=перехват):
            with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'небезопасный файл межпроцессной блокировки|подменён файл межпроцессной блокировки'):
                сам.модуль.выполнить_закрытие(корень, Path(путь_запроса))
        сам.assertEqual(подмена, [True])
        сам.assertFalse(сам.снимок.exists())
        сам.assertEqual(сам.фикстура.отчёт.read_bytes(), сам.исходный_отчёт)

    def test_настоящий_замок_сохраняет_идемпотентное_закрытие(сам):
        корень = сам.фикстура.корень.resolve()
        with mock.patch.object(сам.модуль.tempfile, 'gettempdir', return_value=str(корень)):
            сам.assertEqual(сам.модуль.выполнить_закрытие(корень, Path(путь_запроса)), 0)
            данные = (сам.снимок.read_bytes(), сам.фикстура.отчёт.read_bytes())
            сам.assertEqual(сам.модуль.выполнить_закрытие(корень, Path(путь_запроса)), 0)
        сам.assertEqual((сам.снимок.read_bytes(), сам.фикстура.отчёт.read_bytes()), данные)

    def test_повторное_закрытие_сверяет_замок_перед_успехом(сам):
        сам.закрыть()
        данные = (сам.снимок.read_bytes(), сам.фикстура.отчёт.read_bytes())
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'подменён замок'):
            сам.закрыть(отказ_на=1)
        сам.assertEqual((сам.снимок.read_bytes(), сам.фикстура.отчёт.read_bytes()), данные)


class ПроверкаЗамкаПриВозобновлении(unittest.TestCase):
    @staticmethod
    def это_удаление(путь, параметры, ожидаемый):
        fd = параметры.get('dir_fd')
        if fd is None or путь != ожидаемый.name:
            return False
        каталог, удерживаемый = ожидаемый.parent.stat(), os.fstat(fd)
        return (каталог.st_dev, каталог.st_ino) == (удерживаемый.st_dev, удерживаемый.st_ino)

    def подготовить(сам):
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов(_без_git=True)
        сам.addCleanup(фикстура.очистить)
        фикстура.записать_завершённую_запись(
            1, '00000000-0000-4000-8000-000000000021', 1000)
        корень = фикстура.корень.resolve()
        with mock.patch.object(модуль.tempfile, 'gettempdir', return_value=str(корень)):
            сам.assertEqual(модуль.выполнить_закрытие(корень, Path(путь_запроса)), 0)
        return модуль, фикстура, корень

    def возобновить(сам, модуль, корень, отказ_на=None):
        вызовы = []
        @contextlib.contextmanager
        def замок(*аргументы, срок_монотонный):
            сам.assertTrue(math.isfinite(срок_монотонный))
            def сверить():
                вызовы.append(True)
                if len(вызовы) == отказ_на:
                    raise модуль.ОшибкаОтчёта('подменён замок фикстуры')
            yield сверить
        with mock.patch.object(модуль, 'межпроцессная_блокировка', замок):
            модуль.выполнить_возобновление(корень, Path(путь_запроса))
        return вызовы

    def test_отказ_на_каждой_границе_сохраняет_фактическое_состояние(сам):
        for граница in range(1, 6):
            with сам.subTest(граница=граница):
                модуль, фикстура, корень = сам.подготовить()
                снимок = фикстура.каталог_записей / 'снимок.json'
                журнал = фикстура.каталог_записей / имя_журнала_возобновления
                закрытый_отчёт = фикстура.отчёт.read_bytes()
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'подменён замок'):
                    сам.возобновить(модуль, корень, отказ_на=(1, 3, 5, 12, 19)[граница - 1])
                сам.assertEqual(снимок.exists(), граница <= 3)
                сам.assertEqual(журнал.exists(), 2 <= граница <= 4)
                if граница <= 2:
                    сам.assertEqual(фикстура.отчёт.read_bytes(), закрытый_отчёт)
                else:
                    сам.assertIn(открытый_маркер.encode(), фикстура.отчёт.read_bytes())

    def test_успешное_возобновление_завершает_все_фазы(сам):
        модуль, фикстура, корень = сам.подготовить()
        снимок = фикстура.каталог_записей / 'снимок.json'
        журнал = фикстура.каталог_записей / имя_журнала_возобновления
        фазы = []

        @contextlib.contextmanager
        def замок(*аргументы, срок_монотонный):
            сам.assertTrue(math.isfinite(срок_монотонный))
            def сверить():
                открытый = открытый_маркер.encode() in фикстура.отчёт.read_bytes()
                состояние = (снимок.exists(), журнал.exists(), открытый)
                if not фазы or фазы[-1] != состояние:
                    фазы.append(состояние)
            yield сверить

        with mock.patch.object(модуль, 'межпроцессная_блокировка', замок):
            сам.assertEqual(модуль.выполнить_возобновление(корень, Path(путь_запроса)), 0)
        сам.assertEqual(фазы, [
            (True, False, False),  # Закрытый отчёт и снимок до журнала.
            (True, True, False),   # Журнал опубликован до открытия отчёта.
            (True, True, True),    # Открытый отчёт до удаления снимка.
            (False, True, True),   # Снимок удалён до удаления журнала.
            (False, False, True),  # Оба машинных файла удалены.
        ])
        сам.assertIn(открытый_маркер.encode(), фикстура.отчёт.read_bytes())
        сам.assertFalse(снимок.exists())
        сам.assertFalse(журнал.exists())

    def test_отказ_при_повторной_записи_открытого_отчёта(сам):
        модуль, фикстура, корень = сам.подготовить()
        with сам.assertRaises(модуль.ОшибкаОтчёта):
            сам.возобновить(модуль, корень, отказ_на=5)
        журнал = фикстура.каталог_записей / имя_журнала_возобновления
        до = (фикстура.отчёт.read_bytes(), журнал.read_bytes())
        with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'подменён замок'):
            сам.возобновить(модуль, корень, отказ_на=1)
        сам.assertEqual((фикстура.отчёт.read_bytes(), журнал.read_bytes()), до)

    def проверить_сбой_синхронизации(сам, *, отказ_замка):
        модуль, фикстура, корень = сам.подготовить()
        снимок = фикстура.каталог_записей / 'снимок.json'
        журнал = фикстура.каталог_записей / имя_журнала_возобновления
        реальный_unlink, реальная_синхронизация = os.unlink, os.fsync
        удаление = []
        данные_журнала = []

        def удалить(путь, *аргументы, **параметры):
            if сам.это_удаление(путь, параметры, журнал):
                данные_журнала.append(журнал.read_bytes())
                результат = реальный_unlink(путь, *аргументы, **параметры)
                удаление.append(True)
                return результат
            return реальный_unlink(путь, *аргументы, **параметры)

        def синхронизировать(fd):
            if удаление:
                удаление.clear()
                raise OSError('сбой fsync после удаления журнала')
            return реальная_синхронизация(fd)

        with mock.patch.object(модуль.os, 'unlink', side_effect=удалить), \
             mock.patch.object(модуль.os, 'fsync', side_effect=синхронизировать):
            if отказ_замка:
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'неизвестен исход') as исход:
                    сам.возобновить(модуль, корень, отказ_на=отказ_замка)
                причины = исход.exception.__cause__
                сам.assertIsInstance(причины, BaseExceptionGroup)
                сам.assertEqual(len(причины.exceptions), 2)
                сам.assertIsInstance(причины.exceptions[0], OSError)
                сам.assertIn('сбой fsync', str(причины.exceptions[0]))
                сам.assertIsInstance(причины.exceptions[1], модуль.ОшибкаОтчёта)
                сам.assertIn('подменён замок', str(причины.exceptions[1]))
            else:
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'сохранность не подтверждена') as исход:
                    сам.возобновить(модуль, корень)
                сам.assertIsInstance(исход.exception.__cause__, OSError)
        сам.assertEqual(len(данные_журнала), 1)
        сам.assertFalse(снимок.exists())
