    def test_восстановление_не_затирает_появившийся_журнал(сам):
        модуль, фикстура, корень = сам.подготовить()
        журнал = фикстура.каталог_записей / имя_журнала_возобновления
        реальный_unlink, синхронизация = os.unlink, os.fsync
        атомарно = модуль._атомарно_сохранить_байты
        удаление, после_ошибки, подмена = [], [], []
        чужие = b'external recovery journal'

        def удалить(путь, *аргументы, **параметры):
            целевой = сам.это_удаление(путь, параметры, журнал)
            результат = реальный_unlink(путь, *аргументы, **параметры)
            if целевой:
                удаление.append(True)
            return результат

        def fsync(fd):
            if удаление:
                удаление.clear()
                после_ошибки.append(True)
                raise OSError('сбой fsync после удаления журнала')
            return синхронизация(fd)

        def сохранить(путь, временный, байты, режим, **параметры):
            if после_ошибки and путь == журнал.resolve():
                прежний = параметры['перед_публикацией']
                def вмешательство():
                    путь.write_bytes(чужие)
                    подмена.append(True)
                    прежний()
                параметры['перед_публикацией'] = вмешательство
            return атомарно(путь, временный, байты, режим, **параметры)

        with mock.patch.object(модуль.os, 'unlink', side_effect=удалить), \
             mock.patch.object(модуль.os, 'fsync', side_effect=fsync), \
             mock.patch.object(модуль, '_атомарно_сохранить_байты', side_effect=сохранить):
            with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'неизвестен исход') as исход:
                сам.возобновить(модуль, корень)
        сам.assertEqual(подмена, [True])
        сам.assertEqual(журнал.read_bytes(), чужие)
        причины = исход.exception.__cause__
        сам.assertIsInstance(причины, BaseExceptionGroup)
        сам.assertIn('сбой fsync', str(причины.exceptions[0]))
        сам.assertIsInstance(причины.exceptions[1], модуль.ОшибкаОтчёта)

    def test_восстановление_сохраняет_ошибку_unlink_fsync_и_close(сам):
        модуль, фикстура, корень = сам.подготовить()
        журнал = фикстура.каталог_записей / имя_журнала_возобновления
        реальный_unlink, sync = os.unlink, os.fsync
        открыть, закрыть = os.open, os.close
        удаление, восстановление, вторичный_сбой = [], [], []
        fd_восстановления, временные, исходные, закрытия = [], [], [], []

        def удалить(путь, *аргументы, **параметры):
            if сам.это_удаление(путь, параметры, журнал):
                исходные.append(журнал.read_bytes())
                результат = реальный_unlink(путь, *аргументы, **параметры)
                удаление.append(True)
                return результат
            return реальный_unlink(путь, *аргументы, **параметры)

        def синхронизировать(fd):
            if удаление:
                удаление.clear()
                восстановление.append(True)
                raise OSError('fixture initial fsync')
            if восстановление and not вторичный_сбой and журнал.exists():
                вторичный_сбой.append(True)
                raise OSError('fixture recovery fsync')
            return sync(fd)

        def открыть_свой(*аргументы, **параметры):
            fd = открыть(*аргументы, **параметры)
            путь = аргументы[0]
            if (восстановление and isinstance(путь, str) and параметры.get('dir_fd') is not None
                and путь.startswith('.' + имя_журнала_возобновления + '.')):
                fd_восстановления.append(fd)
                временные.append(фикстура.каталог_записей / путь)
            return fd

        def закрыть_свой(fd):
            if fd in fd_восстановления and вторичный_сбой:
                закрытия.append(fd)
                закрыть(fd)
                raise OSError('fixture recovery close')
            return закрыть(fd)

        with mock.patch.object(модуль.os, 'unlink', side_effect=удалить), \
             mock.patch.object(модуль.os, 'fsync', side_effect=синхронизировать), \
             mock.patch.object(модуль.os, 'open', side_effect=открыть_свой), \
             mock.patch.object(модуль.os, 'close', side_effect=закрыть_свой):
            with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'неизвестен исход') as исход:
                сам.возобновить(модуль, корень)
        причины = исход.exception.__cause__
        сам.assertIsInstance(причины, ExceptionGroup)
        сам.assertIn('fixture initial fsync', str(причины.exceptions[0]))
        вторичные = причины.exceptions[1]
        сам.assertIsInstance(вторичные, ExceptionGroup)
        сам.assertIn('fixture recovery fsync', str(вторичные.exceptions[0]))
        сам.assertIsInstance(вторичные.exceptions[1], модуль.ОшибкаОтчёта)
        сам.assertEqual(закрытия, fd_восстановления)
        сам.assertEqual(len(временные), 1)
        сам.assertEqual(журнал.read_bytes(), исходные[0])
        сам.assertEqual(временные[0].read_bytes(), исходные[0])
        сам.assertEqual(журнал.stat().st_nlink, 2)

