    def test_прерывание_после_recovery_link_не_повторяется(сам):
        модуль, фикстура, корень = сам.подготовить()
        журнал = фикстура.каталог_записей / имя_журнала_возобновления
        unlink, fsync, link = os.unlink, os.fsync, os.link
        удаление, после_ошибки, попытки = [], [], []
        исходные = []

        def удалить(путь, *аргументы, **параметры):
            целевой = сам.это_удаление(путь, параметры, журнал)
            if целевой:
                исходные.append(журнал.read_bytes())
            результат = unlink(путь, *аргументы, **параметры)
            if целевой:
                удаление.append(True)
            return результат

        def синхронизировать(fd):
            if удаление:
                удаление.clear()
                после_ошибки.append(True)
                raise OSError('fixture fsync before recovery')
            return fsync(fd)

        def связать(*аргументы, **параметры):
            результат = link(*аргументы, **параметры)
            if после_ошибки and параметры.get('dst_dir_fd') is not None:
                попытки.append(True)
                raise KeyboardInterrupt('fixture cancellation after link')
            return результат

        with mock.patch.object(модуль.os, 'unlink', side_effect=удалить), \
             mock.patch.object(модуль.os, 'fsync', side_effect=синхронизировать), \
             mock.patch.object(модуль.os, 'link', side_effect=связать):
            with сам.assertRaises(KeyboardInterrupt) as исход:
                сам.возобновить(модуль, корень)
        сам.assertIsInstance(исход.exception.__context__, OSError)
        сам.assertIn('fixture fsync before recovery', str(исход.exception.__context__))
        сам.assertEqual(попытки, [True])
        сам.assertEqual(журнал.read_bytes(), исходные[0])
        сам.assertEqual(журнал.stat().st_nlink, 2)
        временные = list(фикстура.каталог_записей.glob('.' + имя_журнала_возобновления + '.*.tmp'))
        сам.assertEqual(len(временные), 1)
        сам.assertEqual(временные[0].read_bytes(), исходные[0])

    def test_реальная_подмена_inode_до_журнала(сам):
        модуль, фикстура, корень = сам.подготовить()
        снимок = фикстура.каталог_записей / 'снимок.json'
        журнал = фикстура.каталог_записей / имя_журнала_возобновления
        до = (снимок.read_bytes(), фикстура.отчёт.read_bytes())
        ключ = hashlib.sha256(f'{корень}\0{путь_запроса}'.encode()).hexdigest()
        путь_замка = корень / f'fum-check-runs-{ключ}.lock'
        новый_замок = корень / 'replacement.lock'
        атомарно = модуль._атомарно_сохранить_байты
        подмена = []

        def перехват(путь, временный, байты, режим, **параметры):
            if путь == журнал.resolve():
                сверить = параметры['перед_публикацией']
                def заменить_перед_сверкой():
                    fd = os.open(новый_замок, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                    os.close(fd)
                    os.replace(новый_замок, путь_замка)
                    подмена.append(True)
                    сверить()
                параметры['перед_публикацией'] = заменить_перед_сверкой
            return атомарно(путь, временный, байты, режим, **параметры)

        with mock.patch.object(модуль.tempfile, 'gettempdir', return_value=str(корень)), \
             mock.patch.object(модуль, '_атомарно_сохранить_байты', side_effect=перехват):
            with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'небезопасный файл межпроцессной блокировки|подменён файл межпроцессной блокировки'):
                модуль.выполнить_возобновление(корень, Path(путь_запроса))
        сам.assertEqual(подмена, [True])
        сам.assertFalse(журнал.exists())
        сам.assertEqual((снимок.read_bytes(), фикстура.отчёт.read_bytes()), до)

