class ПроверкаЧужогоИзмененияОтчёта(unittest.TestCase):
    удерживаемые_фикстуры = []

    def setUp(сам):
        сам.модуль = загрузить_модуль_автоматизации()
        сам.фикстура = ФикстураОтчётов(_без_git=True)
        сам.удерживаемые_фикстуры.append((сам.фикстура, сам.модуль))
        сам.фикстура.записать_завершённую_запись(
            1, '00000000-0000-4000-8000-000000000021', 1000)
        сам.корень = сам.фикстура.корень.resolve()
        сам.снимок = сам.фикстура.каталог_записей / 'снимок.json'
        сам.журнал = сам.фикстура.каталог_записей / имя_журнала_возобновления

    @contextlib.contextmanager
    def замок(сам, *аргументы, срок_монотонный):
        сам.assertTrue(math.isfinite(срок_монотонный))
        yield lambda: None

    def закрыть(сам):
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', сам.замок):
            return сам.модуль.выполнить_закрытие(сам.корень, Path(путь_запроса))

    def вмешаться_перед_публикацией(сам, операция, *, замена_inode=False):
        атомарно = сам.модуль._атомарно_сохранить_байты
        вызов_владельца = сам.модуль._ВладелецЗаменыПредпросмотра._вызвать
        фактические = []

        def вмешательство():
            путь = сам.фикстура.отчёт
            исходные = путь.read_bytes()
            if замена_inode:
                внешние = исходные
                замена = путь.with_name('external-replacement')
                замена.write_bytes(внешние)
                os.replace(замена, путь)
            else:
                внешние = исходные + b'\nexternal edit\n'
                путь.write_bytes(внешние)
            фактические.append(внешние)

        def перехват(путь, временный, байты, режим, **параметры):
            if путь == сам.фикстура.отчёт.resolve():
                прежний = параметры['перед_публикацией']
                def проверить_после_вмешательства():
                    вмешательство()
                    прежний()
                параметры['перед_публикацией'] = проверить_после_вмешательства
            return атомарно(путь, временный, байты, режим, **параметры)

        def перехват_владельца(владелец, имя, действие, *аргументы, **ключи):
            if имя == 'повторная проверка предпросмотра' and владелец.действие_подтверждено:
                вмешательство()
            return вызов_владельца(владелец, имя, действие, *аргументы, **ключи)

        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', сам.замок), \
             mock.patch.object(сам.модуль, '_атомарно_сохранить_байты', side_effect=перехват), \
             mock.patch.object(сам.модуль._ВладелецЗаменыПредпросмотра, '_вызвать', перехват_владельца):
            ошибка = None
            try:
                операция(сам.корень, Path(путь_запроса))
            except сам.модуль.ОшибкаОтчёта as сбой:
                ошибка = сбой
        сам.assertEqual(len(фактические), 1)
        сам.assertEqual(сам.фикстура.отчёт.read_bytes(), фактические[0])
        сам.assertIsNotNone(ошибка)

    def test_закрытие_не_затирает_чужую_правку(сам):
        сам.вмешаться_перед_публикацией(сам.модуль.выполнить_закрытие)
        сам.assertTrue(сам.снимок.exists())

    def test_замена_inode_с_прежними_байтами_останавливает_закрытие(сам):
        сам.вмешаться_перед_публикацией(сам.модуль.выполнить_закрытие, замена_inode=True)
        сам.assertTrue(сам.снимок.exists())

    def test_открытие_не_затирает_чужую_правку(сам):
        сам.закрыть()
        сам.вмешаться_перед_публикацией(сам.модуль.выполнить_возобновление)
        сам.assertTrue(сам.снимок.exists())
        сам.assertTrue(сам.журнал.exists())

    def test_повторное_открытие_не_затирает_чужую_правку(сам):
        сам.закрыть()
        unlink = os.unlink
        def запретить_снимок(путь, *аргументы, **параметры):
            if ПроверкаЗамкаПриВозобновлении.это_удаление(путь, параметры, сам.снимок):
                raise OSError('fixture stop before snapshot unlink')
            return unlink(путь, *аргументы, **параметры)
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', сам.замок), \
             mock.patch.object(сам.модуль.os, 'unlink', side_effect=запретить_снимок):
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам.модуль.выполнить_возобновление(сам.корень, Path(путь_запроса))
        сам.assertTrue(сам.снимок.exists())
        сам.assertTrue(сам.журнал.exists())
        сам.вмешаться_перед_публикацией(сам.модуль.выполнить_возобновление)
        сам.assertTrue(сам.снимок.exists())
        сам.assertTrue(сам.журнал.exists())

    def test_создание_журнала_не_перезаписывает_появившийся_файл(сам):
        сам.закрыть()
        атомарно = сам.модуль._атомарно_сохранить_байты
        чужие = b'external journal'
        попытки = []
        def перехват(путь, временный, байты, режим, **параметры):
            if путь == сам.журнал.resolve():
                прежний = параметры['перед_публикацией']
                def вмешательство():
                    путь.write_bytes(чужие)
                    попытки.append(True)
                    прежний()
                параметры['перед_публикацией'] = вмешательство
            return атомарно(путь, временный, байты, режим, **параметры)
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', сам.замок), \
             mock.patch.object(сам.модуль, '_атомарно_сохранить_байты', side_effect=перехват):
            ошибка = None
            try:
                сам.модуль.выполнить_возобновление(сам.корень, Path(путь_запроса))
            except сам.модуль.ОшибкаОтчёта as сбой:
                ошибка = сбой
        сам.assertEqual(попытки, [True])
        сам.assertTrue(сам.журнал.exists())
        сам.assertEqual(сам.журнал.read_bytes(), чужие)
        сам.assertIsNotNone(ошибка)

    def вмешаться_перед_удалением(сам, цель):
        сам.закрыть()
        фабрика = сам.модуль._проверка_отчёта_под_замком
        чужие = b'external file before unlink'
        вмешательства = []

        def подготовить(*аргументы):
            проверка = фабрика(*аргументы)
            def проверить():
                проверка()
                открыт = открытый_маркер.encode() in сам.фикстура.отчёт.read_bytes()
                подходящий_этап = (сам.снимок.exists() if цель == сам.снимок
                                   else not сам.снимок.exists())
                if открыт and подходящий_этап and сам.журнал.exists() and not вмешательства:
                    цель.write_bytes(чужие)
                    вмешательства.append(True)
            return проверить

        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', сам.замок), \
             mock.patch.object(сам.модуль, '_проверка_отчёта_под_замком', side_effect=подготовить):
            ошибка = None
            try:
                сам.модуль.выполнить_возобновление(сам.корень, Path(путь_запроса))
            except сам.модуль.ОшибкаОтчёта as сбой:
                ошибка = сбой
        сам.assertEqual(вмешательства, [True])
        сам.assertTrue(цель.exists())
        сам.assertEqual(цель.read_bytes(), чужие)
        сам.assertIsNotNone(ошибка)

    def test_подменённый_снимок_не_удаляется(сам):
        сам.вмешаться_перед_удалением(сам.снимок)

    def test_подменённый_журнал_не_удаляется(сам):
        сам.вмешаться_перед_удалением(сам.журнал)

    def вмешаться_после_закрепления_файла(сам, цель):
        сам.закрыть()
        удержать = сам.модуль._удержать_файл_перед_удалением
        чужие = []
        @contextlib.contextmanager
        def перехват(путь, *аргументы, **параметры):
            with удержать(путь, *аргументы, **параметры) as fd:
                if путь.name == цель.name:
                    данные = сам.фикстура.отчёт.read_bytes() + b'\nexternal after pin\n'
                    сам.фикстура.отчёт.write_bytes(данные)
                    чужие.append(данные)
                yield fd
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', сам.замок), \
             mock.patch.object(сам.модуль, '_удержать_файл_перед_удалением', side_effect=перехват):
            with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                сам.модуль.выполнить_возобновление(сам.корень, Path(путь_запроса))
        сам.assertEqual(len(чужие), 1)
        сам.assertEqual(сам.фикстура.отчёт.read_bytes(), чужие[0])
        сам.assertTrue(цель.exists())

    def test_правка_отчёта_после_pin_сохраняет_снимок(сам):
        сам.вмешаться_после_закрепления_файла(сам.снимок)

    def test_правка_отчёта_после_pin_сохраняет_журнал(сам):
        сам.вмешаться_после_закрепления_файла(сам.журнал)

    def изменить_закреплённый_файл_во_время_сверки_отчёта(сам, цель):
        сам.закрыть()
        фабрика = сам.модуль._проверка_отчёта_под_замком
        этапы, вмешательства = [], []
