    def test_изменение_закреплённого_журнала_не_удаляется(сам):
        сам.изменить_закреплённый_файл_во_время_сверки_отчёта(сам.журнал)

    def test_снимок_появился_во_время_удаления_журнала(сам):
        сам.закрыть()
        unlink = os.unlink
        чужие = b'external snapshot after journal unlink'
        вмешательства = []
        def удалить(путь, *аргументы, **параметры):
            целевой = ПроверкаЗамкаПриВозобновлении.это_удаление(путь, параметры, сам.журнал)
            результат = unlink(путь, *аргументы, **параметры)
            if целевой:
                сам.снимок.write_bytes(чужие)
                вмешательства.append(True)
            return результат
        with mock.patch.object(сам.модуль, 'межпроцессная_блокировка', сам.замок), \
             mock.patch.object(сам.модуль.os, 'unlink', side_effect=удалить):
            with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'снимок появился'):
                сам.модуль.выполнить_возобновление(сам.корень, Path(путь_запроса))
