    def test_владелец_сам_открывает_сверяет_и_закрывает_пару(сам):
        м, _, _, _, _, имя, пара = сам.подготовить_владельца_пары()
        настоящий_open = м.os.open
        открытия = []
        def открыть(путь, флаги, *args, **kwargs):
            if путь == имя:
                открытия.append((флаги, kwargs.get('dir_fd')))
            return настоящий_open(путь, флаги, *args, **kwargs)
        сам.фаза_pin = 'открытие владельца начато'
        with mock.patch.object(м.os, 'open', side_effect=открыть), \
             mock.patch.object(м.fcntl, 'flock') as flock:
            сам.владелец_пары.подготовить()
            сам.assertEqual(сам.владелец_пары.состояние, 'подготовлен')
            сам.assertEqual(len(сам.владелец_пары._fd), 2)
            сам.владелец_пары.сверить()
            with сам.assertRaises(м.ОшибкаОтчёта): сам.владелец_пары.подготовить()
            сам.фаза_pin = 'закрытие владельца начато'
            сам.владелец_пары.закрыть()
            сам.assertEqual(сам.владелец_пары.состояние, 'закрыт')
            with сам.assertRaises(м.ОшибкаОтчёта): сам.владелец_пары.закрыть()
            flock.assert_not_called()
        сам.assertEqual([fd for _, fd in открытия], [пара[2], пара[6]])
        for флаги, _ in открытия:
            сам.assertFalse(флаги & (os.O_CREAT | os.O_EXCL))
            сам.assertTrue(флаги & os.O_NOFOLLOW)
            сам.assertTrue(флаги & os.O_CLOEXEC)
        сам.assertFalse(сам.владелец_пары._fd)
        сам.завершить(м)

