    def _проверить_срок_занятой_пары(сам, номер):
        import select
        сам.assertIn(номер, (0, 1))
        м, корень, _, старый_каталог, новый_каталог, имя, _ = сам.подготовить_владельца_пары()
        владелец = сам.владелец_пары
        владелец.подготовить()
        сам.удерживаемые_конкуренты.append({'фикстура': сам, 'владелец': владелец})
        программа = ('import fcntl,os,sys\n'
                     'fd=os.open(sys.argv[1],os.O_RDWR|os.O_NOFOLLOW|os.O_CLOEXEC)\n'
                     'fcntl.flock(fd,fcntl.LOCK_EX)\n'
                     'os.write(1,b"R")\n'
                     'assert os.read(0,1)==b"Q"\n'
                     'fcntl.flock(fd,fcntl.LOCK_UN)\n'
                     'os.close(fd)\n')
        конкурент = subprocess.Popen(
            (sys.executable, '-I', '-S', '-B', '-c', программа,
             str((старый_каталог, новый_каталог)[номер] / имя)),
            cwd=корень, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'},
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            start_new_session=True, close_fds=True)
        сам.удерживаемые_конкуренты[-1]['конкурент'] = конкурент
        сам.assertTrue(select.select([конкурент.stdout.fileno()], [], [], 3.0)[0])
        сам.assertEqual(os.read(конкурент.stdout.fileno(), 1), b'R')
        начало = time.monotonic()
        срок_захвата = начало + 0.20
        try:
            with сам.assertRaises(м.ОшибкаОтчёта):
                with владелец.удержать(срок_захвата=срок_захвата):
                    сам.fail('занятую пару нельзя захватить')
            длительность = time.monotonic() - начало
            сам.assertGreaterEqual(длительность, 0.15)
            сам.assertLess(длительность, 2.0)
            if номер == 1:
                проба = os.open(старый_каталог / имя, os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC)
                try:
                    м.fcntl.flock(проба, м.fcntl.LOCK_EX | м.fcntl.LOCK_NB)
                    м.fcntl.flock(проба, м.fcntl.LOCK_UN)
                finally:
                    os.close(проба)
        finally:
            сам.assertEqual(os.write(конкурент.stdin.fileno(), b'Q'), 1)
            сам.assertEqual(конкурент.wait(timeout=3), 0)
        сам.assertEqual(владелец.состояние, 'неизвестно')

