        исходная_сверка = м._тестово_сверить_пару_закреплённых_замков
        @contextlib.contextmanager
        def задержанная_сверка(*args, **kwargs):
            with исходная_сверка(*args, **kwargs) as сверить:
                def проверить():
                    time.sleep(0.20)
                    сверить()
                yield проверить
        срок_захвата = time.monotonic() + 0.10
        with mock.patch.object(м, '_тестово_сверить_пару_закреплённых_замков',
                               side_effect=задержанная_сверка), \
             mock.patch.object(владелец, '_flock_один',
                               side_effect=AssertionError('flock после срока')) as flock:
            with сам.assertRaises(м.ОшибкаОтчёта):
                with владелец.удержать(срок_захвата=срок_захвата):
                    сам.fail('истёкший срок не разрешает захват')
            flock.assert_not_called()

