    def test_владелец_удерживает_оба_flock_и_освобождает_обратно(сам):
        import fcntl
        м, _, _, _, _, имя, пара = сам.подготовить_владельца_пары()
        владелец = сам.владелец_пары
        владелец.подготовить()
        операции = []
        настоящий_flock = м.fcntl.flock
        def flock(fd, op):
            if fd in владелец._fd: операции.append((владелец._fd.index(fd), op))
            сам.фаза_pin = ('flock начат', fd, op)
            итог = настоящий_flock(fd, op)
            сам.фаза_pin = ('flock завершён', fd, op)
            return итог
        сам.фаза_pin = 'двойной захват начат'
        with mock.patch.object(м.fcntl, 'flock', side_effect=flock):
            with владелец.удержать() as сверить:
                сверить()
                сам.assertEqual(владелец._взяты, [0, 1])
                сам.assertIn(владелец._маркер, м._тестовые_активные_замки)
                for каталог_fd in (пара[2], пара[6]):
                    проба = м._приобрести_fd(сам.fd_pin, os.open, имя,
                                os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=каталог_fd)
                    with сам.assertRaises(BlockingIOError):
                        flock(проба, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    сам.попытка_закрытия_pin = проба
                    м._отпустить_зарегистрированный_fd(сам.fd_pin, проба)
                    сам.попытка_закрытия_pin = None
            сам.assertEqual(владелец.состояние, 'подготовлен')
            сам.assertFalse(владелец._взяты)
            сам.assertNotIn(владелец._маркер, м._тестовые_активные_замки)
            for каталог_fd in (пара[2], пара[6]):
                проба = м._приобрести_fd(сам.fd_pin, os.open, имя,
                            os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=каталог_fd)
                flock(проба, fcntl.LOCK_EX | fcntl.LOCK_NB)
                flock(проба, fcntl.LOCK_UN)
                сам.попытка_закрытия_pin = проба
                м._отпустить_зарегистрированный_fd(сам.fd_pin, проба)
                сам.попытка_закрытия_pin = None
        сам.assertEqual(операции, [(0, fcntl.LOCK_EX | fcntl.LOCK_NB),
                                    (1, fcntl.LOCK_EX | fcntl.LOCK_NB),
                                    (1, fcntl.LOCK_UN), (0, fcntl.LOCK_UN)])
        сам.фаза_pin = 'закрытие владельца пары начато'
        владелец.закрыть()
        сам.завершить(м)

    def test_фабрика_заимствует_удержанную_пару_для_записи(сам):
        import threading
        м, корень, сессия, _, _, _, пара = сам.подготовить_владельца_пары()
        владелец = сам.владелец_пары
        владелец.подготовить()
        контракт = ('fum.test-lock-bridge.1', пара[1], пара[2], пара[5], пара[6])
        def выбрать(корень_запроса=корень, контракт_запроса=контракт):
            return м._тестово_выбрать_замок_сессии(
                корень_запроса, сессия, срок_монотонный=владелец._срок,
                контракт=контракт_запроса, _тестовый_владелец_пары=владелец)
        with сам.assertRaises(м.ОшибкаОтчёта):
            with выбрать(): pass
        путь = корень / 'состояние.json'
        with владелец.удержать() as внешний:
            отложенное_заимствование = выбрать()
            with mock.patch.object(м.fcntl, 'flock', side_effect=AssertionError('повторный flock')):
                with выбрать() as проверить:
                    проверить()
                    сам.assertEqual(владелец._взяты, [0, 1])
                    with сам.assertRaises(м.ОшибкаОтчёта):
                        with м._тестовый_допуск_git(): pass
                    м.атомарно_записать_байты(
                        путь, b'active', только_новый=True, перед_публикацией=проверить)
                    м.атомарно_записать_байты(путь, b'terminal', перед_публикацией=проверить)
                    сам.assertEqual(путь.read_bytes(), b'terminal')
                    чужой_контракт = ('fum.test-lock-bridge.1', пара[5], пара[6], пара[1], пара[2])
                    with сам.assertRaises(м.ОшибкаОтчёта):
                        with выбрать(контракт_запроса=чужой_контракт): pass
                    ошибки = []
                    def чужой_поток():
                        try:
                            with выбрать(): pass
                        except BaseException as ошибка:
                            ошибки.append(ошибка)
                    поток = threading.Thread(target=чужой_поток)
                    поток.start(); поток.join(timeout=2.0)
                    сам.assertFalse(поток.is_alive())
                    сам.assertEqual(len(ошибки), 1)
                    сам.assertIsInstance(ошибки[0], м.ОшибкаОтчёта)
                with сам.assertRaises(м.ОшибкаОтчёта): проверить()
                устаревшая_проверка = проверить
                for срок in (time.monotonic() - 1.0, владелец._срок + 1.0):
                    with сам.assertRaises(м.ОшибкаОтчёта):
                        with м._тестово_выбрать_замок_сессии(
                                корень, сессия, срок_монотонный=срок,
                                контракт=контракт, _тестовый_владелец_пары=владелец): pass
                исходная_проверка = владелец._проверка_удержания
                вызовы_проверки = []
                первый_отказ = м.ОшибкаОтчёта('неизвестен исход проверки')
                def сбойная_проверка():
                    вызовы_проверки.append(True)
                    if len(вызовы_проверки) == 3:
                        raise первый_отказ
                    if len(вызовы_проверки) > 3:
                        raise AssertionError('повтор после неизвестного исхода')
                    исходная_проверка()
                владелец._проверка_удержания = сбойная_проверка
                try:
                    with сам.assertRaises(м.ОшибкаОтчёта) as ошибка_после_тела:
                        with выбрать() as проверить_сбой:
                            with сам.assertRaises(м.ОшибкаОтчёта):
                                проверить_сбой()
                    сам.assertIs(ошибка_после_тела.exception, первый_отказ)
                    сам.assertEqual(len(вызовы_проверки), 3)
                finally:
                    владелец._проверка_удержания = исходная_проверка
                with сам.assertRaises(BaseExceptionGroup) as ошибки_выхода:
                    with mock.patch.object(
                            м, '_остаток_срока_блокировки',
                            wraps=м._остаток_срока_блокировки) as часы:
                        with выбрать():
                            часы.side_effect = м.ОшибкаОтчёта('срок при выходе')
                            raise ValueError('ошибка записи')
                сам.assertEqual(tuple(type(ошибка) for ошибка in ошибки_выхода.exception.exceptions),
                                (ValueError, м.ОшибкаОтчёта))
                внешний()
        with сам.assertRaises(м.ОшибкаОтчёта):
            with выбрать(): pass
        with владелец.удержать():
            with сам.assertRaises(м.ОшибкаОтчёта):
                with отложенное_заимствование: pass
            with выбрать() as проверить_новое:
                проверить_новое()
                with сам.assertRaises(м.ОшибкаОтчёта): устаревшая_проверка()
        владелец.закрыть()
        сам.завершить(м)

    def test_неизвестная_сверка_пары_не_повторяется_и_не_разблокирует(сам):
        """Запускать в отдельном процессе: UNKNOWN намеренно остаётся удержанным."""
        м, _, _, _, _, _, _ = сам.подготовить_владельца_пары()
        владелец = сам.владелец_пары
        владелец.подготовить()
        удержание = {'фикстура': сам, 'владелец': владелец}
        сам.удерживаемые_конкуренты.append(удержание)
        настоящий_flock = м.fcntl.flock
        with mock.patch.object(м.fcntl, 'flock', wraps=настоящий_flock) as операции:
            with сам.assertRaises(м.ОшибкаОтчёта) as ошибка_выхода:
                with владелец.удержать() as проверить:
                    with mock.patch.object(м.os, 'open', side_effect=OSError('неизвестно открытие')):
                        with сам.assertRaises(м.ОшибкаОтчёта) as исходная:
                            проверить()
                    with mock.patch.object(м.os, 'open', side_effect=AssertionError('повторное I/O')) as открытие:
                        with сам.assertRaises(м.ОшибкаОтчёта) as повтор:
                            проверить()
                        открытие.assert_not_called()
                    сам.assertIs(повтор.exception, исходная.exception)
            сам.assertIs(ошибка_выхода.exception, исходная.exception)
            сам.assertEqual([в.args[1] for в in операции.call_args_list],
                            [м.fcntl.LOCK_EX | м.fcntl.LOCK_NB] * 2)
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual(владелец._взяты, [0, 1])
        сам.assertIn(владелец, м._тестовые_активные_замки)
        сам.assertEqual(len(владелец._fd), 2)
        for fd in владелец._fd:
            os.fstat(fd)
        with сам.assertRaises(м.ОшибкаОтчёта):
            владелец.закрыть()

    def test_неизвестный_участок_сохраняет_внутренние_fd_без_повторного_io(сам):
        """Отдельный процесс: фикстура намеренно остаётся под замками."""
        м, _, _, _, _, _, _ = сам.подготовить_владельца_пары()
        владелец = сам.владелец_пары
        владелец.подготовить()
        сам.удерживаемые_конкуренты.append({'фикстура': сам, 'владелец': владелец})
        неизвестно = [False]
        поздние_операции = []
        открыть, закрыть, flock = os.open, os.close, м.fcntl.flock
        def открыть_под_наблюдением(*аргументы, **параметры):
            if неизвестно[0]:
                поздние_операции.append('open')
                raise AssertionError('open после UNKNOWN')
            return открыть(*аргументы, **параметры)
        def закрыть_под_наблюдением(fd):
            if неизвестно[0]:
                поздние_операции.append('close')
                return None
            return закрыть(fd)
        def flock_под_наблюдением(*аргументы):
            if неизвестно[0]:
                поздние_операции.append('flock')
                raise AssertionError('flock после UNKNOWN')
            return flock(*аргументы)
        исходная = ValueError('модельный отказ участка после active')
        with mock.patch.object(м.os, 'open', side_effect=открыть_под_наблюдением), \
             mock.patch.object(м.os, 'close', side_effect=закрыть_под_наблюдением), \
             mock.patch.object(м.fcntl, 'flock', side_effect=flock_под_наблюдением):
            with сам.assertRaises((ValueError, BaseExceptionGroup)) as итог:
                with владелец.удержать():
                    маркеры = tuple(м._тестовые_владельцы_замков)
                    сам.assertEqual(len(маркеры), 2)
                    дескрипторы = tuple(fd for маркер in маркеры for fd in маркер.дескрипторы)
                    сам.assertTrue(дескрипторы)
                    владелец.попытка = ('active без безопасного выхода', исходная)
                    владелец._состояние = 'неизвестно'
                    неизвестно[0] = True
                    raise исходная
        очередь = [итог.exception]
        while очередь and all(ошибка is not исходная for ошибка in очередь):
            ошибка = очередь.pop()
            if isinstance(ошибка, BaseExceptionGroup):
                очередь.extend(ошибка.exceptions)
        сам.assertIn(исходная, очередь)
        сам.assertEqual(поздние_операции, [])
        сам.assertTrue(all(маркер in м._тестовые_владельцы_замков for маркер in маркеры))
        сам.assertTrue(all(маркер.группа.неизвестно for маркер in маркеры))
        for fd in дескрипторы:
            os.fstat(fd)
        сам.assertEqual(владелец._взяты, [0, 1])
        сам.assertIn(владелец, м._тестовые_активные_замки)

    def test_перехваченный_unknown_пары_не_даёт_сверить_или_освободить_fd(сам):
        """Отдельный процесс: после UNKNOWN фикстура сохраняет владение."""
        м, _, _, _, _, _, _ = сам.подготовить_владельца_пары()
        владелец = сам.владелец_пары
        владелец.подготовить()
        сам.удерживаемые_конкуренты.append({'фикстура': сам, 'владелец': владелец})
        неизвестно = [False]
        поздние_операции = []
        def наблюдать(имя, операция):
            def вызвать(*аргументы, **параметры):
                if неизвестно[0]:
                    поздние_операции.append(имя)
                    raise AssertionError(f'{имя} после UNKNOWN')
                return операция(*аргументы, **параметры)
            return вызвать
        исходная = ValueError('модельный неизвестный исход владельца')
        прямые = []
        выход = None
        with mock.patch.object(м.os, 'open', side_effect=наблюдать('open', os.open)), \
             mock.patch.object(м.os, 'fstat', side_effect=наблюдать('fstat', os.fstat)), \
             mock.patch.object(м.os, 'close', side_effect=наблюдать('close', os.close)), \
             mock.patch.object(м.fcntl, 'flock', side_effect=наблюдать('flock', м.fcntl.flock)):
            try:
                with владелец.удержать() as сверить:
                    маркеры = tuple(м._тестовые_владельцы_замков)
                    сам.assertEqual(len(маркеры), 2)
                    владелец.ошибка = исходная
                    владелец.попытка = ('исход владельца неизвестен', исходная)
                    владелец._состояние = 'неизвестно'
                    неизвестно[0] = True
                    try:
                        сверить()
                    except BaseException as ошибка:
                        прямые.append(ошибка)
            except BaseException as ошибка:
                выход = ошибка
        сам.assertEqual(поздние_операции, [])
        сам.assertEqual(len(прямые), 1)
        сам.assertIsInstance(прямые[0], м.ОшибкаОтчёта)
        сам.assertIs(прямые[0].__cause__, исходная)
        сам.assertIs(выход, прямые[0])
        сам.assertTrue(all(маркер in м._тестовые_владельцы_замков for маркер in маркеры))
        сам.assertTrue(all(маркер.группа.неизвестно for маркер in маркеры))
        сам.assertEqual(владелец._взяты, [0, 1])
        сам.assertIn(владелец, м._тестовые_активные_замки)

