    def test_владелец_сохраняет_fd_при_модельном_отказе_второго_open(сам):
        м, _, _, _, _, имя, пара = сам.подготовить_владельца_пары()
        настоящий_open = м.os.open
        отказы = []
        def открыть(путь, флаги, *args, **kwargs):
            if путь == имя and kwargs.get('dir_fd') == пара[6]:
                отказы.append('второй open не вызывался')
                raise OSError('модельный отказ до системного open')
            return настоящий_open(путь, флаги, *args, **kwargs)
        сам.фаза_pin = 'модельный отказ второго open'
        with mock.patch.object(м.os, 'open', side_effect=открыть):
            with сам.assertRaisesRegex(OSError, 'модельный отказ'):
                сам.владелец_пары.подготовить()
            сам.assertEqual(сам.владелец_пары.состояние, 'неизвестно')
            сам.assertEqual(сам.владелец_пары.попытка, ('open', 1))
            сам.assertEqual(len(сам.владелец_пары._fd), 1)
            with сам.assertRaises(м.ОшибкаОтчёта): сам.владелец_пары.подготовить()
            with сам.assertRaises(м.ОшибкаОтчёта): сам.владелец_пары.закрыть()
        сам.assertEqual(отказы, ['второй open не вызывался'])
        # Отказ инжектирован до реального второго open; первый FD известен фикстуре.
        сам.фаза_pin = 'закрытие известного fixture FD после модельного отказа'
        fd = сам.владелец_пары._fd[-1]
        сам.попытка_закрытия_pin = fd
        м._отпустить_зарегистрированный_fd(сам.владелец_пары._fd, fd)
        сам.попытка_закрытия_pin = None
        сам.завершить(м)

