    def test_pin_совпадает_с_именем_и_не_удерживает_flock_после_выхода(сам):
        import fcntl
        м, корень, каталог, сессия, dirfd, селектор, имя, pin = сам.подготовить()
        срок = time.monotonic() + 10.0
        сам.фаза_pin = 'первый захват начат'
        with м._тестовый_замок_новой_сессии(селектор, dirfd, корень, сессия,
                                            срок_монотонный=срок, _закреплённый_файл=pin) as сверить:
            сверить()
            проба = м._приобрести_fd(сам.fd_pin, os.open, имя,
                                      os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
            сам.фаза_pin = ('занятая проба начата', проба)
            with сам.assertRaises(BlockingIOError): fcntl.flock(проба, fcntl.LOCK_EX | fcntl.LOCK_NB)
            сам.фаза_pin = ('занятая проба подтверждена', проба)
            сам.попытка_закрытия_pin = проба
            м._отпустить_зарегистрированный_fd(сам.fd_pin, проба)
            сам.попытка_закрытия_pin = None
            сверить()
        сам.фаза_pin = 'повторная проба начата'
        проба = м._приобрести_fd(сам.fd_pin, os.open, имя,
                                  os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=dirfd)
        сам.фаза_pin = ('свободная проба начата', проба)
        fcntl.flock(проба, fcntl.LOCK_EX | fcntl.LOCK_NB)
        сам.фаза_pin = ('освобождение пробы начато', проба)
        fcntl.flock(проба, fcntl.LOCK_UN)
        сам.попытка_закрытия_pin = проба
        м._отпустить_зарегистрированный_fd(сам.fd_pin, проба)
        сам.попытка_закрытия_pin = None
        сам.assertEqual(os.fstat(pin[1]).st_ino, pin[3])
        сам.завершить(м)

