    def test_опытные_схемы_не_становятся_обычным_непрофилированным_запуском(сам):
        м = загрузить_модуль_автоматизации()
        for схема in (м._ТЕСТОВАЯ_СХЕМА_ЗАПУСКА_С_НОВЫМ_СНИМКОМ,
                      м._ТЕСТОВАЯ_СХЕМА_ЗАПУСКА_С_УДЕРЖАНИЕМ, 'fum.test-run.future', None):
            запись = {'схема': схема, 'порядок': 1, 'профиль_проверки': {'класс': 'адресная'}}
            with сам.subTest(схема=схема):
                with сам.assertRaises(м.ОшибкаОтчёта):
                    м.профиль_записи(запись)
                сам.assertTrue(м.история_схем_несовместима([запись]))
        for схема in (м.СХЕМА_ЗАПУСКА, м.СХЕМА_ЗАПУСКА_С_НАБЛЮДЕНИЯМИ,
                      м.СХЕМА_ЗАПУСКА_С_РАУНДАМИ):
            сам.assertIsNone(м.профиль_записи({'схема': схема}))
        профиль = {'класс': 'адресная'}
        сам.assertIs(м.профиль_записи({'схема': м.СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА,
                                       'профиль_проверки': профиль}), профиль)
        сам.assertFalse(м.история_схем_несовместима([]))

    def test_план_предпросмотра_сохраняет_границы_и_фактический_статус(сам):
        import importlib
        скрипты = Path(__file__).resolve().parents[2] / 'fum-reyestr-planirovaniya' / 'scripts'
        sys.path.insert(0, str(скрипты))
        try:
            доставка = importlib.import_module('доставка_отчёта')
        finally:
            sys.path.remove(str(скрипты))
        м = доставка.отчёты
        сессия = 'Журнал/этап/запрос.md'
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        отчёт = 'Журнал/этап/отчёт.md'
        исходный = ('Начало\n' + открытый_маркер + '\nстарый блок\n' + конечный_маркер + '\nКонец\n').encode()
        сведения = {'режим': 0o100644, 'sha256': hashlib.sha256(исходный).hexdigest()}
        граница = {'схема': 'fum.test-delivery-boundary.2', 'запрос': сессия, 'прежние': [],
                   'запуск': идентификатор, 'отчёт': отчёт, 'файлы': {отчёт: сведения},
                   'разница': None, 'исходный_отчёт': исходный}
        запись = {'схема': м._ТЕСТОВАЯ_СХЕМА_ЗАПУСКА_С_УДЕРЖАНИЕМ,
            'идентификатор': идентификатор, 'сессия': сессия, 'порядок': 1,
            'исполнитель': 'root', 'вызов': 'a | b', 'состояние': 'завершён',
            'длительность_наносекунды': 1000000, 'статус': 'неуспешно', 'код_завершения': 1,
            'пояснение': None, 'план': None, 'наблюдения': [], 'профиль_проверки': {
                'класс': 'адресная', 'отпечаток_снимка': {
                    'схема': 'fum.test-snapshot.physical-lease.1',
                    'сессия': Path(сессия).parent.as_posix(), 'значение': 'sha256:' + 'a'*64},
                'полные_наборы': [], 'основание': None, 'идентификатор_отказа': None,
                'ожидаемое_свидетельство': None}}
        байты = м.канонические_машинные_байты(запись)
        прежняя = copy.deepcopy(граница)
        готовая, ожидаемый_отчёт = доставка._тестово_спланировать_предпросмотр(граница, идентификатор, байты)
        сам.assertEqual(граница, прежняя)
        сам.assertTrue(ожидаемый_отчёт.startswith('Начало\n'.encode()))
        сам.assertTrue(ожидаемый_отчёт.endswith('\nКонец\n'.encode()))
        сам.assertIn('неуспешно', ожидаемый_отчёт.decode())
        сам.assertIn('a \\| b', ожидаемый_отчёт.decode())
        сам.assertEqual(готовая['разница'][отчёт]['sha256'], hashlib.sha256(ожидаемый_отчёт).hexdigest())
        with сам.assertRaises(доставка.ОшибкаПриёма):
            доставка._тестово_спланировать_предпросмотр(граница, идентификатор, байты + b' ')
        блок = (открытый_маркер + '\n\n' + конечный_маркер + '\n').encode()
        крупный = b'x' * (4 * 1024 * 1024 - len(блок) - 1) + b'\n' + блок
        предельная = copy.deepcopy(граница)
        предельная['исходный_отчёт'] = крупный
        предельная['файлы'][отчёт]['sha256'] = hashlib.sha256(крупный).hexdigest()
        with сам.assertRaisesRegex(доставка.ОшибкаПриёма, 'размер'):
            доставка._тестово_спланировать_предпросмотр(предельная, идентификатор, байты)

    def test_опытная_граница_готовится_до_запуска_и_не_меняется(сам):
        import importlib, stat
        скрипты = Path(__file__).resolve().parents[2] / 'fum-reyestr-planirovaniya' / 'scripts'
        sys.path.insert(0, str(скрипты))
        try:
            доставка = importlib.import_module('доставка_отчёта')
        finally:
            sys.path.remove(str(скрипты))
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            база = Path(временный).resolve()
            корень = база / 'repo'; корень.mkdir(mode=0o700)
            сессия = 'Журнал/этап/запрос.md'
            запрос = корень / сессия; запрос.parent.mkdir(parents=True)
            запрос.write_bytes(b'request')
            отчёт = запрос.parent / 'отчёт.md'
            отчёт.write_text('# Отчёт\n' + открытый_маркер + '\nПусто\n' + конечный_маркер + '\n')
            def сведения(путь):
                return {'режим': путь.lstat().st_mode, 'sha256': hashlib.sha256(путь.read_bytes()).hexdigest()}
            отчёт_имя = отчёт.relative_to(корень).as_posix()
            файлы = {сессия: сведения(запрос), отчёт_имя: сведения(отчёт)}
            lockroot = база / 'locks'; lockroot.mkdir(mode=0o700)
            fd = os.open(lockroot, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            try:
                ст = os.fstat(fd)
                селектор = ('fum.test-lock-root.2', str(lockroot), ст.st_dev, ст.st_ino, ст.st_uid,
                            stat.S_IMODE(ст.st_mode), сессия, str(корень))
                контракт = ('fum.test-lock-single.1', селектор, fd)
                идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
                with mock.patch.object(доставка, 'файлы', side_effect=AssertionError('Git inventory')) as собрать, \
                     mock.patch.object(доставка.отчёты.tempfile, 'gettempdir', side_effect=AssertionError('tempfile')), \
                     mock.patch.object(доставка.отчёты.subprocess, 'Popen', side_effect=AssertionError('Git')):
                    неверный = list(селектор); неверный[2] += 1
                    with сам.assertRaises(доставка.ОшибкаПриёма):
                        доставка._тестово_подготовить_границу(
                            корень, сессия, идентификатор,
                            контракт=('fum.test-lock-single.1', tuple(неверный), fd), срок=time.monotonic()+5)
                    собрать.assert_not_called()
                    граница = доставка._тестово_подготовить_границу(
                        корень, сессия, идентификатор, контракт=контракт, срок=time.monotonic()+5)
                    собрать.assert_not_called()
                    исходный_отчёт = отчёт.read_bytes()
                    прочитать = доставка._тестово_прочитать_отчёт
                    def изменить_после_чтения(*аргументы):
                        текст = прочитать(*аргументы)
                        отчёт.write_bytes(исходный_отчёт + b'changed')
                        return текст
                    try:
                        with mock.patch.object(доставка, '_тестово_прочитать_отчёт', side_effect=изменить_после_чтения):
                            with сам.assertRaises(доставка.ОшибкаПриёма):
                                доставка._тестово_подготовить_границу(
                                    корень, сессия, идентификатор, контракт=контракт, срок=time.monotonic()+5)
                    finally:
                        отчёт.write_bytes(исходный_отчёт)
                сохранённая = copy.deepcopy(граница)
                сам.assertEqual(граница['исходный_отчёт'], исходный_отчёт)
                терминальные = b'fixture terminal'
                готовая = доставка._тестово_закрепить_терминал(граница, идентификатор, терминальные)
                сам.assertEqual(граница, сохранённая)
                имя = f'Журнал/этап/материалы/запуски-проверок/1_{идентификатор}.json'
                сам.assertEqual(готовая['разница'], {отчёт_имя: файлы[отчёт_имя], имя: {
                    'режим': 0o100644, 'sha256': hashlib.sha256(терминальные).hexdigest()}})
                повреждённая = copy.deepcopy(граница)
                повреждённая['файлы'][отчёт_имя] = None
                with сам.assertRaises(доставка.ОшибкаПриёма):
                    доставка._тестово_закрепить_терминал(повреждённая, идентификатор, терминальные)
            finally:
                os.close(fd)

