        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            путь = Path(временный) / 'отчёт.md'; путь.write_bytes(b'fixture')
            закрыть = os.close
            def закрыть_с_отказом(fd):
                закрыть(fd)
