            with mock.patch.object(доставка.os, 'read', side_effect=OSError('fixture read')), \
                 mock.patch.object(доставка.os, 'close', side_effect=закрыть_с_отказом):
                with сам.assertRaises(доставка.ОшибкаПриёма) as итог:
                    доставка._тестово_прочитать_отчёт(путь, time.monotonic()+5)
            сам.assertTrue(any('закрытия FD' in заметка for заметка in getattr(итог.exception, '__notes__', ())))

