    def test_сбой_readback_после_replace_удерживает_оба_замка_моста(сам):
        import errno, fcntl, importlib, stat
        скрипты = Path(__file__).resolve().parents[2] / 'fum-reyestr-planirovaniya' / 'scripts'
        sys.path.insert(0, str(скрипты))
        try:
            доставка = importlib.import_module('доставка_отчёта')
        finally:
            sys.path.remove(str(скрипты))
        м = доставка.отчёты
        сам.фаза_отказа_моста = 'создание фикстуры'
        сам.fd_отказа_моста = []
        сам.закрытие_fd_отказа_моста = None
        сам.владелец_отказа_моста = доставка._ТестовыйВладелецПредпросмотра()
        сам.база_отказа_моста = tempfile.TemporaryDirectory(dir='/tmp')
        сам.база_отказа_моста._finalizer.detach()
        база = Path(сам.база_отказа_моста.name).resolve()
        корень = база / 'repo'; корень.mkdir(mode=0o700)
        сессия = 'Журнал/этап/запрос.md'
        запрос = корень / сессия; запрос.parent.mkdir(parents=True)
        запрос.write_bytes(b'request')
        отчёт = запрос.parent / 'отчёт.md'
        исходный = ('До\n' + открытый_маркер + '\nПусто\n' + конечный_маркер + '\nПосле\n').encode('utf-8')
        отчёт.write_bytes(исходный); os.chmod(отчёт, 0o644)
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        запись = {'схема': м._ТЕСТОВАЯ_СХЕМА_ЗАПУСКА_С_ИЗОЛЯЦИЕЙ_GIT,
            'идентификатор': идентификатор, 'сессия': сессия, 'порядок': 1,
            'исполнитель': 'root', 'вызов': 'bridge-fault', 'состояние': 'завершён',
            'длительность_наносекунды': 1, 'статус': 'успешно', 'код_завершения': 0,
            'пояснение': None, 'план': None, 'наблюдения': [], 'профиль_проверки': {
                'класс': 'адресная', 'отпечаток_снимка': {
                    'схема': 'fum.test-snapshot.physical-lease.2',
                    'сессия': Path(сессия).parent.as_posix(), 'значение': 'sha256:' + 'a'*64},
                'полные_наборы': [], 'основание': None, 'идентификатор_отказа': None,
                'ожидаемое_свидетельство': None}}
        байты = м.канонические_машинные_байты(запись)
        селекторы, корни = [], []
        for имя in ('old', 'new'):
            каталог_замка = база / имя; каталог_замка.mkdir(mode=0o700)
            fd = м._приобрести_fd(сам.fd_отказа_моста, os.open, каталог_замка,
                                  os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            корни.append(fd); ст = os.fstat(fd)
            селекторы.append(('fum.test-lock-root.2', str(каталог_замка), ст.st_dev, ст.st_ino,
                             ст.st_uid, stat.S_IMODE(ст.st_mode), сессия, str(корень)))
        контракт = ('fum.test-lock-bridge.1', селекторы[0], корни[0], селекторы[1], корни[1])
        граница = доставка._тестово_подготовить_границу(
            корень, сессия, идентификатор, контракт=контракт, срок=time.monotonic()+10,
            _изолированная_история=True, _изолированный_мост=True)
        сам.assertEqual(граница['схема'], 'fum.test-delivery-boundary.5')
        каталог = запрос.parent / 'материалы/запуски-проверок'; каталог.mkdir(parents=True)
        терминал = каталог / f'1_{идентификатор}.json'; терминал.write_bytes(байты); os.chmod(терминал, 0o644)
        готовая, ожидаемый = доставка._тестово_спланировать_предпросмотр(граница, идентификатор, байты)
        сам.assertNotEqual(ожидаемый, исходный)
        имя_замка = 'fum-check-runs-' + hashlib.sha256(f'{корень}\0{сессия}'.encode()).hexdigest() + '.lock'
        def отпустить_fd(роль, fd):
            сам.закрытие_fd_отказа_моста = ('начато', роль, fd)
            м._отпустить_зарегистрированный_fd(сам.fd_отказа_моста, fd)
            сам.закрытие_fd_отказа_моста = ('завершено', роль, fd)
        def проверить_оба_заняты():
            for fd_корня in корни:
                fd = м._приобрести_fd(сам.fd_отказа_моста, os.open, имя_замка,
                                     os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=fd_корня)
                try:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                except BlockingIOError as ошибка_замка:
                    сам.assertIn(ошибка_замка.errno, (errno.EAGAIN, errno.EWOULDBLOCK))
                    отпустить_fd('занятый замок', fd)
                else:
                    raise AssertionError('замок моста неожиданно свободен')
        настоящий_мост = м._тестовый_мост_замков
        сам.сверка_отказа_моста = None
        @contextlib.contextmanager
        def захватить_мост(*аргументы, **ключи):
            with настоящий_мост(*аргументы, **ключи) as сверить:
                сам.сверка_отказа_моста = сверить
                yield сверить
        настоящий_replace = м.os.replace
        настоящий_readback = доставка._тестово_прочитать_отчёт
        ошибка = OSError(errno.EIO, 'synthetic bridge readback')
        события = []
        def заменить(источник, цель):
            сам.assertEqual((источник, цель), (сам.владелец_отказа_моста.временный, отчёт))
            проверить_оба_заняты(); события.append('до replace')
            ст = источник.lstat()
            настоящий_replace(источник, цель)
            ст_после = цель.lstat()
            сам.assertEqual((ст.st_dev, ст.st_ino), (ст_после.st_dev, ст_после.st_ino))
            сам.assertFalse(os.path.lexists(источник))
            проверить_оба_заняты(); события.append('после replace')
        def прочитать(путь, срок):
            if путь == отчёт and события == ['до replace', 'после replace']:
                события.append('readback'); raise ошибка
            return настоящий_readback(путь, срок)
        сам.фаза_отказа_моста = 'предпросмотр начат'
        with mock.patch.object(м, '_тестовый_мост_замков', side_effect=захватить_мост) as вызов_моста, \
             mock.patch.object(м.os, 'replace', side_effect=заменить), \
             mock.patch.object(доставка, '_тестово_прочитать_отчёт', side_effect=прочитать), \
             mock.patch.object(м.subprocess, 'Popen', side_effect=AssertionError('процесс под замком')) as popen:
            with сам.assertRaises(OSError) as пойманная:
                доставка._тестово_выполнить_предпросмотр(
                    корень, граница, идентификатор, байты, контракт=контракт,
                    срок=time.monotonic()+10, владелец=сам.владелец_отказа_моста,
                    _привязка=граница['_привязка'])
            popen.assert_not_called()
            вызов_моста.assert_called_once()
        сам.assertIs(пойманная.exception, ошибка)
        владелец = сам.владелец_отказа_моста
        сам.assertEqual(события, ['до replace', 'после replace', 'readback'])
        сам.assertEqual(владелец.состояние, 'неизвестно'); сам.assertIs(владелец.ошибка, ошибка)
        сам.assertIsNotNone(владелец._удержание); сам.assertIsNotNone(сам.сверка_отказа_моста)
        сам.assertEqual(владелец._свидетельства, (корень, сессия, идентификатор, исходный, ожидаемый, байты))
        проверить_оба_заняты()
        срок = time.monotonic()+10
        сам.сверка_отказа_моста(); граница['_привязка'].сверить(граница)
        сам.assertEqual(настоящий_readback(отчёт, срок).encode('utf-8'), ожидаемый)
        сам.assertEqual(stat.S_IMODE(отчёт.lstat().st_mode), 0o644)
        сам.assertFalse(os.path.lexists(владелец.временный))
        записи = доставка._тестово_прочитать_границу_истории(
            корень, каталог, сессия, идентификатор, байты, граница=готовая, срок=срок)
        сам.assertEqual(len(записи), 1); сам.assertEqual(записи[0][1:], (запись, байты))
        доставка._тестово_сверить_файлы_под_замком(
            корень, отчёт, записи, готовая, срок, сам.сверка_отказа_моста,
            hashlib.sha256(ожидаемый).hexdigest())
        сам.фаза_отказа_моста = 'освобождение начато'
        владелец._удержание.__exit__(None, None, None)
        сам.assertIsNone(владелец._удержание); сам.assertEqual(владелец.состояние, 'неизвестно')
        for fd_корня in корни:
            fd = м._приобрести_fd(сам.fd_отказа_моста, os.open, имя_замка,
                                 os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=fd_корня)
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            fcntl.flock(fd, fcntl.LOCK_UN)
            отпустить_fd('освобождённый замок', fd)
        for fd in reversed(корни): отпустить_fd('каталог замка', fd)
        сам.assertEqual(сам.fd_отказа_моста, [])
        сам.база_отказа_моста.cleanup()
        сам.фаза_отказа_моста = 'фикстура закрыта'

