    def test_git_доставки_diff_не_выполняет_локальный_clean_filter(сам):
        import importlib
        скрипты = Path(__file__).resolve().parents[2] / 'fum-reyestr-planirovaniya' / 'scripts'
        sys.path.insert(0, str(скрипты))
        try:
            гит = importlib.import_module('доставка_гит')
        finally:
            sys.path.remove(str(скрипты))
        сам.фикстура_git_filter = ФикстураОтчётов()
        сам.фикстура_git_filter.временный_каталог._finalizer.detach()
        корень = сам.фикстура_git_filter.корень.resolve()
        маркер = корень / 'filter-executed.txt'
        атрибуты = корень / '.gitattributes'
        атрибуты.write_text('*.md filter=fumprobe\n', encoding='utf-8')
        гит.выполнить(корень, 'config', 'filter.fumprobe.clean', f'/usr/bin/touch {маркер}; /bin/cat')
        запрос = сам.фикстура_git_filter.запрос
        запрос.write_bytes(запрос.read_bytes() + b'changed\n')
        относительный = запрос.relative_to(сам.фикстура_git_filter.корень).as_posix()
        приём = importlib.import_module('приём_направления')
        head = гит.выполнить(корень, 'rev-parse', 'HEAD').stdout.decode().strip()
        чистый_индекс = гит.выполнить(корень, 'diff', '--cached', '--no-ext-diff', '--no-textconv',
                                       '--ignore-submodules=none', '--name-only')
        сам.assertEqual(чистый_индекс.stdout, b'')
        сравнение_деревьев = гит.выполнить(корень, 'diff', '--no-ext-diff', '--no-textconv',
                                           '--name-only', '-z', '--no-renames', 'HEAD', head)
        сам.assertEqual(сравнение_деревьев.stdout, b'')
        with mock.patch.object(гит.subprocess, 'run', side_effect=AssertionError('Git diff не должен запускаться')) as запуск:
            with сам.assertRaisesRegex(приём.ОшибкаПриёма, 'рабочего дерева.*закрыто'):
                гит.выполнить(корень, 'diff', '--no-ext-diff', '--no-textconv', '--', относительный)
            with сам.assertRaisesRegex(приём.ОшибкаПриёма, 'рабочего дерева.*закрыто'):
                гит.чисто(корень)
            for обход in (('-c', 'x=y', 'diff'), ('--no-pager', 'diff')):
                with сам.subTest(обход=обход), сам.assertRaisesRegex(приём.ОшибкаПриёма, 'Глобальные аргументы'):
                    гит.выполнить(корень, *обход)
            запуск.assert_not_called()
        сам.assertFalse(маркер.exists(), 'локальный clean filter был выполнен')
        сам.фикстура_git_filter.очистить()
        сам.фикстура_git_filter_закрыта = True

