    def test_доставка_истории_использует_явный_замок(сам):
        import importlib, select, stat
        скрипты = Path(__file__).resolve().parents[2] / 'fum-reyestr-planirovaniya' / 'scripts'
        sys.path.insert(0, str(скрипты))
        try:
            доставка = importlib.import_module('доставка_отчёта')
        finally:
            sys.path.remove(str(скрипты))
        сам.каталог_доставки = tempfile.TemporaryDirectory(dir='/tmp')
        сам.каталог_доставки._finalizer.detach()
        база = Path(сам.каталог_доставки.name).resolve()
        корень = база / 'repo'; корень.mkdir(mode=0o700)
        папка = корень / 'Журнал' / 'этап'; папка.mkdir(parents=True)
        запрос = папка / 'запрос.md'; запрос.write_text('# Запрос\n', encoding='utf-8')
        отчёт = папка / 'отчёт.md'
        исходный_отчёт = ('# Отчёт\n\n' + открытый_маркер + '\nПусто\n' + конечный_маркер + '\n').encode()
        отчёт.write_bytes(исходный_отчёт)
        каталог = база / 'lock'; каталог.mkdir(mode=0o700)
        fd = os.open(каталог, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        сам.fd_доставки = fd
        ст = os.fstat(fd); сессия = запрос.relative_to(корень).as_posix()
        селектор = ('fum.test-lock-root.2', str(каталог), ст.st_dev, ст.st_ino, ст.st_uid,
                    stat.S_IMODE(ст.st_mode), сессия, str(корень))
        контракт = ('fum.test-lock-single.1', селектор, fd)
        имя = 'fum-check-runs-' + hashlib.sha256(f'{корень}\0{сессия}'.encode()).hexdigest() + '.lock'
        lockfd = os.open(имя, os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600, dir_fd=fd)
        сам.lockfd_доставки = lockfd
        os.fchmod(lockfd, 0o600)
        метка_замка = os.fstat(lockfd)
        код_конкурента = '\n'.join([
            'import fcntl,os,sys',
            'p=sys.argv[1]; fd=os.open(p,os.O_RDWR|os.O_NOFOLLOW|os.O_CLOEXEC)',
            'a=os.fstat(fd); b=os.stat(p,follow_symlinks=False)',
            'assert (a.st_dev,a.st_ino)==(int(sys.argv[2]),int(sys.argv[3]))==(b.st_dev,b.st_ino)',
            'fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)',
            'os.write(1,b"H"); assert os.read(0,1)==b"X"',
            'fcntl.flock(fd,fcntl.LOCK_UN); os.close(fd); os.write(1,b"K")',
        ])
        сам.конкурент_доставки = None
        сам.фаза_доставки = 'запуск конкурента начат'
        сам.конкурент_доставки = subprocess.Popen(
            [sys.executable, '-I', '-S', '-B', '-u', '-c', код_конкурента, str(каталог / имя),
             str(метка_замка.st_dev), str(метка_замка.st_ino)],
            env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'}, stdin=subprocess.PIPE,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, close_fds=True, start_new_session=True)
        сам.фаза_доставки = 'конкурент получен'
        os.set_blocking(сам.конкурент_доставки.stdin.fileno(), False)
        сам.assertTrue(select.select([сам.конкурент_доставки.stdout.fileno()], [], [], 5.0)[0])
        сам.assertEqual(os.read(сам.конкурент_доставки.stdout.fileno(), 1), b'H')
        сам.фаза_доставки = 'замок удерживается конкурентом'
        with mock.patch.object(доставка.отчёты.tempfile, 'gettempdir', side_effect=AssertionError('tempfile')) as temp:
            with сам.assertRaisesRegex(доставка.ОшибкаПриёма, 'истёк срок') as отказ:
                доставка.история(корень, запрос, пустой=True, _тестовый_контракт_замка=контракт,
                                 _срок_замка=time.monotonic()+0.2)
            сам.assertIsInstance(отказ.exception.__cause__, доставка.отчёты.ОшибкаОтчёта)
            with сам.assertRaisesRegex(доставка.ОшибкаПриёма, 'истёк срок'):
                доставка.сверить(корень, {'запрос': запрос}, итоговый=True,
                    _тестовый_контракт_замка=контракт, _срок_замка=time.monotonic()+0.2)
            with mock.patch.object(доставка, 'файлы', side_effect=AssertionError('Git inventory')):
                with сам.assertRaisesRegex(доставка.ОшибкаПриёма, 'истёк срок'):
                    доставка._тестово_подготовить_границу(
                        корень, запрос, '00112233-4455-4677-8899-aabbccddeeff',
                        контракт=контракт, срок=time.monotonic()+0.2)
            текущая_метка = (каталог / имя).lstat()
            сам.assertEqual((метка_замка.st_dev, метка_замка.st_ino),
                            (текущая_метка.st_dev, текущая_метка.st_ino))
            сам.assertEqual(отчёт.read_bytes(), исходный_отчёт)
            сам.фаза_доставки = 'освобождение начато'
            сам.assertEqual(os.write(сам.конкурент_доставки.stdin.fileno(), b'X'), 1)
            сам.фаза_доставки = 'освобождение передано'
            сам.assertTrue(select.select([сам.конкурент_доставки.stdout.fileno()], [], [], 5.0)[0])
            сам.assertEqual(os.read(сам.конкурент_доставки.stdout.fileno(), 1), b'K')
            сам.assertEqual(сам.конкурент_доставки.wait(timeout=5.0), 0)
            сам.фаза_доставки = 'конкурент собран'
            путь, записи_каталог, полученная_сессия, записи = доставка.история(
                str(корень), запрос, пустой=True, _тестовый_контракт_замка=контракт,
                _срок_замка=time.monotonic()+5.0)
            сам.assertEqual((путь, полученная_сессия, записи), (отчёт, сессия, []))
            сам.assertEqual(записи_каталог, папка / 'материалы' / 'запуски-проверок')
            сам.assertEqual(отчёт.read_bytes(), исходный_отчёт)
            with mock.patch.object(доставка, 'файлы', side_effect=AssertionError('Git inventory')):
                подготовленная = доставка._тестово_подготовить_границу(
                    корень, запрос, '00112233-4455-4677-8899-aabbccddeeff',
                    контракт=контракт, срок=time.monotonic()+5)
            сам.assertEqual(подготовленная['запрос'], сессия)
            сам.assertIsNone(подготовленная['разница'])
            with сам.assertRaisesRegex(доставка.ОшибкаПриёма, 'каталог запусков отсутствует'):
                доставка.сверить(корень, {'запрос': запрос, 'прежние': [], 'запуск': 'fixture'},
                    итоговый=True, _тестовый_контракт_замка=контракт, _срок_замка=time.monotonic()+5.0)
            temp.assert_not_called()
        сам.конкурент_доставки.stdin.close()
        сам.конкурент_доставки.stdout.close()
        сам.конкурент_доставки.stderr.close()
        os.close(lockfd); сам.lockfd_доставки = None
        os.close(fd); сам.fd_доставки = None
        сам.фаза_доставки = 'закрыт'

