    def test_явный_маршрут_блокирует_оба_inode_без_tempfile(сам):
        import fcntl, stat
        модуль = загрузить_модуль_автоматизации()
        @contextlib.contextmanager
        def сохранить_каталог():
            сам.каталог_явного_маршрута = tempfile.TemporaryDirectory(dir='/tmp')
            сам.каталог_явного_маршрута._finalizer.detach()
            yield сам.каталог_явного_маршрута.name
        with сохранить_каталог() as временный:
            база = Path(временный).resolve()
            корень = база / 'repo'; корень.mkdir(mode=0o700)
            старый = база / 'old'; старый.mkdir(mode=0o700)
            новый = база / 'new'; новый.mkdir(mode=0o700)
            сессия = 'Журнал/этап/запрос.md'
            открытые = []
            сам.fd_явного_маршрута = открытые
            завершено = False
            def закрепить(путь):
                fd = os.open(путь, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
                открытые.append(fd)
                ст = os.fstat(fd)
                return ('fum.test-lock-root.2', str(путь), ст.st_dev, ст.st_ino, ст.st_uid,
                        stat.S_IMODE(ст.st_mode), сессия, str(корень)), fd
            старый_селектор, старый_fd = закрепить(старый)
            новый_селектор, новый_fd = закрепить(новый)
            контракт = ('fum.test-lock-bridge.1', старый_селектор, старый_fd, новый_селектор, новый_fd)
            имя = 'fum-check-runs-' + hashlib.sha256(f'{корень}\0{сессия}'.encode()).hexdigest() + '.lock'
            try:
                with mock.patch.object(модуль.tempfile, 'gettempdir', side_effect=AssertionError('tempfile')):
                    with модуль._тестово_выбрать_замок_сессии(
                        корень, сессия, срок_монотонный=time.monotonic()+5.0, контракт=контракт,
                    ) as проверить:
                        проверить()
                        for каталог in (старый, новый):
                            конкурент = os.open(каталог / имя, os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC)
                            try:
                                with сам.assertRaises(BlockingIOError):
                                    fcntl.flock(конкурент, fcntl.LOCK_EX | fcntl.LOCK_NB)
                            finally:
                                os.close(конкурент)
                for каталог in (старый, новый):
                    конкурент = os.open(каталог / имя, os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC)
                    try:
                        fcntl.flock(конкурент, fcntl.LOCK_EX | fcntl.LOCK_NB)
                        fcntl.flock(конкурент, fcntl.LOCK_UN)
                    finally:
                        os.close(конкурент)
                завершено = True
            finally:
                if завершено:
                    for fd in открытые:
                        os.close(fd)
                    открытые.clear()

