class ПроверкаReleaseПередачиОтказа(unittest.TestCase):
    версия = "fum-run-witness.3"
    setUp = ПроверкаПередачиНаблюдателя.setUp

    def проверить(self, первичная, освобождение, ожидаемая):
        import threading
        class СбойныйЗамок:
            def __init__(self): self.lock = threading.Lock(); self.first = True
            def acquire(self, blocking): return self.lock.acquire(blocking)
            def release(self):
                self.lock.release()
                if self.first:
                    self.first = False
                    raise освобождение
        self.передача._блокировка = СбойныйЗамок()
        настоящее = os.write
        def писать(fd, data):
            result = настоящее(fd, data)
            if первичная is not None: raise первичная
            return result
        with mock.patch.object(self.м.os, "write", side_effect=писать):
            with self.assertRaises(type(ожидаемая)) as поймано:
                self.передача.отправить(b"A", lambda: None)
        self.assertIs(поймано.exception, ожидаемая)
        self.assertEqual(os.read(self.чтение, 1), b"A")
        self.assertEqual(self.передача.попытки, ((b"A", "начата" if первичная else 1),))
        self.assertEqual(self.передача.состояние, "неизвестно")
        self.assertEqual(self.п.состояние, "неизвестно")
        self.assertIs(self.передача._ошибка, первичная if первичная is not None else освобождение)
        self.assertEqual(self.передача._ошибки_освобождения, [освобождение])
        with mock.patch.object(self.м.os, "write", side_effect=AssertionError("повтор")) as писать_снова:
            with self.assertRaises(self.м.ОшибкаОтчёта): self.передача.отправить(b"A", lambda: None)
            писать_снова.assert_not_called()

    def test_повтор_A_G_в_окне_после_unlock(self):
        import threading
        unlocked = threading.Event(); закончено = threading.Event(); результаты = []
        главный = threading.get_ident()
        class СбойныйЗамок:
            def __init__(self): self.lock = threading.Lock()
            def acquire(self, blocking): return self.lock.acquire(blocking)
            def release(self):
                self.lock.release()
                if threading.get_ident() == главный:
                    unlocked.set()
                    if not закончено.wait(3): raise AssertionError("worker timeout")
                    raise OSError("release after unlock")
        self.передача._блокировка = СбойныйЗамок()
        def worker():
            try:
                if not unlocked.wait(3): raise AssertionError("unlock timeout")
                for команда in (b"A", b"G"):
                    try: self.передача.отправить(команда, lambda: None)
                    except self.м.ОшибкаОтчёта: результаты.append(команда)
                    else: результаты.append(b"unexpected")
                try: self.п.квитанция_отказа()
                except self.м.ОшибкаОтчёта: результаты.append(b"no-receipt")
                else: результаты.append(b"unexpected-receipt")
            finally:
                закончено.set()
        поток = threading.Thread(target=worker, daemon=True); поток.start()
        with self.assertRaisesRegex(OSError, "release after unlock"):
            self.передача.отправить(b"A", lambda: None)
        поток.join(3); self.assertFalse(поток.is_alive())
        self.assertEqual(результаты, [b"A", b"G", b"no-receipt"])
        self.assertEqual(os.read(self.чтение, 1), b"A")
        os.set_blocking(self.чтение, False)
        with self.assertRaises(BlockingIOError): os.read(self.чтение, 1)
        self.assertEqual(self.передача.состояние, "неизвестно")
        self.assertEqual(self.п.состояние, "неизвестно")

    def test_release_после_A(self):
        release = OSError("release")
        self.проверить(None, release, release)

    def test_две_обычные_ошибки(self):
        первичная = ValueError("primary"); release = OSError("release")
        self.проверить(первичная, release, первичная)

    def test_контекст_первичной_ошибки_не_теряется(self):
        первичная = ValueError("primary"); earlier = LookupError("earlier")
        первичная.__context__ = earlier
        release = OSError("release")
        self.проверить(первичная, release, первичная)
        self.assertIs(первичная.__context__, earlier)

    def test_первичная_отмена(self):
        первичная = KeyboardInterrupt("primary"); release = OSError("release")
        self.проверить(первичная, release, первичная)

    def test_поздняя_отмена(self):
        первичная = ValueError("primary"); release = KeyboardInterrupt("release")
        self.проверить(первичная, release, release)


