class ПроверкаReleaseШагаКонтура(unittest.TestCase):
    def test_связанный_terminal_и_итог_после_закрытия_доступны_владельцу(self):
        import threading, _thread
        м = загрузить_модуль_автоматизации()
        в = м._ТестовыйВладелецЗапуска(); в._блокировка.acquire()
        try:
            в._поток_владельца = _thread.get_ident(); в._объект_потока = threading.current_thread()
            идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
            к = м._ТестовыйКонтурНаблюдателя(в, идентификатор, 10000, None, длительность_цели_ms=500)
            приёмник = к._приёмник
            class Процесс:
                pid = 1234
                returncode = 0
            процесс = Процесс(); pid_якоря = 2345; pid_цели = 3456
            метка = uuid.UUID(идентификатор).bytes
            якорь = pid_якоря.to_bytes(4, 'big'); цель = pid_цели.to_bytes(4, 'big')
            raw = (0).to_bytes(4, 'big'); kill = int(signal.SIGKILL).to_bytes(4, 'big')
            кадры = (b'FUA1' + метка + якорь,
                      b'FUS2' + метка + якорь + цель + (150).to_bytes(8, 'big'),
                      b'FUP2' + метка + raw + (180).to_bytes(8, 'big'),
                      b'FUD1' + метка + якорь + цель + raw + kill + b'\0')
            приёмник._кадры = list(кадры); приёмник._якорь = pid_якоря; приёмник._цель = pid_цели
            приёмник._статус = 0; приёмник._команда = b'C'; приёмник._фаза = 'завершено'
            приёмник._подтверждён_тайм_аут = False; приёмник._край_очистки = 15000
            приёмник._начало_цели_ms = 150
            передача = object.__new__(м._ТестоваяПередачаНаблюдателя)
            передача._приёмник = приёмник; передача._попытки = [(b'G', 1), (b'C', 1)]
            к._передача = передача
            читатель = mock.Mock(); читатель.полученные = list(кадры)
            в.состояние = 'занят'; в.процесс = процесс; в.pid = процесс.pid
            в.код_лидера = 0; в.этап_сбора = 'собран'; в.запись_вернула_успех = True
            в.терминальные_байты = b'terminal'; в.терминальная_запись_вернула_успех = True
            в._читатель_binding = читатель; в._go_binding = передача
            участок = object.__new__(м._ТестовыйУчастокЗапускаПодПарой)
            участок._предпуск = к; участок._фаза = 'закрыт'
            участок._связь = (None, в, приёмник, передача, читатель, None, None, процесс, процесс.pid)
            участок._тайм_аут_цели = False; участок._сырой_статус_цели = 0
            участок._попытка_сбора = ('получен', 0); участок._попытка_eof = b''
            участок._байты_терминала = b'terminal'
            к._предпуск_участок = участок; к._предпуск_попытка_active = 'начата'
            к._предпуск_связь = (в, приёмник, процесс, процесс.pid, читатель, передача,
                                  None, None, None, None, None, None)
            к._начало_попытки_ns = 100_000_000; к._состояние = 'предпуск готов'
            к._свидетельство = м._ТестовоеСвидетельствоНаблюдателя(
                идентификатор, процесс.pid, pid_якоря, pid_цели, 0, 0, False, кадры,
                0, 100_000_000, 200_000_000, 10000, 15000)
            def закрыть(*_): к._состояние = 'закрыт'
            with mock.patch.object(м, '_КЛАСС_СОБСТВЕННОГО_POPEN', Процесс), \
                 mock.patch.object(к, '_закрыть_каналы_предпуска', side_effect=закрыть) as закрытие:
                к.закрыть_после_успешного_участка()
                закрытие.assert_called_once()
                итог = м._тестовый_итог_контура_наблюдателя(к, _после_закрытия=True)
                self.assertEqual((итог.статус, итог.код_записи, итог.возвращаемый_код), ('успешно', 0, 0))
                self.assertEqual(итог.длительность_ns, 100_000_000)
        finally:
            в._блокировка.release()

    def test_внутренний_итог_допускается_лишь_точному_участку_и_маркеру(self):
        import threading, _thread
        м = загрузить_модуль_автоматизации()
        в = м._ТестовыйВладелецЗапуска(); в._блокировка.acquire()
        try:
            в._поток_владельца = _thread.get_ident(); в._объект_потока = threading.current_thread()
            к = м._ТестовыйКонтурНаблюдателя(в, '00112233-4455-4677-8899-aabbccddeeff', 10000, 15000)
            участок = object.__new__(м._ТестовыйУчастокЗапускаПодПарой)
            другой = object.__new__(м._ТестовыйУчастокЗапускаПодПарой)
            к._предпуск_участок = участок; к._состояние = 'предпуск готов'
            def действие():
                маркер = к._ТестовыйКонтурНаблюдателя__маркер_шага[0]
                with к._удержать_доступ_к_итогу(_разрешение=маркер, _участок=участок):
                    with self.assertRaisesRegex(м.ОшибкаОтчёта, 'уже используется'):
                        к._шаг('предпуск готов', lambda: self.fail('повтор'))
                for разрешение, часть in ((object(), участок), (маркер, другой)):
                    with self.assertRaisesRegex(м.ОшибкаОтчёта, 'нет внутреннего разрешения'):
                        with к._удержать_доступ_к_итогу(_разрешение=разрешение, _участок=часть):
                            self.fail('подмена допуска')
                return 'подтверждено'
            self.assertEqual(к._шаг('предпуск готов', действие, _для_итога_участок=участок),
                             'подтверждено')
            with self.assertRaises(м.ОшибкаОтчёта):
                with к._удержать_доступ_к_итогу(_разрешение=object(), _участок=участок):
                    self.fail('допуск вне шага')
        finally:
            в._блокировка.release()

    def test_чужой_поток_не_получает_свидетельство_до_или_во_время_шага(self):
        import threading, _thread
        м = загрузить_модуль_автоматизации()
        в = м._ТестовыйВладелецЗапуска(); в._блокировка.acquire()
        try:
            в._поток_владельца = _thread.get_ident(); в._объект_потока = threading.current_thread()
            к = м._ТестовыйКонтурНаблюдателя(в, '00112233-4455-4677-8899-aabbccddeeff', 10000, 15000)
            старое, новое = object(), object(); к._свидетельство = старое
            исходы = []
            def чужой():
                try: исходы.append(('выдано', к.свидетельство))
                except м.ОшибкаОтчёта: исходы.append(('запрещено', None))
            def проверить_поток():
                поток = threading.Thread(target=чужой)
                поток.start(); поток.join(3)
                self.assertFalse(поток.is_alive())
            проверить_поток()
            def действие():
                к._свидетельство = новое
                проверить_поток()
            к._шаг('готов', действие)
            self.assertEqual(исходы, [('запрещено', None), ('запрещено', None)])
            self.assertIs(к.свидетельство, новое)
        finally:
            в._блокировка.release()

