    def проверить_прерывание_после_вызова(self, имя_метода, замок_должен_быть_занят):
        import dis, threading, _thread
        м = загрузить_модуль_автоматизации()
        в = м._ТестовыйВладелецЗапуска(); в._блокировка.acquire()
        try:
            в._поток_владельца = _thread.get_ident(); в._объект_потока = threading.current_thread()
            к = м._ТестовыйКонтурНаблюдателя(в, '00112233-4455-4677-8899-aabbccddeeff', 10000, 15000)
            код = type(к)._шаг.__code__
            инструкции = list(dis.get_instructions(код))
            индекс = next(i for i, x in enumerate(инструкции)
                          if x.opname == 'LOAD_ATTR' and x.argval == имя_метода)
            вызов = next(i for i in range(индекс + 1, len(инструкции))
                         if инструкции[i].opname == 'CALL')
            граница = инструкции[вызов + 1].offset
            отмена = KeyboardInterrupt('между вызовом и фиксацией результата')
            def трасса(кадр, событие, аргумент):
                if кадр.f_code is код:
                    кадр.f_trace_opcodes = True
                    if событие == 'opcode' and кадр.f_lasti == граница:
                        sys.settrace(None)
                        raise отмена
                return трасса
            try:
                sys.settrace(трасса)
                with self.assertRaises(KeyboardInterrupt) as получено:
                    к._шаг('готов', lambda: self.fail('действие после прерывания'))
                self.assertIs(получено.exception, отмена)
                self.assertEqual(к.состояние, 'неизвестно')
                self.assertEqual(к._блокировка.locked(), замок_должен_быть_занят)
                with self.assertRaises(м.ОшибкаОтчёта): к.свидетельство
                with self.assertRaises(м.ОшибкаОтчёта): к._шаг('готов', lambda: self.fail('повтор'))
            finally:
                sys.settrace(None)
                if к._блокировка.locked(): к._блокировка.release()
        finally:
            в._блокировка.release()

