    def подготовить_несовпадение(сам, ошибка_замка=None):
        модуль, владелец, контейнер, сверка, контекст = сам.подготовить()
        корень, запрос = Path('/private/tmp/fixture'), 'Журнал/этап/запрос.md'
        идентификатор, селектор = '00112233-4455-4677-8899-aabbccddeeff', ('fixture',)
        срок = time.monotonic() + 5.0
        контейнер._срок = срок
        снимок = модуль._ТестовыйВерсионированныйСнимок(
            'fum.test-snapshot.physical-lease.1', 'Журнал/этап', 'sha256:' + 'a' * 64)
        контейнер._значение = (снимок, сверка)
        владелец._снимок_binding = (корень, запрос, object(), 900, селектор, 901, object())
        каталог = корень / 'Журнал/этап/материалы/запуски-проверок'
        старый = снимок._asdict()
        старый['значение'] = 'sha256:' + 'b' * 64
        запись = {'статус': 'успешно', 'код_завершения': 0,
                  'профиль_проверки': {'отпечаток_снимка': старый}}
        замок = mock.MagicMock()
        замок.__enter__.return_value = mock.Mock()
        замок.__exit__.return_value = False
        if ошибка_замка is not None:
            замок.__exit__.side_effect = ошибка_замка
        подмены = contextlib.ExitStack()
        сам.addCleanup(подмены.close)
        подмены.enter_context(mock.patch.object(модуль, '_тестовый_замок_новой_сессии', return_value=замок))
        подмены.enter_context(mock.patch.object(модуль, 'разрешить_сессию', return_value=(корень, None, корень / 'отчёт', каталог, запрос)))
        подмены.enter_context(mock.patch.object(модуль, 'запретить_действие_при_возобновлении'))
        подмены.enter_context(mock.patch.object(Path, 'exists', return_value=False))
        подмены.enter_context(mock.patch.object(Path, 'is_symlink', return_value=False))
        подмены.enter_context(mock.patch.object(модуль, '_тестово_прочитать_терминал_удержания', return_value=[(каталог / 'record', запись, b'terminal')]))
        формировать = подмены.enter_context(mock.patch.object(модуль, 'сформировать_блок_истории'))
        def закрыть(): контейнер.состояние = 'закрыт после чтения'
        закрытие = подмены.enter_context(mock.patch.object(модуль._ТестовыйКонтейнерСнимка, 'закрыть_чтение', side_effect=закрыть))
        def вызвать():
            return модуль._тестово_проверить_физическую_контрольную_точку(
                корень, запрос, идентификатор, b'terminal', b'report',
                контейнер=контейнер, селектор=селектор, селектор_fd=901, срок=срок)
        return модуль, контейнер, контекст, замок, формировать, закрытие, вызвать

