class ПроверкаКонтейнераНаблюдателя(unittest.TestCase):
    def test_новая_политика_private_writer_требует_полный_явный_допуск(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        сам.addCleanup(владелец._блокировка.release)
        владелец.состояние = 'занят'
        владелец._поток_владельца = модуль._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        наблюдатель = (Path('/tmp/witness'), 'a' * 64, Path('/tmp/anchor'), 'b' * 64)
        селектор = ('fum.test-lock-root.2', '/tmp', 1, 2, 3, 0o700, 'session', '/tmp')
        база = {'_владелец': владелец, '_тестовый_наблюдатель': наблюдатель,
                '_тестовый_снимок': True, '_тестовый_удерживаемый_снимок': True,
                '_тестовый_селектор': селектор, '_тестовый_дескриптор': 7,
                '_тестовая_политика_снимка': 'isolated-git.2'}
        случаи = (('неизвестная', {'_тестовая_политика_снимка': 'isolated-git.3'}, идентификатор),
                  ('без-owner', {'_владелец': None}, идентификатор),
                  ('без-lease', {'_тестовый_удерживаемый_снимок': False}, идентификатор),
                  ('без-uuid', {}, None), ('без-observer', {'_тестовый_наблюдатель': None}, идентификатор),
                  ('без-selector', {'_тестовый_селектор': None}, идентификатор),
                  ('bridge', {'_тестовый_старый_селектор': селектор, '_тестовый_старый_fd': 8}, идентификатор))
        with mock.patch.object(модуль, 'разрешить_сессию') as сессия, \
             mock.patch.object(модуль, '_тестово_проверить_исполнитель_наблюдателя') as проверить, \
             mock.patch.object(модуль.subprocess, 'Popen') as popen:
            for название, изменения, uuid_запуска in случаи:
                параметры = dict(база); параметры.update(изменения)
                with сам.subTest(случай=название), сам.assertRaises(модуль.ОшибкаОтчёта):
                    модуль._выполнить_ограниченный_запуск_внутри(
                        Path('/tmp'), Path('Журнал/этап/запрос.md'), 'fixture', 'root',
                        uuid_запуска, 5.0, ('/bin/sleep', '1'), класс_проверки='адресная',
                        тайм_аут_блокировки=5.0, **параметры)
            сессия.assert_not_called(); проверить.assert_not_called(); popen.assert_not_called()

    def test_изолированный_маршрут_готовит_защищённую_среду_до_записи(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        сам.addCleanup(владелец._блокировка.release)
        владелец.состояние = 'занят'
        владелец._поток_владельца = модуль._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        корень = Path('/private/tmp/fixture')
        сессия = 'Журнал/этап/запрос.md'
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        селектор = ('fum.test-lock-root.2', '/tmp', 1, 2, 3, 0o700, сессия, str(корень))
        наблюдатель = (Path('/tmp/witness'), 'a' * 64, Path('/tmp/anchor'), 'b' * 64)
        исходная_среда = модуль.подготовить_ограниченную_среду_проверки
        class ПроверкаСредыЗавершена(Exception): pass
        def проверить_среду(*аргументы, **параметры):
            среда = исходная_среда(*аргументы, **параметры)
            сам.assertEqual(среда['GIT_CONFIG_NOSYSTEM'], '1')
            сам.assertEqual(среда['GIT_CONFIG_GLOBAL'], '/dev/null')
            сам.assertEqual(среда['GIT_ATTR_NOSYSTEM'], '1')
            сам.assertEqual(среда['FUM_CHECK_RUN_ID'], идентификатор)
            raise ПроверкаСредыЗавершена()
        with mock.patch.object(модуль, 'разрешить_сессию',
                return_value=(корень, None, корень / 'отчёт.md', корень / 'записи', сессия)), \
             mock.patch.object(модуль, '_тестово_проверить_исполнитель_наблюдателя'), \
             mock.patch.object(модуль, 'является_неполной_проверкой_проекции', return_value=False), \
             mock.patch.object(модуль, 'подготовить_ограниченную_среду_проверки', side_effect=проверить_среду), \
             mock.patch.object(модуль, 'атомарно_записать_байты') as запись, \
             mock.patch.object(модуль.subprocess, 'Popen') as popen:
            with сам.assertRaises(ПроверкаСредыЗавершена):
                модуль._выполнить_ограниченный_запуск_внутри(
                    корень, Path(сессия), 'fixture', 'root', идентификатор, 5.0, ('/bin/true',),
                    класс_проверки='адресная', тайм_аут_блокировки=5.0, _владелец=владелец,
                    _тестовый_наблюдатель=наблюдатель, _тестовый_снимок=True,
                    _тестовый_удерживаемый_снимок=True, _тестовый_селектор=селектор,
                    _тестовый_дескриптор=7, _тестовая_политика_снимка='isolated-git.2')
            запись.assert_not_called(); popen.assert_not_called()

    def test_связь_active_снимка_отчёта_и_команды_отклоняет_подмену(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        случаи = ('верно', 'мост', 'active', 'отчёт', 'байты-owner', 'оба-active', 'после-callback',
                  'поздний-active', 'контур-id', 'после-замка', 'срок-после-замка',
                  'команда', 'исполнитель', 'история', 'закрыт', 'popen-ok', 'popen-отчёт', 'popen-корень',
                  'popen-без-связи', 'popen-без-контейнера', 'go-связь-пропала', 'go-связь-заменена',
                  'go-после-fua', 'go-обе-ссылки-после-fua', 'go-active-после-fua')
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            корень = Path(временный).resolve()
            сессия = 'Журнал/этап/запрос.md'
            папка = корень / Path(сессия).parent
            каталог = папка / 'материалы/запуски-проверок'; каталог.mkdir(parents=True)
            отчёт = папка / 'отчёт.md'; отчёт.write_bytes(b'baseline report\n')
            идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
            путь = каталог / f'1_{идентификатор}.json'
            снимок = модуль._тестовый_отпечаток_физического_снимка('Журнал/этап', bytes(range(32)), 'isolated-git.2')
            запись = {'схема': 'fum.test-run.experimental-physical-lease.2', 'идентификатор': идентификатор,
                'сессия': сессия, 'порядок': 1, 'исполнитель': 'root', 'вызов': 'test',
                'состояние': 'выполняется', 'длительность_наносекунды': None, 'статус': None,
                'код_завершения': None, 'пояснение': None, 'план': None, 'наблюдения': [],
                'профиль_проверки': {'класс': 'адресная', 'отпечаток_снимка': снимок._asdict(),
                    'полные_наборы': [], 'основание': None, 'идентификатор_отказа': None,
                    'ожидаемое_свидетельство': None}}
            active = модуль.канонические_машинные_байты(запись)
            команда = ('/bin/true',)
            исполнители = (Path('/tmp/witness'), 'a' * 64, Path('/tmp/anchor'), 'b' * 64)
            for случай in случаи:
                with сам.subTest(случай=случай):
                    селектор = (('fum.test-lock-root.2', '/tmp/new-lock', 1, 2, 501, 0o700, сессия, str(корень))
                                if случай == 'мост' else ('fixture-selector',))
                    старый = ('fum.test-lock-root.2', '/tmp/old-lock', 1, 3, 501, 0o700, сессия, str(корень))
                    путь.write_bytes(active); os.chmod(путь, 0o644)
                    отчёт.write_bytes(b'baseline report\n')
                    владелец = модуль._ТестовыйВладелецЗапуска()
                    владелец._блокировка.acquire(); владелец.состояние = 'занят'
                    владелец._поток_владельца = модуль._thread.get_ident()
                    владелец._объект_потока = threading.current_thread()
                    контейнер = модуль._ТестовыйКонтейнерСнимка(владелец, _политика='isolated-git.2')
                    callback = mock.Mock()
                    контекст = mock.MagicMock(); контекст.__enter__.return_value = снимок, callback
                    лишний = каталог / 'extra.txt'
                    контур = None
                    контроль = []
                    try:
                        with mock.patch.object(модуль, '_удержать_тестовый_снимок_без_git_под_замком', return_value=контекст), \
                             mock.patch.object(модуль.subprocess, 'Popen', side_effect=AssertionError('процесс')) as popen:
                            контейнер.открыть(корень, сессия, селектор, 7, срок=time.monotonic()+5)
                            владелец._снимок_binding = (корень, сессия, None, контейнер.дескрипторы[0], селектор, 7, None)
                            владелец.активная_запись, владелец.байты_записи = путь, active
                            владелец.запись_вернула_успех, владелец.состояние = True, 'active записан'
                            срок_ms = time.monotonic_ns() // 1_000_000 + 5000
                            контур = модуль._ТестовыйКонтурНаблюдателя(владелец, идентификатор, срок_ms, срок_ms+5000)
                            связь = модуль._ТестоваяСвязьИзолированногоЗапуска(
                                владелец, контейнер, контур, корень, сессия, селектор, 7, снимок,
                                идентификатор, команда, исполнители, b'baseline report\n',
                                **({'_контракт_замка': ('fum.test-lock-bridge.1', старый, 8, селектор, 7)}
                                   if случай == 'мост' else {}))
                            if случай == 'active': путь.write_bytes(active + b' ')
                            elif случай == 'отчёт': отчёт.write_bytes(b'changed\n')
                            elif случай == 'байты-owner': владелец.байты_записи = active + b' '
                            elif случай == 'оба-active':
                                изменённая = copy.deepcopy(запись); изменённая['вызов'] = 'other'
                                владелец.байты_записи = модуль.канонические_машинные_байты(изменённая)
                                путь.write_bytes(владелец.байты_записи)
                            elif случай == 'после-callback': callback.side_effect = lambda: отчёт.write_bytes(b'late change\n')
                            elif случай == 'поздний-active':
                                изменённая = copy.deepcopy(запись); изменённая['вызов'] = 'late'
                                поздние_байты = модуль.канонические_машинные_байты(изменённая)
                                def подменить_оба():
                                    путь.write_bytes(поздние_байты)
                                    владелец.байты_записи = поздние_байты
                                callback.side_effect = подменить_оба
                            elif случай == 'контур-id': контур._идентификатор = '00000000-0000-4000-8000-000000000001'
                            elif случай == 'история': лишний.write_bytes(b'')
                            elif случай == 'закрыт': контейнер.состояние = 'закрыт'
                            elif случай == 'popen-отчёт': отчёт.write_bytes(b'changed before popen\n')
                            elif случай == 'popen-без-контейнера': владелец._контейнер_снимка = None
                            фактическая = ('/bin/false',) if случай == 'команда' else команда
                            фактические = (Path('/tmp/witness'), 'c' * 64, *исполнители[2:]) if случай == 'исполнитель' else исполнители
                            сверить_замок = mock.Mock()
                            if случай in ('после-замка', 'срок-после-замка'):
                                def подменить_после_замка():
                                    if сверить_замок.call_count == 3:
                                        if случай == 'после-замка': контур._идентификатор = '00000000-0000-4000-8000-000000000001'
                                        else: контур._приёмник._срок_запуска = 0
                                сверить_замок.side_effect = подменить_после_замка
                            if случай == 'go-active-после-fua':
                                class Процесс:
                                    pid = 777
                                    returncode = None
                                владелец.процесс, владелец.pid = Процесс(), 777
                                владелец.состояние = 'опытный наблюдатель запускается'
                                контур._состояние = 'запущен'
                                контур._политика_среды = 'isolated-git.2'
                                контур._команда_связи, контур._корень_связи = команда, корень
                                контур._исполнители, контур._связь_изолированного_запуска = исполнители, связь
                                контур._ТестовыйКонтурНаблюдателя__режим_и_связь = ('real.2', связь, контейнер)
                                контроль.extend(os.pipe())
                                os.set_blocking(контроль[1], False)
                                контур._управление = контроль[1]
                                контур._читатель = mock.Mock()
                                изменённая = copy.deepcopy(запись); изменённая['вызов'] = 'late'
                                поздние_байты = модуль.канонические_машинные_байты(изменённая)
                                def получить_fua(*_аргументы, **_ключи):
                                    кадр = b'FUA1' + uuid.UUID(идентификатор).bytes + (111).to_bytes(4, 'big')
                                    результат = контур._приёмник.принять(кадр, time.monotonic_ns() // 1_000_000)
                                    путь.write_bytes(поздние_байты); владелец.байты_записи = поздние_байты
                                    return результат
                                контур._читатель.читать_кадр.side_effect = получить_fua
                                factory = mock.Mock(side_effect=AssertionError('чужая фабрика'))
                                with mock.patch.object(модуль, '_КЛАСС_СОБСТВЕННОГО_POPEN', Процесс), \
                                     mock.patch.object(модуль.os, 'getpgid', return_value=777), \
                                     mock.patch.object(модуль.os, 'getsid', return_value=777), \
                                     mock.patch.object(модуль, '_тестовый_замок_новой_сессии',
                                                       return_value=contextlib.nullcontext(сверить_замок)), \
                                     mock.patch.object(контур, '_проверить_исполнитель'), \
                                     mock.patch.object(модуль.os, 'write') as отправка:
                                    with сам.assertRaises(модуль.ОшибкаОтчёта): контур.довести(factory)
                                    отправка.assert_not_called()
                                сам.assertEqual(контур._передача.попытки, ())
                                сам.assertEqual(контур.состояние, 'неизвестно')
                                сам.assertIs(владелец._контейнер_снимка, контейнер)
                                factory.assert_not_called()
                            elif случай in ('go-связь-пропала', 'go-связь-заменена', 'go-после-fua', 'go-обе-ссылки-после-fua'):
                                контур._состояние = 'запущен'
                                контур._политика_среды = 'isolated-git.2'
                                контур._команда_связи = команда
                                контур._корень_связи = корень
                                контур._ТестовыйКонтурНаблюдателя__режим_и_связь = ('real.2', связь, контейнер)
                                контур._связь_изолированного_запуска = (
                                    None if случай == 'go-связь-пропала' else object()
                                    if случай == 'go-связь-заменена' else связь)
                                контур._читатель = mock.Mock()
                                контур._читатель.читать_кадр.return_value = ('готов', 111)
                                контур._управление = 3
                                if случай in ('go-после-fua', 'go-обе-ссылки-после-fua'):
                                    def потерять_связь(*_аргументы, **_ключи):
                                        контур._связь_изолированного_запуска = None
                                        if случай == 'go-обе-ссылки-после-fua': владелец._контейнер_снимка = None
                                        return 'готов', 111
                                    контур._читатель.читать_кадр.side_effect = потерять_связь
                                factory = mock.Mock(side_effect=AssertionError('чужая фабрика'))
                                with mock.patch.object(модуль.os, 'write') as запись_канала, \
                                     mock.patch.object(модуль, '_ТестоваяПередачаНаблюдателя'):
                                    with сам.assertRaises(модуль.ОшибкаОтчёта): контур.довести(factory)
                                    запись_канала.assert_not_called()
                                if случай in ('go-после-fua', 'go-обе-ссылки-после-fua'):
                                    контур._читатель.читать_кадр.assert_called_once()
                                else: контур._читатель.читать_кадр.assert_not_called()
                                factory.assert_not_called()
                                сам.assertEqual(контур.состояние, 'неизвестно')
                                if случай != 'go-обе-ссылки-после-fua': сам.assertIs(владелец._контейнер_снимка, контейнер)
                            elif случай in ('popen-ok', 'popen-отчёт', 'popen-корень', 'popen-без-связи', 'popen-без-контейнера'):
                                factory = (mock.Mock(return_value=contextlib.nullcontext(сверить_замок))
                                           if случай == 'popen-без-контейнера' else
                                           mock.Mock(side_effect=AssertionError('чужая фабрика замка')))
                                with mock.patch.object(модуль, '_тестовый_замок_новой_сессии',
                                                       return_value=contextlib.nullcontext(сверить_замок)), \
                                     mock.patch.object(контур, '_проверить_исполнитель'):
                                    if случай == 'popen-ok':
                                        with сам.assertRaisesRegex(AssertionError, 'процесс'):
                                            контур.запустить(*исполнители, корень, команда, factory,
                                                             _связь_изолированного_запуска=связь)
                                        сам.assertEqual(popen.call_args.args[0][1], 'fum-run-witness.2')
                                        сам.assertEqual(popen.call_args.kwargs['env'], {})
                                    else:
                                        with сам.assertRaises(модуль.ОшибкаОтчёта):
                                            контур.запустить(*исполнители, корень / 'other' if случай == 'popen-корень' else корень,
                                                             команда, factory,
                                                             _связь_изолированного_запуска=None if случай in ('popen-без-связи', 'popen-без-контейнера') else связь)
                                        popen.assert_not_called()
                                    if случай == 'popen-без-контейнера': factory.assert_called_once_with()
                                    else: factory.assert_not_called()
                            elif случай == 'мост':
                                маркер_замка = object()
                                with mock.patch.object(модуль, '_тестово_выбрать_замок_сессии', return_value=маркер_замка) as factory:
                                    for очистка in (False, True):
                                        сам.assertIs(связь.взять_замок(контур, _для_очистки=очистка), маркер_замка)
                                        контракт = factory.call_args.kwargs['контракт']
                                        сам.assertEqual(контракт, ('fum.test-lock-bridge.1', старый, 8, селектор, 7))
                                        сам.assertIs(контракт[1], старый)
                                        сам.assertIs(контракт[3], селектор)
                                        сам.assertEqual(factory.call_args.kwargs['срок_монотонный'],
                                            (срок_ms + 5000) / 1000 if очистка else min(контейнер._срок, срок_ms / 1000))
                                for плохой, fd in ((None, 8), (старый, None), (селектор, 7),
                                                   (старый[:-1] + ('/tmp/other',), 8)):
                                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                                        модуль._ТестоваяСвязьИзолированногоЗапуска(
                                            владелец, контейнер, контур, корень, сессия, селектор, 7, снимок,
                                            идентификатор, команда, исполнители, b'baseline report\n',
                                            _контракт_замка=('fum.test-lock-bridge.1', плохой, fd, селектор, 7))
                                связь.сверить(контур, корень, фактическая, фактические, сверить_замок)
                                связь._ТестоваяСвязьИзолированногоЗапуска__контракт_замка = None
                                with mock.patch.object(модуль, '_тестовый_замок_новой_сессии') as одиночный, \
                                     mock.patch.object(модуль, '_тестово_выбрать_замок_сессии') as мост:
                                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                                        связь.взять_замок(контур)
                                    одиночный.assert_not_called(); мост.assert_not_called()
                            elif случай == 'верно':
                                маркер_замка = object()
                                with mock.patch.object(модуль, '_тестовый_замок_новой_сессии', return_value=маркер_замка) as factory:
                                    сам.assertIs(связь.взять_замок(контур), маркер_замка)
                                    сам.assertEqual(factory.call_args.args, (селектор, 7, корень, сессия))
                                    сам.assertEqual(factory.call_args.kwargs['срок_монотонный'],
                                                    min(контейнер._срок, срок_ms / 1000))
                                    сам.assertIs(связь.взять_замок(контур, _для_очистки=True), маркер_замка)
                                    сам.assertEqual(factory.call_args.kwargs['срок_монотонный'], (срок_ms + 5000) / 1000)
                                    with сам.assertRaises(модуль.ОшибкаОтчёта): связь.взять_замок(контур, _для_очистки=1)
                                    with сам.assertRaises(модуль.ОшибкаОтчёта): связь.взять_замок(object())
                                связь.сверить(контур, корень, фактическая, фактические, сверить_замок)
                                callback.assert_called()
                            else:
                                with сам.assertRaises(модуль.ОшибкаОтчёта):
                                    связь.сверить(контур, корень, фактическая, фактические, сверить_замок)
                                with сам.assertRaises(модуль.ОшибкаОтчёта):
                                    связь.сверить(контур, корень, команда, исполнители, сверить_замок)
                                if случай == 'закрыт': сам.assertEqual(контейнер.состояние, 'закрыт')
                            if случай != 'popen-ok': popen.assert_not_called()
                    finally:
                        if лишний.exists(): лишний.unlink()
                        # Lease подменён и не владеет дочерними процессами.
                        for fd in контроль: os.close(fd)
                        if контур is not None:
                            for fd in контур._дескрипторы: os.close(fd)
                        for fd in контейнер.дескрипторы: os.close(fd)
                        владелец._блокировка.release()

    def test_снимок_сверяет_точную_привязку_до_callback(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            корень = Path(временный).resolve()
            запрос = 'Журнал/этап/запрос.md'
            селектор = ('synthetic',)
            снимок = модуль._тестовый_отпечаток_физического_снимка('Журнал/этап', bytes(range(32)), 'isolated-git.2')
            другой_снимок = модуль._тестовый_отпечаток_физического_снимка('Журнал/этап', bytes(reversed(range(32))), 'isolated-git.2')
            варианты = ('верно', 'корень', 'запрос', 'селектор', 'fd', 'снимок', 'срок',
                        'политика', 'режим', 'контекст', 'callback', 'после-callback', 'ошибка-callback',
                        'владелец-после', 'истёк', 'закрыт')
            for случай in варианты:
                with сам.subTest(случай=случай):
                    владелец = модуль._ТестовыйВладелецЗапуска()
                    владелец._блокировка.acquire()
                    владелец.состояние = 'занят'
                    владелец._поток_владельца = модуль._thread.get_ident()
                    владелец._объект_потока = threading.current_thread()
                    контейнер = модуль._ТестовыйКонтейнерСнимка(владелец, _политика='isolated-git.2')
                    сверка = mock.Mock()
                    контекст = mock.MagicMock()
                    контекст.__enter__.return_value = снимок, сверка
                    try:
                        with mock.patch.object(модуль, '_удержать_тестовый_снимок_без_git_под_замком', return_value=контекст):
                            контейнер.открыть(корень, запрос, селектор, 7, срок=time.monotonic()+5)
                            if случай == 'срок':
                                контейнер._срок += 1
                            elif случай == 'политика':
                                контейнер._ТестовыйКонтейнерСнимка__политика = 'legacy.1'
                            elif случай == 'режим':
                                контейнер._режим = 'чтение'
                            elif случай == 'контекст':
                                контейнер._контекст = mock.MagicMock()
                            elif случай == 'callback':
                                контейнер._значение = (снимок, mock.Mock())
                            elif случай == 'после-callback':
                                сверка.side_effect = lambda: setattr(контейнер, '_срок', контейнер._срок + 1)
                            elif случай == 'ошибка-callback':
                                сверка.side_effect = модуль.ОшибкаОтчёта('ошибка сверки')
                            elif случай == 'владелец-после':
                                сверка.side_effect = lambda: setattr(владелец, '_поток_владельца', -1)
                            elif случай == 'закрыт':
                                контейнер.состояние = 'закрыт'
                            аргументы = (корень / 'other' if случай == 'корень' else корень,
                                         'Журнал/другая/запрос.md' if случай == 'запрос' else запрос,
                                         ('other',) if случай == 'селектор' else селектор,
                                         8 if случай == 'fd' else 7,
                                         другой_снимок if случай == 'снимок' else снимок)
                            if случай == 'верно':
                                контейнер.сверить_привязку(*аргументы)
                                сверка.assert_called_once_with()
                                сам.assertEqual(контейнер.состояние, 'удерживается')
                            else:
                                часы = (mock.patch.object(модуль, '_срок_действителен', side_effect=(True, False))
                                        if случай == 'истёк' else contextlib.nullcontext())
                                with часы, сам.assertRaises(модуль.ОшибкаОтчёта):
                                    контейнер.сверить_привязку(*аргументы)
                                if случай in ('после-callback', 'ошибка-callback', 'владелец-после', 'истёк'):
                                    сверка.assert_called_once_with()
                                else:
                                    сверка.assert_not_called()
                                сам.assertEqual(контейнер.состояние, 'закрыт' if случай == 'закрыт' else 'неизвестно')
                                контекст.__exit__.assert_not_called()
                    finally:
                        # Lease подменён, процессы и внутренние FD отсутствуют.
                        for fd in контейнер.дескрипторы:
                            os.close(fd)
                        владелец._блокировка.release()

