    def test_контейнер_снимка_фиксирует_явную_политику_до_открытия(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        владелец.состояние = 'занят'
        владелец._поток_владельца = модуль._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        контейнер = None
        try:
            for плохая in ('isolated-git.1', None, 1):
                with сам.subTest(политика=плохая), сам.assertRaises(модуль.ОшибкаОтчёта):
                    модуль._ТестовыйКонтейнерСнимка(владелец, _политика=плохая)
                сам.assertIsNone(владелец._контейнер_снимка)
            контейнер = модуль._ТестовыйКонтейнерСнимка(владелец, _политика='isolated-git.2')
            сам.assertEqual(контейнер.политика, 'isolated-git.2')
            with сам.assertRaises(AttributeError):
                контейнер.политика = 'legacy.1'
            снимок = модуль._тестовый_отпечаток_физического_снимка(
                'Журнал/этап', bytes(range(32)), 'isolated-git.2')
            сверка = mock.Mock()
            контекст = mock.MagicMock()
            контекст.__enter__.return_value = снимок, сверка
            with tempfile.TemporaryDirectory(dir='/tmp') as временный:
                корень = Path(временный).resolve()
                with mock.patch.object(модуль, '_удержать_тестовый_снимок_без_git_под_замком',
                                       return_value=контекст) as lease, \
                     mock.patch.object(модуль.subprocess, 'Popen', side_effect=AssertionError('процесс')) as popen:
                    результат = контейнер.открыть(корень, 'Журнал/этап/запрос.md', (), -1, срок=time.monotonic()+5)
                    сам.assertEqual(результат, снимок)
                    сам.assertIs(владелец._контейнер_снимка, контейнер)
                    сам.assertEqual(контейнер.состояние, 'удерживается')
                    сам.assertEqual(lease.call_args.kwargs['_политика'], 'isolated-git.2')
                    контейнер.сверить()
                    сверка.assert_called_once_with()
                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                        контейнер.открыть(корень, 'Журнал/этап/запрос.md', (), -1, срок=time.monotonic()+5)
                    popen.assert_not_called()
        finally:
            # Подменённый lease не открывал файлов и процессов.
            if контейнер is not None:
                for fd in контейнер.дескрипторы:
                    os.close(fd)
            владелец._блокировка.release()

