    def test_новый_отпечаток_связывает_заявленный_pin_не_меняя_прежние(сам):
        import hashlib
        модуль = загрузить_модуль_автоматизации()
        сессия, сырой = 'Журнал/этап', bytes(range(32))
        pin = ('/fixture/git', 'sha256:' + 'a' * 64)
        преды = {}
        for политика, версия in (('legacy.1', '1'), ('isolated-git.2', '2')):
            домен = ('fum.test-physical-lease.' + версия + '\0').encode('ascii')
            с = сессия.encode('utf-8')
            данные = домен + len(с).to_bytes(8, 'big') + с
            if версия == '2':
                профиль = (b'isolated-git.2\0run\0none\0PATH=/bin:/usr/bin\0LC_ALL=C\0GIT_OPTIONAL_LOCKS=0\0'
                           b'GIT_NO_LAZY_FETCH=1\0GIT_NO_REPLACE_OBJECTS=1\0'
                           b'GIT_CONFIG_NOSYSTEM=1\0GIT_CONFIG_GLOBAL=/dev/null\0GIT_ATTR_NOSYSTEM=1\0'
                           b'FUM_CHECK_RUN_ID=<run-id>')
                данные += len(сырой).to_bytes(8, 'big') + сырой + len(профиль).to_bytes(8, 'big') + профиль
            else:
                данные += сырой
            результат = модуль._тестовый_отпечаток_физического_снимка(сессия, сырой, политика)
            сам.assertEqual(результат.значение, 'sha256:' + hashlib.sha256(данные).hexdigest())
            преды[политика] = результат
        новый = модуль._тестовый_отпечаток_физического_снимка(
            сессия, сырой, 'isolated-git.3', _ожидаемый_pin=pin)
        сам.assertEqual(новый.схема, 'fum.test-snapshot.physical-lease.3')
        сам.assertEqual((новый.путь_git, новый.sha256_git), pin)
        профиль3 = (b'isolated-git.3\0run\0none\0PATH=/bin:/usr/bin\0LC_ALL=C\0GIT_OPTIONAL_LOCKS=0\0'
                    b'GIT_NO_LAZY_FETCH=1\0GIT_NO_REPLACE_OBJECTS=1\0'
                    b'GIT_CONFIG_NOSYSTEM=1\0GIT_CONFIG_GLOBAL=/dev/null\0GIT_ATTR_NOSYSTEM=1\0'
                    b'FUM_CHECK_RUN_ID=<run-id>')
        части = (сессия.encode('utf-8'), сырой, профиль3, pin[0].encode('utf-8'), pin[1].encode('ascii'))
        данные = b'fum.test-physical-lease.3\0' + b''.join(len(часть).to_bytes(8, 'big') + часть for часть in части)
        сам.assertEqual(новый.значение, 'sha256:' + hashlib.sha256(данные).hexdigest())
        for другой in (('/fixture/other-git', pin[1]), (pin[0], 'sha256:' + 'b' * 64)):
            изменённый = модуль._тестовый_отпечаток_физического_снимка(
                сессия, сырой, 'isolated-git.3', _ожидаемый_pin=другой)
            сам.assertNotEqual(новый.значение, изменённый.значение)
        for политика, другой in (('isolated-git.3', None), ('isolated-git.3', ('relative', pin[1])),
                                  ('isolated-git.3', (pin[0], 'sha256:' + 'A' * 64)),
                                  ('isolated-git.3', ('/fixture/' + chr(0xd800), pin[1])),
                                  ('isolated-git.2', pin), ('legacy.1', pin)):
            with сам.subTest(политика=политика, pin=другой), сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестовый_отпечаток_физического_снимка(
                    сессия, сырой, политика, _ожидаемый_pin=другой)
        for политика, прежний in преды.items():
            сам.assertEqual(модуль._тестовый_отпечаток_физического_снимка(сессия, сырой, политика), прежний)

