    def test_контейнер_запуска_передаёт_pin_в_существующий_lease(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        pin = ('/fixture/git', 'sha256:' + 'a' * 64)
        снимок = модуль._тестовый_отпечаток_физического_снимка(
            'Журнал/этап', bytes(range(32)), 'isolated-git.3', _ожидаемый_pin=pin)
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        владелец.состояние = 'занят'
        владелец._поток_владельца = модуль._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        контейнер = None
        try:
            with tempfile.TemporaryDirectory(dir='/tmp') as временный:
                корень = Path(временный).resolve(); запрос = 'Журнал/этап/запрос.md'; селектор = ('fixture',)
                контейнер = модуль._ТестовыйКонтейнерСнимка(
                    владелец, _политика='isolated-git.3', _ожидаемый_pin=pin)
                контекст = mock.MagicMock(); контекст.__enter__.return_value = снимок, mock.Mock()
                контекст.__exit__.return_value = False
                with mock.patch.object(модуль, '_удержать_тестовый_снимок_без_git_под_замком',
                                       return_value=контекст) as lease, \
                     mock.patch.object(модуль.subprocess, 'Popen', side_effect=AssertionError('Git')) as popen:
                    получен = контейнер.открыть(корень, запрос, селектор, 7, срок=time.monotonic()+5)
                    сам.assertEqual(получен, снимок)
                    сам.assertEqual(lease.call_args.kwargs['_ожидаемый_pin'], pin)
                    контейнер.сверить_привязку(корень, запрос, селектор, 7, получен)
                    popen.assert_not_called()
                владелец.состояние = 'завершён'
                владелец.терминальные_байты = b'fixture'
                владелец.терминальная_запись_вернула_успех = True
                контейнер.закрыть()
                сам.assertEqual(контейнер.состояние, 'закрыт')
        finally:
            if контейнер is not None and контейнер.дескрипторы:
                # В этой mock-фикстуре lease не владеет дочерними процессами.
                for fd in контейнер.дескрипторы:
                    os.close(fd)
            владелец._блокировка.release()

