    def test_контур_передаёт_сверку_изменённого_якоря_до_go(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        try:
            владелец._поток_владельца = модуль._thread.get_ident()
            владелец._объект_потока = threading.current_thread()
            with tempfile.TemporaryDirectory(dir='/tmp') as каталог:
                корень = Path(каталог).resolve()
                свидетель, якорь = корень / 'witness', корень / 'anchor'
                свидетель.write_bytes(b'witness')
                якорь.write_bytes(b'original anchor')
                sha_свидетеля = hashlib.sha256(b'witness').hexdigest()
                sha_якоря = hashlib.sha256(b'original anchor').hexdigest()
                срок = time.monotonic_ns() // 1_000_000 + 5000
                контур = модуль._ТестовыйКонтурНаблюдателя(
                    владелец, '00112233-4455-4677-8899-aabbccddeeff', срок, срок + 5000)
                контур._состояние = 'запущен'
                контур._политика_среды = 'legacy.1'
                контур._ТестовыйКонтурНаблюдателя__режим_и_связь = ('legacy.1', None, None)
                контур._читатель = mock.Mock()
                контур._читатель.читать_кадр.return_value = ('готов', 111)
                контур._управление = 3
                контур._исполнители = (свидетель, sha_свидетеля, якорь, sha_якоря)
                якорь.write_bytes(b'changed anchor')
                передача = mock.Mock()
                def получить_go(команда, сверить, *, _сверить_go):
                    сам.assertEqual(команда, b'G')
                    сверить()
                    _сверить_go()
                    сам.fail('подмена якоря не обнаружена')
                передача.отправить.side_effect = получить_go
                with mock.patch.object(модуль, '_ТестоваяПередачаНаблюдателя', return_value=передача), \
                     mock.patch.object(модуль.os, 'write') as запись:
                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                        контур.довести(lambda: contextlib.nullcontext(lambda: None))
                    запись.assert_not_called()
                передача.отправить.assert_called_once()
                сам.assertEqual(контур.состояние, 'неизвестно')
                сам.assertIs(владелец._транспорт_binding, контур)
        finally:
            владелец._блокировка.release()

