    def test_отказ_читателя_после_popen_сохраняет_owner_до_go(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        try:
            владелец._поток_владельца = модуль._thread.get_ident()
            владелец._объект_потока = threading.current_thread()
            владелец.активная_запись = Path('/tmp/active-fixture')
            владелец.байты_записи = b'active'
            владелец.запись_вернула_успех = True
            идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
            срок = time.monotonic_ns() // 1_000_000 + 5000
            контур = модуль._ТестовыйКонтурНаблюдателя(владелец, идентификатор, срок, срок + 5000)
            запись = {'идентификатор': идентификатор, 'состояние': 'выполняется'}

            class ПроцессФикстуры:
                pid = 4242

            процесс = ПроцессФикстуры()
            with mock.patch.object(контур, '_проверить_исполнитель'), \
                 mock.patch.object(модуль, 'прочитать_машинную_запись', return_value=(запись, b'active')), \
                 mock.patch.object(модуль, '_тестовая_маска_транспорта', return_value=contextlib.nullcontext(set())), \
                 mock.patch.object(модуль.signal, 'sigpending', return_value=set()), \
                 mock.patch.object(модуль.os, 'pipe', side_effect=[(101, 102), (103, 104)]), \
                 mock.patch.object(модуль.os, 'set_blocking'), \
                 mock.patch.object(модуль.os, 'close') as закрыть, \
                 mock.patch.object(модуль.os, 'write') as записать, \
                 mock.patch.object(модуль, '_КЛАСС_СОБСТВЕННОГО_POPEN', ПроцессФикстуры), \
                 mock.patch.object(модуль.subprocess, 'Popen', return_value=процесс) as popen, \
                 mock.patch.object(модуль, '_ТестовоеЧтениеНаблюдателя', side_effect=RuntimeError('отказ читателя')):
                with сам.assertRaisesRegex(RuntimeError, 'отказ читателя'):
                    контур.запустить(Path('/tmp/witness'), '0' * 64, Path('/tmp/anchor'), '0' * 64,
                                     Path('/tmp'), ('/bin/sleep', '1'),
                                     lambda: contextlib.nullcontext(lambda: None))
                popen.assert_called_once()
                записать.assert_not_called()
                сам.assertEqual(закрыть.call_args_list, [mock.call(101), mock.call(104)])
                сам.assertIs(владелец.процесс, процесс)
                сам.assertEqual(владелец.pid, 4242)
                сам.assertEqual(контур._попытка_popen, 'объект получен')
                сам.assertEqual(контур.состояние, 'неизвестно')
                сам.assertEqual(контур._дескрипторы, [102, 103])
                сам.assertIsNone(контур._передача)
        finally:
            владелец._блокировка.release()

