class ПроверкаОдноразовогоБарьера(unittest.TestCase):
    """Только synthetic модель; межпроцессное исполнение здесь не доказано."""
    удержания = []

    def _фикстура(сам):
        м = загрузить_модуль_автоматизации()
        корень = Path(tempfile.mkdtemp(prefix='fum-life-root-', dir='/private/tmp')).resolve()
        (корень / 'Журнал' / 'сессия').mkdir(parents=True)
        сессия = 'Журнал/сессия/запрос.md'
        опора = Path('/private/tmp').lstat()
        отпечаток = (опора.st_dev, опора.st_ino, опора.st_uid, опора.st_mode & 0o7777)
        def создать():
            return м._ТестовыйОдноразовыйБарьер(отпечаток)
        def владелец(барьер):
            хозяин = м._ТестовыйВладелецЗапуска()
            сам.assertTrue(хозяин._блокировка.acquire(False))
            хозяин.состояние = 'занят'
            хозяин._поток_владельца = м._thread.get_ident()
            хозяин._объект_потока = м.threading.current_thread()
            хозяин._жизненный_барьер = барьер
            return хозяин
        return м, корень, сессия, создать, владелец

    def _войти(сам, м, барьер, хозяин):
        хозяин._фаза_реестра_запуска = 'зарегистрирован'
        м._тестовые_владельцы_запусков.add(хозяин)
        барьер.войти(хозяин)

    def _сымитировать_закрытие(сам, м, хозяин):
        """Только модель полей, не свидетельство реального wait/close/signal."""
        м._тестовые_владельцы_запусков.remove(хозяин)
        хозяин._блокировка.release()
        хозяин.состояние = 'завершён'
        хозяин._фаза_реестра_запуска = 'снят'
        хозяин.терминальная_запись_вернула_успех = True
        хозяин.этап_сбора, хозяин.код_лидера = 'собран', 0
        хозяин._сигнальная_фаза = 'маска возвращена'
        хозяин._сигнальные_данные = {'снятие_маски': 'возвращено'}
        снимок = object.__new__(м._ТестовыйКонтейнерСнимка)
        снимок.состояние, снимок._дескрипторы = 'закрыт', []
        контур = object.__new__(м._ТестовыйКонтурНаблюдателя)
        контур._состояние, контур._дескрипторы = 'закрыт', []
        пара = object.__new__(м._ТестовыйВладелецПарыФайловЗамков)
        пара._состояние, пара._фаза_мьютекса = 'закрыт', None
        пара._fd, пара._первые_fd, пара._взяты, пара.попытка = [], [], [], None
        приём = object.__new__(м._ТестовыйПриёмОпорМоста)
        приём.состояние, приём._fd, приём._владелец_пары = 'закрыт', [], пара
        хозяин._контейнер_снимка, хозяин._транспорт_binding = снимок, контур
        хозяин._приём_опор_binding = приём
        return снимок, контур

    def test_шестая_версия_без_signal_api_отказывает_до_барьера(сам):
        м = загрузить_модуль_автоматизации()
        параметры = (Path('/private/tmp/фикстура'), Path('запрос.md'), 'test', 'root',
                     '00000000-0000-4000-8000-000000000001', 1.0, ['/usr/bin/true'])
        for имя in ('pthread_sigmask', 'sigpending'):
            for режим in ('нет', 'none', 'невызываемый'):
                with сам.subTest(имя=имя, режим=режим):
                    владелец = м._ТестовыйВладелецЗапуска()
                    барьер = м._ТестовыйОдноразовыйБарьер((0, 0, 0, 0o1777))
                    значение = object() if режим == 'невызываемый' else None
                    with mock.patch.object(м.signal, имя, значение), \
                         mock.patch.object(м, '_тестово_запретить_помощника_без_pin') as помощник, \
                         mock.patch.object(м, 'разрешить_сессию',
                                           side_effect=м.ОшибкаОтчёта('сессия вызвана')) as сессия, \
                         mock.patch.object(м._ТестовыйОдноразовыйБарьер, 'начать') as начать, \
                         mock.patch.object(м, '_выполнить_ограниченный_запуск_внутри') as внутри, \
                         mock.patch.object(м.subprocess, 'Popen') as popen:
                        if режим == 'нет':
                            delattr(м.signal, имя)
                        with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'маска и наблюдение сигналов'):
                            м._выполнить_ограниченный_запуск(
                                *параметры, класс_проверки='адресная', тайм_аут_блокировки=1.0,
                                _тестовый_владелец=владелец, _тестовая_версия_6=True,
                                _тестовый_жизненный_барьер=барьер)
                        помощник.assert_not_called()
                        сессия.assert_not_called()
                        начать.assert_not_called()
                        внутри.assert_not_called()
                        popen.assert_not_called()
                    сам.assertEqual(владелец.состояние, 'готов')
