    def test_оба_состояния_запрещают_повтор_в_той_же_фикстуре(сам):
        м, корень, сессия, создать, владелец = сам._фикстура()
        первый_барьер = создать()
        первый_владелец = владелец(первый_барьер)
        первый_барьер.начать(первый_владелец, корень, сессия, '00000000-0000-4000-8000-000000000001')
        сам._войти(м, первый_барьер, первый_владелец)
        активная = Path('/private/tmp') / первый_барьер._имя / 'ACTIVE'
        сам.assertTrue(активная.is_file())
        второй_барьер = создать()
        второй_владелец = владелец(второй_барьер)
        with сам.assertRaises(FileExistsError):
            второй_барьер.начать(второй_владелец, корень, сессия, '00000000-0000-4000-8000-000000000002')
        сам.assertEqual(второй_барьер.состояние, 'неизвестно')
        сам.удержания.append((м, второй_барьер, второй_владелец))
        сам._сымитировать_закрытие(м, первый_владелец)
        with mock.patch.object(м.os, 'write', side_effect=AssertionError('запись чужим owner')), \
             mock.patch.object(м.os, 'close', side_effect=AssertionError('close чужим owner')):
            with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'чужой владелец'):
                первый_барьер.завершить(второй_владелец)
        сам.assertEqual(первый_барьер.состояние, 'активен')
        первый_барьер.завершить(первый_владелец)
        сам.assertEqual(первый_барьер.состояние, 'закрыт')
        сам.assertTrue((активная.parent / 'CLOSED').is_file())
        with mock.patch.object(м.os, 'write', side_effect=AssertionError('повторная запись')), \
             mock.patch.object(м.os, 'close', side_effect=AssertionError('повторный close')):
            with сам.assertRaises(м.ОшибкаОтчёта):
                первый_барьер.завершить(первый_владелец)
        сам.assertEqual(первый_барьер.состояние, 'закрыт')
        сам.assertIsNone(первый_барьер.ошибка)
        третий_барьер = создать()
        третий_владелец = владелец(третий_барьер)
        with сам.assertRaises(FileExistsError):
            третий_барьер.начать(третий_владелец, корень, сессия, '00000000-0000-4000-8000-000000000003')
        сам.удержания.append((м, третий_барьер, третий_владелец))

