    def test_ошибка_сообщения_не_теряет_отказ_освобождения(сам):
        м, корень, сессия, создать, владелец = сам._фикстура()
        барьер = создать()
        хозяин = м._ТестовыйВладелецЗапуска()
        ошибка_освобождения = OSError('освобождение после эффекта')
        class ЗамокСОшибкой:
            def __init__(сам):
                сам._замок = м._thread.allocate_lock()
            def acquire(сам, *аргументы):
                return сам._замок.acquire(*аргументы)
            def locked(сам):
                return сам._замок.locked()
            def release(сам):
                сам._замок.release()
                raise ошибка_освобождения
        хозяин._блокировка = ЗамокСОшибкой()
        def регистрация(переданный, *, зарегистрировать):
            сам.assertTrue(зарегистрировать)
            м._тестовые_владельцы_запусков.add(переданный)
            переданный._фаза_реестра_запуска = 'зарегистрирован'
        def возврат(*аргументы, _владелец, **параметры):
            барьер.войти(_владелец)
            _владелец.состояние = 'завершён'
            return 0
        with mock.patch.object(м, 'разрешить_сессию', return_value=(корень, None, None, None, сессия)), \
             mock.patch.object(м, '_тестово_сменить_регистрацию_запуска', side_effect=регистрация), \
             mock.patch.object(м, '_выполнить_ограниченный_запуск_внутри', side_effect=возврат), \
             mock.patch.object(м._ТестовыйОдноразовыйБарьер, 'отметить_сбой',
                               side_effect=RuntimeError('отказ сообщения')) as сообщение:
            with сам.assertRaises(BaseExceptionGroup) as полученная_группа:
                м._выполнить_ограниченный_запуск(
                    корень, Path(сессия), 'проверить', 'тест',
                    '00000000-0000-4000-8000-000000000001', 1.0, ['/usr/bin/true'],
                    тайм_аут_блокировки=1.0, _тестовый_владелец=хозяин,
                    _тестовая_версия_6=True, _тестовый_жизненный_барьер=барьер)
        сам.assertEqual(хозяин.состояние, 'неизвестно')
        сам.assertIs(хозяин.ошибка, ошибка_освобождения)
        сам.assertEqual(хозяин.ошибки_освобождения, [ошибка_освобождения])
        сам.assertTrue(хозяин._доступ_запрещён)
        сам.assertTrue(any(значение is ошибка_освобождения for значение in полученная_группа.exception.exceptions))
        сам.assertTrue(any(type(значение) is RuntimeError and str(значение) == 'отказ сообщения'
                           for значение in полученная_группа.exception.exceptions))
        сам.assertEqual(сообщение.call_count, 1)
        сам.assertFalse((Path('/private/tmp') / барьер._имя / 'CLOSED').exists())
        сам.удержания.append((м, барьер, хозяин))

    def test_освобождение_не_подменяет_ложную_первичную_ошибку(сам):
        м, корень, сессия, создать, владелец = сам._фикстура()
        барьер = создать()
        хозяин = м._ТестовыйВладелецЗапуска()
        class ЛожнаяОшибка(м.ОшибкаОтчёта):
            def __bool__(сам):
                return False
        первичная = ЛожнаяОшибка('первая причина')
        освобождение = OSError('освобождение после эффекта')
        class ЗамокСОшибкой:
            def __init__(сам):
                сам._замок = м._thread.allocate_lock()
            def acquire(сам, *аргументы):
                return сам._замок.acquire(*аргументы)
            def locked(сам):
                return сам._замок.locked()
            def release(сам):
                сам._замок.release()
                raise освобождение
        хозяин._блокировка = ЗамокСОшибкой()
        def регистрация(переданный, *, зарегистрировать):
            сам.assertTrue(зарегистрировать)
            м._тестовые_владельцы_запусков.add(переданный)
            переданный._фаза_реестра_запуска = 'зарегистрирован'
        def сбой(*аргументы, _владелец, **параметры):
            барьер.войти(_владелец)
            raise первичная
        уведомления = []
        исходное_уведомление = м._ТестовыйОдноразовыйБарьер.отметить_сбой
        def уведомить(переданный_барьер, переданный_владелец, причина):
            уведомления.append(причина)
            return исходное_уведомление(переданный_барьер, переданный_владелец, причина)
        with mock.patch.object(м, 'разрешить_сессию', return_value=(корень, None, None, None, сессия)), \
             mock.patch.object(м, '_тестово_сменить_регистрацию_запуска', side_effect=регистрация), \
             mock.patch.object(м, '_выполнить_ограниченный_запуск_внутри', side_effect=сбой), \
             mock.patch.object(м._ТестовыйОдноразовыйБарьер, 'отметить_сбой', new=уведомить):
            with сам.assertRaises(BaseExceptionGroup) as полученная_группа:
                м._выполнить_ограниченный_запуск(
                    корень, Path(сессия), 'проверить', 'тест',
                    '00000000-0000-4000-8000-000000000001', 1.0, ['/usr/bin/true'],
                    тайм_аут_блокировки=1.0, _тестовый_владелец=хозяин,
                    _тестовая_версия_6=True, _тестовый_жизненный_барьер=барьер)
        сам.assertEqual(хозяин.состояние, 'неизвестно')
        сам.assertIs(хозяин.ошибка, первичная)
        сам.assertIs(барьер.ошибка, первичная)
        сам.assertEqual(хозяин.ошибки_освобождения, [освобождение])
        сам.assertEqual(len(уведомления), 2)
        сам.assertTrue(all(значение is первичная for значение in уведомления))
        сам.assertTrue(any(значение is первичная for значение in полученная_группа.exception.exceptions))
        сам.assertTrue(any(значение is освобождение for значение in полученная_группа.exception.exceptions))
        сам.assertFalse((Path('/private/tmp') / барьер._имя / 'CLOSED').exists())
        сам.удержания.append((м, барьер, хозяин))

