        владелец._поток_владельца = threading.get_ident()
        владелец._объект_потока = threading.current_thread()
        владелец._блокировка.locked.return_value = True
        владелец.состояние, владелец.ошибка = 'занят', None
        читатель = object.__new__(м._ТестовоеЧтениеНаблюдателя)
        читатель._блокировка = threading.Lock()
        читатель._состояние = 'готов'
