    def test_сбой_освобождения_передачи_не_повторяет_неизвестный_запрет(сам):
        import threading
        м = загрузить_модуль_автоматизации()
        for после in (False, True):
            with сам.subTest(после=после):
                class Замок:
                    def __init__(свой):
                        свой.взят = False
                        свой.попытки = 0
                    def acquire(свой, блокировать):
                        свой.взят = True
                        return True
                    def release(свой):
                        свой.попытки += 1
                        if после:
                            свой.взят = False
                        raise OSError('исход release неизвестен')
                владелец = м._ТестовыйВладелецЗапуска()
                владелец.состояние = 'неизвестно'
                владелец.ошибка = м.ОшибкаОтчёта('первый отказ')
                владелец._поток_владельца = threading.get_ident()
                владелец._объект_потока = threading.current_thread()
                приёмник = м._ТестовыйПриёмникБессрочногоНаблюдателя(
                    str(uuid.uuid4()), time.monotonic_ns() // 1_000_000 + 5000, 5000,
                    версия='fum-run-witness.6')
                передача = object.__new__(м._ТестоваяПередачаНаблюдателя)
                передача._блокировка, передача._состояние = Замок(), 'готов-go'
                передача._ошибка, передача._ошибки_освобождения = None, []
                передача._владелец, передача._приёмник = владелец, приёмник
                with mock.patch.object(приёмник, 'запретить_продолжение',
                                       side_effect=AssertionError('повтор запрета')) as запрет, \
                     mock.patch.object(м.os, 'write', side_effect=AssertionError('запись')) as запись:
                    with сам.assertRaises(м.ОшибкаОтчёта):
                        передача.отправить(b'G', lambda: None)
                    запрет.assert_not_called()
                    запись.assert_not_called()
                сам.assertEqual(передача._блокировка.попытки, 1)
                сам.assertEqual(len(передача._ошибки_освобождения), 1)
                сам.assertIsInstance(передача._ошибки_освобождения[0], OSError)
                сам.assertEqual(передача._состояние, 'неизвестно')

