    def test_общий_запрет_выполняется_только_одним_потоком(сам):
        import threading
        м = загрузить_модуль_автоматизации()
        начат, продолжить = threading.Event(), threading.Event()
        результат, ошибки, вызовы, связь = [], [], [], {}
        def выполнить_владельцем():
            try:
                приёмник = м._ТестовыйПриёмникБессрочногоНаблюдателя(
                    str(uuid.uuid4()), time.monotonic_ns() // 1_000_000 + 5000, 5000,
                    версия='fum-run-witness.6')
                связь['приёмник'] = приёмник
                def запретить():
                    вызовы.append(True)
                    начат.set()
                    if not продолжить.wait(timeout=2):
                        raise AssertionError('нет завершения конкурентного опыта')
                    приёмник._фаза = 'неизвестно'
                with mock.patch.object(приёмник, 'запретить_продолжение', side_effect=запретить):
                    результат.append(м._тестово_запретить_приёмник_один_раз(приёмник))
            except BaseException as ошибка:
                ошибки.append(ошибка)
        поток = threading.Thread(target=выполнить_владельцем)
        поток.start()
        try:
            сам.assertTrue(начат.wait(timeout=2))
            with сам.assertRaises(м.ОшибкаОтчёта):
                м._тестово_запретить_приёмник_один_раз(связь['приёмник'])
        finally:
            продолжить.set()
            поток.join(timeout=3)
        сам.assertFalse(поток.is_alive())
        сам.assertFalse(ошибки)
        сам.assertEqual(вызовы, [True])
        сам.assertEqual(результат, ['завершена'])

