                действие._блокировка, действие._ошибка = threading.Lock(), None
                действие._владелец, действие._приёмник = владелец, приёмник
                исходная_фаза = действие._состояние
                ошибки = []
                def вызвать():
                    try:
                        if режим == 'чтение':
                            действие.читать_кадр(срок=приёмник._срок_подготовки)
                        else:
                            действие.отправить(b'G', lambda: None)
                    except BaseException as ошибка:
                        ошибки.append(ошибка)
                try:
                    with mock.patch.object(приёмник, 'запретить_продолжение',
                                           wraps=приёмник.запретить_продолжение) as запрет, \
                         mock.patch.object(м.os, 'fstat') as сведения, \
                         mock.patch.object(м.os, 'read') as чтение, \
                         mock.patch.object(м.os, 'write') as запись:
                        поток = threading.Thread(target=вызвать)
                        поток.start()
                        поток.join(timeout=2)
                        сам.assertFalse(поток.is_alive())
                        сам.assertEqual(len(ошибки), 1)
                        сам.assertIsInstance(ошибки[0], м.ОшибкаОтчёта)
                        запрет.assert_not_called()
                        сведения.assert_not_called()
                        чтение.assert_not_called()
                        запись.assert_not_called()
                    сам.assertEqual(действие._состояние, исходная_фаза)
                    сам.assertEqual(приёмник.состояние, 'готовность')
                    сам.assertFalse(м._тестово_приёмник_запрещён(приёмник))
                finally:
                    владелец._блокировка.release()

