    def test_реентерация_до_регистрации_не_повторяет_запрет(сам):
        import threading
        м = загрузить_модуль_автоматизации()
        вызовы, вложенные = [], []
        class Данные(dict):
            def get(свой, ключ, значение=None):
                результат = super().get(ключ, значение)
                if (ключ == '_общая_попытка_маски' and результат == 'не начата'
                    and not свой.get('_вложенный_вызов', False)):
                    свой['_вложенный_вызов'] = True
                    вложенные.append(м._тестово_запретить_приёмник_один_раз(приёмник))
                return результат
        class Приёмник:
            def __init__(свой):
                object.__setattr__(свой, 'данные', Данные({
                    '_общий_замок_запрета': threading.Lock(),
                    '_pid_общего_запрета': os.getpid(),
                    '_номер_потока_общего_запрета': threading.get_ident(),
                    '_объект_потока_общего_запрета': threading.current_thread(),
                }))
            def __getattribute__(свой, имя):
                if имя == '__dict__':
                    return object.__getattribute__(свой, 'данные')
                return object.__getattribute__(свой, имя)
            def запретить_продолжение(свой):
                вызовы.append(True)
        приёмник = Приёмник()
        сам.assertEqual(м._тестово_запретить_приёмник_один_раз(приёмник), 'завершена')
        сам.assertEqual(вложенные, ['завершена'])
        сам.assertEqual(вызовы, [True])

    def test_вложенная_неизвестная_маска_не_повторяется_внешним_вызовом(сам):
        import threading
        м = загрузить_модуль_автоматизации()
        for после in (False, True):
            with сам.subTest(после=после):
                вызовы, вложенные = [], []
                class Данные(dict):
                    def get(свой, ключ, значение=None):
                        результат = super().get(ключ, значение)
                        if (ключ == '_общая_попытка_маски' and результат == 'не начата'
                            and not свой.get('_вложенный_вызов', False)):
                            свой['_вложенный_вызов'] = True
                            try:
                                м._тестово_запретить_приёмник_один_раз(приёмник)
                            except OSError as ошибка:
                                вложенные.append(ошибка)
                        return результат
                class Приёмник:
                    def __init__(свой):
                        object.__setattr__(свой, 'данные', Данные({
                            '_общий_замок_запрета': threading.Lock(),
                            '_pid_общего_запрета': os.getpid(),
                            '_номер_потока_общего_запрета': threading.get_ident(),
                            '_объект_потока_общего_запрета': threading.current_thread(),
                        }))
                    def __getattribute__(свой, имя):
                        if имя == '__dict__':
                            return object.__getattribute__(свой, 'данные')
                        return object.__getattribute__(свой, имя)
                    def запретить_продолжение(свой):
                        вызовы.append(True)
                class Маска:
                    def __enter__(свой):
                        if not после:
                            raise OSError('маска неизвестна до входа')
                        return None
                    def __exit__(свой, *_):
                        if после:
                            raise OSError('маска неизвестна после выхода')
                приёмник = Приёмник()
                with mock.patch.object(м, '_тестовая_маска_транспорта', side_effect=Маска) as маска:
                    итог = м._тестово_запретить_приёмник_один_раз(приёмник)
                сам.assertEqual(итог, 'неизвестна')
                сам.assertEqual(len(вложенные), 1)
                сам.assertEqual(маска.call_count, 1)
                сам.assertEqual(вызовы, [True] if после else [])
                сам.assertEqual(vars(приёмник)['_общая_попытка_маски'], 'неизвестна')

