    def test_фазы_общего_запрета_готовы_до_ошибки_памяти(сам):
        import threading
        м = загрузить_модуль_автоматизации()
        обычный = м._ТестовыйПриёмникБессрочногоНаблюдателя(
            str(uuid.uuid4()), time.monotonic_ns() // 1_000_000 + 5000, 5000,
            версия='fum-run-witness.6')
        фазы = {'_общая_попытка_маски', '_общая_попытка_захвата',
                '_общая_попытка_запрета', '_общая_ошибка_запрета'}
        сам.assertTrue(фазы <= vars(обычный).keys())
        class Данные(dict):
            def __setitem__(свой, ключ, значение):
                if ключ not in свой:
                    raise AssertionError('недопустима вставка при отказе памяти')
                super().__setitem__(ключ, значение)
        class Приёмник:
            def __init__(свой):
                object.__setattr__(свой, 'данные', Данные({
                    '_общий_замок_запрета': threading.Lock(),
                    '_pid_общего_запрета': os.getpid(),
                    '_номер_потока_общего_запрета': threading.get_ident(),
                    '_объект_потока_общего_запрета': threading.current_thread(),
                    '_общая_попытка_маски': 'не начата',
                    '_общая_попытка_захвата': 'не начата',
                    '_общая_попытка_запрета': 'не начата',
                    '_общая_ошибка_запрета': None,
                }))
            def __getattribute__(свой, имя):
                if имя == '__dict__':
                    return object.__getattribute__(свой, 'данные')
                return object.__getattribute__(свой, имя)
        приёмник = Приёмник()
        отказ = MemoryError('модельный отказ регистрации')
        with mock.patch.object(м, '_тестово_зарегистрировать_общую_маску', side_effect=отказ) as регистрация:
            with сам.assertRaises(MemoryError):
                м._тестово_запретить_приёмник_один_раз(приёмник)
            сам.assertIs(vars(приёмник)['_общая_ошибка_запрета'], отказ)
            сам.assertEqual(vars(приёмник)['_общая_попытка_маски'], 'неизвестна')
            сам.assertEqual(м._тестово_запретить_приёмник_один_раз(приёмник), 'неизвестна')
            регистрация.assert_called_once()

