    def test_ошибки_тела_и_запрета_сохраняются_вместе(сам):
        import threading
        м = загрузить_модуль_автоматизации()
        for режим in ('контур', 'передача'):
            with сам.subTest(режим=режим):
                владелец = м._ТестовыйВладелецЗапуска()
                владелец._блокировка.acquire()
                владелец._поток_владельца = threading.get_ident()
                владелец._объект_потока = threading.current_thread()
                приёмник = м._ТестовыйПриёмникБессрочногоНаблюдателя(
                    str(uuid.uuid4()), time.monotonic_ns() // 1_000_000 + 5000, 5000,
                    версия='fum-run-witness.6')
                первичная, вторичная = KeyboardInterrupt('сигнал'), RuntimeError('отказ запрета')
                if режим == 'контур':
                    действие = object.__new__(м._ТестовыйКонтурНаблюдателя)
                    действие._блокировка, действие._поток_шага = threading.Lock(), None
                    действие._состояние, действие._ошибка = 'готов', None
                    действие._ошибки_освобождения = []
                    действие._владелец, действие._приёмник = владелец, приёмник
                    владелец._транспорт_binding = действие
                    def вызвать():
                        def прервать():
                            raise первичная
                        действие._шаг('готов', прервать)
                else:
                    действие = object.__new__(м._ТестоваяПередачаНаблюдателя)
                    действие._блокировка, действие._состояние = threading.Lock(), 'готов-go'
                    действие._ошибка, действие._ошибки_освобождения = None, []
                    действие._владелец, действие._приёмник = владелец, приёмник
                    действие._отправить_внутри = mock.Mock(side_effect=первичная)
                    def вызвать():
                        действие.отправить(b'G', lambda: None)
                try:
                    with mock.patch.object(приёмник, 'запретить_продолжение', side_effect=вторичная) as запрет:
                        with сам.assertRaises(BaseExceptionGroup) as ошибки:
                            вызвать()
                        сам.assertEqual(ошибки.exception.exceptions, (первичная, вторичная))
                        запрет.assert_called_once()
                finally:
                    владелец._блокировка.release()

