    def _создать_предпуск_до_active(сам, *, _команда=None):
        import threading
        if (сам.исполнитель_наблюдателя is None or сам.отпечаток_наблюдателя is None
            or сам.исполнитель_якоря is None or сам.отпечаток_якоря is None
            or сам.удержать_неизвестный_исход is not True):
            сам.skipTest('нужны закреплённые исполнители и владелец неизвестного исхода')
        м = загрузить_модуль_автоматизации()
        каталог = tempfile.TemporaryDirectory(prefix='fum-preactive-', dir='/private/tmp')
        каталог._finalizer.detach()
        корень = Path(каталог.name).resolve()
        идентификатор = str(uuid.uuid4())
        владелец = м._ТестовыйВладелецЗапуска()
        сам.assertTrue(владелец._блокировка.acquire(False))
        владелец.состояние = 'занят'
        владелец._поток_владельца = м._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        край = time.monotonic_ns() // 1_000_000 + 8000
        контур = м._ТестовыйКонтурНаблюдателя(
            владелец, идентификатор, край, None, длительность_цели_ms=2000)
        удержание = {'каталог': каталог, 'владелец': владелец, 'контур': контур}
        сам.удерживаемые_предпуски.append(удержание)
        цель = корень / 'цель-запущена'
        готовность = контур.предпустить(
            Path(сам.исполнитель_наблюдателя), сам.отпечаток_наблюдателя,
            Path(сам.исполнитель_якоря), сам.отпечаток_якоря,
            корень, ('/usr/bin/touch', str(цель)) if _команда is None else _команда)
        сам.assertEqual(готовность[0], 'готов')
        сам.assertIsNone(владелец.активная_запись)
        сам.assertFalse(владелец.запись_вернула_успех)
        сам.assertFalse(цель.exists())
        return м, каталог, владелец, контур, цель, удержание, идентификатор, готовность

    def test_реальный_предпуск_можно_отменить_до_active_без_запуска_цели(сам):
        м, каталог, владелец, контур, цель, удержание, идентификатор, готовность = сам._создать_предпуск_до_active()
        итог = контур.отказать_до_active()
        сам.assertEqual(итог.идентификатор, идентификатор)
        сам.assertEqual((итог.pid, итог.якорь, итог.код), (владелец.pid, готовность[1], 0))
        сам.assertEqual(tuple(кадр[:4] for кадр in итог.кадры), (b'FUA1', b'FUC1'))
        сам.assertEqual(контур._передача.попытки, ((b'A', 1),))
        сам.assertEqual(контур._попытка_eof, b'')
        сам.assertEqual(владелец.этап_сбора, 'собран')
        сам.assertIsNone(владелец.активная_запись)
        сам.assertFalse(владелец.запись_вернула_успех)
        сам.assertFalse(цель.exists())
        контур.закрыть_после_отказа_предпуска()
        сам.assertEqual((контур.состояние, контур._дескрипторы), ('закрыт', []))
        владелец._блокировка.release()
        каталог.cleanup()
        сам.удерживаемые_предпуски.remove(удержание)

    def _проверить_git_снимок_и_предпуск(сам, вариант):
        import stat
        import threading
        м = загрузить_модуль_автоматизации()
        каталог = tempfile.TemporaryDirectory(prefix='fum-preactive-', dir='/private/tmp')
        каталог._finalizer.detach()
        область = tempfile.TemporaryDirectory(prefix='fum-snapshot-lock-', dir='/private/tmp')
        область._finalizer.detach()
        корень = Path(каталог.name).resolve()
        замки = Path(область.name).resolve()
        сессия = 'Журнал/этап/запрос.md'
        запрос = корень / сессия
        запрос.parent.mkdir(parents=True)
        запрос.write_bytes(b'request\n')
        отчёт = запрос.with_name('отчёт.md')
        отчёт.write_bytes(b'report\n')
        шаблон = замки / 'template'
        шаблон.mkdir(mode=0o700)
        окружение = {
            'PATH': '/usr/bin:/bin', 'LC_ALL': 'C', 'GIT_OPTIONAL_LOCKS': '0',
            'GIT_NO_LAZY_FETCH': '1', 'GIT_NO_REPLACE_OBJECTS': '1',
            'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_GLOBAL': '/dev/null', 'GIT_ATTR_NOSYSTEM': '1',
        }
        for аргументы in (
            ('init', '-q', '--template=' + str(шаблон)),
            ('add', '--', сессия, str(Path(сессия).with_name('отчёт.md'))),
            ('-c', 'user.name=FUM Tests', '-c', 'user.email=fum-tests@example.invalid',
             'commit', '-q', '-m', 'fixture'),
        ):
            subprocess.run(('/usr/bin/git', '-C', str(корень), '-c', 'core.fsmonitor=false',
                            '-c', 'core.hooksPath=/dev/null', '-c', 'commit.gpgsign=false',
                            '-c', 'maintenance.auto=false', '-c', 'gc.auto=0',
                            '-c', 'index.version=2', '-c', 'core.attributesFile=/dev/null', *аргументы),
                           cwd=корень, env=окружение, stdin=subprocess.DEVNULL,
                           stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, check=True)
        (корень / '.git/config').write_bytes(м._ТЕСТОВАЯ_КОНФИГУРАЦИЯ_БЕЗ_ПРЕОБРАЗОВАНИЙ)
        (корень / '.git/config').chmod(0o600)
        (корень / '.git/index').chmod(0o600)
        дескрипторы = []
        fd = м._приобрести_fd(дескрипторы, os.open, замки,
                              os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        сведения = os.fstat(fd)
        селектор = ('fum.test-lock-root.2', str(замки), сведения.st_dev, сведения.st_ino,
                    сведения.st_uid, stat.S_IMODE(сведения.st_mode), сессия, str(корень))
        владелец = м._ТестовыйВладелецЗапуска()
        сам.assertTrue(владелец._блокировка.acquire(False))
        владелец.состояние = 'занят'
        владелец._поток_владельца = м._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        контейнер = м._ТестовыйКонтейнерСнимка(владелец, _политика='isolated-git.2')
        удержание = {'каталог': каталог, 'область': область, 'владелец': владелец,
                     'контейнер': контейнер, 'дескрипторы': дескрипторы}
        сам.удерживаемые_предпуски.append(удержание)
        снимок = контейнер.открыть(корень, сессия, селектор, fd, срок=time.monotonic()+30.0)
        идентификатор = str(uuid.uuid4())
        контур = м._ТестовыйКонтурНаблюдателя(
            владелец, идентификатор, time.monotonic_ns() // 1_000_000 + 8000,
            None, длительность_цели_ms=2000)
        удержание['контур'] = контур
        контур.предпустить(Path(сам.исполнитель_наблюдателя), сам.отпечаток_наблюдателя,
                           Path(сам.исполнитель_якоря), сам.отпечаток_якоря,
                           корень, ('/usr/bin/true',), _тестовый_снимок=снимок)
        if вариант == 'подмена метки FD до A':
            корневой_fd = контейнер.дескрипторы[0]
            настоящий_fstat = м.os.fstat

            def подменить_метку(номер):
                сведения = настоящий_fstat(номер)
                if номер != корневой_fd:
                    return сведения
                поля = list(сведения)
                поля[1] += 1
                return os.stat_result(поля)

            with mock.patch.object(м.os, 'fstat', side_effect=подменить_метку) as проверка, \
                 mock.patch.object(м.os, 'write', side_effect=AssertionError('передача до сверки FD')) as передача:
                with сам.assertRaises(м.ОшибкаОтчёта):
                    контур.отказать_до_active()
                передача.assert_not_called()
                сам.assertTrue(any(вызов.args == (корневой_fd,) for вызов in проверка.call_args_list))
            сам.assertEqual(контур.состояние, 'неизвестно')
            сам.assertEqual(контейнер.состояние, 'неизвестно')
            сам.assertIsNone(владелец.активная_запись)
            with mock.patch.object(м.os, 'fstat', side_effect=AssertionError('повтор fstat')) as проверка:
                with сам.assertRaises(м.ОшибкаОтчёта):
                    контур._сверить_предпуск_до_active()
                with сам.assertRaises(м.ОшибкаОтчёта):
                    контейнер.сверить()
                проверка.assert_not_called()
            return
        if вариант == 'подмена до A':
            контейнер._контекст = object()
            with mock.patch.object(м.os, 'write', side_effect=AssertionError('передача до сверки')) as передача:
                with сам.assertRaises(м.ОшибкаОтчёта):
                    контур.отказать_до_active()
                передача.assert_not_called()
            сам.assertEqual(контур.состояние, 'неизвестно')
            сам.assertEqual(контейнер.состояние, 'неизвестно')
            сам.assertEqual(контур._передача.попытки, ())
            сам.assertIsNone(владелец.активная_запись)
            return
        свидетельство = контур.отказать_до_active()
        контур.закрыть_после_отказа_предпуска()
        причина = м._ТестовыйОтказИстории('fixture: отказ до active')
        if вариант == 'неизвестная проверка FD':
            with mock.patch.object(м.os, 'fstat', side_effect=OSError('модельный отказ fstat')) as проверка, \
                 mock.patch.object(м, '_тестовый_допуск_git',
                                   side_effect=AssertionError('Git после отказа fstat')) as допуск, \
                 mock.patch.object(м, '_отпустить_зарегистрированный_fd',
                                   side_effect=AssertionError('закрытие после отказа fstat')) as закрытие:
                with сам.assertRaisesRegex(OSError, 'модельный отказ fstat') as ошибка:
                    контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
                проверка.assert_called_once()
                допуск.assert_not_called()
                закрытие.assert_not_called()
            сам.assertIs(контейнер.ошибка, ошибка.exception)
            сам.assertEqual(контейнер.состояние, 'неизвестно')
            with mock.patch.object(м.os, 'fstat', side_effect=AssertionError('повтор fstat после UNKNOWN')) as проверка:
                with сам.assertRaises(м.ОшибкаОтчёта):
                    контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
                проверка.assert_not_called()
            return
        if вариант == 'неизвестный исход охраны':
            исходная_охрана = м._тестовый_допуск_git

            @contextlib.contextmanager
            def потеря_после_охраны():
                with исходная_охрана():
                    yield
                raise OSError('модельный неизвестный исход после освобождения охраны')

            исходный_контекст = контейнер._контекст
            исходные_fd = контейнер.дескрипторы
            with mock.patch.object(м, '_тестовый_допуск_git', new=потеря_после_охраны), \
                 mock.patch.object(м, '_отпустить_зарегистрированный_fd',
                                   side_effect=AssertionError('освобождение после UNKNOWN')) as отпустить:
                with сам.assertRaisesRegex(OSError, 'модельный неизвестный исход') as ошибка:
                    контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
                отпустить.assert_not_called()
            сам.assertIs(контейнер.ошибка, ошибка.exception)
            сам.assertEqual(контейнер.состояние, 'неизвестно')
            сам.assertIs(контейнер._контекст, исходный_контекст)
            сам.assertEqual(контейнер.дескрипторы, исходные_fd)
            with mock.patch.object(м, '_тестовый_допуск_git',
                                   side_effect=AssertionError('повтор после UNKNOWN')) as допуск:
                with сам.assertRaises(м.ОшибкаОтчёта):
                    контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
                допуск.assert_not_called()
            return
        сам.assertEqual(вариант, 'успех')
        исходный_контекст = контейнер._контекст
        контейнер._контекст = object()
        with mock.patch.object(м, '_тестовый_допуск_git',
                               side_effect=AssertionError('Git до сверки lease')) as допуск:
            with сам.assertRaises(м.ОшибкаОтчёта):
                контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
            допуск.assert_not_called()
        контейнер._контекст = исходный_контекст
        исходный_fd = контейнер._дескрипторы[0]
        контейнер._дескрипторы[0] = fd
        with mock.patch.object(м, '_тестовый_допуск_git',
                               side_effect=AssertionError('Git до сверки FD')) as допуск:
            with сам.assertRaises(м.ОшибкаОтчёта):
                контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
            допуск.assert_not_called()
        контейнер._дескрипторы[0] = исходный_fd
        исходная_связь = контур._предпуск_связь
        контур._предпуск_связь = (*исходная_связь[:2], object(), *исходная_связь[3:])
        with mock.patch.object(м, '_тестовый_допуск_git',
                               side_effect=AssertionError('Git до сверки процесса')) as допуск:
            with сам.assertRaises(м.ОшибкаОтчёта):
                контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
            допуск.assert_not_called()
        контур._предпуск_связь = исходная_связь
        подмена = свидетельство._replace(pid=свидетельство.pid + 1)
        with mock.patch.object(м, '_тестовый_допуск_git',
                               side_effect=AssertionError('Git до подтверждения отказа')) as допуск:
            with сам.assertRaises(м.ОшибкаОтчёта):
                контейнер.отменить_до_active(причина, _свидетельство_предпуска=подмена)
            допуск.assert_not_called()
        контейнер.отменить_до_active(причина, _свидетельство_предпуска=свидетельство)
