    def _создать_предпуск_с_участком(сам, *, _команда=None):
        м, каталог, владелец, контур, цель, удержание, идентификатор, _ = сам._создать_предпуск_до_active(
            _команда=_команда)
        фикстура = ПроверкаЗакреплённогоФайлаЗамка('runTest')
        удержание['фикстура_пары'] = фикстура
        удержание['модуль'] = м
        _, корень, сессия, _, _, _, _ = фикстура.подготовить_владельца_пары(
            _тестовый_корень=цель.parent, _модуль=м)
        пара = фикстура.владелец_пары
        пара.подготовить()
        active = (корень / Path(сессия).parent / 'материалы/запуски-проверок'
                  / f'1_{идентификатор}.json')
        участок = контур.подготовить_участок(пара, active)
        return м, каталог, владелец, контур, цель, удержание, фикстура, пара, участок, active

    def test_сверка_транспорта_не_требует_удерживать_пару(сам):
        м, каталог, владелец, контур, цель, удержание, фикстура, пара, участок, active = (
            сам._создать_предпуск_с_участком())
        try:
            сам.assertEqual(пара.состояние, 'подготовлен')
            with mock.patch.object(м.fcntl, 'flock', side_effect=AssertionError('flock при сверке транспорта')), \
                 mock.patch.object(м.os, 'open', side_effect=AssertionError('open при сверке транспорта')), \
                 mock.patch.object(м, 'прочитать_машинную_запись',
                                   side_effect=AssertionError('чтение записи при сверке транспорта')):
                участок._сверить_транспорт()
                исходный_pid = владелец.pid
                try:
                    владелец.pid = исходный_pid + 1
                    with сам.assertRaises(м.ОшибкаОтчёта):
                        участок._сверить_транспорт()
                finally:
                    владелец.pid = исходный_pid
            сам.assertFalse(active.exists())
            сам.assertFalse(цель.exists())
        finally:
            if контур.состояние == 'предпуск готов' and not участок._active_начат:
                контур.отказать_до_active()
                контур.закрыть_после_отказа_предпуска()
                пара.закрыть()
                фикстура.завершить(м)
                владелец._блокировка.release()
                каталог.cleanup()
                сам.удерживаемые_предпуски.remove(удержание)

