    def test_начатый_active_не_допускает_отмену_как_до_active(сам):
        м, _, владелец, контур, цель, удержание, фикстура, пара, участок, active = (
            сам._создать_предпуск_с_участком())
        удержание['участок'] = участок
        настоящий_close = os.close
        поздние_закрытия = []
        def закрыть(fd):
            if пара._состояние == 'неизвестно':
                поздние_закрытия.append(fd)
                return None
            return настоящий_close(fd)
        with mock.patch.object(м.os, 'close', side_effect=закрыть):
            with сам.assertRaises(BaseExceptionGroup):
                with участок.удержать():
                    маркеры = tuple(м._тестовые_владельцы_замков)
                    сам.assertEqual(len(маркеры), 2)
                    сам.assertEqual(участок.начать_active(), active)
                    сам.assertEqual(контур._предпуск_попытка_active, 'начата')
                    with mock.patch.object(м.os, 'write', side_effect=AssertionError('ошибочный A')) as запись:
                        with сам.assertRaises(м.ОшибкаОтчёта):
                            контур.отказать_до_active()
                        запись.assert_not_called()
                    raise ValueError('модельный сбой после начала active')
        сам.assertEqual(поздние_закрытия, [])
        сам.assertTrue(all(маркер in м._тестовые_владельцы_замков for маркер in маркеры))
        сам.assertTrue(all(маркер.группа.неизвестно for маркер in маркеры))
        сам.assertFalse(active.exists())
        сам.assertFalse(цель.exists())
        сам.assertEqual(контур.состояние, 'неизвестно')
        сам.assertEqual(участок._фаза, 'неизвестно')
        сам.assertIs(участок._связь[0], пара)

