    def test_цель_работает_между_двумя_захватами_пары(сам):
        import select
        if сам.исполнитель_короткой_цели is None or сам.отпечаток_короткой_цели is None:
            сам.skipTest('нужна явно закреплённая короткая цель')
        путь_цели = Path(сам.исполнитель_короткой_цели)
        сам.assertTrue(путь_цели.is_absolute() and путь_цели.is_file())
        сам.assertEqual(hashlib.sha256(путь_цели.read_bytes()).hexdigest(), сам.отпечаток_короткой_цели)
        м, каталог, владелец, контур, _, удержание, фикстура, пара, участок, active = (
            сам._создать_предпуск_с_участком(_команда=(str(путь_цели), '1')))
        завершено = False
        try:
            active.parent.mkdir(parents=True)
            приёмник, читатель, передача = контур._приёмник, контур._читатель, контур._передача
            with участок.удержать_начало() as текущий:
                сам.assertEqual(текущий.начать_active(), active)
                байты_active = м.канонические_машинные_байты(
                    {'идентификатор': контур._идентификатор, 'состояние': 'выполняется'})
                with пара.использовать_удержание(срок_монотонный=пара._срок) as сверить:
                    м.атомарно_записать_байты(active, байты_active, только_новый=True,
                                             перед_публикацией=сверить)
                владелец.активная_запись = active
                владелец.байты_записи = байты_active
                владелец.запись_вернула_успех = True
                текущий.подтвердить_active()
                контур.отправить_go_раздельного_участка(текущий)
            сам.assertEqual(пара.состояние, 'подготовлен')
            with mock.patch.object(м.fcntl, 'flock', side_effect=AssertionError('ранний flock')) as flock, \
                 mock.patch.object(м, 'прочитать_машинную_запись',
                                   side_effect=AssertionError('раннее чтение')) as чтение:
                with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'сначала дождитесь'):
                    with участок.удержать_завершение():
                        сам.fail('ранний повторный захват недопустим')
                flock.assert_not_called()
                чтение.assert_not_called()
            сам.assertEqual(участок._фаза, 'между захватами')
            сам.assertEqual(читатель.читать_кадр(срок=контур._срок_подготовки)[0], 'запущен')
            сам.assertFalse(select.select([контур._статус], [], [], 0)[0],
                            'цель завершилась до проверки конкуренции')
            имя = 'fum-check-runs-' + hashlib.sha256(
                f'{пара._корень}\0{пара._сессия}'.encode('utf-8')).hexdigest() + '.lock'
            пути = [str(Path(опора[0][1]) / имя) for опора in пара._опоры]
            метки = [(с.st_dev, с.st_ino) for с in map(os.fstat, пара._fd)]
            программа = _программа_конкурента_пары()
            удержание['фаза_конкурента'] = 'popen начат'
            конкурент = subprocess.Popen(
                [sys.executable, '-I', '-S', '-B', '-c', программа, 'один', *пути,
                 *(str(значение) for метка in метки for значение in метка)],
                env={}, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                start_new_session=True, close_fds=True)
            удержание['конкурент'] = конкурент
            удержание['фаза_конкурента'] = 'запущен'
            выход, ошибки = конкурент.communicate(timeout=3)
            удержание['фаза_конкурента'] = 'завершён'
            сам.assertEqual((конкурент.returncode, выход, ошибки), (0, b'FF', b''))
            сам.assertFalse(select.select([контур._статус], [], [], 0)[0],
                            'цель завершилась до конца проверки конкуренции')
            сам.assertEqual(читатель.читать_кадр(срок=приёмник.край_ожидания_цели), ('статус', 0))
            with mock.patch.object(м.fcntl, 'flock', side_effect=AssertionError('flock при очистке')) as flock:
                участок.отправить_очистку_без_замка()
                сам.assertEqual(участок.дождаться_очистки_без_замка(), ('очистка-наблюдена', 0, False))
                фактическое_чтение = os.read
                получен_конец = []
                def читать(дескриптор, размер):
                    данные = фактическое_чтение(дескриптор, размер)
                    if дескриптор == контур._статус and данные == b'':
                        получен_конец.append(True)
                    return данные
                with mock.patch.object(м, '_кандидат_собрать_статус_лидера',
                                       wraps=м._кандидат_собрать_статус_лидера) as сбор, \
                     mock.patch.object(м.os, 'read', side_effect=читать):
                    участок.подтвердить_наблюдение()
                    сбор.assert_called_once()
                    сам.assertEqual(получен_конец, [True])
                    with mock.patch.object(м, '_кандидат_собрать_статус_лидера',
                                           side_effect=AssertionError('повторный wait')), \
                         mock.patch.object(м.os, 'read', side_effect=AssertionError('повторный EOF')):
                        итог = контур.принять_успешное_наблюдение_участка(участок)
                flock.assert_not_called()
            with участок.удержать_завершение() as текущий:
                терминал = м.канонические_машинные_байты({
                    'идентификатор': контур._идентификатор, 'состояние': 'завершён',
                    'статус': 'успешно', 'код_завершения': 0})
                with пара.использовать_удержание(срок_монотонный=пара._срок) as сверить:
                    м.атомарно_записать_байты(active, терминал, перед_публикацией=сверить)
                владелец.терминальные_байты = терминал
                владелец.терминальная_запись_вернула_успех = True
                текущий.подтвердить_terminal()
            сам.assertEqual((итог.статус, итог.код_записи), ('успешно', 0))
            сам.assertEqual(участок._попытка_сбора, ('получен', 0))
            сам.assertEqual(участок._попытка_eof, b'')
            сам.assertEqual(active.read_bytes(), терминал)
            контур.закрыть_после_успешного_участка()
            завершено = True
        finally:
            if not участок._active_начат and контур.состояние == 'предпуск готов':
                контур.отказать_до_active()
                контур.закрыть_после_отказа_предпуска()
                завершено = True
