    def test_unknown_записи_A_не_повторяет_write_wait_или_read(сам):
        м, _, владелец, контур, цель, _, _, _ = сам._создать_предпуск_до_active()
        настоящий_write = os.write
        def записать_и_потерять_результат(fd, данные):
            if fd == контур._управление and данные == b'A':
                сам.assertEqual(настоящий_write(fd, данные), 1)
                raise OSError('модельный UNKNOWN после записи A')
            return настоящий_write(fd, данные)
        with mock.patch.object(м.os, 'write', side_effect=записать_и_потерять_результат) as запись:
            with сам.assertRaisesRegex(OSError, 'UNKNOWN'):
                контур.отказать_до_active()
            сам.assertEqual(запись.call_count, 1)
        сам.assertEqual(контур.состояние, 'неизвестно')
        сам.assertEqual(контур._передача.попытки, ((b'A', 'начата'),))
        сам.assertIsNone(контур._попытка_eof)
        сам.assertEqual(владелец.этап_сбора, 'не начат')
        исходная_ошибка = контур._ошибка
        with mock.patch.object(м.os, 'write', side_effect=AssertionError('повтор write')) as запись, \
             mock.patch.object(м.os, 'read', side_effect=AssertionError('повтор read')) as чтение, \
             mock.patch.object(м, '_кандидат_собрать_статус_лидера',
                               side_effect=AssertionError('повтор wait')) as сбор:
            with сам.assertRaises(м.ОшибкаОтчёта):
                контур.отказать_до_active()
            запись.assert_not_called(); чтение.assert_not_called(); сбор.assert_not_called()
        внешняя_ошибка = OSError('внешний отказ')
        with mock.patch.object(м, '_закрыть_удержанные_fd',
                               side_effect=AssertionError('close при UNKNOWN')) as закрыть, \
             mock.patch.object(м, '_кандидат_собрать_статус_лидера',
                               side_effect=AssertionError('wait при UNKNOWN')) as сбор:
            м._очистить_ошибочный_штатный_транспорт(владелец, внешняя_ошибка)
            закрыть.assert_not_called(); сбор.assert_not_called()
        сам.assertIs(контур._ошибка, исходная_ошибка)
        сам.assertIs(владелец.ошибка, внешняя_ошибка)
        сам.assertFalse(цель.exists())

    def test_unknown_после_wait_не_повторяет_сбор_или_eof(сам):
        м, _, владелец, контур, цель, _, _, _ = сам._создать_предпуск_до_active()
        настоящий_сбор = м._кандидат_собрать_статус_лидера
        def собрать_и_потерять_результат(*args, **kwargs):
            сам.assertEqual(настоящий_сбор(*args, **kwargs), 0)
            raise OSError('модельный UNKNOWN после wait')
        with mock.patch.object(м, '_кандидат_собрать_статус_лидера',
                               side_effect=собрать_и_потерять_результат) as сбор:
            with сам.assertRaisesRegex(OSError, 'UNKNOWN'):
                контур.отказать_до_active()
