        сам.assertEqual(контур.состояние, 'неизвестно')
        сам.assertEqual(контур._предпуск_попытка_сбора, 'начата')
        сам.assertEqual(владелец.этап_сбора, 'сбор начат')
        сам.assertEqual(владелец.процесс.returncode, 0)
        сам.assertIsNone(контур._попытка_eof)
        with mock.patch.object(м.os, 'read', side_effect=AssertionError('повтор EOF')) as чтение, \
             mock.patch.object(м, '_кандидат_собрать_статус_лидера',
                               side_effect=AssertionError('повтор wait')) as сбор:
            with сам.assertRaises(м.ОшибкаОтчёта):
                контур.отказать_до_active()
            чтение.assert_not_called(); сбор.assert_not_called()
        сам.assertFalse(цель.exists())

