    def test_unknown_в_контексте_сохраняет_fd_каталога_замка(сам):
        м = загрузить_модуль_автоматизации()
        каталог = tempfile.TemporaryDirectory(prefix='fum-legacy-owner-', dir='/private/tmp')
        каталог._finalizer.detach()
        корень = Path(каталог.name).resolve()
        замки = корень / 'locks'
        замки.mkdir(mode=0o700)
        владелец = м._ТестовыйВладелецЗапуска()
        сам.удерживаемые_предпуски.append({'каталог': каталог, 'владелец': владелец})
        ошибка = ValueError('модельный сбой внутри контекста')
        with mock.patch.object(м, 'разрешить_сессию',
                               return_value=(корень, None, None, None, 'Журнал/этап/запрос.md')), \
             mock.patch.object(м, '_закрыть_удержанные_fd',
                               side_effect=AssertionError('закрытие при UNKNOWN')) as закрытие:
            with сам.assertRaises(ValueError) as итог:
                with м._закрепить_каталог_прежнего_замка(
                    корень, Path('запрос.md'), замки, _тестовый_владелец=владелец
                ) as (_, _, fd):
                    сам.assertEqual(владелец._каталог_legacy_fd, [fd])
                    raise ошибка
            закрытие.assert_not_called()
        сам.assertIs(итог.exception, ошибка)
        сам.assertEqual(владелец._каталог_legacy_состояние, 'неизвестно')
        сам.assertIn(владелец, м._тестовые_каталоги_legacy)
        сам.assertEqual(os.fstat(fd).st_ino, замки.stat().st_ino)

