    def _проверить_сбой_регистрации_fd_каталога(сам, закрыть_до_ошибки):
        м = загрузить_модуль_автоматизации()
        каталог = tempfile.TemporaryDirectory(prefix='fum-legacy-owner-', dir='/private/tmp')
        каталог._finalizer.detach()
        корень = Path(каталог.name).resolve()
        замки = корень / 'locks'
        замки.mkdir(mode=0o700)
        владелец = м._ТестовыйВладелецЗапуска()
        сам.удерживаемые_предпуски.append({'каталог': каталог, 'владелец': владелец})
        class ОтказРегистрации(list):
            def append(сам, fd):
                raise OSError('модельный отказ регистрации')
        владелец._каталог_legacy_fd = ОтказРегистрации()
        открыть, закрыть = os.open, os.close
        открытые = []
        def открыть_с_учётом(*args, **kwargs):
            fd = открыть(*args, **kwargs)
            открытые.append(fd)
            return fd
        def потерять_результат_close(fd):
            if fd != открытые[-1]:
                return закрыть(fd)
            if закрыть_до_ошибки:
                закрыть(fd)
            raise OSError('модельный отказ компенсации')
        with mock.patch.object(м, 'разрешить_сессию',
                               return_value=(корень, None, None, None, 'Журнал/этап/запрос.md')), \
             mock.patch.object(м.os, 'open', side_effect=открыть_с_учётом), \
             mock.patch.object(м.os, 'close', side_effect=потерять_результат_close) as закрытие:
            with сам.assertRaises(BaseExceptionGroup) as итог:
                with м._закрепить_каталог_прежнего_замка(
                    корень, Path('запрос.md'), замки, _тестовый_владелец=владелец
                ):
                    сам.fail('контекст не должен начаться')
            закрытие.assert_called_once_with(открытые[0])
        сам.assertEqual(len(открытые), 1)
        сам.assertEqual(владелец._каталог_legacy_попытка,
                        ('компенсационный close', открытые[0], 'начата'))
        сам.assertIs(владелец._каталог_legacy_ошибка, итог.exception)
        сам.assertEqual(len(итог.exception.exceptions), 2)
        if not закрыть_до_ошибки:
            сам.assertEqual(os.fstat(открытые[0]).st_ino, замки.stat().st_ino)

