    def test_внешняя_очистка_удерживает_зарегистрированный_предпуск(сам):
        import threading
        м = загрузить_модуль_автоматизации()
        владелец = м._ТестовыйВладелецЗапуска()
        сам.assertTrue(владелец._блокировка.acquire(False))
        владелец.состояние = 'занят'
        владелец._поток_владельца = м._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        контур = м._ТестовыйКонтурНаблюдателя(
            владелец, str(uuid.uuid4()), time.monotonic_ns() // 1_000_000 + 8000,
            None, длительность_цели_ms=2000)
        м._тестовые_предпуски_наблюдателя.add(контур)
        try:
            for состояние in ('неизвестно', 'предпуск готов', 'отказ до active подтверждён'):
                with сам.subTest(состояние=состояние):
                    контур._состояние = состояние
                    контур._ошибка = None
                    владелец.состояние = 'занят'
                    владелец.ошибка = None
                    ошибка = OSError('внешний отказ')
                    with mock.patch.object(м, '_закрыть_удержанные_fd') as закрыть, \
                         mock.patch.object(м, '_кандидат_собрать_статус_лидера') as сбор:
                        м._очистить_ошибочный_штатный_транспорт(владелец, ошибка)
                        закрыть.assert_not_called(); сбор.assert_not_called()
                    сам.assertEqual((контур.состояние, владелец.состояние), ('неизвестно', 'неизвестно'))
                    сам.assertIs(контур._ошибка, ошибка)
                    сам.assertIs(владелец.ошибка, ошибка)
        finally:
            м._тестовые_предпуски_наблюдателя.remove(контур)
            владелец._блокировка.release()

