    def _проверить_предпуск_под_парой(сам, вариант):
        import select
        import threading
        сам.assertIn(вариант, ('успех', 'ошибка', 'без_terminal', 'перехват_terminal',
                               'чужой_unknown', 'частичный_unlock'))
        if (сам.исполнитель_наблюдателя is None or сам.отпечаток_наблюдателя is None
            or сам.исполнитель_якоря is None or сам.отпечаток_якоря is None
            or сам.исходник_legacy is None or сам.отпечаток_legacy is None
            or сам.удержать_неизвестный_исход is not True):
            сам.skipTest('нужны закреплённые исполнители и владелец неизвестного исхода')
        for путь, отпечаток in ((сам.исполнитель_наблюдателя, сам.отпечаток_наблюдателя),
                               (сам.исполнитель_якоря, сам.отпечаток_якоря),
                               (сам.исходник_legacy, сам.отпечаток_legacy)):
            сам.assertEqual(hashlib.sha256(Path(путь).read_bytes()).hexdigest(), отпечаток)
        м = загрузить_модуль_автоматизации()
        фикстура = ПроверкаЗакреплённогоФайлаЗамка('runTest')
        _, корень, сессия, старый_каталог, _, имя, пара = фикстура.подготовить_владельца_пары()
        владелец_замка = фикстура.владелец_пары
        владелец_замка.подготовить()
        контракт = ('fum.test-lock-bridge.1', пара[1], пара[2], пара[5], пара[6])
        удержание = {'фикстура': фикстура, 'фаза': 'подготовка', 'наблюдатель': None,
                     'конкурент': None, 'fd': []}
        сам.удерживаемые_предпуски.append(удержание)
        def закрыть(fd):
            удержание['фаза'] = ('close начат', fd)
            os.close(fd)
            удержание['fd'].remove(fd)
            удержание['фаза'] = ('close завершён', fd)
        удержание['фаза'] = 'pipe управления начат'
        управление_r, управление_w = os.pipe()
        удержание['fd'].extend((управление_r, управление_w))
        удержание['фаза'] = 'pipe управления зарегистрирован'
        удержание['фаза'] = 'pipe статуса начат'
        статус_r, статус_w = os.pipe()
        удержание['fd'].extend((статус_r, статус_w))
        удержание['фаза'] = 'pipe статуса зарегистрирован'
        os.set_blocking(управление_w, False)
        os.set_blocking(статус_r, False)
        идентификатор = uuid.uuid4()
        край_пуска = time.monotonic_ns() // 1_000_000 + 4500
        владелец = м._ТестовыйВладелецЗапуска()
        сам.assertTrue(владелец._блокировка.acquire(False))
        владелец._поток_владельца = м._thread.get_ident()
        владелец._объект_потока = threading.current_thread()
        приёмник = м._ТестовыйПриёмникБессрочногоНаблюдателя(
            str(идентификатор), край_пуска, 5000, версия='fum-run-witness.6', длительность_цели_ms=2000)
        удержание['владелец'] = владелец
        удержание['приёмник'] = приёмник
        удержание['владелец_замка'] = владелец_замка
        active = (корень / Path(сессия).parent / 'материалы/запуски-проверок'
                  / f'1_{идентификатор}.json')
        метка_цели = корень / 'цель-запущена'
        команда = ['/bin/sh', '-c', 'test -f "$1" && /usr/bin/touch "$2"',
                   'проверка', str(active), str(метка_цели)]
        argv = [сам.исполнитель_наблюдателя, 'fum-run-witness.6', str(идентификатор),
                сам.исполнитель_якоря, str(статус_w), '5000', 'none', str(край_пуска),
                '5000', '2000', '--', *команда]
        удержание['фаза'] = 'popen наблюдателя начат'
        наблюдатель = subprocess.Popen(argv, cwd=корень, env={}, stdin=управление_r,
                                      stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                      pass_fds=(статус_w,), start_new_session=True, close_fds=True)
        удержание['наблюдатель'] = наблюдатель
        удержание['фаза'] = 'popen наблюдателя вернул объект'
        владелец.процесс, владелец.pid = наблюдатель, наблюдатель.pid
        закрыть(управление_r)
        закрыть(статус_w)
        читатель = м._ТестовоеЧтениеНаблюдателя(владелец, приёмник, статус_r)
        удержание['читатель'] = читатель
        удержание['фаза'] = 'ожидание FUA начато'
        готовность = читатель.читать_кадр(срок=край_пуска)
        удержание['готовность'] = готовность
        удержание['фаза'] = 'готовность получена'
        сам.assertEqual(готовность[0], 'готов')
        pid_якоря = готовность[1]
        удержание['pid_якоря'] = pid_якоря
        сам.assertFalse(active.exists())
        сам.assertFalse(метка_цели.exists())
        передача = м._ТестоваяПередачаНаблюдателя(владелец, приёмник, управление_w)
        удержание['передача'] = передача
        участок = м._ТестовыйУчастокЗапускаПодПарой(
            владелец_замка, владелец, приёмник, передача, active)
        удержание['участок'] = участок

        код_конкурента = '\n'.join([
            'import fcntl,hashlib,os,pathlib,select,sys,time,types',
            'data=pathlib.Path(sys.argv[1]).read_bytes()',
            'assert hashlib.sha256(data).hexdigest()==sys.argv[2]',
            'm=types.ModuleType("fixture_legacy"); m.__file__=sys.argv[1]; sys.modules[m.__name__]=m',
            'exec(compile(data,sys.argv[1],"exec"),m.__dict__)',
            'm.tempfile.gettempdir=lambda:sys.argv[3]',
            'fd=os.open(sys.argv[4],os.O_RDWR|os.O_NOFOLLOW|os.O_CLOEXEC)',
            's=os.fstat(fd); assert (s.st_dev,s.st_ino)==(int(sys.argv[7]),int(sys.argv[8]))',
            'deadline=time.monotonic()+9.0',
            'def command(expected):',
            ' left=deadline-time.monotonic()',
            ' if left<=0 or not select.select([0],[],[],left)[0]: os._exit(8)',
            ' if os.read(0,1)!=expected: os._exit(9)',
            'os.write(1,b"R")',
            'for _ in range(4 if sys.argv[9]=="partial" else 3):',
            ' command(b"P")',
            ' try: fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)',
            ' except BlockingIOError: os.write(1,b"B")',
            ' else: os.write(1,b"E"); os._exit(4)',
            'if sys.argv[9] in ("abort","partial"):',
            ' command(b"X"); os.close(fd); os.write(1,b"X"); sys.exit(0)',
            'command(b"G"); os.close(fd)',
            'with m.межпроцессная_блокировка(pathlib.Path(sys.argv[5]),sys.argv[6]): os.write(1,b"F")',
        ])
        удержание['фаза'] = 'popen конкурента начат'
        конкурент = subprocess.Popen(
            (sys.executable, '-I', '-S', '-B', '-u', '-c', код_конкурента,
             сам.исходник_legacy, сам.отпечаток_legacy, str(старый_каталог), str(старый_каталог / имя),
             str(корень), сессия, str(пара[3][2]), str(пара[3][3]),
             'run' if вариант == 'успех' else 'partial' if вариант == 'частичный_unlock' else 'abort'),
            cwd=корень, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'},
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            start_new_session=True, close_fds=True)
        удержание['конкурент'] = конкурент
        удержание['фаза'] = 'popen конкурента вернул объект'
        предел = time.monotonic() + 8.0
        def получить(байт):
            удержание['фаза'] = ('чтение конкурента начато', байт)
            остаток = предел - time.monotonic()
            сам.assertGreater(остаток, 0)
            сам.assertTrue(select.select([конкурент.stdout.fileno()], [], [], остаток)[0])
            сам.assertEqual(os.read(конкурент.stdout.fileno(), 1), байт)
            удержание['фаза'] = ('чтение конкурента завершено', байт)
        def послать(байт):
            удержание['фаза'] = ('передача конкуренту начата', байт)
            сам.assertEqual(os.write(конкурент.stdin.fileno(), байт), 1)
            удержание['фаза'] = ('передача конкуренту завершена', байт)
        получить(b'R')
        def заимствовать():
            return м._тестово_выбрать_замок_сессии(
                корень, сессия, срок_монотонный=владелец_замка._срок,
                контракт=контракт, _тестовый_владелец_пары=владелец_замка)
        удержание['фаза'] = 'захват пары начат'
        проверка_повтора_завершена = False
        старая_попытка = ('исходный неизвестный эффект', object())
        ожидание = (contextlib.nullcontext() if вариант == 'успех'
                    else сам.assertRaises(OSError if вариант == 'частичный_unlock' else BaseExceptionGroup))
        with ожидание, участок.удержать() as текущий, \
             mock.patch.object(м.subprocess, 'Popen', side_effect=AssertionError('fork под lock')):
            удержание['фаза'] = 'пара удерживается'
            байты_active = м.канонические_машинные_байты(
                {'идентификатор': str(идентификатор), 'состояние': 'выполняется'})
            удержание['фаза'] = 'запись active начата'
            сам.assertEqual(текущий.начать_active(), active)
            with заимствовать() as сверить:
                м.атомарно_записать_байты(active, байты_active, только_новый=True,
                                         перед_публикацией=сверить)
            владелец.активная_запись = active
            владелец.байты_записи = байты_active
            владелец.запись_вернула_успех = True
            текущий.подтвердить_active()
            удержание['фаза'] = 'запись active завершена'
            сам.assertFalse(метка_цели.exists())
            послать(b'P'); получить(b'B')
            if вариант in ('ошибка', 'без_terminal', 'чужой_unknown'):
                удержание['фаза'] = 'отказ наблюдателя начат'
                with заимствовать() as сверить:
                    передача.отправить(b'A', сверить)
                очистка = читатель.читать_кадр(срок=приёмник.край_очистки)
                сам.assertEqual(очистка, ('отказ-очистка-наблюдена',))
                код = м._кандидат_собрать_статус_лидера(наблюдатель, срок=приёмник.край_очистки / 1000)
                сам.assertEqual(код, 0)
                сам.assertTrue(select.select([статус_r], [], [], 1.0)[0])
                сам.assertEqual(os.read(статус_r, 1), b'')
                with сам.assertRaises(ProcessLookupError):
                    os.killpg(pid_якоря, 0)
                приёмник.подтвердить_завершение(код, True, time.monotonic_ns() // 1_000_000)
                сам.assertFalse(метка_цели.exists())
                if вариант == 'чужой_unknown':
                    владелец_замка.попытка = старая_попытка
                    raise ValueError('модельный сбой с прежним UNKNOWN')
                if вариант == 'ошибка':
                    raise ValueError('модельный сбой после active')
            else:
                удержание['фаза'] = 'передача GO начата'
                with заимствовать() as сверить:
                    передача.отправить(b'G', сверить)
                удержание['фаза'] = 'передача GO завершена'
                запуск = читатель.читать_кадр(срок=край_пуска)
                удержание['запуск'] = запуск
                сам.assertEqual(запуск[0], 'запущен')
                статус = читатель.читать_кадр(срок=приёмник.край_ожидания_цели)
                удержание['статус'] = статус
                сам.assertEqual(статус, ('статус', 0))
                сам.assertTrue(метка_цели.is_file())
                послать(b'P'); получить(b'B')
                удержание['фаза'] = 'передача C начата'
                with заимствовать() as сверить:
                    передача.отправить(b'C', сверить)
                удержание['фаза'] = 'передача C завершена'
                очистка = читатель.читать_кадр(срок=приёмник.край_очистки)
                удержание['очистка'] = очистка
                сам.assertEqual(очистка, ('очистка-наблюдена', 0, False))
                удержание['фаза'] = 'подтверждение наблюдателя начато'
                текущий.подтвердить_наблюдение()
                удержание['фаза'] = 'наблюдатель подтверждён'
                терминал = м.канонические_машинные_байты({
                    'идентификатор': str(идентификатор), 'состояние': 'завершён',
                    'статус': 'успешно', 'код_завершения': 0})
                удержание['фаза'] = 'запись terminal начата'
                with заимствовать() as сверить:
                    м.атомарно_записать_байты(active, терминал,
                                             перед_публикацией=сверить)
                владелец.терминальные_байты = терминал
                владелец.терминальная_запись_вернула_успех = True
                if вариант == 'перехват_terminal':
                    with mock.patch.object(м, 'прочитать_машинную_запись',
                                           side_effect=RuntimeError('неизвестный исход чтения')) as чтение:
                        with сам.assertRaises(RuntimeError):
                            текущий.подтвердить_terminal()
                        with сам.assertRaises(м.ОшибкаОтчёта):
                            текущий.подтвердить_terminal()
                        сам.assertEqual(чтение.call_count, 1)
                        проверка_повтора_завершена = True
                else:
                    текущий.подтвердить_terminal()
                    удержание['фаза'] = 'запись terminal завершена'
                    сам.assertEqual(active.read_bytes(), терминал)
                    текущий._сверить_владение()
                    послать(b'P'); получить(b'B')
                    if вариант == 'частичный_unlock':
                        исходный_flock = владелец_замка._flock_один
                        def отказ_второго_unlock(номер, операция):
                            if номер == 0 and операция == м.fcntl.LOCK_UN:
                                raise OSError('модельный отказ второго unlock')
                            return исходный_flock(номер, операция)
                        перехват = mock.patch.object(владелец_замка, '_flock_один',
                                                    side_effect=отказ_второго_unlock)
                        удержание['перехват'] = перехват
                        перехват.start()
        if вариант != 'успех':
            сам.assertEqual(участок._фаза, 'неизвестно')
            сам.assertEqual(владелец_замка.состояние, 'неизвестно')
            сам.assertEqual(владелец_замка._взяты, [0] if вариант == 'частичный_unlock' else [0, 1])
            число_проб = 1 if вариант in ('частичный_unlock', 'перехват_terminal') else 2
            for _ in range(число_проб):
                послать(b'P'); получить(b'B')
            послать(b'X'); получить(b'X')
            удержание['фаза'] = 'wait конкурента после UNKNOWN начат'
            код_конкурента = конкурент.wait(timeout=max(0.001, предел-time.monotonic()))
            удержание['фаза'] = ('wait конкурента после UNKNOWN завершён', код_конкурента)
            сам.assertEqual(код_конкурента, 0)
            if вариант == 'чужой_unknown':
                сам.assertIs(владелец_замка.попытка, старая_попытка)
                сам.assertIs(владелец_замка._участок_удержания, участок)
            else:
                сам.assertEqual(владелец_замка.попытка[0], 'active без безопасного выхода')
            сам.assertIn(владелец_замка._маркер, м._тестовые_активные_замки)
            if вариант in ('перехват_terminal', 'частичный_unlock'):
                сам.assertEqual(active.read_bytes(), терминал)
                сам.assertTrue(метка_цели.is_file())
            else:
                сам.assertEqual(active.read_bytes(), байты_active)
                сам.assertFalse(метка_цели.exists())
            if вариант == 'перехват_terminal':
                сам.assertTrue(проверка_повтора_завершена)
            return
        сам.assertEqual(участок._фаза, 'закрыт')
        послать(b'G'); получить(b'F')
