        удержание['фаза'] = ('wait конкурента завершён', код_конкурента)
        сам.assertEqual(код_конкурента, 0)
        for fd in tuple(удержание['fd']):
            закрыть(fd)
        for роль, поток in (('stdin', конкурент.stdin), ('stdout', конкурент.stdout), ('stderr', конкурент.stderr)):
            удержание['фаза'] = ('close канала конкурента начат', роль)
            поток.close()
            удержание['фаза'] = ('close канала конкурента завершён', роль)
        владелец._блокировка.release()
        владелец_замка.закрыть()
        фикстура.завершить(м)
        сам.удерживаемые_предпуски.remove(удержание)

