    def test_штатный_шестой_профиль_передаёт_вывод_целевой_команды(сам):
        import select

        выход_чтение, выход_запись = os.pipe()
        ошибки_чтение, ошибки_запись = os.pipe()
        прежний_выход, прежние_ошибки = os.dup(1), os.dup(2)
        наследуется_выход = os.get_inheritable(1)
        наследуются_ошибки = os.get_inheritable(2)
        удержание = {'дескрипторы': (выход_чтение, выход_запись, ошибки_чтение,
                                    ошибки_запись, прежний_выход, прежние_ошибки)}
        сам.удерживаемые_предпуски.append(удержание)
        os.dup2(выход_запись, 1)
        os.dup2(ошибки_запись, 2)
        os.close(выход_запись)
        os.close(ошибки_запись)
        try:
            сам._проверить_изолированный_предпросмотр(
                'isolated-git.2', _непрерывность=True, _версия_6=True,
                _штатный_профиль=True, _проверка_вывода=True)
        except BaseException:
            os.write(прежние_ошибки, b'HOLD: fixture output descriptors retained\n')
            raise
        os.dup2(прежний_выход, 1, inheritable=наследуется_выход)
        os.dup2(прежние_ошибки, 2, inheritable=наследуются_ошибки)
        os.close(прежний_выход)
        os.close(прежние_ошибки)
        содержимое = {выход_чтение: bytearray(), ошибки_чтение: bytearray()}
        ожидаются = set(содержимое)
        предел = time.monotonic() + 2.0
        while ожидаются:
            остаток = предел - time.monotonic()
            сам.assertGreater(остаток, 0, 'не получен EOF обоих потоков в срок')
            готовые, _, _ = select.select(list(ожидаются), [], [], остаток)
            сам.assertTrue(готовые, 'не получен EOF обоих потоков в срок')
            for fd in готовые:
                часть = os.read(fd, 1024)
                if часть:
                    содержимое[fd].extend(часть)
                    сам.assertLessEqual(len(содержимое[fd]), 1024)
                else:
                    ожидаются.remove(fd)
        выход, ошибки = bytes(содержимое[выход_чтение]), bytes(содержимое[ошибки_чтение])
        os.close(выход_чтение)
        os.close(ошибки_чтение)
        сам.удерживаемые_предпуски.remove(удержание)
        сам.assertEqual(выход, b'fum-stdout-fixture')
        сам.assertEqual(ошибки, b'fum-stderr-fixture')

