    def test_вывод_отклоняет_закрытый_ненаследуемый_или_непишущий_дескриптор(сам):
        import ast
        import fcntl
        import types

        дерево = ast.parse(сценарий.read_text(encoding='utf-8'))
        класс = next(узел for узел in дерево.body
                     if isinstance(узел, ast.ClassDef) and узел.name == '_ТестовыйКонтурНаблюдателя')
        предпуск = next(узел for узел in класс.body
                        if isinstance(узел, ast.FunctionDef) and узел.name == 'предпустить')
        проверки = [узел for узел in ast.walk(предпуск)
                    if isinstance(узел, ast.If) and isinstance(узел.test, ast.Name)
                    and узел.test.id == '_передать_вывод']
        сам.assertEqual(len(проверки), 1)
        код = compile(ast.fix_missing_locations(ast.Module(body=проверки, type_ignores=[])),
                      str(сценарий), 'exec')
        м = загрузить_модуль_автоматизации()
        for вариант in ('закрыт', 'не наследуется', 'только чтение', 'исправен', 'вывод выключен'):
            with сам.subTest(вариант=вариант):
                def проверить(fd, операция):
                    if вариант == 'закрыт' and fd == 2:
                        raise OSError('закрытый дескриптор')
                    if операция == fcntl.F_GETFD:
                        return fcntl.FD_CLOEXEC if вариант == 'не наследуется' and fd == 2 else 0
                    if операция == fcntl.F_GETFL:
                        return os.O_RDONLY if вариант == 'только чтение' and fd == 2 else os.O_WRONLY
                    raise AssertionError('неожиданная операция')
                вызов = mock.Mock(side_effect=проверить)
                среда = {
                    '_передать_вывод': вариант != 'вывод выключен', 'os': os,
                    'ОшибкаОтчёта': м.ОшибкаОтчёта,
                    'fcntl': types.SimpleNamespace(fcntl=вызов, F_GETFD=fcntl.F_GETFD,
                                                   F_GETFL=fcntl.F_GETFL, FD_CLOEXEC=fcntl.FD_CLOEXEC),
                }
                if вариант in ('исправен', 'вывод выключен'):
                    exec(код, среда)
                    сам.assertEqual(вызов.call_count, 4 if вариант == 'исправен' else 0)
                else:
                    with сам.assertRaises(OSError if вариант == 'закрыт' else м.ОшибкаОтчёта):
                        exec(код, среда)

