    def test_неизвестная_маска_запрещает_восстанавливать_обработчики_шестого_профиля(сам):
        import ast
        import types

        дерево = ast.parse(сценарий.read_text(encoding='utf-8'))
        запуск = next(узел for узел in дерево.body
                      if isinstance(узел, ast.FunctionDef) and узел.name == '_выполнить_ограниченный_запуск_внутри')
        восстановление = next(узел for узел in запуск.body
                              if isinstance(узел, ast.FunctionDef) and узел.name == 'восстановить_состояние')
        фабрика = ast.FunctionDef(
            name='фабрика', args=ast.arguments(posonlyargs=[], args=[], vararg=None, kwonlyargs=[],
                                                kw_defaults=[], kwarg=None, defaults=[]),
            body=[ast.Assign(targets=[ast.Name(id='восстановление_начато', ctx=ast.Store())],
                             value=ast.Constant(value=False)),
                  восстановление,
                  ast.Return(value=ast.Name(id='восстановить_состояние', ctx=ast.Load()))],
            decorator_list=[])
        блокировка = mock.Mock(side_effect=OSError('неизвестен исход блокировки маски'))
        восстановить = mock.Mock()
        среда = {
            'заблокировать_управляемые_сигналы': блокировка,
            'восстановить_сигналы_шестой_версии': восстановить,
            'управляемый': True, '_тестовая_версия_6': True,
            'учёт_терминальных_сигналов_закончен': False,
            '_владелец': types.SimpleNamespace(_транспорт_binding=None),
            'метка_каталога_наблюдений': None,
        }
        модуль = ast.fix_missing_locations(ast.Module(body=[фабрика], type_ignores=[]))
        exec(compile(модуль, str(сценарий), 'exec'), среда)
        применить = среда['фабрика']()
        первичная = ValueError('исходная ошибка запуска')
        with сам.assertRaises(BaseExceptionGroup) as группа:
            применить(первичная)
        сам.assertEqual(len(группа.exception.exceptions), 2)
        сам.assertIs(группа.exception.exceptions[0], первичная)
        сам.assertIsInstance(группа.exception.exceptions[1], OSError)
        блокировка.assert_called_once()
        восстановить.assert_not_called()
        применить(None)
        блокировка.assert_called_once()
        восстановить.assert_not_called()

