    def test_неизвестная_установка_обработчика_сохраняет_опоры_и_не_повторяется(сам):
        import ast
        import types

        дерево = ast.parse(сценарий.read_text(encoding='utf-8'))
        запуск = next(узел for узел in дерево.body
                      if isinstance(узел, ast.FunctionDef) and узел.name == '_выполнить_ограниченный_запуск_внутри')
        циклы = [узел for узел in ast.walk(запуск)
                 if isinstance(узел, ast.For) and isinstance(узел.target, ast.Name)
                 and узел.target.id == 'номер_сигнала' and isinstance(узел.iter, ast.Name)
                 and узел.iter.id == 'управляемые_сигналы']
        сам.assertEqual(len(циклы), 1)
        код = compile(ast.fix_missing_locations(ast.Module(body=циклы, type_ignores=[])),
                      str(сценарий), 'exec')
        м = загрузить_модуль_автоматизации()
        номера = (signal.SIGINT, signal.SIGTERM)
        for номер_сбоя in (0, 1):
            for после_действия in (False, True):
                with сам.subTest(номер_сбоя=номер_сбоя, после_действия=после_действия):
                    причина = OSError('неизвестна установка обработчика')
                    прежние = {номер: object() for номер in номера}
                    записи = dict(прежние)
                    установки = {}
                    данные = {'обработчики': записи, 'установки_обработчиков': установки}
                    владелец = types.SimpleNamespace(
                        _сигнальная_фаза='блокировка завершена', _сигнальная_ошибка=None,
                        _сигнальные_данные=данные)
                    действия = []
                    def установить(номер, обработчик):
                        позиция = номера.index(номер)
                        if позиция == номер_сбоя:
                            if после_действия:
                                действия.append(номер)
                            raise причина
                        действия.append(номер)
                    чтение = mock.Mock(side_effect=lambda номер: прежние[номер])
                    установка = mock.Mock(side_effect=установить)
                    среда = {
                        'управляемые_сигналы': номера, 'прежние_обработчики': записи,
                        'принять_сигнал': object(), '_тестовая_версия_6': True, 'управляемый': True,
                        '_владелец': владелец, 'ОшибкаОтчёта': м.ОшибкаОтчёта,
                        'signal': types.SimpleNamespace(getsignal=чтение, signal=установка),
                    }
                    with сам.assertRaises(OSError) as первая:
                        exec(код, среда)
                    сам.assertIs(первая.exception, причина)
                    сам.assertEqual(владелец._сигнальная_фаза, 'неизвестно')
                    сам.assertIs(владелец._сигнальная_ошибка, причина)
                    for номер in номера:
                        сам.assertIs(записи[номер], прежние[номер])
                    сам.assertEqual(установки[номера[номер_сбоя]], 'неизвестно')
                    if номер_сбоя:
                        сам.assertEqual(установки[номера[0]], 'возвращена')
                    with сам.assertRaises(м.ОшибкаОтчёта):
                        exec(код, среда)
                    сам.assertEqual(установка.call_count, номер_сбоя + 1)
                    чтение.assert_not_called()
                    ожидаемые = list(номера[:номер_сбоя])
                    if после_действия:
                        ожидаемые.append(номера[номер_сбоя])
                    сам.assertEqual(действия, ожидаемые)

    def test_невосстановимый_обработчик_не_заменяет_ни_один_из_двух(сам):
        import ast
        import types

        дерево = ast.parse(сценарий.read_text(encoding='utf-8'))
        запуск = next(узел for узел in дерево.body
                      if isinstance(узел, ast.FunctionDef) and узел.name == '_выполнить_ограниченный_запуск_внутри')
        основной = next(узел for узел in запуск.body if isinstance(узел, ast.Try) and any(
            isinstance(шаг, ast.For) and isinstance(шаг.target, ast.Name)
            and шаг.target.id == 'номер_сигнала' for шаг in узел.body))
        номер_цикла = next(номер for номер, шаг in enumerate(основной.body)
                           if isinstance(шаг, ast.For) and isinstance(шаг.target, ast.Name)
                           and шаг.target.id == 'номер_сигнала')
        шаги = [основной.body[номер_цикла]]
        предыдущий = основной.body[номер_цикла - 1]
        if isinstance(предыдущий, ast.If) and any(
            isinstance(узел, ast.Attribute) and узел.attr == 'getsignal' for узел in ast.walk(предыдущий)
        ):
            шаги.insert(0, предыдущий)
        код = compile(ast.fix_missing_locations(ast.Module(body=шаги, type_ignores=[])),
                      str(сценарий), 'exec')
        м = загрузить_модуль_автоматизации()
        номера = (signal.SIGINT, signal.SIGTERM)
        for недоступный in номера:
            with сам.subTest(недоступный=недоступный):
                обработчики = {номер: (None if номер == недоступный else lambda *_: None) for номер in номера}
                установка = mock.Mock()
                владелец = types.SimpleNamespace(
                    _сигнальная_фаза='блокировка завершена', _сигнальная_ошибка=None,
                    _сигнальные_данные={'установки_обработчиков': {}})
                среда = {
                    'управляемые_сигналы': номера, 'прежние_обработчики': {},
                    'принять_сигнал': lambda *_: None, '_тестовая_версия_6': True, 'управляемый': True,
                    '_владелец': владелец, 'ОшибкаОтчёта': м.ОшибкаОтчёта,
                    'signal': types.SimpleNamespace(getsignal=lambda номер: обработчики[номер],
                                                    signal=установка, SIG_DFL=signal.SIG_DFL, SIG_IGN=signal.SIG_IGN),
                }
                with сам.assertRaises(м.ОшибкаОтчёта):
                    exec(код, среда)
                установка.assert_not_called()

    def test_неизвестный_возврат_сигнала_сохраняет_долг_и_не_повторяется(сам):
        import ast
        import types

        дерево = ast.parse(сценарий.read_text(encoding='utf-8'))
        запуск = next(узел for узел in дерево.body
                      if isinstance(узел, ast.FunctionDef) and узел.name == '_выполнить_ограниченный_запуск_внутри')
        восстановление = next(узел for узел in запуск.body
                              if isinstance(узел, ast.FunctionDef)
                              and узел.name == 'восстановить_сигналы_шестой_версии')
        код = compile(ast.fix_missing_locations(ast.Module(body=[восстановление], type_ignores=[])),
                      str(сценарий), 'exec')
        м = загрузить_модуль_автоматизации()
        for сбой in ('ожидающие', 'возврат-до', 'возврат-после'):
            with сам.subTest(сбой=сбой):
                причина = OSError('неизвестен исход сигнальной операции')
                действия = []
                def поставить(номер):
                    if сбой == 'возврат-после':
                        действия.append(номер)
                    raise причина
                ожидание = mock.Mock(side_effect=причина if сбой == 'ожидающие' else None,
                                      return_value=set())
                возврат = mock.Mock(side_effect=поставить)
                обработчики = mock.Mock()
                маска = mock.Mock()
                долг = {signal.SIGINT: 1}
                прежний = object()
                данные = {'обработчики': {signal.SIGINT: прежний}, 'долги': долг,
                          'попытки_возврата': {}, 'чтение_ожидающих': 'не начато'}
                владелец = types.SimpleNamespace(
                    _сигнальная_фаза='блокировка завершена', _сигнальная_ошибка=None,
                    _сигнальные_данные=данные)
                среда = {
                    'восстановить_обработчики': обработчики, 'восстановить_рабочую_маску': маска,
                    'принятые_обработчиком': долг, '_владелец': владелец,
                    'ОшибкаОтчёта': м.ОшибкаОтчёта,
                    'signal': types.SimpleNamespace(sigpending=ожидание, raise_signal=возврат),
                }
                exec(код, среда)
                применить = среда['восстановить_сигналы_шестой_версии']
                with сам.assertRaises(OSError) as первая:
                    применить()
                сам.assertIs(первая.exception, причина)
                сам.assertEqual(владелец._сигнальная_фаза, 'неизвестно')
                сам.assertIs(владелец._сигнальная_ошибка, причина)
                сам.assertIs(данные['обработчики'][signal.SIGINT], прежний)
                сам.assertEqual(данные['долги'], {signal.SIGINT: 1})
                сам.assertEqual(данные['чтение_ожидающих'],
                                'неизвестно' if сбой == 'ожидающие' else 'получено')
                if сбой != 'ожидающие':
                    сам.assertEqual(данные['попытки_возврата'][signal.SIGINT], 'неизвестно')
                with сам.assertRaises(м.ОшибкаОтчёта):
                    применить()
                обработчики.assert_called_once()
                ожидание.assert_called_once()
                сам.assertEqual(возврат.call_count, 0 if сбой == 'ожидающие' else 1)
                сам.assertEqual(действия, [signal.SIGINT] if сбой == 'возврат-после' else [])
                маска.assert_not_called()

