    def test_опытный_writer_принимает_только_точный_блок_отчёта(сам):
        м = загрузить_модуль_автоматизации()
        исходный = ('До\n' + открытый_маркер + '\nСтарый блок\n'
                    + конечный_маркер + '\nПосле\n').encode('utf-8')
        блок = открытый_маркер + '\nВычисленный блок\n' + конечный_маркер
        ожидаемый = ('До\n' + блок + '\nПосле\n').encode('utf-8')
        сам.assertEqual(м._тестово_принять_обновлённый_отчёт(исходный, исходный, блок), исходный)
        сам.assertEqual(м._тестово_принять_обновлённый_отчёт(исходный, ожидаемый, блок), ожидаемый)
        for подмена in (
            b'Changed\n' + ожидаемый,
            ожидаемый + b'Changed\n',
            ожидаемый.replace('Вычисленный'.encode(), 'Подменённый'.encode()),
        ):
            with сам.subTest(подмена=подмена):
                with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'выходит за'):
                    м._тестово_принять_обновлённый_отчёт(исходный, подмена, блок)
        with сам.assertRaises(м.ОшибкаОтчёта):
            м._тестово_принять_обновлённый_отчёт(исходный + исходный, ожидаемый, блок)

