    @staticmethod
    def _программа_конкурента_gc():
        return (
            'import errno,fcntl,os,signal,sys\n'
            'def watchdog(signum, frame):\n'
            ' try: os.write(2,b"W")\n'
            ' except BaseException: pass\n'
            'signal.signal(signal.SIGALRM,watchdog)\n'
            'signal.alarm(20)\n'
            'pins=None; held=[]\n'
            'os.write(1,b"R")\n'
            'while True:\n'
            ' c=os.read(0,1)\n'
            ' if c in (b"Q",b""): break\n'
            ' result=b""; current=[]; hold=False\n'
            ' try:\n'
            '  assert c==b"P"\n'
            '  for path in sys.argv[1:]:\n'
            '   fd=os.open(path,os.O_RDWR|os.O_NOFOLLOW|os.O_CLOEXEC)\n'
            '   held.append(fd)\n'
            '   stat=os.fstat(fd); named=os.stat(path,follow_symlinks=False)\n'
            '   ident=(stat.st_dev,stat.st_ino); current.append(ident)\n'
            '   assert ident==(named.st_dev,named.st_ino)\n'
            '   try:\n'
            '    fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)\n'
            '   except OSError as error:\n'
            '    if error.errno not in (errno.EAGAIN,errno.EWOULDBLOCK): raise\n'
            '    os.close(fd); held.remove(fd); result+=b"B"\n'
            '   else:\n'
            '    result+=b"F"; hold=True; break\n'
            '  if result==b"BB":\n'
            '   if pins is None: pins=current\n'
            '   else: assert pins==current\n'
            '  else: hold=True\n'
            ' except BaseException:\n'
            '  result=b"UU"; hold=True\n'
            ' try: sent=os.write(1,(result+b"UU")[:2])\n'
            ' except BaseException: sent=0\n'
            ' if hold or sent!=2:\n'
            '  while True: signal.pause()\n'
        )

    def test_конкурент_gc_сохраняет_неожиданно_взятый_lock(сам):
        import errno
        import fcntl
        import select
        import shutil

        префикс = (
            'import signal\n'
            'original_alarm=signal.alarm\n'
            'signal.alarm=lambda seconds: original_alarm(1)\n'
        )
        программа = префикс + сам._программа_конкурента_gc()
        compile(программа, '<конкурент-gc>', 'exec')
        каталог = tempfile.TemporaryDirectory(prefix='fum-gc-competitor-', dir='/private/tmp')
        каталог._finalizer.detach()
        корень = Path(каталог.name)
        первый, второй = корень / 'first.lock', корень / 'second.lock'
        первый.write_bytes(b'')
        второй.write_bytes(b'')
        удержание = {'каталог': каталог, 'процесс': None, 'fd': []}
        сам.удерживаемые_предпуски.append(удержание)
        конкурент = subprocess.Popen(
            (sys.executable, '-I', '-S', '-B', '-c', программа, str(первый), str(второй)),
            cwd=корень, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'},
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            start_new_session=True, close_fds=True)
        удержание['процесс'] = конкурент
        сам.assertTrue(select.select([конкурент.stdout.fileno()], [], [], 3.0)[0])
        сам.assertEqual(os.read(конкурент.stdout.fileno(), 1), b'R')
        сам.assertEqual(os.write(конкурент.stdin.fileno(), b'P'), 1)
        сам.assertTrue(select.select([конкурент.stdout.fileno()], [], [], 3.0)[0])
        сам.assertEqual(os.read(конкурент.stdout.fileno(), 2), b'FU')
        сам.assertTrue(select.select([конкурент.stderr.fileno()], [], [], 3.0)[0])
        сам.assertEqual(os.read(конкурент.stderr.fileno(), 1), b'W')
        сам.assertIsNone(конкурент.poll())
        fd = os.open(первый, os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC)
        удержание['fd'].append(fd)
        with сам.assertRaises(BlockingIOError) as отказ:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        сам.assertIn(отказ.exception.errno, (errno.EAGAIN, errno.EWOULDBLOCK))
        os.close(fd)
        удержание['fd'].remove(fd)
        сам.assertIsNone(конкурент.poll())
        # Конкурент известен, захват им подтверждён в собственной фикстуре.
        os.kill(конкурент.pid, signal.SIGTERM)
        сам.assertEqual(конкурент.wait(timeout=3), -signal.SIGTERM)
        for поток in (конкурент.stdin, конкурент.stdout, конкурент.stderr):
            поток.close()
        shutil.rmtree(корень)
        сам.удерживаемые_предпуски.remove(удержание)

    def test_конкурент_gc_не_закрывает_fd_при_неизвестном_flock(сам):
        import select
        import shutil

        префикс = (
            'import errno,fcntl,os,signal\n'
            'original_alarm=signal.alarm\n'
            'signal.alarm=lambda seconds: original_alarm(1)\n'
            'def отказ_flock(fd, operation):\n'
            ' os.write(1,b"X")\n'
            ' raise OSError(errno.EIO,"synthetic")\n'
            'def запрет_close(fd):\n'
            ' os.write(1,b"C")\n'
            ' raise AssertionError("unexpected close")\n'
            'fcntl.flock=отказ_flock; os.close=запрет_close\n'
        )
        программа = префикс + сам._программа_конкурента_gc()
        compile(программа, '<конкурент-gc-неизвестно>', 'exec')
        каталог = tempfile.TemporaryDirectory(prefix='fum-gc-unknown-', dir='/private/tmp')
        каталог._finalizer.detach()
        корень = Path(каталог.name)
        первый, второй = корень / 'first.lock', корень / 'second.lock'
        первый.write_bytes(b'')
        второй.write_bytes(b'')
        удержание = {'каталог': каталог, 'процесс': None}
        сам.удерживаемые_предпуски.append(удержание)
        конкурент = subprocess.Popen(
            (sys.executable, '-I', '-S', '-B', '-c', программа, str(первый), str(второй)),
            cwd=корень, env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'},
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            start_new_session=True, close_fds=True)
        удержание['процесс'] = конкурент

        def получить(размер):
            данные = bytearray()
            while len(данные) < размер:
                сам.assertTrue(select.select([конкурент.stdout.fileno()], [], [], 3.0)[0])
                часть = os.read(конкурент.stdout.fileno(), размер - len(данные))
                сам.assertTrue(часть)
                данные.extend(часть)
            return bytes(данные)

        сам.assertEqual(получить(1), b'R')
        сам.assertEqual(os.write(конкурент.stdin.fileno(), b'P'), 1)
        сам.assertEqual(получить(3), b'XUU')
        сам.assertTrue(select.select([конкурент.stderr.fileno()], [], [], 3.0)[0])
        сам.assertEqual(os.read(конкурент.stderr.fileno(), 1), b'W')
        сам.assertFalse(select.select([конкурент.stdout.fileno()], [], [], 0.2)[0])
        сам.assertIsNone(конкурент.poll())
        # Маркер X подтверждает mock: настоящий flock не вызывался.
        os.kill(конкурент.pid, signal.SIGTERM)
        сам.assertEqual(конкурент.wait(timeout=3), -signal.SIGTERM)
        for поток in (конкурент.stdin, конкурент.stdout, конкурент.stderr):
            поток.close()
        shutil.rmtree(корень)
        сам.удерживаемые_предпуски.remove(удержание)

    def test_неизвестный_active_удерживает_пару_после_gc(сам):
        import fcntl
        import gc
        import select

        м = загрузить_модуль_автоматизации()
        защищённые = set()
        попытки, необрабатываемые = [], []
        проба = {'модуль': м, 'защищённые': защищённые}
        сам.удерживаемые_предпуски.append(проба)
        настоящий_close, настоящий_flock = os.close, fcntl.flock

        def закрыть(fd):
            if fd in защищённые:
                попытки.append(('close', fd))
                raise OSError('запрещённая попытка закрыть удерживаемый lock')
            return настоящий_close(fd)

        def flock(fd, операция):
            if fd in защищённые and операция & fcntl.LOCK_UN:
                попытки.append(('unlock', fd))
                raise OSError('запрещённая попытка освободить удерживаемый lock')
            return настоящий_flock(fd, операция)

        def необрабатываемое(событие):
            необрабатываемые.append((событие.exc_type.__name__, str(событие.exc_value)))

        with mock.patch.object(os, 'close', side_effect=закрыть), \
             mock.patch.object(fcntl, 'flock', side_effect=flock), \
             mock.patch.object(sys, 'unraisablehook', side_effect=необрабатываемое):
            отдельная = type(сам)('runTest')
            данные = отдельная._проверить_изолированный_предпросмотр(
                'isolated-git.2', _версия_6=True, _код_цели=124,
                _тайм_аут_цели=True, _подмена_исхода='этап сбора', _gc_probe=проба)
            del отдельная
            gc.collect()
            сам.assertFalse(попытки, попытки)
            сам.assertFalse(необрабатываемые, необрабатываемые)
            сам.assertGreaterEqual(len(защищённые), 2)
            сам.assertTrue(any(id(участок._связь[1]) == проба['owner_id']
                                for участок in м._тестовые_удерживаемые_участки))
            for fd, метка in zip(данные['fd_пары'], данные['метки']):
                ст = os.fstat(fd)
                сам.assertEqual((ст.st_dev, ст.st_ino), метка)
            конкурент = данные['конкурент']
            сам.assertEqual(os.write(конкурент.stdin.fileno(), b'P'), 1)
            сам.assertTrue(select.select([конкурент.stdout.fileno()], [], [], 3.0)[0])
            сам.assertEqual(os.read(конкурент.stdout.fileno(), 2), b'BB')
            сам.assertEqual(os.write(конкурент.stdin.fileno(), b'Q'), 1)
            сам.assertEqual(конкурент.wait(timeout=3), 0)
            for поток in (конкурент.stdin, конкурент.stdout, конкурент.stderr):
                поток.close()
            сам.assertFalse(попытки, попытки)
            сам.assertFalse(необрабатываемые, необрабатываемые)

