    def _проверить_занятую_охрану(сам, отказ_release=None):
        import threading
        м = загрузить_модуль_автоматизации()
        владелец = м._ТестовыйВладелецЗапуска()
        настоящий_mutex = владелец._блокировка
        if отказ_release is not None:
            class MutexСОтказом:
                попыток_release = 0
                def acquire(себя, блокировать):
                    return настоящий_mutex.acquire(блокировать)
                def locked(себя):
                    return настоящий_mutex.locked()
                def release(себя):
                    себя.попыток_release += 1
                    if отказ_release == 'после':
                        настоящий_mutex.release()
                    raise RuntimeError('модельный отказ release владельца')
            владелец._блокировка = MutexСОтказом()
        взята, отпустить = threading.Event(), threading.Event()
        ошибки = []

        def занять_охрану():
            if not м._тестовая_охрана_пуска.acquire(False):
                ошибки.append('не удалось занять охрану')
                взята.set()
                return
            try:
                взята.set()
                if not отпустить.wait(3):
                    ошибки.append('нет команды освободить охрану')
            finally:
                м._тестовая_охрана_пуска.release()

        поток = threading.Thread(target=занять_охрану)
        поток.start()
        try:
            сам.assertTrue(взята.wait(3))
            сам.assertFalse(ошибки)
            with mock.patch.object(м, '_выполнить_ограниченный_запуск_внутри',
                                   side_effect=AssertionError('запуск до регистрации')) as запуск:
                def запустить():
                    м._выполнить_ограниченный_запуск(
                        Path('/private/tmp'), Path('неиспользуемый-запрос'), 'проверка',
                        'исполнитель', None, 1, ['/usr/bin/true'],
                        тайм_аут_блокировки=1, _тестовый_владелец=владелец,
                        _тестовая_версия_6=True)
                if отказ_release is None:
                    with сам.assertRaisesRegex(м.ОшибкаОтчёта, 'охрана регистрации запуска занята'):
                        запустить()
                else:
                    with сам.assertRaises(BaseExceptionGroup) as группа:
                        запустить()
                    листья = группа.exception.exceptions
                    сам.assertTrue(any(type(о) is м._ТестовыйОтказОхраныДоЗапуска for о in листья))
                    сам.assertTrue(any(type(о) is RuntimeError and 'отказ release' in str(о) for о in листья))
                запуск.assert_not_called()
        finally:
            отпустить.set()
            поток.join(3)
        сам.assertFalse(поток.is_alive())
        сам.assertFalse(ошибки)
        if отказ_release is not None:
            сам.assertEqual(владелец.состояние, 'неизвестно')
            сам.assertEqual(владелец._блокировка.попыток_release, 1)
            сам.assertEqual(настоящий_mutex.locked(), отказ_release == 'до')
            сам.assertEqual(len(владелец.ошибки_освобождения), 1)
            сам.assertIsNone(владелец.процесс)
            сам.assertIsNone(владелец.активная_запись)
            return
        сам.assertEqual(владелец.состояние, 'отказ до допуска')
        сам.assertFalse(владелец._блокировка.locked())
        сам.assertFalse(владелец._доступ_запрещён)
        сам.assertIsNone(владелец.процесс)
        сам.assertIsNone(владелец.активная_запись)
        сам.assertEqual(владелец._фаза_реестра_запуска, 'не зарегистрирован')
        with mock.patch.object(м.subprocess, 'Popen',
                               side_effect=AssertionError('неожиданный запуск Git')) as popen:
            with м._тестовый_допуск_git():
                pass
            popen.assert_not_called()

