    def _проверить_исключение_охраны_типа_busy(сам, фаза):
        м = загрузить_модуль_автоматизации()
        владелец = м._ТестовыйВладелецЗапуска()
        настоящая_охрана = м._тестовая_охрана_пуска
        class ОхранаСОтказом:
            попыток = 0
            освобождений = 0
            def acquire(себя, блокировать):
                себя.попыток += 1
                if фаза == 'после':
                    сам.assertTrue(настоящая_охрана.acquire(блокировать))
                raise м._ТестовыйОтказОхраныДоЗапуска('модельный сбой охраны')
            def release(себя):
                себя.освобождений += 1
                raise AssertionError('повторное освобождение неизвестной охраны')
        охрана = ОхранаСОтказом()
        with mock.patch.object(м, '_тестовая_охрана_пуска', охрана), \
             mock.patch.object(м, '_выполнить_ограниченный_запуск_внутри',
                               side_effect=AssertionError('запуск до регистрации')) as запуск:
            with сам.assertRaises(м.ОшибкаОтчёта) as отказ:
                м._выполнить_ограниченный_запуск(
                    Path('/private/tmp'), Path('неиспользуемый-запрос'), 'проверка',
                    'исполнитель', None, 1, ['/usr/bin/true'],
                    тайм_аут_блокировки=1, _тестовый_владелец=владелец,
                    _тестовая_версия_6=True)
            запуск.assert_not_called()
        сам.assertIsNot(type(отказ.exception), м._ТестовыйОтказОхраныДоЗапуска)
        сам.assertIs(type(отказ.exception.__cause__), м._ТестовыйОтказОхраныДоЗапуска)
        сам.assertEqual(владелец.состояние, 'неизвестно')
        сам.assertEqual((охрана.попыток, охрана.освобождений), (1, 0))
        сам.assertEqual(настоящая_охрана.locked(), фаза == 'после')
        сам.assertIsNone(владелец.процесс)
        сам.assertIsNone(владелец.активная_запись)

