            шаблон = база / 'empty-template'; шаблон.mkdir(mode=0o700)
            команды = (('init', '-q', '--template=' + str(шаблон)),
                       ('config', '--local', 'user.name', 'FUM Tests'),
                       ('config', '--local', 'user.email', 'fum-tests@example.invalid'),
                       ('add', '--', 'Журнал/этап/запрос.md', 'Журнал/этап/отчёт.md'),
                       ('commit', '-q', '-m', 'fixture'))
            for номер, аргументы in enumerate(команды):
                рабочий = база / ('worker-' + str(номер)); рабочий.mkdir(mode=0o700)
                идентификатор = str(uuid.uuid4())
