            сам.байты_терминала_до_подмены = байты_моста
            сам.байты_отчёта_до_подмены = отчёт_моста.read_bytes()
            def метка_файла(путь):
                ст = путь.lstat()
                сам.assertTrue(stat.S_ISREG(ст.st_mode))
                return (ст.st_dev, ст.st_ino, stat.S_IMODE(ст.st_mode), ст.st_uid, ст.st_nlink)
            сам.метка_терминала_до_подмены = метка_файла(путь_моста)
