                сам.assertEqual(сам.фикстура_обёртки.файлы_записей(), [старый_файл])
                сам.assertFalse(сам.owner_обёртки.запись_вернула_успех)
                сам.assertIsNone(сам.owner_обёртки._транспорт_binding)
                сам.assertIsNone(сам.owner_обёртки.процесс)
