    def _подготовить_конкурентную_фикстуру_под_надзором(сам, модуль):
        import stat, threading
        сам.фикстура_конкуренции = ФикстураОтчётов.__new__(ФикстураОтчётов)
        сам.подготовка_конкуренции = 'создание файлов'
        сам.владельцы_подготовки_конкуренции = []
        сам.контуры_подготовки_конкуренции = []
        сам.fd_подготовки_конкуренции = []
        ФикстураОтчётов.__init__(сам.фикстура_конкуренции, _без_git=True)
        сам.база_подготовки_конкуренции = tempfile.TemporaryDirectory(dir='/tmp')
        сам.база_подготовки_конкуренции._finalizer.detach()
        база = Path(сам.база_подготовки_конкуренции.name).resolve()
        корень = сам.фикстура_конкуренции.корень.resolve()
        каталог = база / 'locks'; каталог.mkdir(mode=0o700)
        fd = модуль._приобрести_fd(сам.fd_подготовки_конкуренции, os.open, каталог,
                                    os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        ст = os.fstat(fd)
        шаблон = база / 'empty-template'; шаблон.mkdir(mode=0o700)
        команды = (('init', '-q', '--template=' + str(шаблон)),
                   ('config', '--local', 'user.name', 'FUM Tests'),
                   ('config', '--local', 'user.email', 'fum-tests@example.invalid'),
                   ('add', '--', сам.фикстура_конкуренции.запрос.resolve().relative_to(корень).as_posix(),
                    сам.фикстура_конкуренции.отчёт.resolve().relative_to(корень).as_posix()),
                   ('commit', '-q', '-m', 'fixture'))
        for номер, аргументы in enumerate(команды):
            сам.подготовка_конкуренции = ('подготовка Git', номер)
            рабочий = база / ('worker-' + str(номер)); рабочий.mkdir(mode=0o700)
            идентификатор = str(uuid.uuid4()); active = рабочий / 'active.json'
            байты = json.dumps({'идентификатор': идентификатор, 'состояние': 'выполняется'},
                               ensure_ascii=False).encode()
            active.write_bytes(байты)
            владелец = модуль._ТестовыйВладелецЗапуска()
            сам.владельцы_подготовки_конкуренции.append(владелец)
            владелец._блокировка.acquire()
            владелец._поток_владельца = модуль._thread.get_ident()
            владелец._объект_потока = threading.current_thread()
            владелец.активная_запись = active; владелец.байты_записи = байты
            владелец.запись_вернула_успех = True
            срок = time.monotonic_ns() // 1_000_000 + 15000
            контур = модуль._ТестовыйКонтурНаблюдателя(владелец, идентификатор, срок, срок + 5000)
            сам.контуры_подготовки_конкуренции.append(контур)
            селектор = ('fum.test-lock-root.2', str(каталог), ст.st_dev, ст.st_ino, ст.st_uid,
                        stat.S_IMODE(ст.st_mode), 'prepare-' + идентификатор, str(рабочий))
            def получить_замок():
                return модуль._тестовый_замок_новой_сессии(
                    селектор, fd, рабочий, селектор[6], срок_монотонный=(срок + 5000) / 1000)
            команда = ('/usr/bin/git', '-C', str(корень), '-c', 'core.fsmonitor=false',
                       '-c', 'core.hooksPath=/dev/null', '-c', 'commit.gpgsign=false',
                       '-c', 'maintenance.auto=false', '-c', 'gc.auto=0', '-c', 'index.version=2',
                       '-c', 'core.attributesFile=/dev/null', *аргументы)
            контур.запустить(Path(сам.исполнитель_наблюдателя), сам.отпечаток_наблюдателя,
                             Path(сам.исполнитель_якоря), сам.отпечаток_якоря,
                             рабочий, команда, получить_замок, _изолировать_git=True)
            результат = контур.довести(получить_замок)
            сам.assertEqual((результат.сырой_статус, результат.код_цели, результат.тайм_аут,
                             результат.код_наблюдателя), (0, 0, False, 0))
            сам.assertEqual([кадр[:4] for кадр in результат.кадры], [b'FUA1', b'FUS1', b'FUP1', b'FUD1'])
            итог = модуль._тестовый_итог_контура_наблюдателя(контур)
            сам.assertEqual((итог.статус, итог.код_записи, итог.возвращаемый_код), ('успешно', 0, 0))
            pid = int.from_bytes(результат.кадры[0][20:24], 'big')
            with сам.assertRaises(ProcessLookupError): os.killpg(pid, 0)
            контур.закрыть_после_успеха(); сам.assertEqual(контур.состояние, 'закрыт')
            сам.подготовка_конкуренции = ('освобождение владельца начато', номер)
            владелец._блокировка.release()
            сам.подготовка_конкуренции = ('освобождение владельца завершено', номер)
        конфигурация = корень / '.git/config'
        сам.подготовка_конкуренции = 'запись конфигурации начата'
        конфигурация.write_bytes(модуль._ТЕСТОВАЯ_КОНФИГУРАЦИЯ_БЕЗ_ПРЕОБРАЗОВАНИЙ)
        конфигурация.chmod(0o600)
        (корень / '.git/index').chmod(0o600)
        сам.assertEqual(конфигурация.read_bytes(), модуль._ТЕСТОВАЯ_КОНФИГУРАЦИЯ_БЕЗ_ПРЕОБРАЗОВАНИЙ)
        сам.подготовка_конкуренции = 'завершена'

    def _проверить_конкурента_с_удержанием(сам, фаза, мост_со_старым=False, изолировать_git=False,
                                          ожидается_ошибка=False):
        import select, stat, threading
        if (type(ожидается_ошибка) is not bool or (ожидается_ошибка and not изолировать_git)
            or type(изолировать_git) is not bool or (изолировать_git and
            (not мост_со_старым or фаза not in ('внутри-active', 'внутри-terminal')
             or signal.getsignal(signal.SIGPIPE) != signal.SIG_IGN
             or threading.current_thread() is not threading.main_thread()))):
            raise ValueError('изолированная проверка требует мост со старым замком')
        if (сам.исполнитель_якоря is None or сам.отпечаток_якоря is None
            or сам.исполнитель_наблюдателя is None or сам.отпечаток_наблюдателя is None
            or сам.удержать_неизвестный_исход is not True):
            сам.skipTest('нужны исполнители и живой владелец неизвестного исхода')
        модуль = загрузить_модуль_автоматизации()
        сам.fd_конкуренции = []
        сам.закрытие_fd_конкуренции = None
        сам.закрытие_канала_конкуренции = None
        def отпустить_fd(роль, значение):
            сам.закрытие_fd_конкуренции = ('начато', роль, значение)
            модуль._отпустить_зарегистрированный_fd(сам.fd_конкуренции, значение)
            сам.закрытие_fd_конкуренции = ('завершено', роль, значение)
        if изолировать_git:
            сам._подготовить_конкурентную_фикстуру_под_надзором(модуль)
        else:
            сам.фикстура_конкуренции = ФикстураОтчётов()
            сам.фикстура_конкуренции.временный_каталог._finalizer.detach()
        сам.замок_конкуренции = tempfile.TemporaryDirectory(dir='/tmp')
        сам.замок_конкуренции._finalizer.detach()
        сам.владелец_конкуренции = модуль._ТестовыйВладелецЗапуска()
        сам.конкурент = None
        сам.попытка_конкурента = 'не начата'
        сам.передача_конкуренту = 'не начата'
        корень = сам.фикстура_конкуренции.корень.resolve()
        каталог = Path(сам.замок_конкуренции.name).resolve()
        запрос = сам.фикстура_конкуренции.запрос.resolve().relative_to(корень)
        _, _, _, _, сессия = модуль.разрешить_сессию(корень, запрос)
        fd = модуль._приобрести_fd(сам.fd_конкуренции, os.open, каталог,
                                   os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        сам.fd_замка_конкуренции = fd
        ст = os.fstat(fd)
        селектор = ('fum.test-lock-root.2', str(каталог), ст.st_dev, ст.st_ino, ст.st_uid,
                    ст.st_mode & 0o7777, сессия, str(корень))
        старый_селектор = старый_fd = None
        каталог_конкурента, fd_конкурента = каталог, fd
        if мост_со_старым:
            сам.старый_замок_конкуренции = tempfile.TemporaryDirectory(dir='/tmp')
            сам.старый_замок_конкуренции._finalizer.detach()
            каталог_конкурента = Path(сам.старый_замок_конкуренции.name).resolve()
            старый_fd = модуль._приобрести_fd(сам.fd_конкуренции, os.open, каталог_конкурента,
                                              os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            сам.старый_fd_конкуренции = старый_fd
            старый_ст = os.fstat(старый_fd)
            старый_селектор = ('fum.test-lock-root.2', str(каталог_конкурента), старый_ст.st_dev,
                               старый_ст.st_ino, старый_ст.st_uid, старый_ст.st_mode & 0o7777,
                               сессия, str(корень))
            fd_конкурента = старый_fd
        имя = 'fum-check-runs-' + hashlib.sha256(f'{корень}\0{сессия}'.encode('utf-8')).hexdigest() + '.lock'
        файл_fd = модуль._приобрести_fd(сам.fd_конкуренции, os.open, имя,
            os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600, dir_fd=fd_конкурента)
        os.fchmod(файл_fd, 0o600)
        метка = os.fstat(файл_fd)
        сам.assertTrue(stat.S_ISREG(метка.st_mode))
        сам.assertEqual((метка.st_uid, метка.st_nlink, метка.st_mode & 0o7777), (os.geteuid(), 1, 0o600))
        отпустить_fd('файл замка', файл_fd)
        код_нового = '\n'.join([
            'import fcntl,os,sys',
            'p=sys.argv[1]; fd=os.open(p,os.O_RDWR|os.O_NOFOLLOW|os.O_CLOEXEC)',
            'a=os.fstat(fd); b=os.stat(p,follow_symlinks=False)',
            'assert (a.st_dev,a.st_ino)==(int(sys.argv[2]),int(sys.argv[3]))==(b.st_dev,b.st_ino)',
            'os.write(1,b"R"); command=os.read(0,1)',
            'if command==b"B":',
            ' try: fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)',
            ' except BlockingIOError: os.write(1,b"B")',
            ' else: os.write(1,b"E"); os._exit(3)',
            ' command=os.read(0,1)',
            'assert command==b"G"',
            'fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)',
            'os.write(1,b"H"); assert os.read(0,1)==b"X"',
            'fcntl.flock(fd,fcntl.LOCK_UN); os.close(fd); os.write(1,b"K")',
        ])
        код_старого = '\n'.join([
            'import errno,fcntl,hashlib,os,pathlib,select,signal,sys,tempfile,types',
            'source=pathlib.Path(sys.argv[1]); data=source.read_bytes()',
            'assert hashlib.sha256(data).hexdigest()==sys.argv[7]',
            'native_flock=fcntl.flock',
            'assert type(native_flock).__name__=="builtin_function_or_method"',
            'assert native_flock.__module__=="fcntl" and native_flock.__name__=="flock"',
            'm=types.ModuleType("fum_legacy_child"); m.__file__=str(source); sys.modules[m.__name__]=m',
            'exec(compile(data,str(source),"exec"),m.__dict__)',
            'assert m.fcntl.flock is native_flock',
            'root=pathlib.Path(sys.argv[2]); session=sys.argv[3]; p=pathlib.Path(sys.argv[4])',
            'assert pathlib.Path(tempfile.gettempdir())==p.parent',
            'expected=(int(sys.argv[5]),int(sys.argv[6]))',
            's=p.lstat(); assert (s.st_dev,s.st_ino)==expected',
            'def send(x): os.write(1,x)',
            'def timeout(_number,_frame): raise TimeoutError("срок процесса legacy")',
            'assert signal.SIGALRM not in signal.pthread_sigmask(signal.SIG_BLOCK,set())',
            'signal.signal(signal.SIGALRM,timeout); signal.alarm(20)',
            'def receive():',
            ' if not select.select([0],[],[],10)[0]: raise TimeoutError("срок команды legacy")',
            ' return os.read(0,1)',
            'send(b"R"); command=receive()',
            'if command==b"B":',
            ' def observe(fd,operation):',
            '  s=os.fstat(fd)',
            '  if operation==fcntl.LOCK_EX and (s.st_dev,s.st_ino)==expected:',
            '   try: native_flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)',
            '   except BlockingIOError as error:',
            '    assert error.errno in (errno.EAGAIN,errno.EWOULDBLOCK)',
            '    send(b"B")',
            '   else:',
            '    native_flock(fd,fcntl.LOCK_UN)',
            '    raise AssertionError("legacy lock не был занят при публикации")',
            '   assert receive()==b"G"',
            '  return native_flock(fd,operation)',
            ' m.fcntl.flock=observe',
            'else: assert command==b"G"',
            'try:',
            ' with m.межпроцессная_блокировка(root,session):',
            '  s=p.lstat(); assert (s.st_dev,s.st_ino)==expected',
            '  send(b"H"); assert receive()==b"X"',
            'finally: m.fcntl.flock=native_flock',
            'send(b"K")',
        ])
        if мост_со_старым:
            if сам.исходник_legacy is None and сам.отпечаток_legacy is None:
                исходник_legacy = Path(сценарий)
                отпечаток_legacy = hashlib.sha256(исходник_legacy.read_bytes()).hexdigest()
            else:
                if (type(сам.исходник_legacy) is not str or type(сам.отпечаток_legacy) is not str
                    or re.fullmatch(r'[0-9a-f]{64}', сам.отпечаток_legacy) is None):
                    raise ValueError('нужны путь и SHA256 исходника прежнего замка')
                исходник_legacy, отпечаток_legacy = Path(сам.исходник_legacy), сам.отпечаток_legacy
            команда_конкурента = [sys.executable, '-I', '-S', '-B', '-u', '-c', код_старого,
                                 str(исходник_legacy), str(корень), сессия, str(каталог_конкурента / имя),
                                 str(метка.st_dev), str(метка.st_ino), отпечаток_legacy]
            среда_конкурента = {'PATH': '/usr/bin:/bin', 'LC_ALL': 'C', 'TMPDIR': str(каталог_конкурента)}
        else:
            команда_конкурента = [sys.executable, '-I', '-S', '-B', '-u', '-c', код_нового,
                                 str(каталог_конкурента / имя), str(метка.st_dev), str(метка.st_ino)]
            среда_конкурента = {'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'}
        сам.попытка_конкурента = 'запуск начат'
        сам.параметры_конкурента = (tuple(команда_конкурента), dict(среда_конкурента))
        сам.конкурент = subprocess.Popen(
            команда_конкурента, env=среда_конкурента,
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            close_fds=True, start_new_session=True)
        сам.попытка_конкурента = 'получен'
        сам.каналы_конкурента = (сам.конкурент.stdin, сам.конкурент.stdout, сам.конкурент.stderr)
        сам.метки_каналов_конкурента = tuple((поток.fileno(), os.fstat(поток.fileno()).st_dev,
                                              os.fstat(поток.fileno()).st_ino)
                                             for поток in сам.каналы_конкурента)
        сам.assertGreater(сам.конкурент.pid, 1)
        os.set_blocking(сам.конкурент.stdin.fileno(), False)
        if изолировать_git:
            os.set_blocking(сам.конкурент.stdout.fileno(), False)
            os.set_blocking(сам.конкурент.stderr.fileno(), False)
        сам.assertTrue(select.select([сам.конкурент.stdout.fileno()], [], [], 5.0)[0])
        сам.assertEqual(os.read(сам.конкурент.stdout.fileno(), 1), b'R')
        на_диске = (каталог_конкурента / имя).lstat()
        сам.assertEqual((на_диске.st_dev, на_диске.st_ino), (метка.st_dev, метка.st_ino))
        def занять():
            сам.передача_конкуренту = 'захват начат'
            сам.assertEqual(os.write(сам.конкурент.stdin.fileno(), b'G'), 1)
            сам.передача_конкуренту = 'захват передан'
            сам.assertTrue(select.select([сам.конкурент.stdout.fileno()], [], [], 5.0)[0])
            сам.assertEqual(os.read(сам.конкурент.stdout.fileno(), 1), b'H')
            сам.передача_конкуренту = 'замок занят'

        def выполнить():
            return модуль._выполнить_ограниченный_запуск(
                корень, запрос, 'конкурент замка', 'корень', str(uuid.uuid4()), 5.0,
                (('/usr/bin/false' if ожидается_ошибка else '/usr/bin/true'),),
                класс_проверки='адресная', тайм_аут_блокировки=0.2,
                _тестовый_селектор=селектор, _тестовый_дескриптор=fd,
                _тестовый_владелец=сам.владелец_конкуренции, _тестовый_снимок=True,
                _тестовый_удерживаемый_снимок=True,
                _тестовая_политика_снимка='isolated-git.2' if изолировать_git else 'legacy.1',
                _тестовый_старый_селектор=старый_селектор, _тестовый_старый_fd=старый_fd,
                _тестовый_наблюдатель=(Path(сам.исполнитель_наблюдателя), сам.отпечаток_наблюдателя,
                                       Path(сам.исполнитель_якоря), сам.отпечаток_якоря))
        if фаза == 'до-active':
            занять()
            with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'истёк срок'):
                выполнить()
            сам.assertEqual(сам.фикстура_конкуренции.файлы_записей(), [])
        elif фаза == 'до-terminal':
            штатное_закрытие = модуль._ТестовыйКонтурНаблюдателя.закрыть_после_успеха
            def после_наблюдателя(контур):
                результат = штатное_закрытие(контур)
                сам.активные_байты_до_конкуренции = сам.владелец_конкуренции.активная_запись.read_bytes()
                занять()
                return результат
            with mock.patch.object(модуль._ТестовыйКонтурНаблюдателя,
                                   'закрыть_после_успеха', new=после_наблюдателя):
                сам.assertEqual(выполнить(), модуль.КОД_ОШИБКИ_ОБЁРТКИ)
            файлы = сам.фикстура_конкуренции.файлы_записей()
            сам.assertEqual(len(файлы), 1)
            сам.assertEqual(файлы[0].read_bytes(), сам.активные_байты_до_конкуренции)
            сам.assertEqual(json.loads(файлы[0].read_bytes())['состояние'], 'выполняется')
        elif фаза in ('внутри-active', 'внутри-terminal'):
            штатная_запись = модуль.атомарно_записать_байты
            сам.попытки_внутри_замка = 0
            def запись_с_конкурентом(путь, байты, **ключи):
                начало = ключи.get('только_новый', False)
                if (путь == сам.владелец_конкуренции.активная_запись
                    and начало == (фаза == 'внутри-active')):
                    def проверить_конкурента():
                        сам.попытки_внутри_замка += 1
                        сам.передача_конкуренту = 'проба начата'
                        сам.assertEqual(os.write(сам.конкурент.stdin.fileno(), b'B'), 1)
                        сам.передача_конкуренту = 'проба передана'
                        сам.assertTrue(select.select([сам.конкурент.stdout.fileno()], [], [], 5.0)[0])
                        сам.assertEqual(os.read(сам.конкурент.stdout.fileno(), 1), b'B')
                        сам.передача_конкуренту = 'замок подтвердил отказ'
                    if изолировать_git:
                        штатная_сверка = ключи['перед_публикацией']
                        def перед_публикацией():
                            штатная_сверка(); проверить_конкурента()
                        ключи['перед_публикацией'] = перед_публикацией
                    else:
                        проверить_конкурента()
                return штатная_запись(путь, байты, **ключи)
            with mock.patch.object(модуль, 'атомарно_записать_байты', new=запись_с_конкурентом):
                сам.assertEqual(выполнить(), 1 if ожидается_ошибка else 0)
            сам.assertEqual(сам.попытки_внутри_замка, 1)
            сам.assertEqual(сам.владелец_конкуренции.состояние, 'завершён')
            сам.assertTrue(сам.владелец_конкуренции.терминальная_запись_вернула_успех)
            сам.assertEqual(сам.владелец_конкуренции._контейнер_снимка.состояние, 'закрыт')
            файлы = сам.фикстура_конкуренции.файлы_записей()
            сам.assertEqual(len(файлы), 1)
            сам.assertEqual(файлы[0].read_bytes(), сам.владелец_конкуренции.терминальные_байты)
            if изолировать_git:
                терминал = json.loads(файлы[0].read_bytes())
                сам.assertEqual(терминал['схема'], модуль._ТЕСТОВАЯ_СХЕМА_ЗАПУСКА_С_ИЗОЛЯЦИЕЙ_GIT)
                сам.assertEqual(терминал['профиль_проверки']['отпечаток_снимка']['схема'],
                                'fum.test-snapshot.physical-lease.2')
                контур = сам.владелец_конкуренции._транспорт_binding
                with сам.владелец_конкуренции._блокировка:
                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                        модуль._тестовый_итог_контура_наблюдателя(контур)
                    for неверный_выбор in (None, 0, 1, 'да'):
                        with сам.assertRaises(модуль.ОшибкаОтчёта):
                            модуль._тестовый_итог_контура_наблюдателя(контур, _после_закрытия=неверный_выбор)
                    итог = модуль._тестовый_итог_контура_наблюдателя(контур, _после_закрытия=True)
                    сам.assertEqual((итог.статус, итог.код_записи, итог.возвращаемый_код),
                                    ('неуспешно', 1, 1) if ожидается_ошибка else ('успешно', 0, 0))
                    изменённое = контур._свидетельство._replace(сырой_статус=контур._свидетельство.сырой_статус ^ 256)
                    for поле, значение in (('_ошибка', OSError('synthetic close error')),
                                           ('_дескрипторы', [-1]), ('_свидетельство', изменённое)):
                        with mock.patch.object(контур, поле, значение), сам.assertRaises(модуль.ОшибкаОтчёта):
                            модуль._тестовый_итог_контура_наблюдателя(контур, _после_закрытия=True)
                    сам.assertEqual(модуль._тестовый_итог_контура_наблюдателя(
                        контур, _после_закрытия=True), итог)
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    модуль._тестовый_итог_контура_наблюдателя(контур, _после_закрытия=True)
                свидетельство = сам.владелец_конкуренции._проект_свидетельства
                if ожидается_ошибка:
                    сам.assertIsNone(свидетельство)
                    сам.assertEqual((терминал['статус'], терминал['код_завершения']), ('неуспешно', 1))
                else:
                    сам._проверить_проект_двойного_запуска(
                        модуль, свидетельство, корень, сессия, терминал,
                        старый_селектор, старый_fd, селектор, fd)
            занять()
        else:
            raise AssertionError('неверная фаза конкуренции')
        if фаза in ('до-active', 'до-terminal'):
            сам.assertEqual(сам.владелец_конкуренции.состояние, 'неизвестно')
            сам.assertEqual(сам.владелец_конкуренции.запись_вернула_успех, фаза == 'до-terminal')
            сам.assertFalse(сам.владелец_конкуренции.терминальная_запись_вернула_успех)
        if фаза == 'до-active':
            сам.assertIsNone(сам.владелец_конкуренции.процесс)
            сам.assertIsNone(сам.владелец_конкуренции._транспорт_binding)
        else:
            сам.assertEqual(сам.владелец_конкуренции.процесс.returncode, 0)
            сам.assertEqual(сам.владелец_конкуренции._транспорт_binding.состояние, 'закрыт')
        if фаза in ('до-active', 'до-terminal'):
            сам.assertEqual(сам.владелец_конкуренции._контейнер_снимка.состояние, 'удерживается')
        сам.assertFalse(модуль._тестовые_активные_замки)
        сам.assertFalse(модуль._тестовые_git_под_надзором)
        сам.assertTrue(сам.владелец_конкуренции._git_снимка)
        сам.assertTrue(all(группа and all(в.состояние == 'лидер-собран' and в.код == 0
                                          and в.закрытие == ('закрыт', 'закрыт') for в in группа)
                            for группа in сам.владелец_конкуренции._git_снимка))
        сам.передача_конкуренту = 'начата'
        сам.assertEqual(os.write(сам.конкурент.stdin.fileno(), b'X'), 1)
        сам.передача_конкуренту = 'подтверждена'
        сам.assertTrue(select.select([сам.конкурент.stdout.fileno()], [], [], 5.0)[0])
        сам.assertEqual(os.read(сам.конкурент.stdout.fileno(), 1), b'K')
        if изолировать_git:
            for поток in (сам.конкурент.stdout, сам.конкурент.stderr): os.set_blocking(поток.fileno(), False)
            сам.попытка_конкурента = 'чтение и сбор начаты'
            результат = модуль._тестовое_согласовать_чтение_и_сбор(
                сам.конкурент, сам.конкурент.stdout.fileno(), сам.конкурент.stderr.fileno(),
                срок=time.monotonic()+5, предел_вывода=256, предел_ошибок=8192, предел_суммы=8448)
            сам.assertEqual(результат, (b'', b'', 0))
            with сам.assertRaises(ProcessLookupError): os.killpg(сам.конкурент.pid, 0)
            for имя_канала, поток in zip(('stdin', 'stdout', 'stderr'), сам.каналы_конкурента):
                сам.закрытие_канала_конкуренции = ('начато', имя_канала, поток.fileno())
                поток.close()
                сам.закрытие_канала_конкуренции = ('завершено', имя_канала)
        else:
            сам.assertEqual(сам.конкурент.wait(timeout=5.0), 0)
        сам.попытка_конкурента = 'собран'
        if изолировать_git:
            сам.assertEqual(сам.владелец_конкуренции.состояние, 'завершён')
            сам.assertEqual(сам.владелец_конкуренции._контейнер_снимка.состояние, 'закрыт')
            сам.очистка_конкуренции = 'начата'
            for значение in tuple(reversed(сам.fd_конкуренции)): отпустить_fd('каталог замка', значение)
            for значение in tuple(reversed(сам.fd_подготовки_конкуренции)):
                сам.закрытие_подготовки_конкуренции = ('начато', значение)
                модуль._отпустить_зарегистрированный_fd(сам.fd_подготовки_конкуренции, значение)
                сам.закрытие_подготовки_конкуренции = ('завершено', значение)
            if сам.сохранить_фикстуру_конкуренции is True:
                сам.очистка_конкуренции = 'дескрипторы закрыты, фикстуры сохранены'
            else:
                сам.фикстура_конкуренции.очистить()
                сам.замок_конкуренции.cleanup(); сам.старый_замок_конкуренции.cleanup()
                сам.база_подготовки_конкуренции.cleanup()
                сам.очистка_конкуренции = 'завершена'

    def _проверить_проект_двойного_запуска(сам, модуль, свидетельство, корень, сессия, терминал,
                                          старый_селектор, старый_fd, селектор, fd):
        сам.assertIs(type(свидетельство), модуль._ТестовыйПроектСвидетельстваДвойногоЗапуска)
        сам.assertEqual(свидетельство.схема, 'fum.test-dual-producer-draft.1')
        сам.assertIs(свидетельство.владелец, сам.владелец_конкуренции)
        сам.assertIs(свидетельство.контейнер, сам.владелец_конкуренции._контейнер_снимка)
        сам.assertIs(свидетельство.транспорт, сам.владелец_конкуренции._транспорт_binding)
        сам.assertEqual((свидетельство.корень, свидетельство.сессия, свидетельство.идентификатор),
                        (корень, сессия, терминал['идентификатор']))
        сам.assertEqual(свидетельство.контракт[0], 'fum.test-lock-bridge.1')
        сам.assertIs(свидетельство.контракт[1], старый_селектор)
        сам.assertEqual(свидетельство.контракт[2], старый_fd)
        сам.assertIs(свидетельство.контракт[3], селектор)
        сам.assertEqual(свидетельство.контракт[4], fd)
        сам.assertEqual(свидетельство.снимок._asdict(), терминал['профиль_проверки']['отпечаток_снимка'])
        сам.assertIs(свидетельство.терминал, сам.владелец_конкуренции.терминальные_байты)
        сам.assertEqual(свидетельство.исходный_отчёт, сам.фикстура_конкуренции.отчёт.read_bytes())
        owner = сам.владелец_конкуренции
        контур = свидетельство.транспорт
        связь = контур._связь_изолированного_запуска
        with owner._блокировка, \
             mock.patch.object(модуль.subprocess, 'Popen', side_effect=AssertionError('процесс')) as popen, \
             mock.patch.object(модуль, '_тестово_выбрать_замок_сессии', side_effect=AssertionError('замок')) as замок, \
             mock.patch.object(модуль, 'прочитать_машинную_запись', side_effect=AssertionError('файл')) as чтение:
            сам.assertIsNone(связь.сверить_проект_после_запуска(контур, свидетельство))
            чужой_снимок = свидетельство.снимок._replace(значение=свидетельство.снимок.значение)
            подделка = свидетельство._replace(снимок=чужой_снимок)
            with mock.patch.object(owner, '_проект_свидетельства', подделка), сам.assertRaises(модуль.ОшибкаОтчёта):
                связь.сверить_проект_после_запуска(контур, подделка)
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                связь.сверить_проект_после_запуска(контур, подделка)
            чужой_контракт = tuple(list(свидетельство.контракт))
            сам.assertEqual(чужой_контракт, свидетельство.контракт)
            сам.assertIsNot(чужой_контракт, свидетельство.контракт)
            поддельный_контракт = свидетельство._replace(контракт=чужой_контракт)
            with mock.patch.object(owner, '_проект_свидетельства', поддельный_контракт), сам.assertRaises(модуль.ОшибкаОтчёта):
                связь.сверить_проект_после_запуска(контур, поддельный_контракт)
            чужой_терминал = memoryview(свидетельство.терминал).tobytes()
            сам.assertEqual(чужой_терминал, свидетельство.терминал)
            сам.assertIsNot(чужой_терминал, свидетельство.терминал)
            поддельный_терминал = свидетельство._replace(терминал=чужой_терминал)
            with mock.patch.object(owner, '_проект_свидетельства', поддельный_терминал), сам.assertRaises(модуль.ОшибкаОтчёта):
                связь.сверить_проект_после_запуска(контур, поддельный_терминал)
            for объект, поле, значение in (
                (owner, 'состояние', 'неизвестно'),
                (owner, 'терминальная_запись_вернула_успех', False),
                (контур, '_команда_связи', ('/usr/bin/false',)),
                (контур, '_корень_связи', Path('/private/tmp/other')),
                (контур, '_исполнители', ())):
                with mock.patch.object(объект, поле, значение), сам.assertRaises(модуль.ОшибкаОтчёта):
                    связь.сверить_проект_после_запуска(контур, свидетельство)
            сам.assertIsNone(связь.сверить_проект_после_запуска(контур, свидетельство))
            popen.assert_not_called(); замок.assert_not_called(); чтение.assert_not_called()
        with сам.assertRaises(модуль.ОшибкаОтчёта):
            связь.сверить_проект_после_запуска(контур, свидетельство)

