    def _проверить_контейнер_наблюдателя(сам, истечение, проверка_среды=False, изолировать_git=False):
        import threading
        сам.assertFalse(истечение and проверка_среды)
        сам.assertFalse(изолировать_git and not проверка_среды)
        if (сам.исполнитель_якоря is None or сам.отпечаток_якоря is None
            or сам.исполнитель_наблюдателя is None or сам.отпечаток_наблюдателя is None
            or сам.удержать_неизвестный_исход is not True):
            сам.skipTest('нужны исполнители, отпечатки и живой владелец неизвестного исхода')
        модуль = загрузить_модуль_автоматизации()
        сам.дескриптор_корня_замка = None
        сам.каталог_контейнера = tempfile.TemporaryDirectory(dir='/tmp')
        сам.owner_контейнера = модуль._ТестовыйВладелецЗапуска()
        сам.owner_контейнера._блокировка.acquire()
        сам.owner_контейнера._поток_владельца = модуль._thread.get_ident()
        сам.owner_контейнера._объект_потока = threading.current_thread()
        завершено = False
        try:
            корень = Path(сам.каталог_контейнера.name).resolve()
            идентификатор = str(uuid.uuid4())
            активная = корень / 'active.json'
            байты = json.dumps({'идентификатор': идентификатор, 'состояние': 'выполняется'},
                               ensure_ascii=False).encode()
            активная.write_bytes(байты)
            сам.owner_контейнера.активная_запись = активная
            сам.owner_контейнера.байты_записи = байты
            сам.owner_контейнера.запись_вернула_успех = True
            каталог_замка = корень / 'lock-root'
            каталог_замка.mkdir(mode=0o700)
            сам.дескриптор_корня_замка = os.open(
                каталог_замка, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            метка = os.fstat(сам.дескриптор_корня_замка)
            сессия = 'container-' + идентификатор
            селектор = ('fum.test-lock-root.2', str(каталог_замка), метка.st_dev, метка.st_ino,
                        метка.st_uid, метка.st_mode & 0o7777, сессия, str(корень))
            срок = time.monotonic_ns() // 1_000_000 + (3000 if истечение else 8000)
            стоп = срок + 5000
            def получить_замок():
                return модуль._тестовый_замок_новой_сессии(
                    селектор, сам.дескриптор_корня_замка, корень, сессия, срок_монотонный=стоп / 1000)
            сам.контейнер = модуль._ТестовыйКонтурНаблюдателя(сам.owner_контейнера, идентификатор, срок, стоп)
            if проверка_среды:
                проверка = ('[ "${PATH-}" = "/bin:/usr/bin" ] && [ "${LC_ALL-}" = C ] && '
                            '[ "${GIT_OPTIONAL_LOCKS-}" = 0 ] && [ "${GIT_NO_LAZY_FETCH-}" = 1 ] && '
                            '[ "${GIT_NO_REPLACE_OBJECTS-}" = 1 ] && [ "${FUM_CHECK_RUN_ID-}" = "$1" ] && ')
                проверка += ('[ "${GIT_CONFIG_NOSYSTEM-}" = 1 ] && [ "${GIT_CONFIG_GLOBAL-}" = /dev/null ] && '
                             '[ "${GIT_ATTR_NOSYSTEM-}" = 1 ]' if изолировать_git else
                             '[ "${GIT_CONFIG_NOSYSTEM+x}" != x ] && [ "${GIT_CONFIG_GLOBAL+x}" != x ] && '
                             '[ "${GIT_ATTR_NOSYSTEM+x}" != x ]')
                команда = ('/bin/sh', '-c', проверка, 'fixture', идентификатор)
            else:
                команда = ('/bin/sleep', '30' if истечение else '1')
            сам.контейнер.запустить(Path(сам.исполнитель_наблюдателя), сам.отпечаток_наблюдателя,
                                    Path(сам.исполнитель_якоря), сам.отпечаток_якоря, корень,
                                    команда, получить_замок, _изолировать_git=изолировать_git)
            сам.assertEqual(сам.контейнер._политика_среды,
                            'isolated-git.2' if изолировать_git else 'legacy.1')
            свидетельство = сам.контейнер.довести(получить_замок)
            if проверка_среды and изолировать_git:
                сам.assertEqual(сам.owner_контейнера.сырой_статус, 0)
            raw, код, тайм_аут = свидетельство.сырой_статус, свидетельство.код_цели, свидетельство.тайм_аут
            кадры, код_наблюдателя = свидетельство.кадры, свидетельство.код_наблюдателя
            сам.assertEqual(свидетельство.идентификатор, идентификатор)
            сам.assertLessEqual(свидетельство.начало_попытки_ns, свидетельство.конец_наблюдения_ns)
            сам.assertLess(свидетельство.конец_наблюдения_ns // 1_000_000, стоп)
            сам.assertEqual(тайм_аут, истечение)
            сам.assertEqual(код_наблюдателя, 0)
            сам.assertEqual([кадр[:4] for кадр in кадры], [b'FUA1', b'FUS1', b'FUP1', b'FUD1'])
            сам.assertEqual(код, -int(raw) if истечение else 0)
            сам.assertIn(raw, (signal.SIGTERM, signal.SIGKILL) if истечение else (0,))
            итог = модуль._тестовый_итог_контура_наблюдателя(сам.контейнер)
            сам.assertEqual(итог.статус, 'не завершено' if истечение else 'успешно')
            сам.assertEqual(итог.код_записи, 124 if истечение else 0)
            сам.assertEqual(итог.возвращаемый_код, 124 if истечение else 0)
            сам.assertEqual(итог.длительность_ns, свидетельство.конец_наблюдения_ns - свидетельство.начало_попытки_ns)
            pid_якоря = int.from_bytes(кадры[0][20:24], 'big')
            with сам.assertRaises(ProcessLookupError):
                os.killpg(pid_якоря, 0)
            сам.контейнер.закрыть_после_успеха()
            сам.assertEqual(сам.контейнер.состояние, 'закрыт')
            завершено = True
        finally:
            if завершено:
                сам.очистка_контейнера = 'закрытие корня замка начато'
                try:
                    os.close(сам.дескриптор_корня_замка)
                    сам.очистка_контейнера = 'закрытие владельца начато'
                    сам.owner_контейнера._блокировка.release()
                    сам.очистка_контейнера = 'удаление своего каталога начато'
                    сам.каталог_контейнера.cleanup()
                except BaseException:
                    сам.очистка_контейнера = 'неизвестна'
                    raise
                сам.очистка_контейнера = 'завершена'

