    def test_выходы_наблюдателя_отклоняют_совпадение_и_неподходящий_fd(сам):
        модуль = загрузить_модуль_автоматизации()
        with contextlib.ExitStack() as очистка:
            первый_чтение, первый_выход = os.pipe()
            очистка.callback(os.close, первый_чтение)
            очистка.callback(os.close, первый_выход)
            второй_чтение, второй_выход = os.pipe()
            очистка.callback(os.close, второй_чтение)
            очистка.callback(os.close, второй_выход)
            копия = os.dup(первый_выход)
            очистка.callback(os.close, копия)
            выходы = (первый_выход, второй_выход)
            метки = модуль._тестово_сверить_выходы_наблюдателя(выходы)
            сам.assertEqual(модуль._тестово_сверить_выходы_наблюдателя(
                выходы, ожидаемые=метки), метки)
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестово_сверить_выходы_наблюдателя((первый_выход, копия))
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестово_сверить_выходы_наблюдателя((первый_чтение, второй_выход))
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестово_сверить_выходы_наблюдателя(
                    выходы, служебные=(первый_чтение,))
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестово_сверить_выходы_наблюдателя(
                    выходы, служебные=(второй_чтение,))
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестово_сверить_выходы_наблюдателя(
                    выходы, ожидаемые=(метки[1], метки[0]))
            os.set_inheritable(первый_выход, True)
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестово_сверить_выходы_наблюдателя(выходы)
            os.set_inheritable(первый_выход, False)

