    def test_отказ_второй_пары_сохраняет_первую_без_повтора(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        try:
            владелец._поток_владельца = модуль._thread.get_ident()
            владелец._объект_потока = threading.current_thread()
            срок = time.monotonic_ns() // 1_000_000 + 5000
            контур = модуль._ТестовыйКонтурНаблюдателя(
                владелец, '00112233-4455-4677-8899-aabbccddeeff', срок, срок + 5000)
            ошибка = OSError('вторая пара до вызова')
            with mock.patch.object(модуль.os, 'pipe',
                    side_effect=[(10101, 10102), ошибка]) as pipe, \
                 mock.patch.object(модуль.os, 'close') as закрыть, \
                 mock.patch.object(модуль.subprocess, 'Popen') as popen:
                with сам.assertRaisesRegex(OSError, 'вторая пара до вызова') as перехвачена:
                    контур.подготовить_собственные_выходы()
                сам.assertIs(перехвачена.exception, ошибка)
                сам.assertEqual(контур.состояние, 'неизвестно')
                сам.assertEqual(контур._фаза_собственных_выходов, 'создание stderr начато')
                сам.assertEqual(контур._пара_выхода, (10101, 10102))
                сам.assertIsNone(контур._пара_ошибок)
                сам.assertEqual(контур._дескрипторы, [10101, 10102])
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    контур.подготовить_собственные_выходы()
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    контур.закрыть_собственные_выходы_до_запуска()
                сам.assertEqual(pipe.call_count, 2)
                закрыть.assert_not_called()
                popen.assert_not_called()
        finally:
            владелец._блокировка.release()

    def test_неизвестное_закрытие_пары_не_повторяется(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        try:
            владелец._поток_владельца = модуль._thread.get_ident()
            владелец._объект_потока = threading.current_thread()
            срок = time.monotonic_ns() // 1_000_000 + 5000
            контур = модуль._ТестовыйКонтурНаблюдателя(
                владелец, '00112233-4455-4677-8899-aabbccddeeff', срок, срок + 5000)
            контур._пара_выхода = (10101, 10102)
            контур._пара_ошибок = (10103, 10104)
            контур._дескрипторы = [10101, 10102, 10103, 10104]
            контур._фаза_собственных_выходов = 'подготовлены'
            контур._метки_собственных_выходов = ('искусственная метка',)
            ошибка = OSError('закрытие до системного вызова')
            with mock.patch.object(контур, '_сверить_собственные_выходы',
                                   return_value=('искусственная метка',)), \
                 mock.patch.object(модуль.os, 'close', side_effect=[None, ошибка]) as закрыть:
                with сам.assertRaises(модуль.ОшибкаОтчёта) as перехвачена:
                    контур.закрыть_собственные_выходы_до_запуска()
                сам.assertIs(перехвачена.exception.__cause__, ошибка)
                сам.assertEqual(контур.состояние, 'неизвестно')
                сам.assertEqual(контур._попытка_закрытия_выхода, (10102, 'начата'))
                сам.assertEqual(контур._дескрипторы, [10103, 10104])
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    контур.закрыть_собственные_выходы_до_запуска()
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    контур.подготовить_собственные_выходы()
                сам.assertEqual(закрыть.call_count, 2)
                сам.assertEqual(закрыть.call_args_list, [mock.call(10101), mock.call(10102)])
        finally:
            владелец._блокировка.release()

    def test_лишний_fd_в_реестре_выходов_отклоняется_до_fstat(сам):
        import threading
