    def test_приём_собственных_выходов_сохраняет_обе_порции(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        сам.owner_приёма = модуль._ТестовыйВладелецЗапуска()
        сам.owner_приёма._блокировка.acquire()
        сам.owner_приёма._поток_владельца = модуль._thread.get_ident()
        сам.owner_приёма._объект_потока = threading.current_thread()
        срок = time.monotonic_ns() // 1_000_000 + 5000
        сам.контур_приёма = модуль._ТестовыйКонтурНаблюдателя(
            сам.owner_приёма, '00112233-4455-4677-8899-aabbccddeeff', срок, срок + 5000)
        сам.контур_приёма.подготовить_собственные_выходы()
        сам.приём_выходов = сам.контур_приёма.подготовить_приём_собственных_выходов(
            предел_stdout=2, предел_stderr=3, предел_суммы=5)
        stdout_r, stdout_w = сам.контур_приёма._пара_выхода
        stderr_r, stderr_w = сам.контур_приёма._пара_ошибок
        сам.assertEqual(сам.приём_выходов.прочитать_готовый(stdout_r), 'нет данных')
        os.set_blocking(stdout_w, False)
        сам.assertNotEqual(сам.контур_приёма._сверить_собственные_выходы(),
                           сам.контур_приёма._метки_собственных_выходов)
        os.set_blocking(stdout_w, True)
        сам.assertEqual(сам.контур_приёма._сверить_собственные_выходы(),
                        сам.контур_приёма._метки_собственных_выходов)
        сам.assertEqual(os.write(stdout_w, b'AB'), 2)
        сам.assertEqual(os.write(stderr_w, b'xyz'), 3)
        сам.assertEqual(сам.приём_выходов.прочитать_готовый(stderr_r), 'данные')
        сам.assertEqual(сам.контур_приёма._шаг(
            'готов', lambda: сам.приём_выходов._прочитать_готовый_внутри(stdout_r)), 'данные')
        сам.assertEqual(сам.приём_выходов.снимок(), ((b'AB', b'xyz'), (False, False), None, 'готов'))
        сам.приём_выходов.отпустить_до_запуска()
        сам.контур_приёма.закрыть_собственные_выходы_до_запуска()
        сам.assertEqual(сам.контур_приёма._дескрипторы, [])
        сам.owner_приёма._блокировка.release()

    def test_waitid_дренирует_выходы_до_следующего_опроса(сам):
        import threading
        import types
        модуль = загрузить_модуль_автоматизации()
        сам.owner_waitid = модуль._ТестовыйВладелецЗапуска()
        сам.owner_waitid._блокировка.acquire()
        сам.owner_waitid._поток_владельца = модуль._thread.get_ident()
        сам.owner_waitid._объект_потока = threading.current_thread()
        срок = time.monotonic_ns() // 1_000_000 + 5000
        сам.контур_waitid = модуль._ТестовыйКонтурНаблюдателя(
            сам.owner_waitid, '00112233-4455-4677-8899-aabbccddeeff', срок, срок + 5000)
        сам.контур_waitid.подготовить_собственные_выходы()
        сам.приём_waitid = сам.контур_waitid.подготовить_приём_собственных_выходов(
            предел_stdout=2, предел_stderr=3, предел_суммы=5)
        сам.owner_waitid.pid = 777
        сам.owner_waitid.процесс = types.SimpleNamespace(pid=777)
        stdout_r, stdout_w = сам.контур_waitid._пара_выхода
        stderr_r, stderr_w = сам.контур_waitid._пара_ошибок
        сам.assertEqual(os.write(stdout_w, b'AB'), 2)
        сам.assertEqual(os.write(stderr_w, b'xyz'), 3)
        вызовы = []
        def waitid(тип, pid, флаги):
            вызовы.append((тип, pid, флаги))
            if len(вызовы) == 1:
                return None
            сам.assertEqual(tuple(bytes(x) for x in сам.приём_waitid._буферы), (b'AB', b'xyz'))
            return types.SimpleNamespace(si_pid=777, si_code=os.CLD_EXITED, si_status=0)
        with mock.patch.object(модуль.os, 'waitid', side_effect=waitid), \
             mock.patch.object(модуль.os, 'waitpid') as waitpid, \
             mock.patch.object(модуль.subprocess, 'Popen') as popen:
            with сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._тестово_дренировать_при_ожидании(сам.приём_waitid, срок=time.monotonic()+1)
            def отвергнуть_чужой_pid():
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'не принадлежит'):
                    модуль._тестовое_наблюдение_дочернего_процесса(
                        778, срок=time.monotonic()+1, _тестовый_приём_выходов=сам.приём_waitid)
            сам.контур_waitid._шаг('готов', отвергнуть_чужой_pid)
            сам.assertEqual(вызовы, [])
            результат = сам.контур_waitid._шаг('готов', lambda:
                модуль._тестовое_наблюдение_дочернего_процесса(
                    777, срок=time.monotonic()+1, _тестовый_приём_выходов=сам.приём_waitid))
            сам.assertEqual(результат, 0)
            сам.assertEqual(вызовы, [(os.P_PID, 777, os.WEXITED | os.WNOHANG | os.WNOWAIT)] * 2)
            waitpid.assert_not_called(); popen.assert_not_called()
        сам.приём_waitid.отпустить_до_запуска()
        сам.контур_waitid.закрыть_собственные_выходы_до_запуска()
        сам.owner_waitid._блокировка.release()

