            сам.assertFalse(результат)
            сам.assertEqual(tuple(bytes(x) for x in сам.приём_eof._буферы), (b'AB', b'xyz'))
            сам.assertEqual(os.write(status_w, b'!'), 1)
            результат = сам.контур_eof._шаг('готов', lambda:
                модуль._тестово_ожидать_готовность_eof(
                    сам.контур_eof, сам.приём_eof, процесс, срок=time.monotonic()+1))
            сам.assertTrue(результат)
            сам.assertEqual(os.read(status_r, 1), b'!')
            waitpid.assert_not_called(); popen.assert_not_called()
