    def _проверить_отказ_регистрации_open(сам, вариант):
        сам.модуль_open_fault = загрузить_модуль_автоматизации()
        модуль = сам.модуль_open_fault
        сам.корень_open_fault = Path(tempfile.mkdtemp(prefix='fum-lock-open-fault-', dir='/private/tmp'))
        каталог = сам.корень_open_fault / 'locks'
        каталог.mkdir(mode=0o700)
        сам.fd_open_fault = os.open(каталог, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        метка = os.fstat(сам.fd_open_fault)
        сессия = 'open-fault-fixture'
        селектор = ('fum.test-lock-root.2', str(каталог), метка.st_dev, метка.st_ino,
                    метка.st_uid, метка.st_mode & 0o7777, сессия, str(сам.корень_open_fault))
        до = set(модуль._тестовые_владельцы_замков)
        настоящий_open = os.open
        сам.fd_из_модели = None
        сам.ошибка_open_fault = OSError('модель отказа open')
        сам.ошибка_mask_fault = RuntimeError('модель отказа маски')
        def открыть(*аргументы, **ключи):
            if вариант == 'двойная':
                raise сам.ошибка_open_fault
            if вариант == 'регистрация':
                return 777
            сам.fd_из_модели = настоящий_open(*аргументы, **ключи)
            return сам.fd_из_модели
        def маска(операция, значения):
            if вариант in ('маска', 'двойная') and операция == signal.SIG_SETMASK:
                raise сам.ошибка_mask_fault
            return set()
        сам.прерывание_open_fault = False
        def установить(маркер, имя, значение):
            object.__setattr__(маркер, имя, значение)
            if (вариант == 'регистрация' and имя == 'попытка_открытия'
                and isinstance(значение, tuple) and значение[1] == 'получен'
                and not сам.прерывание_open_fault):
                сам.прерывание_open_fault = True
                raise KeyboardInterrupt('модель отказа регистрации')
        with mock.patch.object(модуль.os, 'open', side_effect=открыть) as открыть_mock, \
             mock.patch.object(модуль.os, 'close') as close_mock, \
             mock.patch.object(модуль.signal, 'pthread_sigmask', side_effect=маска), \
             mock.patch.object(модуль._ТестовыйМаркерУдержанияЗамка, '__setattr__', new=установить), \
             mock.patch.object(модуль.fcntl, 'flock') as flock:
            ожидаемая_ошибка = (KeyboardInterrupt if вариант == 'регистрация' else
                                BaseExceptionGroup if вариант == 'двойная' else RuntimeError)
            with сам.assertRaises(ожидаемая_ошибка) as отказ:
                with модуль._тестовый_замок_новой_сессии(
                    селектор, сам.fd_open_fault, сам.корень_open_fault, сессия,
                    срок_монотонный=time.monotonic()+2):
                    сам.fail('неизвестный open допущен')
            сам.маркеры_open_fault = list(модуль._тестовые_владельцы_замков - до)
            сам.assertEqual(len(сам.маркеры_open_fault), 1)
            маркер = сам.маркеры_open_fault[0]
            сам.assertTrue(маркер.группа.неизвестно)
            ожидаемый_fd = 777 if вариант == 'регистрация' else сам.fd_из_модели
            сам.assertEqual(маркер.попытка_открытия[1:],
                            ('начата' if вариант == 'двойная' else 'получен', ожидаемый_fd))
            if вариант == 'двойная':
                сам.assertIs(отказ.exception.exceptions[0], сам.ошибка_open_fault)
                сам.assertIs(отказ.exception.exceptions[1], сам.ошибка_mask_fault)
            сам.assertEqual(маркер.дескрипторы, [ожидаемый_fd] if вариант == 'маска' else [])
            открыть_mock.assert_called_once(); close_mock.assert_not_called(); flock.assert_not_called()
        # В первом случае open был модельным; во втором модель маски не меняла маску ОС.
        with модуль._тестовая_охрана_пуска:
            модуль._тестовые_активные_замки.discard(маркер)
            модуль._тестовые_владельцы_замков.remove(маркер)
        if сам.fd_из_модели is not None:
            os.close(сам.fd_из_модели)
            сам.fd_из_модели = None
        os.close(сам.fd_open_fault)
        сам.fd_open_fault = None

