    def test_eexist_с_ошибкой_маски_не_открывает_замок_повторно(сам):
        сам.модуль_eexist_mask = загрузить_модуль_автоматизации()
        модуль = сам.модуль_eexist_mask
        сам.корень_eexist_mask = Path(tempfile.mkdtemp(prefix='fum-lock-eexist-', dir='/private/tmp'))
        каталог = сам.корень_eexist_mask / 'locks'
        каталог.mkdir(mode=0o700)
        сам.fd_eexist_mask = os.open(каталог, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        метка = os.fstat(сам.fd_eexist_mask)
        сессия = 'eexist-mask-fixture'
        селектор = ('fum.test-lock-root.2', str(каталог), метка.st_dev, метка.st_ino,
                    метка.st_uid, метка.st_mode & 0o7777, сессия, str(сам.корень_eexist_mask))
        до = set(модуль._тестовые_владельцы_замков)
        настоящий_open, настоящий_close = os.open, os.close
        сам.eexist_вызовы = []
        сам.close_после_eexist = []
        сам.ошибка_маски_eexist = RuntimeError('модель ошибки маски после EEXIST')
        def открыть(имя, флаги, *аргументы, **ключи):
            if isinstance(имя, str) and имя.startswith('fum-check-runs-'):
                сам.eexist_вызовы.append(флаги)
                if флаги & os.O_EXCL:
                    raise FileExistsError(17, 'модель EEXIST')
            return настоящий_open(имя, флаги, *аргументы, **ключи)
        def маска(операция, значения):
            if операция == signal.SIG_SETMASK and сам.eexist_вызовы:
                raise сам.ошибка_маски_eexist
            return set()
        def закрыть(fd):
            if сам.eexist_вызовы:
                сам.close_после_eexist.append(fd)
                raise AssertionError('неожиданный close после UNKNOWN')
            return настоящий_close(fd)
        with mock.patch.object(модуль.os, 'open', side_effect=открыть), \
             mock.patch.object(модуль.os, 'close', side_effect=закрыть), \
             mock.patch.object(модуль.signal, 'pthread_sigmask', side_effect=маска), \
             mock.patch.object(модуль.fcntl, 'flock') as flock:
            with сам.assertRaises(BaseExceptionGroup) as отказ:
                with модуль._тестовый_замок_новой_сессии(
                    селектор, сам.fd_eexist_mask, сам.корень_eexist_mask, сессия,
                    срок_монотонный=time.monotonic()+2):
                    сам.fail('неизвестный EEXIST допущен')
            сам.assertEqual(len(сам.eexist_вызовы), 1)
            сам.assertTrue(сам.eexist_вызовы[0] & os.O_EXCL)
            сам.assertIsInstance(отказ.exception.exceptions[0].__cause__, FileExistsError)
            сам.assertIs(отказ.exception.exceptions[1], сам.ошибка_маски_eexist)
            сам.маркеры_eexist_mask = list(модуль._тестовые_владельцы_замков - до)
            сам.assertEqual(len(сам.маркеры_eexist_mask), 1)
            маркер = сам.маркеры_eexist_mask[0]
            сам.assertTrue(маркер.группа.неизвестно)
            сам.assertEqual(маркер.попытка_открытия[1:], ('начата', None))
            сам.assertEqual(сам.close_после_eexist, [])
            flock.assert_not_called()
        # Модель EEXIST и маски не выполняла соответствующих системных вызовов.
        with модуль._тестовая_охрана_пуска:
            модуль._тестовые_активные_замки.discard(маркер)
            модуль._тестовые_владельцы_замков.remove(маркер)
        while маркер.дескрипторы:
            os.close(маркер.дескрипторы.pop())
        os.close(сам.fd_eexist_mask)
        сам.fd_eexist_mask = None

    def test_совмещённый_select_сохраняет_выходы_и_частичный_кадр(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        сам.owner_select = модуль._ТестовыйВладелецЗапуска()
        сам.owner_select._блокировка.acquire()
        сам.owner_select._поток_владельца = модуль._thread.get_ident()
        сам.owner_select._объект_потока = threading.current_thread()
        срок = time.monotonic_ns() // 1_000_000 + 5000
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        сам.контур_select = модуль._ТестовыйКонтурНаблюдателя(
            сам.owner_select, идентификатор, срок, срок + 5000)
        сам.контур_select.подготовить_собственные_выходы()
        сам.приём_select = сам.контур_select.подготовить_приём_собственных_выходов(
            предел_stdout=2, предел_stderr=3, предел_суммы=5)
        stdout_r, stdout_w = сам.контур_select._пара_выхода
        stderr_r, stderr_w = сам.контур_select._пара_ошибок
        сам.пара_статуса_select = сам.контур_select.подготовить_тестовый_статус()
        status_r, status_w = сам.пара_статуса_select
        class Процесс:
            pid = 777
        сам.owner_select.процесс = Процесс()
        сам.owner_select.pid = 777
        кадр = b'FUA1' + uuid.UUID(идентификатор).bytes + (111).to_bytes(4, 'big')
        сам.assertEqual(os.write(stdout_w, b'AB'), 2)
        сам.assertEqual(os.write(stderr_w, b'xyz'), 3)
        сам.assertEqual(os.write(status_w, кадр[:8]), 8)
        вызовы = []
        def выбрать(чтение, запись, исключения, ожидание):
            вызовы.append(tuple(чтение))
            if len(вызовы) == 1:
                return [stdout_r, stderr_r, status_r], [], []
            сам.assertEqual(os.write(status_w, кадр[8:]), len(кадр) - 8)
            return [status_r], [], []
        with mock.patch.object(модуль, '_КЛАСС_СОБСТВЕННОГО_POPEN', Процесс), \
             mock.patch.object(модуль.select, 'select', side_effect=выбрать), \
             mock.patch.object(модуль.subprocess, 'Popen') as popen:
            сам.читатель_select = модуль._ТестовоеЧтениеНаблюдателя(
                сам.owner_select, сам.контур_select._приёмник, status_r)
            итог = сам.контур_select._шаг('готов', lambda: сам.читатель_select.читать_кадр(
                срок=срок, _тестовый_приём_выходов=сам.приём_select))
            сам.assertEqual(итог, ('готов', 111))
            сам.assertEqual(сам.читатель_select.полученные, (кадр[:8], кадр[8:]))
            сам.assertEqual(len(вызовы), 2)
            сам.assertEqual(сам.приём_select.снимок(), ((b'AB', b'xyz'), (False, False), None, 'готов'))
            popen.assert_not_called()
        сам.приём_select.отпустить_до_запуска()
        сам.контур_select.закрыть_собственные_выходы_до_запуска()
        сам.owner_select._читатель_binding = None
        сам.owner_select.процесс = None
        сам.owner_select.pid = None
        сам.контур_select.закрыть_тестовый_статус()
        сам.owner_select._блокировка.release()

    def test_переполнение_совмещённого_select_не_читает_статус(сам):
        import stat
        import threading
        from types import SimpleNamespace
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        try:
            владелец._поток_владельца = модуль._thread.get_ident()
            владелец._объект_потока = threading.current_thread()
            срок = time.monotonic_ns() // 1_000_000 + 5000
            контур = модуль._ТестовыйКонтурНаблюдателя(
                владелец, '00112233-4455-4677-8899-aabbccddeeff', срок, срок + 5000)
            контур._пара_выхода = (10101, 10102)
            контур._пара_ошибок = (10103, 10104)
            контур._дескрипторы = [10101, 10102, 10103, 10104]
            контур._фаза_собственных_выходов = 'подготовлены'
            контур._метки_собственных_выходов = ('выходы',)
            контур._пара_тестового_статуса = (10105, 10106)
            контур._реестр_тестового_статуса = [10105, 10106]
            контур._фаза_тестового_статуса = 'подготовлен'
            контур._метки_тестового_статуса = ('статус',)
            контур._статус = 10105
            class Процесс:
                pid = 777
            владелец.процесс = Процесс()
            владелец.pid = 777
            def fcntl_фикстуры(fd, операция):
                if операция == модуль.fcntl.F_GETFL:
                    return os.O_RDONLY | os.O_NONBLOCK
                if операция == модуль.fcntl.F_GETFD:
                    return модуль.fcntl.FD_CLOEXEC
                raise AssertionError('неожиданный fcntl')
            with mock.patch.object(контур, '_сверить_собственные_выходы', return_value=('выходы',)), \
                 mock.patch.object(контур, '_сверить_тестовый_статус', return_value=('статус',)), \
                 mock.patch.object(модуль, '_КЛАСС_СОБСТВЕННОГО_POPEN', Процесс), \
                 mock.patch.object(модуль.os, 'fstat',
                    side_effect=lambda fd: SimpleNamespace(st_dev=1, st_ino=fd, st_mode=stat.S_IFIFO)), \
                 mock.patch.object(модуль.fcntl, 'fcntl', side_effect=fcntl_фикстуры), \
                 mock.patch.object(модуль.select, 'select', return_value=([10105, 10101], [], [])), \
                 mock.patch.object(модуль.os, 'read', return_value=b'ABX') as прочитать, \
                 mock.patch.object(модуль.subprocess, 'Popen',
                                   side_effect=AssertionError('нельзя запускать процесс')) as popen:
                приём = контур.подготовить_приём_собственных_выходов(
                    предел_stdout=2, предел_stderr=3, предел_суммы=5)
                читатель = модуль._ТестовоеЧтениеНаблюдателя(владелец, контур._приёмник, 10105)
                with сам.assertRaises(модуль.ОшибкаПереполненияЧтения):
                    контур._шаг('готов', lambda: читатель.читать_кадр(
                        срок=срок, _тестовый_приём_выходов=приём))
                прочитать.assert_called_once_with(10101, 3)
                popen.assert_not_called()
                сам.assertEqual(bytes(приём._буферы[0]), b'AB')
                сам.assertEqual(приём._избыток, (10101, b'X'))
                сам.assertEqual(приём._ожидающая_часть, (10101, b'ABX'))
                сам.assertEqual((контур.состояние, читатель.состояние, приём._состояние),
                                ('неизвестно', 'неизвестно', 'неизвестно'))
                сам.assertEqual(контур._приёмник.состояние, 'неизвестно')
        finally:
            владелец._блокировка.release()

    def test_метки_pipe_маскируют_только_darwin_fwaswritten_писателя(сам):
        import stat
        import threading
        from types import SimpleNamespace
        модуль = загрузить_модуль_автоматизации()
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        try:
            владелец._поток_владельца = модуль._thread.get_ident()
            владелец._объект_потока = threading.current_thread()
            срок = time.monotonic_ns() // 1_000_000 + 5000
            контур = модуль._ТестовыйКонтурНаблюдателя(
                владелец, '00112233-4455-4677-8899-aabbccddeeff', срок, срок + 5000)
            контур._пара_выхода = (10101, 10102)
            контур._пара_ошибок = (10103, 10104)
            контур._дескрипторы = [10101, 10102, 10103, 10104]
            флаги = {10101: os.O_RDONLY | os.O_NONBLOCK, 10102: os.O_WRONLY,
                     10103: os.O_RDONLY | os.O_NONBLOCK, 10104: os.O_WRONLY}
            cloexec = {fd: модуль.fcntl.FD_CLOEXEC for fd in флаги}
            def фейковый_fcntl(fd, операция):
                if операция == модуль.fcntl.F_GETFL:
                    return флаги[fd]
                if операция == модуль.fcntl.F_GETFD:
                    return cloexec[fd]
                raise AssertionError('неожиданный fcntl')
            def фейковый_fstat(fd):
                return SimpleNamespace(st_dev=1, st_ino=fd, st_mode=stat.S_IFIFO | 0o600)
            with mock.patch.object(модуль.os, 'fstat', side_effect=фейковый_fstat), \
                 mock.patch.object(модуль.fcntl, 'fcntl', side_effect=фейковый_fcntl), \
                 mock.patch.object(модуль.sys, 'platform', 'darwin'):
                исходные = контур._сверить_собственные_выходы()
                флаги[10102] |= 0x00010000
                сам.assertEqual(контур._сверить_собственные_выходы(), исходные)
                флаги[10101] |= 0x00010000
                сам.assertNotEqual(контур._сверить_собственные_выходы(), исходные)
                флаги[10101] &= ~0x00010000
                флаги[10102] |= os.O_NONBLOCK
                сам.assertNotEqual(контур._сверить_собственные_выходы(), исходные)
                флаги[10102] &= ~os.O_NONBLOCK
                cloexec[10102] = 0
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    контур._сверить_собственные_выходы()
                cloexec[10102] = модуль.fcntl.FD_CLOEXEC
                with mock.patch.object(модуль.sys, 'platform', 'linux'):
                    сам.assertNotEqual(контур._сверить_собственные_выходы(), исходные)
        finally:
            владелец._блокировка.release()

