    def test_истечение_после_read_сохраняет_известный_результат(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        for результат in (b'AB', BlockingIOError()):
            with сам.subTest(нет_данных=isinstance(результат, BlockingIOError)):
                владелец = модуль._ТестовыйВладелецЗапуска()
                владелец._блокировка.acquire()
                try:
                    владелец._поток_владельца = модуль._thread.get_ident()
                    владелец._объект_потока = threading.current_thread()
                    срок = time.monotonic_ns() // 1_000_000 + 5000
                    стоп = срок + 5000
                    контур = модуль._ТестовыйКонтурНаблюдателя(
                        владелец, '00112233-4455-4677-8899-aabbccddeeff', срок, стоп)
                    контур._пара_выхода = (10101, 10102)
                    контур._пара_ошибок = (10103, 10104)
                    контур._дескрипторы = [10101, 10102, 10103, 10104]
                    контур._фаза_собственных_выходов = 'подготовлены'
                    контур._метки_собственных_выходов = ('искусственная метка',)
                    with mock.patch.object(контур, '_сверить_собственные_выходы',
                                           return_value=('искусственная метка',)), \
                         mock.patch.object(модуль.time, 'monotonic_ns',
                                           side_effect=[(стоп - 1) * 1000000, стоп * 1000000]), \
                         mock.patch.object(модуль.os, 'read',
                                           side_effect=результат if isinstance(результат, Exception) else None,
                                           return_value=результат) as прочитать:
                        приём = контур.подготовить_приём_собственных_выходов(
                            предел_stdout=2, предел_stderr=3, предел_суммы=5)
                        with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'истёк срок после чтения'):
                            приём.прочитать_готовый(10101)
                        сам.assertEqual(bytes(приём._буферы[0]),
                                        b'' if isinstance(результат, Exception) else b'AB')
                        сам.assertEqual(приём._состояние, 'неизвестно')
                        сам.assertEqual(контур.состояние, 'неизвестно')
                        with сам.assertRaises(модуль.ОшибкаОтчёта):
                            приём.прочитать_готовый(10101)
                        прочитать.assert_called_once_with(10101, 3)
                finally:
                    владелец._блокировка.release()

    def _проверить_git_на_своём_макете(сам, *, живой_вывод):
        """Настоящий Git, но не bounded Git-reader и не публичная обёртка."""
        import threading
        if (сам.исполнитель_якоря is None or сам.отпечаток_якоря is None
            or сам.исполнитель_наблюдателя is None or сам.отпечаток_наблюдателя is None
            or сам.исполнитель_git != '/usr/bin/git'
            or type(сам.отпечаток_git) is not str
            or сам.удержать_неизвестный_исход is not True):
            сам.skipTest('нужны исполнители, отпечатки и живой владелец неизвестного исхода')
        сам.assertRegex(сам.отпечаток_git, r'^[0-9a-f]{64}$')
        сам.assertEqual(hashlib.sha256(Path(сам.исполнитель_git).read_bytes()).hexdigest(), сам.отпечаток_git)
        модуль = загрузить_модуль_автоматизации()
        сам.каталог_git_witness = Path(tempfile.mkdtemp(prefix='fum-witness-git-', dir='/private/tmp'))
        корень = сам.каталог_git_witness
        репозиторий = корень / 'repo'
        репозиторий.mkdir(mode=0o700)
        служебный = репозиторий / '.git'
        служебный.mkdir(mode=0o700)
        (служебный / 'objects').mkdir(mode=0o700)
        (служебный / 'refs').mkdir(mode=0o700)
        (служебный / 'HEAD').write_bytes(b'ref: refs/heads/fixture\n')
        (служебный / 'config').write_bytes(b'[core]\n\trepositoryformatversion = 0\n\tbare = false\n')
        идентификатор = str(uuid.uuid4())
        активная = корень / 'active.json'
        байты = json.dumps({'идентификатор': идентификатор, 'состояние': 'выполняется'},
                           ensure_ascii=False).encode()
        активная.write_bytes(байты)
        каталог_замка = корень / 'locks'
        каталог_замка.mkdir(mode=0o700)
        сам.дескрипторы_git_witness = []
        сам.fd_git_witness = модуль._приобрести_fd(
            сам.дескрипторы_git_witness, os.open, каталог_замка,
            os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
        метка = os.fstat(сам.fd_git_witness)
        сессия = 'git-witness-' + идентификатор
        селектор = ('fum.test-lock-root.2', str(каталог_замка), метка.st_dev, метка.st_ino,
                    метка.st_uid, метка.st_mode & 0o7777, сессия, str(корень))
        срок = time.monotonic_ns() // 1_000_000 + 8000
        стоп = срок + 5000
        def получить_замок():
            return модуль._тестовый_замок_новой_сессии(
                селектор, сам.fd_git_witness, корень, сессия, срок_монотонный=стоп / 1000)
        сам.owner_git_witness = модуль._ТестовыйВладелецЗапуска()
        сам.owner_git_witness._блокировка.acquire()
        сам.owner_git_witness._поток_владельца = модуль._thread.get_ident()
        сам.owner_git_witness._объект_потока = threading.current_thread()
        сам.owner_git_witness.активная_запись = активная
        сам.owner_git_witness.байты_записи = байты
        сам.owner_git_witness.запись_вернула_успех = True
        сам.контур_git_witness = модуль._ТестовыйКонтурНаблюдателя(
            сам.owner_git_witness, идентификатор, срок, стоп)
        if живой_вывод:
            сам.контур_git_witness.подготовить_собственные_выходы()
            сам.приём_git_witness = сам.контур_git_witness.подготовить_приём_собственных_выходов(
                предел_stdout=32, предел_stderr=32, предел_суммы=64)
            получить_замок = модуль._ТестоваяФабрикаЗамкаПриёма(
                сам.контур_git_witness, корень, сессия, селектор, сам.fd_git_witness)
        команда = (сам.исполнитель_git, '-C', str(репозиторий), '-c', 'core.fsmonitor=false',
                   'rev-parse', '--show-object-format')
        сам.контур_git_witness.запустить(
            Path(сам.исполнитель_наблюдателя), сам.отпечаток_наблюдателя,
            Path(сам.исполнитель_якоря), сам.отпечаток_якоря, корень,
            команда, получить_замок, _изолировать_git=True,
            _тестовый_живой_вывод=живой_вывод)
        свидетельство = сам.контур_git_witness.довести(получить_замок)
        сам.assertEqual((свидетельство.сырой_статус, свидетельство.код_цели,
                         свидетельство.тайм_аут, свидетельство.код_наблюдателя), (0, 0, False, 0))
        сам.assertEqual([кадр[:4] for кадр in свидетельство.кадры],
                        [b'FUA1', b'FUS1', b'FUP1', b'FUD1'])
        pid_якоря = int.from_bytes(свидетельство.кадры[0][20:24], 'big')
        with сам.assertRaises(ProcessLookupError):
            os.killpg(pid_якоря, 0)
        if живой_вывод:
            сам.assertEqual(сам.контур_git_witness._тестовые_байты_выходов, (b'sha1\n', b''))
            сам.assertEqual(сам.приём_git_witness._eof, [True, True])
        сам.assertEqual(hashlib.sha256(Path(сам.исполнитель_git).read_bytes()).hexdigest(), сам.отпечаток_git)
        сам.контур_git_witness.закрыть_после_успеха()
        модуль._отпустить_зарегистрированный_fd(сам.дескрипторы_git_witness, сам.fd_git_witness)
        сам.освобождение_owner_git_witness = 'начато'
        сам.owner_git_witness._блокировка.release()
        сам.освобождение_owner_git_witness = 'завершено'

