    def _проверить_наблюдатель_без_тайм_аута(сам, потомок=False, *, прерывание=None, отказ_до_go=False, обрыв=False):
        import select, stat, threading
        if (сам.исполнитель_якоря is None or сам.отпечаток_якоря is None
            or сам.исполнитель_наблюдателя is None or сам.отпечаток_наблюдателя is None
            or сам.удержать_неизвестный_исход is not True):
            сам.skipTest('нужны исполнители и живой владелец неизвестного исхода')
        for путь, отпечаток in ((сам.исполнитель_якоря, сам.отпечаток_якоря),
                               (сам.исполнитель_наблюдателя, сам.отпечаток_наблюдателя)):
            сам.assertEqual(hashlib.sha256(Path(путь).read_bytes()).hexdigest(), отпечаток)
        сам.дескрипторы_бессрочного = []
        сам.процесс_бессрочного = None
        завершено = False
        def закрыть(fd):
            os.close(fd)
            сам.дескрипторы_бессрочного.remove(fd)
        try:
            control_r, control_w = os.pipe()
            сам.дескрипторы_бессрочного.extend((control_r, control_w))
            status_r, status_w = os.pipe()
            сам.дескрипторы_бессрочного.extend((status_r, status_w))
            os.set_blocking(control_w, False)
            os.set_blocking(status_r, False)
            идентификатор = uuid.uuid4()
            край_подготовки = time.monotonic_ns() // 1_000_000 + (5000 if обрыв else 3000)
            модуль = загрузить_модуль_автоматизации()
            версия = 'fum-run-witness.6' if прерывание is not None or отказ_до_go or обрыв else 'fum-run-witness.5'
            сам.приёмник_бессрочного = модуль._ТестовыйПриёмникБессрочногоНаблюдателя(
                str(идентификатор), край_подготовки, 5000, версия=версия)
            сам.владелец_бессрочного = модуль._ТестовыйВладелецЗапуска()
            сам.владелец_бессрочного._блокировка.acquire()
            сам.владелец_бессрочного._поток_владельца = модуль._thread.get_ident()
            сам.владелец_бессрочного._объект_потока = threading.current_thread()
            сам.каталог_бессрочного = tempfile.TemporaryDirectory(dir='/tmp')
            сам.каталог_бессрочного._finalizer.detach()
            корень = Path(сам.каталог_бессрочного.name).resolve()
            active = корень / 'active.json'
            байты_active = json.dumps({'идентификатор': str(идентификатор), 'состояние': 'выполняется'}).encode()
            active.write_bytes(байты_active)
            сам.владелец_бессрочного.активная_запись = active
            сам.владелец_бессрочного.байты_записи = байты_active
            сам.владелец_бессрочного.запись_вернула_успех = True
            каталог_замка = корень / 'locks'
            каталог_замка.mkdir(mode=0o700)
            fd_замка = os.open(каталог_замка, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            сам.дескрипторы_бессрочного.append(fd_замка)
            метка = os.fstat(fd_замка)
            сессия = 'бессрочная-фикстура'
            селектор = ('fum.test-lock-root.2', str(каталог_замка), метка.st_dev, метка.st_ino,
                        метка.st_uid, stat.S_IMODE(метка.st_mode), сессия, str(корень))
            def взять_замок(край):
                return модуль._тестовый_замок_новой_сессии(
                    селектор, fd_замка, корень, сессия, срок_монотонный=край)
            путь_потомка = корень / 'потомок.pid'
            метка_цели = корень / 'цель-запустилась'
            if отказ_до_go:
                команда = ['/usr/bin/touch', str(метка_цели)]
            elif потомок:
                команда = ['/bin/sh', '-c',
                           'trap "" TERM; /bin/sleep 15 & /bin/echo "$!" > "$1"; /bin/sleep 5; exit 0',
                           'фикстура', str(путь_потомка)]
            else:
                команда = ['/bin/sleep', '5']
            сам.процесс_бессрочного = subprocess.Popen(
                [сам.исполнитель_наблюдателя, версия, str(идентификатор),
                 сам.исполнитель_якоря, str(status_w), '5000', 'none', str(край_подготовки), '5000',
                 '--', *команда], env={}, stdin=control_r, stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL, pass_fds=(status_w,), start_new_session=True, close_fds=True)
            сам.владелец_бессрочного.процесс = сам.процесс_бессрочного
            сам.владелец_бессрочного.pid = сам.процесс_бессрочного.pid
            закрыть(control_r)
            закрыть(status_w)
            сам.читатель_бессрочного = модуль._ТестовоеЧтениеНаблюдателя(
                сам.владелец_бессрочного, сам.приёмник_бессрочного, status_r)
            готовность = сам.читатель_бессрочного.читать_кадр(срок=край_подготовки)
            ready = сам.приёмник_бессрочного.кадры[-1]
            сам.assertEqual(ready[:20], b'FUA1' + идентификатор.bytes)
            pid_якоря = int.from_bytes(ready[20:], 'big')
            сам.assertGreater(pid_якоря, 1)
            сам.assertEqual(os.getpgid(pid_якоря), pid_якоря)
            сам.assertEqual(os.getsid(pid_якоря), сам.процесс_бессрочного.pid)
            сам.assertEqual(готовность, ('готов', pid_якоря))
            сам.передача_бессрочного = модуль._ТестоваяПередачаНаблюдателя(
                сам.владелец_бессрочного, сам.приёмник_бессрочного, control_w)
            def подтвердить_очистку(команда):
                код_наблюдателя = модуль._кандидат_собрать_статус_лидера(
                    сам.процесс_бессрочного, срок=сам.приёмник_бессрочного.край_очистки / 1000)
                сам.assertEqual(код_наблюдателя, 0)
                сам.assertTrue(select.select([status_r], [], [], 1.0)[0])
                сам.assertEqual(os.read(status_r, 1), b'')
                with сам.assertRaises(ProcessLookupError):
                    os.killpg(pid_якоря, 0)
                сам.приёмник_бессрочного.подтвердить_завершение(
                    код_наблюдателя, True, time.monotonic_ns() // 1_000_000)
                сам.assertEqual(сам.приёмник_бессрочного.состояние, 'завершено')
                сам.assertEqual(сам.передача_бессрочного.попытки, команда)
            if отказ_до_go:
                with взять_замок(край_подготовки / 1000) as сверить:
                    сам.передача_бессрочного.отправить(b'A', сверить)
                очистка = сам.читатель_бессрочного.читать_кадр(срок=сам.приёмник_бессрочного.край_очистки)
                сам.assertEqual(очистка, ('отказ-очистка-наблюдена',))
                ожидаемый = b'FUC1' + ready[4:] + int(signal.SIGKILL).to_bytes(4, 'big')
                сам.assertEqual(сам.приёмник_бессрочного.кадры, (ready, ожидаемый))
                подтвердить_очистку(((b'A', 1),))
                сам.assertFalse(метка_цели.exists())
                завершено = True
                return
            with взять_замок(край_подготовки / 1000) as сверить:
                сам.передача_бессрочного.отправить(b'G', сверить)
            запуск = сам.читатель_бессрочного.читать_кадр(срок=край_подготовки)
            start = сам.приёмник_бессрочного.кадры[-1]
            сам.assertEqual(start[:24], b'FUS1' + идентификатор.bytes + pid_якоря.to_bytes(4, 'big'))
            pid_цели = int.from_bytes(start[24:], 'big')
            сам.assertGreater(pid_цели, 1)
            сам.assertNotEqual(pid_цели, pid_якоря)
            сам.assertEqual(os.getpgid(pid_цели), pid_якоря)
            сам.assertEqual(запуск, ('запущен', pid_цели))
            if обрыв:
                закрыть(control_w)
                край = time.monotonic() + 5
                сам.assertEqual(модуль._кандидат_собрать_статус_лидера(
                    сам.процесс_бессрочного, срок=край), 125)
                сам.assertTrue(select.select([status_r], [], [], 1.0)[0])
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'преждевременный EOF'):
                    сам.читатель_бессрочного.читать_кадр(срок=None)
                сам.assertEqual(сам.приёмник_бессрочного.кадры, (ready, start))
                сам.assertEqual(сам.приёмник_бессрочного.состояние, 'неизвестно')
                while True:
                    try:
                        os.killpg(pid_якоря, 0)
                    except ProcessLookupError:
                        break
                    except (PermissionError, InterruptedError):
                        pass
                    сам.assertLess(time.monotonic(), край, 'группа осталась после обрыва')
                    time.sleep(0.01)
                завершено = True
                return
            ожидание = max(0, край_подготовки / 1000 + 0.2 - time.monotonic())
            сам.assertFalse(select.select([status_r], [], [], ожидание)[0])
            сам.assertGreaterEqual(time.monotonic_ns() // 1_000_000, край_подготовки)
            сам.assertEqual(os.getpgid(pid_цели), pid_якоря)
            if прерывание is None:
                сам.assertTrue(select.select([status_r], [], [], 5.0)[0])
                результат_статуса = сам.читатель_бессрочного.читать_кадр(срок=None)
                статус = сам.приёмник_бессрочного.кадры[-1]
                сам.assertEqual(статус[:24], b'FUP2' + идентификатор.bytes + bytes(4))
                время_статуса = int.from_bytes(статус[24:], 'big')
                сам.assertGreaterEqual(время_статуса, край_подготовки)
                сам.assertLessEqual(время_статуса, time.monotonic_ns() // 1_000_000)
                сам.assertLess(time.monotonic_ns() // 1_000_000, время_статуса + 5000)
                сам.assertEqual(результат_статуса, ('статус', 0))
                сам.assertEqual(сам.приёмник_бессрочного.край_ответа, время_статуса + 5000)
                край_замка = сам.приёмник_бессрочного.край_ответа / 1000
                команда_очистки, вид, raw, последний_байт = b'C', b'FUD1', 0, b'\x00'
                ожидаемая_очистка = ('очистка-наблюдена', 0, False)
            else:
                номер = None
                def запомнить(полученный, _кадр):
                    nonlocal номер
                    номер = полученный
                обработчик = signal.signal(прерывание, запомнить)
                отправитель = threading.Timer(0.08, os.kill, (os.getpid(), прерывание))
                try:
                    отправитель.start()
                    результат = сам.читатель_бессрочного.читать_кадр(
                        срок=None, _сигнал_прерывания=lambda: номер)
                finally:
                    отправитель.cancel()
                    отправитель.join(timeout=1.0)
                    signal.signal(прерывание, обработчик)
                сам.assertEqual(результат, ('сигнал-прерывания', int(прерывание)))
                сам.assertEqual(сам.приёмник_бессрочного.состояние, 'работает')
                край_замка = time.monotonic() + 2.0
                команда_очистки = b'I' if прерывание == signal.SIGINT else b'E'
                вид, raw, последний_байт = b'FUI1', int(прерывание), команда_очистки
                ожидаемая_очистка = ('прерывание-наблюдено', raw, int(прерывание))
            if потомок:
                строка_потомка = путь_потомка.read_text(encoding='ascii').strip()
                сам.assertRegex(строка_потомка, r'^[1-9][0-9]*$')
                pid_потомка = int(строка_потомка)
                сам.assertGreater(pid_потомка, 1)
                сам.assertEqual(os.getpgid(pid_потомка), pid_якоря)
                os.kill(pid_потомка, 0)
            with взять_замок(край_замка) as сверить:
                сам.передача_бессрочного.отправить(команда_очистки, сверить)
            результат_очистки = сам.читатель_бессрочного.читать_кадр(
                срок=сам.приёмник_бессрочного.край_очистки)
            конец = сам.приёмник_бессрочного.кадры[-1]
            сам.assertEqual(конец, вид + идентификатор.bytes + pid_якоря.to_bytes(4, 'big')
                            + pid_цели.to_bytes(4, 'big') + raw.to_bytes(4, 'big')
                            + int(signal.SIGKILL).to_bytes(4, 'big') + последний_байт)
            сам.assertEqual(результат_очистки, ожидаемая_очистка)
            подтвердить_очистку(((b'G', 1), (команда_очистки, 1)))
            завершено = True
        finally:
            if завершено:
                for fd in tuple(сам.дескрипторы_бессрочного):
                    закрыть(fd)
                сам.владелец_бессрочного._блокировка.release()
                сам.каталог_бессрочного.cleanup()

