    def test_штатный_запуск_использует_прежний_замок(сам):
        if not all((сам.исполнитель_наблюдателя, сам.отпечаток_наблюдателя,
                    сам.исполнитель_якоря, сам.отпечаток_якоря)):
            сам.skipTest('нужны закреплённые исполнители наблюдения')
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        сам.addCleanup(фикстура.очистить)
        корень = фикстура.корень.resolve()
        идентификатор = str(uuid.uuid4())
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            каталог_замка = Path(временный).resolve()
            параметры = фикстура.аргументы(
                'запустить', '--каталог-замка', str(каталог_замка),
                '--наблюдатель', сам.исполнитель_наблюдателя, сам.отпечаток_наблюдателя,
                '--якорь', сам.исполнитель_якоря, сам.отпечаток_якоря,
                '--название', 'Проверить штатный запуск', '--исполнитель', 'корень',
                '--класс-проверки', 'адресная', '--обычная-схема-профиля',
                '--идентификатор-запуска', идентификатор,
            )
            проверить_среду = ('--', 'sh', '-c',
                               'test "$FUM_CHECK_RUN_ID" = "$1" && '
                               'test -z "${FUM_TEST_PRIVATE_SENTINEL+x}" && ! read -r строка',
                               'проверка', идентификатор)
            окружение = {'LC_ALL': 'C', 'FUM_TEST_PRIVATE_SENTINEL': 'фикстура'}
            def команда_обёртки(аргументы, цель=проверить_среду):
                return [аргументы[0], '-B', *аргументы[1:], *цель]
            def запустить(аргументы, цель=проверить_среду):
                return subprocess.run(команда_обёртки(аргументы, цель),
                                      env=окружение, stdin=subprocess.DEVNULL,
                                      capture_output=True, timeout=15)
            неверные = list(параметры)
            неверные[неверные.index('--наблюдатель') + 2] = '0' * 64
            отказ = запустить(неверные)
            сам.assertEqual(отказ.returncode, 1, отказ.stderr)
            сам.assertIn('отпечаток исполнителя не совпал', отказ.stderr.decode())
            сам.assertEqual(list(каталог_замка.iterdir()), [])
            сам.assertFalse(фикстура.каталог_записей.exists())

            with contextlib.ExitStack() as запуски, \
                 mock.patch.object(модуль.tempfile, 'gettempdir', return_value=str(каталог_замка)):
                with модуль._блокировка_файла_сессии(корень, путь_запроса):
                    отказ = запустить(параметры)
                    сам.assertEqual(отказ.returncode, 1, отказ.stderr)
                    сам.assertIn('истёк', отказ.stderr.decode())
                    сам.assertFalse(фикстура.каталог_записей.exists())
                    ожидающий = запуски.enter_context(subprocess.Popen(
                        команда_обёртки(параметры), env=окружение, stdin=subprocess.DEVNULL,
                        stdout=subprocess.PIPE, stderr=subprocess.PIPE))
                    with сам.assertRaises(subprocess.TimeoutExpired):
                        ожидающий.wait(timeout=0.4)
                    сам.assertFalse(фикстура.каталог_записей.exists())
                _, ошибки = ожидающий.communicate(timeout=15)
                сам.assertEqual(ожидающий.returncode, 0, ошибки)
            записи = list(фикстура.каталог_записей.iterdir())
            сам.assertEqual([путь.name for путь in записи], [f'1_{идентификатор}.json'])
            запись, _ = модуль.прочитать_машинную_запись(записи[0])
            сам.assertEqual((запись['схема'], запись['состояние'], запись['код_завершения']),
                            (модуль.СХЕМА_ПРОФИЛИРОВАННОГО_ЗАПУСКА, 'завершён', 0))
            сам.assertGreater(запись['длительность_наносекунды'], 0)

            идентификатор_отказа = str(uuid.uuid4())
            отказ = запустить([*параметры[:-1], идентификатор_отказа], ('--', '/bin/sh', '-c', 'exit 7'))
            сам.assertEqual(отказ.returncode, 7, отказ.stderr)
            диагностика = параметры[:-2]
            диагностика[диагностика.index('--класс-проверки') + 1] = 'диагностическая'
            диагностика += ['--полный-набор', 'проверки/набор', '--основание',
                            'локализация_наблюдаемого_отказа', '--идентификатор-отказа', идентификатор_отказа,
                            '--ожидаемое-свидетельство', 'Уточнить причину отказа']
            итог = запустить(диагностика, ('--', '/usr/bin/true'))
            сам.assertEqual(итог.returncode, 0, итог.stderr)
            сессия = модуль.прочитать_историю_проверок(фикстура.каталог_записей, путь_запроса)
            сам.assertEqual([запись['код_завершения'] for _, запись, _ in сессия], [0, 7, 0])
            сам.assertEqual(сессия[-1][1]['профиль_проверки']['идентификатор_отказа'], идентификатор_отказа)

    def test_штатный_тайм_аут_и_сигнал_завершают_группу(сам):
        import errno

        if not all((сам.исполнитель_наблюдателя, сам.отпечаток_наблюдателя,
                    сам.исполнитель_якоря, сам.отпечаток_якоря)):
            сам.skipTest('нужны закреплённые исполнители наблюдения')
        модуль = загрузить_модуль_автоматизации()
        ожидать = (
            "import os, signal, sys, time\n"
            "from pathlib import Path\n"
            "signal.signal(signal.SIGTERM, signal.SIG_IGN)\n"
            "потомок = os.fork()\n"
            "if потомок == 0:\n    time.sleep(8)\n    os._exit(0)\n"
            "метка = Path(sys.argv[1])\n"
            "временная = метка.with_suffix('.tmp')\n"
            "временная.write_text(str(os.getpgrp()), encoding='ascii')\n"
            "временная.rename(метка)\n"
            "os.waitpid(потомок, 0)\n"
        )
        for случай, срок, ожидаемый_возврат, ожидаемый_исход in (
            ('выход', '2', 7, ('неуспешно', 7)),
            ('тайм-аут', '1.5', 124, ('не завершено', 124)),
            ('сигнал', '6', 130, ('прервано', -signal.SIGINT)),
            ('сигнал у срока', '1.5', -signal.SIGTERM, ('не завершено', 124)),
            ('отказ запуска', '2', 125, ('не завершено', 125)),
        ):
            with сам.subTest(случай=случай), tempfile.TemporaryDirectory(dir='/tmp') as замки:
                фикстура = ФикстураОтчётов()
                try:
                    метка = фикстура.корень / 'группа-цели'
                    цель = [sys.executable, '-I', '-S', '-B', '-c', ожидать, str(метка)]
                    if случай == 'выход':
                        цель = ['/bin/sh', '-c', 'exit 7']
                    elif случай == 'отказ запуска':
                        цель = [str(фикстура.корень / 'отсутствующая-цель')]
                    параметры = фикстура.аргументы(
                        'запустить', '--каталог-замка', str(Path(замки).resolve()),
                        '--наблюдатель', сам.исполнитель_наблюдателя, сам.отпечаток_наблюдателя,
                        '--якорь', сам.исполнитель_якоря, сам.отпечаток_якоря,
                        '--название', 'Проверить конечный запуск', '--исполнитель', 'корень',
                        '--класс-проверки', 'адресная', '--обычная-схема-профиля',
                        '--тайм-аут-секунды', срок, '--', *цель,
                    )
                    with subprocess.Popen([параметры[0], '-B', *параметры[1:]], env={},
                                          stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                          stderr=subprocess.PIPE) as процесс:
                        if случай in ('тайм-аут', 'сигнал', 'сигнал у срока'):
                            край = time.monotonic() + 8
                            while not метка.is_file():
                                if процесс.poll() is not None:
                                    _, ошибки = процесс.communicate(timeout=2)
                                    сам.fail(ошибки.decode())
                                сам.assertLess(time.monotonic(), край)
                                time.sleep(0.01)
                            группа = int(метка.read_bytes())
                            сам.assertGreater(группа, 1)
                            сам.assertNotEqual(группа, os.getpgrp())
                            if случай == 'сигнал':
                                процесс.send_signal(signal.SIGINT)
                            else:
                                замок = (модуль._блокировка_каталога_сессии(
                                    фикстура.каталог_сессии.resolve(), time.monotonic() + 2)
                                    if случай == 'сигнал у срока' else contextlib.nullcontext())
                                with замок:
                                    процесс.send_signal(signal.SIGSTOP if случай == 'тайм-аут' else signal.SIGTERM)
                                    try:
                                        # Swift соблюдает срок и при остановленном Python, и при ожидании замка.
                                        край = time.monotonic() + 4
                                        while True:
                                            try:
                                                os.killpg(группа, 0)
                                            except ProcessLookupError:
                                                break
                                            except PermissionError as ошибка:
                                                if ошибка.errno != errno.EPERM:
                                                    raise
                                            сам.assertLess(time.monotonic(), край)
                                            time.sleep(0.01)
                                        запись, = фикстура.каталог_записей.iterdir()
                                        сам.assertEqual(json.loads(запись.read_bytes())['состояние'], 'выполняется')
                                    finally:
                                        if случай == 'тайм-аут':
                                            процесс.send_signal(signal.SIGCONT)
                        _, ошибки = процесс.communicate(timeout=12)
                        сам.assertEqual(процесс.returncode, ожидаемый_возврат, ошибки.decode())
                    if случай in ('тайм-аут', 'сигнал', 'сигнал у срока'):
                        with сам.assertRaises(ProcessLookupError):
                            os.killpg(группа, 0)
                    запись, = фикстура.каталог_записей.iterdir()
                    результат = json.loads(запись.read_bytes())
                    сам.assertEqual(результат['состояние'], 'завершён')
                    сам.assertEqual((результат['статус'], результат['код_завершения']), ожидаемый_исход)
                    if ожидаемый_исход[1] == 124:
                        сам.assertEqual(результат['пояснение'], 'превышен тайм-аут запуска')
                finally:
                    фикстура.очистить()

