    def test_go_требует_active_и_не_повторяет_неизвестную_попытку(сам):
        модуль = загрузить_модуль_автоматизации()
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        class Процесс:
            pid = 777
            returncode = None
        случаи = ('успех', 'другая-запись', 'короткая-запись', 'ошибка-после-эффекта',
                  'sigpipe', 'блокирующий', 'поздний')
        for случай in случаи:
            with сам.subTest(случай=случай), tempfile.TemporaryDirectory(dir='/tmp') as каталог:
                путь = Path(каталог) / 'active.json'
                данные = json.dumps({'идентификатор': идентификатор, 'состояние': 'выполняется'},
                                    ensure_ascii=False).encode('utf-8')
                путь.write_bytes(данные)
                владелец = модуль._ТестовыйВладелецЗапуска()
                владелец.активная_запись = путь
                владелец.байты_записи = 'другие'.encode('utf-8') if случай == 'другая-запись' else данные
                владелец.запись_вернула_успех = True
                владелец.процесс = Процесс()
                владелец.pid = владелец.процесс.pid
                владелец._блокировка.acquire()
                владелец._поток_владельца = модуль._thread.get_ident()
                приёмник = модуль._ПриёмникКадровСупервизора(идентификатор)
                приёмник.принять(b'FUR1' + uuid.UUID(идентификатор).bytes)
                чтение, запись = os.pipe()
                try:
                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                        модуль._ТестоваяПередачаGO(идентификатор, владелец, приёмник, запись)
                    os.set_blocking(запись, False)
                    передача = модуль._ТестоваяПередачаGO(идентификатор, владелец, приёмник, запись)
                    with сам.assertRaises(модуль.ОшибкаОтчёта):
                        модуль._ТестоваяПередачаGO(идентификатор, владелец, приёмник, запись)
                    if случай == 'блокирующий':
                        os.set_blocking(запись, True)
                    блокировка = mock.Mock()
                    штатная_запись = os.write
                    def записать_и_прервать(fd, данные):
                        штатная_запись(fd, данные)
                        raise KeyboardInterrupt('неизвестен исход')
                    эффект = (записать_и_прервать if случай == 'ошибка-после-эффекта'
                              else штатная_запись if случай == 'поздний' else None)
                    счётчик = 0 if случай == 'короткая-запись' else 1
                    disposition = signal.SIG_DFL if случай == 'sigpipe' else signal.SIG_IGN
                    проверка_срока = (mock.patch.object(модуль, '_срок_действителен', side_effect=[True, True, False])
                                      if случай == 'поздний' else contextlib.nullcontext())
                    with mock.patch.object(модуль, '_КЛАСС_СОБСТВЕННОГО_POPEN', Процесс), \
                         mock.patch.object(модуль.os, 'getpgid', return_value=777), \
                         mock.patch.object(модуль.os, 'getsid', return_value=777), \
                         mock.patch.object(модуль.signal, 'getsignal', return_value=disposition), \
                         mock.patch.object(модуль.os, 'write', return_value=счётчик, side_effect=эффект) as write, \
                         проверка_срока:
                        if случай == 'успех':
                            передача.отправить(блокировка, срок=time.monotonic() + 5)
                            сам.assertEqual(передача.состояние, 'отправлено')
                            сам.assertEqual(приёмник.состояние, 'результат')
                            сам.assertEqual(блокировка.call_count, 2)
                            write.assert_called_once_with(запись, b'G')
                        else:
                            тип = KeyboardInterrupt if случай == 'ошибка-после-эффекта' else модуль.ОшибкаОтчёта
                            with сам.assertRaises(тип):
                                передача.отправить(блокировка, срок=time.monotonic() + 5)
                            сам.assertEqual(передача.состояние, 'неизвестно')
                            сам.assertEqual(приёмник.состояние, 'неизвестно')
                            количество = 1 if случай in ('короткая-запись', 'ошибка-после-эффекта', 'поздний') else 0
                            сам.assertEqual(write.call_count, количество)
                            if случай in ('ошибка-после-эффекта', 'поздний'):
                                сам.assertEqual(os.read(чтение, 1), b'G')
                            with сам.assertRaises(модуль.ОшибкаОтчёта):
                                передача.отправить(блокировка, срок=time.monotonic() + 5)
                            сам.assertEqual(write.call_count, количество)
                finally:
                    os.close(чтение)
                    os.close(запись)
                    владелец._блокировка.release()

    def test_go_не_передаётся_из_другого_потока(сам):
        import threading
        модуль = загрузить_модуль_автоматизации()
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        владелец = модуль._ТестовыйВладелецЗапуска()
        владелец._блокировка.acquire()
        владелец._поток_владельца = модуль._thread.get_ident()
        приёмник = модуль._ПриёмникКадровСупервизора(идентификатор)
        чтение, запись = os.pipe()
        try:
            os.set_blocking(запись, False)
            ошибки = []
            def попытка():
                try:
                    модуль._ТестоваяПередачаGO(идентификатор, владелец, приёмник, запись)
                except BaseException as ошибка:
                    ошибки.append(ошибка)
            поток = threading.Thread(target=попытка)
            поток.start()
            поток.join(timeout=5)
            сам.assertFalse(поток.is_alive())
            сам.assertEqual(len(ошибки), 1)
            сам.assertIsInstance(ошибки[0], модуль.ОшибкаОтчёта)
            сам.assertIsNone(владелец._go_binding)
        finally:
            os.close(чтение)
            os.close(запись)
            владелец._блокировка.release()

    def test_приёмник_кадров_не_смешивает_состояния_и_части(сам):
        модуль = загрузить_модуль_автоматизации()
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        идентификатор_байты = uuid.UUID(идентификатор).bytes
        приёмник = модуль._ПриёмникКадровСупервизора(идентификатор)
        def передать_побайтно(кадр):
            for часть in кадр[:-1]:
                сам.assertIsNone(приёмник.принять(bytes([часть])))
            return приёмник.принять(кадр[-1:])
        сам.assertEqual(передать_побайтно(b'FUR1' + идентификатор_байты), ('готов',))
        сам.assertEqual(приёмник.состояние, 'ожидает-go')
        приёмник.подтвердить_go(1)
        status = b'FUP1' + идентификатор_байты + (7 << 8).to_bytes(4, 'big')
        сам.assertEqual(передать_побайтно(status), ('статус', 7 << 8))
        сам.assertEqual(приёмник.состояние, 'после-результата')
        сам.assertEqual(приёмник.свидетельство_статуса, (status, 7 << 8))
        unknown = b'FUE1' + идентификатор_байты + (2).to_bytes(4, 'big') + (13).to_bytes(4, 'big')
        сам.assertEqual(передать_побайтно(unknown), ('неизвестно', 2, 13))
        сам.assertEqual(приёмник.состояние, 'неизвестно')
        сам.assertEqual(приёмник.свидетельство_статуса, (status, 7 << 8))

