    def test_приёмник_ограничивает_чтение_и_сохраняет_отказ(сам):
        модуль = загрузить_модуль_автоматизации()
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        id_bytes = uuid.UUID(идентификатор).bytes
        ready = b'FUR1' + id_bytes
        status = b'FUP1' + id_bytes + (7 << 8).to_bytes(4, 'big')
        unknown = b'FUE1' + id_bytes + (2).to_bytes(4, 'big') + (13).to_bytes(4, 'big')
        приёмник = модуль._ПриёмникКадровСупервизора(идентификатор)
        сам.assertEqual(приёмник.сколько_читать, 4)
        сам.assertIsNone(приёмник.принять(ready[:4]))
        сам.assertEqual(приёмник.сколько_читать, 16)
        сам.assertEqual(приёмник.принять(ready[4:]), ('готов',))
        сам.assertEqual(приёмник.сколько_читать, 0)
        приёмник.подтвердить_go(1)
        поток = status + unknown
        результаты = []
        while поток:
            размер = приёмник.сколько_читать
            сам.assertGreater(размер, 0)
            часть, поток = поток[:размер], поток[размер:]
            результат = приёмник.принять(часть)
            if результат is not None:
                результаты.append(результат)
        сам.assertEqual(результаты, [('статус', 7 << 8), ('неизвестно', 2, 13)])
        сам.assertEqual(приёмник.сколько_читать, 0)
        приёмник = модуль._ПриёмникКадровСупервизора(идентификатор)
        with mock.patch.object(модуль, '_разобрать_кадр_супервизора', side_effect=KeyboardInterrupt):
            with сам.assertRaises(KeyboardInterrupt):
                приёмник.принять(ready)
        сам.assertEqual(приёмник.состояние, 'неизвестно')
        сам.assertEqual(приёмник.остаток, ready)
        for записано in (0, 2, -1, True, None):
            приёмник = модуль._ПриёмникКадровСупервизора(идентификатор)
            приёмник.принять(ready)
            with сам.subTest(записано=записано), сам.assertRaises(модуль.ОшибкаОтчёта):
                приёмник.подтвердить_go(записано)
            сам.assertEqual(приёмник.состояние, 'неизвестно')

    def test_строгие_кадры_супервизора_сохраняют_различие_статусов(сам):
        модуль = загрузить_модуль_автоматизации()
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        id_bytes = uuid.UUID(идентификатор).bytes
        разобрать = модуль._разобрать_кадр_супервизора
        готов = b'FUR1' + id_bytes
        сам.assertEqual(разобрать(готов, идентификатор, 'готовность'), ('готов',))
        for raw in (0, 7 << 8, signal.SIGTERM, signal.SIGTERM | 0x80):
            with сам.subTest(raw=raw):
                frame = b'FUP1' + id_bytes + int(raw).to_bytes(4, 'big', signed=True)
                сам.assertEqual(разобрать(frame, идентификатор, 'результат'), ('статус', raw))
        for stage, error in ((1, 0), (2, 13), (3, 4), (4, 0), (4, 1)):
            frame = b'FUE1' + id_bytes + stage.to_bytes(4, 'big') + error.to_bytes(4, 'big')
            for phase in ('результат', 'после-результата'):
                with сам.subTest(stage=stage, error=error, phase=phase):
                    сам.assertEqual(разобрать(frame, идентификатор, phase), ('неизвестно', stage, error))

    def test_кадры_супервизора_отклоняют_неоднозначные_данные(сам):
        модуль = загрузить_модуль_автоматизации()
        идентификатор = '00112233-4455-4677-8899-aabbccddeeff'
        id_bytes = uuid.UUID(идентификатор).bytes
        готов = b'FUR1' + id_bytes
        status = b'FUP1' + id_bytes
        unknown = b'FUE1' + id_bytes
        ошибки = [(готов[:-1], 'готовность'), (готов + b'X', 'готовность'),
                  (b'BAD1' + готов[4:], 'готовность'),
                  (b'FUR1' + bytes(16), 'готовность'),
                  (готов, 'результат'), (status + bytes(4), 'готовность'),
                  (status + bytes(4), 'после-результата')]
        for raw in (-1, 0x7f, 0x80, 0x0101, 0x10000, int(signal.NSIG)):
            ошибки.append((status + raw.to_bytes(4, 'big', signed=True), 'результат'))
        for stage, error in ((0, 0), (1, 1), (2, 0), (3, -1), (4, -1), (5, 0)):
            ошибки.append((unknown + stage.to_bytes(4, 'big') + error.to_bytes(4, 'big', signed=True), 'результат'))
        корректная_ошибка = unknown + (2).to_bytes(4, 'big') + (13).to_bytes(4, 'big')
        ошибки.extend(((корректная_ошибка[:-1], 'результат'),
                       (корректная_ошибка + b'X', 'результат'),
                       (b'FUE1' + bytes(16) + корректная_ошибка[20:], 'результат')))
        for frame, phase in ошибки:
            with сам.subTest(frame=frame, phase=phase), сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._разобрать_кадр_супервизора(frame, идентификатор, phase)
        class Подстрока(str):
            pass
        for frame, ident, phase in ((bytearray(готов), идентификатор, 'готовность'),
                                    (готов, идентификатор.upper(), 'готовность'),
                                    (готов, идентификатор, 'другая'),
                                    (готов, Подстрока(идентификатор), 'готовность'),
                                    (готов, идентификатор, Подстрока('готовность'))):
            with сам.subTest(phase=phase), сам.assertRaises(модуль.ОшибкаОтчёта):
                модуль._разобрать_кадр_супервизора(frame, ident, phase)

