    def test_старый_supervisor_отклоняет_новую_политику_до_ready(сам):
        import select
        if сам.исполнитель is None or сам.отпечаток is None or сам.удержать_неизвестный_исход is not True:
            сам.skipTest('нужны исполнитель, отпечаток и удержание неизвестного исхода')
        модуль = загрузить_модуль_автоматизации()
        исполнитель = Path(сам.исполнитель)
        сам.assertTrue(исполнитель.is_absolute())
        сам.assertEqual(hashlib.sha256(исполнитель.read_bytes()).hexdigest(), сам.отпечаток)
        сам.каталог_отказа = tempfile.TemporaryDirectory(dir='/tmp')
        сам.fd_отказа = []
        сам.процесс_отказа = None
        сам.попытка_отказа = 'не начата'
        сам.очистка_отказа = 'не начата'
        завершено = False
        try:
            with модуль._тестовая_маска_транспорта():
                if set(signal.sigpending()) & {signal.SIGINT, signal.SIGTERM}:
                    raise RuntimeError('управляемый сигнал до запуска фикстуры')
                управление = os.pipe()
                сам.fd_отказа.extend(управление)
                статус = os.pipe()
                сам.fd_отказа.extend(статус)
                идентификатор = str(uuid.uuid4())
                argv = [str(исполнитель), 'fum-supervisor.4', идентификатор, str(статус[1]),
                        'none', 'run', 'none', '--', '/bin/sh', '-c', 'printf called > sentinel']
                сам.попытка_отказа = 'начата'
                сам.процесс_отказа = subprocess.Popen(
                    argv, cwd=сам.каталог_отказа.name, env={}, stdin=управление[0],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    pass_fds=(статус[1],), start_new_session=True, close_fds=True)
                сам.попытка_отказа = 'объект получен'
                модуль._отпустить_зарегистрированный_fd(сам.fd_отказа, управление[0])
                модуль._отпустить_зарегистрированный_fd(сам.fd_отказа, статус[1])
            сам.assertEqual(сам.процесс_отказа.wait(timeout=5), 125)
            if not select.select([статус[0]], [], [], 5)[0]:
                raise TimeoutError('нет EOF статуса supervisor')
            сам.assertEqual(os.read(статус[0], 1), b'')
            сам.assertFalse((Path(сам.каталог_отказа.name) / 'sentinel').exists())
            with сам.assertRaises(ProcessLookupError):
                os.killpg(сам.процесс_отказа.pid, 0)
            завершено = True
        finally:
            if завершено:
                сам.очистка_отказа = 'начата'
                for fd in tuple(сам.fd_отказа):
                    модуль._отпустить_зарегистрированный_fd(сам.fd_отказа, fd)
                сам.каталог_отказа.cleanup()
                сам.очистка_отказа = 'завершена'

