    def test_фикстура_тайм_аута_удерживает_fd_при_отказе_flock(сам):
        import fcntl
        import stat

        сам.исполнитель = '/usr/bin/true'
        сам.отпечаток = '0' * 64
        завершено = False
        try:
            with mock.patch.object(fcntl, 'flock', side_effect=OSError('фиктивный отказ flock')) as flock, \
                 mock.patch.object(subprocess, 'Popen', side_effect=AssertionError('ранний запуск')) as popen, \
                 mock.patch.object(tempfile, 'TemporaryDirectory', side_effect=AssertionError('финализатор')):
                with сам.assertRaisesRegex(OSError, 'фиктивный отказ flock'):
                    сам._реальная_фикстура_супервизора(наблюдения=False, тайм_аут=True)
                flock.assert_called_once(); popen.assert_not_called()
            сам.assertFalse(сам.запуск_начат)
            сам.assertEqual(сам.фаза_фикстуры_тайм_аута, 'создана')
            сам.assertEqual(len(сам.дескрипторы), 1)
            сам.assertTrue(stat.S_ISREG(os.fstat(сам.дескрипторы[0]).st_mode))
            сам.assertTrue(сам.владелец_запуска._блокировка.locked())
            каталог = сам.путь_фикстуры_тайм_аута
            сам.assertEqual({п.name for п in каталог.iterdir()}, {'active.json', 'fixture.lock'})
            завершено = True
        finally:
            # Mock flock не вызывал syscall, а FD был получен и ещё не закрывался.
            # При любом другом исходе case и все ресурсы остаются у внешнего владельца.
            if завершено:
                fd = сам.дескрипторы[0]
                os.close(fd)
                сам.дескрипторы.remove(fd)
                сам.владелец_запуска._блокировка.release()
                (каталог / 'active.json').unlink()
                (каталог / 'fixture.lock').unlink()
                каталог.rmdir()

