    def test_общий_срок_останавливает_собственный_git_процесс(сам):
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            база = Path(временный).resolve()
            начало = time.monotonic()
            исходный_popen = subprocess.Popen
            процессы = []
            def запомнить(вызов, **параметры):
                сам.assertEqual(вызов, ['git', '-C', str(база), '-c', 'core.fsmonitor=false',
                                          'rev-parse', 'HEAD'])
                процесс = исходный_popen(['/bin/sh', '-c', 'printf started\nexec /bin/sleep 5'],
                                         **параметры)
                процессы.append(процесс)
                return процесс
            with mock.patch.object(модуль.subprocess, 'Popen', side_effect=запомнить):
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'тайм-аут Git-чтения') as ошибка:
                    модуль.выполнить_чтение_репозитория(
                        база, 'rev-parse', 'HEAD', срок=начало + 2.0
                    )
            длительность = time.monotonic() - начало
            сам.assertIsInstance(ошибка.exception.__cause__, subprocess.TimeoutExpired)
            сам.assertIn(b'started', ошибка.exception.__cause__.stdout)
            сам.assertEqual(len(процессы), 1)
            сам.assertEqual(процессы[0].returncode, -signal.SIGKILL)
            сам.assertLess(длительность, 6.0)

    def test_настоящий_тайм_аут_git_чтения_останавливает_лидера(сам):
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            база = Path(временный).resolve()
            маркер = база / 'child-started'
            обычный_запуск = subprocess.run
            def сокращённый(вызов, **параметры):
                сам.assertEqual(вызов, ['git', '-C', str(база), '-c', 'core.fsmonitor=false',
                                          'rev-parse', 'HEAD'])
                сам.assertEqual(параметры['timeout'], 30)
                параметры['timeout'] = 1.0
                return обычный_запуск(
                    ['/bin/sh', '-c', 'printf "%s" "$$" > "$1"\nexec /bin/sleep 5',
                     'фикстура', str(маркер)], **параметры)
            начало = time.monotonic()
            with mock.patch.object(модуль.subprocess, 'run', side_effect=сокращённый):
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'тайм-аут Git-чтения'):
                    модуль.выполнить_чтение_репозитория(база, 'rev-parse', 'HEAD')
            pid = int(маркер.read_bytes())
            with сам.assertRaises(ProcessLookupError): os.kill(pid, 0)
            сам.assertLess(time.monotonic() - начало, 4.0)
            сам.assertFalse(any(п.suffix == '.py' for п in база.rglob('*')))

