class ПроверкаОграниченногоGitЧтения(unittest.TestCase):
    def test_снимок_принимает_реальное_переименование_с_именем_похожим_на_статус(сам):
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        try:
            исходное = '1 .M S.M. source-name'
            (фикстура.корень / исходное).write_text('fixture\n', encoding='utf-8')
            среда = {'PATH': os.defpath, 'LC_ALL': 'C', 'GIT_OPTIONAL_LOCKS': '0',
                     'GIT_NO_LAZY_FETCH': '1', 'GIT_NO_REPLACE_OBJECTS': '1',
                     'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_GLOBAL': os.devnull,
                     'GIT_ATTR_NOSYSTEM': '1'}
            def гит(*аргументы):
                return subprocess.run(['/usr/bin/git', '-C', str(фикстура.корень),
                    '-c', 'core.fsmonitor=false', '-c', 'core.hooksPath='+os.devnull, *аргументы],
                    env=среда, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE, timeout=10, check=True).stdout
            гит('add', '--', исходное)
            гит('commit', '-q', '-m', 'fixture source')
            гит('mv', '--', исходное, 'target')
            статус = гит('status', '--porcelain=v2', '-z', '--untracked-files=all',
                         '--ignore-submodules=none', '--', '.')
            сам.assertIn(b'2 R. N...', статус)
            сам.assertIn(исходное.encode('ascii') + b'\0', статус)
            сам.assertRegex(модуль.вычислить_отпечаток_снимка(
                фикстура.корень, Path(путь_запроса).parent), r'^sha256:[0-9a-f]{64}$')
        finally:
            фикстура.очистить()

