    def test_наблюдение_и_попытка_waitpid_различаются_до_сигналов(сам):
        модуль = загрузить_модуль_автоматизации()
        ребёнок = mock.Mock(pid=4321, returncode=None)
        этапы = []
        истечение = модуль.ОшибкаИстеченияНаблюдения('deadline')
        with mock.patch.object(модуль, '_тестовое_наблюдение_дочернего_процесса', side_effect=истечение), \
             mock.patch.object(модуль.os, 'waitpid') as waitpid, \
             mock.patch.object(модуль.os, 'killpg') as сигнал:
            with сам.assertRaises(модуль.ОшибкаИстеченияНаблюдения):
                модуль._кандидат_собрать_статус_лидера(
                    ребёнок, срок=time.monotonic()+5, _перед_сбором=lambda: этапы.append('сбор'))
            сам.assertEqual(этапы, []); waitpid.assert_not_called(); сигнал.assert_not_called()
        with mock.patch.object(модуль, '_тестовое_наблюдение_дочернего_процесса', return_value=0), \
             mock.patch.object(модуль.os, 'waitpid', side_effect=ChildProcessError('ECHILD')) as waitpid, \
             mock.patch.object(модуль.os, 'killpg') as сигнал:
            with сам.assertRaises(модуль.ОшибкаСбораЛидера):
                модуль._кандидат_собрать_статус_лидера(
                    ребёнок, срок=time.monotonic()+5, _перед_сбором=lambda: этапы.append('сбор'))
            сам.assertEqual(этапы, ['сбор']); waitpid.assert_called_once(); сигнал.assert_not_called()

    def test_один_sigterm_собственной_группе_до_сбора(сам):
        import select, threading
        модуль = загрузить_модуль_автоматизации()
        сам.assertEqual(len(threading.enumerate()), 1)
        сам.assertEqual(signal.getsignal(signal.SIGCHLD), signal.SIG_DFL)
        программа = (
            'import os,select,signal; '
            'p=os.getpid(); assert p==os.getpgrp()==os.getsid(0); '
            'signal.signal(signal.SIGTERM,lambda *_: os._exit(23)); '
            'print(p,flush=True); select.select([0],[],[],10); os._exit(24)'
        )
        сам.процесс_сигнального_теста = None
        ребёнок = subprocess.Popen(
            [sys.executable, '-I', '-S', '-B', '-c', программа],
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'}, start_new_session=True)
        сам.процесс_сигнального_теста = ребёнок
        сам.assertIsNotNone(ребёнок.stdin); сам.assertIsNotNone(ребёнок.stdout)
        готово, _, _ = select.select([ребёнок.stdout], [], [], 3.0)
        сам.assertTrue(готово, 'лидер не подтвердил готовность')
        сам.assertEqual(ребёнок.stdout.readline(), str(ребёнок.pid).encode() + b'\n')
        сам.assertGreater(ребёнок.pid, 1)
        сам.assertEqual(os.getpgid(ребёнок.pid), ребёнок.pid)
        сам.assertIsNone(os.waitid(os.P_PID, ребёнок.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT))
        os.killpg(ребёнок.pid, signal.SIGTERM)
        наблюдение = модуль._тестовое_наблюдение_дочернего_процесса(
            ребёнок.pid, срок=time.monotonic()+4.0)
        сам.assertEqual(наблюдение, 23)
        pid, статус = os.waitpid(ребёнок.pid, os.WNOHANG)
        сам.assertEqual(pid, ребёнок.pid)
        сам.assertEqual(os.waitstatus_to_exitcode(статус), наблюдение)
        ребёнок.returncode = наблюдение
        ребёнок.stdin.close(); ребёнок.stdout.close()

