    def test_реальное_наблюдение_своего_лидера_до_сбора(сам):
        import errno, select
        модуль = загрузить_модуль_автоматизации()
        программа = (
            'import os,select,sys; '
            'p=os.getpid(); '
            'assert p==os.getpgrp()==os.getsid(0); '
            'print(p,flush=True); '
            'r=select.select([0],[],[],5)[0]; '
            'os._exit(0 if r and os.read(0,1)==b"x" else 2)'
        )
        сам.наблюдаемый_процесс = None
        ребёнок = subprocess.Popen(
            [sys.executable, '-I', '-S', '-B', '-c', программа],
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'}, start_new_session=True)
        сам.наблюдаемый_процесс = ребёнок
        сам.assertIsNotNone(ребёнок.stdin); сам.assertIsNotNone(ребёнок.stdout)
        готово, _, _ = select.select([ребёнок.stdout], [], [], 3.0)
        сам.assertTrue(готово, 'лидер не подтвердил готовность')
        сам.assertEqual(ребёнок.stdout.readline(), str(ребёнок.pid).encode() + b'\n')
        сам.assertEqual(os.getpgid(ребёнок.pid), ребёнок.pid)
        try:
            os.killpg(ребёнок.pid, 0)
            исход_живого = 'доступна'
        except OSError as ошибка:
            if ошибка.errno not in (errno.EPERM, errno.ESRCH): raise
            исход_живого = 'EPERM' if ошибка.errno == errno.EPERM else 'ESRCH'
        сам.исход_живой_группы = исход_живого
        ребёнок.stdin.write(b'x'); ребёнок.stdin.flush(); ребёнок.stdin.close()
        наблюдение = модуль._тестовое_наблюдение_дочернего_процесса(
            ребёнок.pid, срок=time.monotonic()+4.0)
        сам.assertEqual(наблюдение, 0)
        try:
            os.killpg(ребёнок.pid, 0)
            исход_группы = 'доступна'
        except OSError as ошибка:
            if ошибка.errno not in (errno.EPERM, errno.ESRCH): raise
            исход_группы = 'EPERM' if ошибка.errno == errno.EPERM else 'ESRCH'
        сам.исход_наблюдения_группы = исход_группы
        print('Наблюдение группы при живом лидере:', исход_живого,
              '; до сбора завершённого лидера:', исход_группы, flush=True)
        pid, статус = os.waitpid(ребёнок.pid, os.WNOHANG)
        сам.assertEqual(pid, ребёнок.pid)
        сам.assertEqual(os.waitstatus_to_exitcode(статус), наблюдение)
        ребёнок.returncode = наблюдение
        try:
            os.killpg(ребёнок.pid, 0)
            исход_после_сбора = 'доступна'
        except OSError as ошибка:
            if ошибка.errno not in (errno.EPERM, errno.ESRCH): raise
            исход_после_сбора = 'EPERM' if ошибка.errno == errno.EPERM else 'ESRCH'
        сам.исход_группы_после_сбора = исход_после_сбора
        print('Наблюдение числового PGID после сбора:', исход_после_сбора, flush=True)
        ребёнок.stdout.close()

    def test_сигнатура_кандидата_сохранена_кроме_владельца(сам):
        import inspect
        модуль = загрузить_модуль_автоматизации()
        внешняя = inspect.signature(модуль._выполнить_ограниченный_запуск)
        внутренняя = inspect.signature(модуль._выполнить_ограниченный_запуск_внутри)
        прежние = [п for имя, п in внутренняя.parameters.items() if имя != '_владелец']
        текущие = [п for имя, п in внешняя.parameters.items() if имя != '_тестовый_владелец']
        сам.assertEqual(текущие, прежние)
        сам.assertEqual(внешняя.return_annotation, внутренняя.return_annotation)
        сам.assertEqual(внешняя.parameters['_тестовый_владелец'].kind, inspect.Parameter.KEYWORD_ONLY)

