    def test_сборщик_передаёт_тип_истечения_без_waitpid_и_сигналов(сам):
        модуль = загрузить_модуль_автоматизации()
        for часы, ждём_истечение in (([100.0], True), ([99.0, 99.0, 100.0], True), ([float('nan')], False)):
            ребёнок = mock.Mock(pid=4321, returncode=None)
            with сам.subTest(часы=часы), \
                 mock.patch.object(модуль.time, 'monotonic', side_effect=часы), \
                 mock.patch.object(модуль.os, 'waitid', return_value=None) as наблюдать, \
                 mock.patch.object(модуль.os, 'waitpid') as собрать, \
                 mock.patch.object(модуль.os, 'kill') as сигнал, \
                 mock.patch.object(модуль.os, 'killpg') as группа:
                with сам.assertRaises(модуль.ОшибкаОтчёта) as ошибка:
                    модуль._кандидат_собрать_статус_лидера(ребёнок, срок=100.0)
                сам.assertIs(type(ошибка.exception), модуль.ОшибкаИстеченияНаблюдения if ждём_истечение else модуль.ОшибкаОтчёта)
                сам.assertEqual(наблюдать.call_count, 1 if len(часы) > 1 else 0)
                сам.assertIsNone(ребёнок.returncode)
                собрать.assert_not_called(); сигнал.assert_not_called(); группа.assert_not_called()

    def test_истечение_наблюдения_не_подменяет_echild_или_ошибку_часов(сам):
        модуль = загрузить_модуль_автоматизации()
        for часы, ответ, ожидалось in (
            ([100.0], None, 'истёк'),
            ([99.0, 100.0], None, 'истёк'),
            ([float('nan')], None, 'часы'),
            ([True], None, 'часы'),
            ([99.0], ChildProcessError('echild'), 'echild'),
        ):
            with сам.subTest(ожидалось=ожидалось, часы=часы), \
                 mock.patch.object(модуль.time, 'monotonic', side_effect=часы), \
                 mock.patch.object(модуль.os, 'waitid', side_effect=ответ if isinstance(ответ, BaseException) else None, return_value=None) as наблюдать, \
                 mock.patch.object(модуль.os, 'waitpid') as собрать, \
                 mock.patch.object(модуль.os, 'kill') as сигнал, \
                 mock.patch.object(модуль.os, 'killpg') as группа:
                with сам.assertRaises(модуль.ОшибкаОтчёта) as ошибка:
                    модуль._тестовое_наблюдение_дочернего_процесса(4321, срок=100.0)
                if ожидалось == 'истёк':
                    сам.assertIs(type(ошибка.exception), модуль.ОшибкаИстеченияНаблюдения)
                else:
                    сам.assertIs(type(ошибка.exception), модуль.ОшибкаОтчёта)
                    if ожидалось == 'echild':
                        сам.assertIs(ошибка.exception.__cause__, ответ)
                сам.assertEqual(наблюдать.call_count, 1 if len(часы) > 1 or ожидалось == 'echild' else 0)
                собрать.assert_not_called(); сигнал.assert_not_called(); группа.assert_not_called()

