    def test_двойной_сбой_маски_сохраняет_обе_ошибки_без_повторного_close(сам):
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory(prefix='fum-mask-double-', dir='/tmp') as временный:
            каталог = Path(временный).resolve(); цель = каталог / 'terminal.json'; цель.write_bytes(b'old')
            настоящий_open, настоящий_close = os.open, os.close
            дескрипторы = []; попытки = []; подтверждённые = []
            первая = OSError('restore unknown'); вторая = OSError('block unknown')
            def открыть(путь, флаги, *a, **k):
                fd = настоящий_open(путь, флаги, *a, **k)
                if isinstance(путь, (str, Path)) and Path(путь).name.startswith('.terminal.json.'):
                    дескрипторы.append(fd)
                return fd
            def закрыть(fd):
                if fd in дескрипторы:
                    попытки.append(fd)
                return настоящий_close(fd)
            try:
                with mock.patch.object(модуль.os, 'open', side_effect=открыть), \
                     mock.patch.object(модуль.os, 'close', side_effect=закрыть), \
                     mock.patch.object(модуль.signal, 'pthread_sigmask', side_effect=[set(), первая, вторая]), \
                     mock.patch.object(модуль.os, 'replace') as замена:
                    with сам.assertRaises(BaseExceptionGroup) as ошибка:
                        модуль.атомарно_записать_байты(цель, b'new')
                сам.assertIs(ошибка.exception.exceptions[0].__cause__, первая)
                сам.assertIs(ошибка.exception.exceptions[1], вторая)
                замена.assert_not_called()
                сам.assertEqual(попытки, [])
                сам.assertEqual(цель.read_bytes(), b'old')
                сам.assertEqual(len(list(каталог.glob('.terminal.json.*.tmp'))), 1)
                сам.assertEqual(len(дескрипторы), 1)
                os.fstat(дескрипторы[0])
                подтверждённые.append(дескрипторы[0])
            finally:
                for fd in подтверждённые:
                    настоящий_close(fd)

