    def test_точный_режим_истории_не_зависит_от_ограничительной_маски(сам):
        import stat
        модуль = загрузить_модуль_автоматизации()
        сам.точный_режим_фикстуры = [tempfile.TemporaryDirectory(prefix='fum-exact-mode-', dir='/tmp')]
        сам.точный_режим_фикстуры[0]._finalizer.detach()
        каталог = Path(сам.точный_режим_фикстуры[0].name).resolve(); цель = каталог / 'active.json'
        открыть = модуль.os.open
        def ограниченное_открытие(путь, флаги, режим=0o777, **ключи):
            if флаги & os.O_CREAT and Path(путь).name.startswith('.active.json.'):
                режим &= ~0o077
            return открыть(путь, флаги, режим, **ключи)
        with mock.patch.object(модуль.os, 'open', side_effect=ограниченное_открытие):
            модуль.атомарно_записать_байты(цель, b'active', только_новый=True, _точный_режим=0o644)
            сам.assertEqual((цель.read_bytes(), stat.S_IMODE(цель.stat().st_mode), цель.stat().st_nlink),
                            (b'active', 0o644, 1))
            модуль.атомарно_записать_байты(цель, b'terminal', _точный_режим=0o644)
        сам.assertEqual((цель.read_bytes(), stat.S_IMODE(цель.stat().st_mode), цель.stat().st_nlink),
                        (b'terminal', 0o644, 1))
        сам.assertEqual(list(каталог.glob('.active.json.*.tmp')), [])
        сам.точный_режим_фикстуры[0].cleanup(); сам.точный_режим_фикстуры.clear()

