    def test_создание_каталога_после_допуска_и_проверка_появления(сам):
        модуль = загрузить_модуль_автоматизации()
        class ДошлиДоЗаписи(Exception):
            pass
        for вариант in ('закрытый', 'допущен', 'появился', 'отчёт-изменён'):
            with сам.subTest(вариант=вариант), tempfile.TemporaryDirectory(prefix='fum-preflight-', dir='/tmp') as временный:
                корень = Path(временный).resolve()
                отчёт = корень / 'отчёт.md'
                отчёт.write_bytes(b'test')
                каталог = корень / 'материалы' / 'запуски-проверок'
                def снимок(*_):
                    if вариант == 'появился':
                        каталог.mkdir(parents=True)
                        (каталог / 'чужой.txt').write_bytes(b'preserve')
                    elif вариант == 'отчёт-изменён':
                        отчёт.write_bytes(b'changed')
                    return 'sha256:' + '0' * 64
                маркер = 'закрыт' if вариант == 'закрытый' else модуль.ОТКРЫТЫЙ_МАРКЕР
                параметры = (корень, корень / 'запрос.md', 'test', 'root',
                             '00000000-0000-4000-8000-000000000018', 5.0, ['/bin/true'])
                with mock.patch.object(модуль, 'разрешить_сессию', return_value=(корень, None, отчёт, каталог, путь_запроса)), \
                     mock.patch.object(модуль, 'межпроцессная_блокировка', return_value=contextlib.nullcontext(lambda: None)), \
                     mock.patch.object(модуль, 'является_неполной_проверкой_проекции', return_value=False), \
                     mock.patch.object(модуль, 'является_запуском_полной_проверки', return_value=False), \
                     mock.patch.object(модуль, 'границы_управляемого_блока', return_value=(None, None, маркер)), \
                     mock.patch.object(модуль, 'вычислить_отпечаток_снимка', side_effect=снимок) as проверка, \
                     mock.patch.object(модуль, 'атомарно_записать_байты', side_effect=ДошлиДоЗаписи) as запись, \
                     mock.patch.object(модуль.subprocess, 'Popen') as процесс:
                    if вариант == 'допущен':
                        with сам.assertRaises(ДошлиДоЗаписи):
                            модуль._выполнить_ограниченный_запуск(*параметры, класс_проверки='адресная', тайм_аут_блокировки=1.0)
                        сам.assertTrue(каталог.is_dir())
                        запись.assert_called_once()
                    else:
                        with сам.assertRaises(модуль.ОшибкаОтчёта):
                            модуль._выполнить_ограниченный_запуск(*параметры, класс_проверки='адресная', тайм_аут_блокировки=1.0)
                        запись.assert_not_called()
                        if вариант == 'закрытый':
                            сам.assertFalse(каталог.exists())
                            проверка.assert_not_called()
                        elif вариант == 'появился':
                            сам.assertEqual((каталог / 'чужой.txt').read_bytes(), b'preserve')
                        else:
                            сам.assertEqual(отчёт.read_bytes(), b'changed')
                            сам.assertFalse(каталог.exists())
                    процесс.assert_not_called()

