    def _реальная_конкуренция(сам, терминальный):
        import fcntl
        import select

        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        корень = фикстура.корень.resolve()
        каталог_замка = корень / ".git"
        ключ = hashlib.sha256(f"{корень}\0{путь_запроса}".encode()).hexdigest()
        замок = каталог_замка / f"fum-check-runs-{ключ}.lock"
        старт = корень / "child-start"
        разрешение = корень / "child-release"
        конец = корень / "child-done"
        снимок = корень / "active-snapshot"
        идентификатор = "00000000-0000-4000-8000-000000000017"
        запись = фикстура.каталог_записей / f"1_{идентификатор}.json"
        готово_чтение, готово_запись = os.pipe()
        отпустить_чтение, отпустить_запись = os.pipe()
        процесс = None
        try:
            процесс = os.fork()
            if процесс == 0:
                try:
                    os.close(готово_чтение)
                    os.close(отпустить_запись)
                    if терминальный:
                        дождаться_файла(старт, 5.0)
                        дождаться_файла(замок, 5.0)
                    дескриптор = os.open(замок, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
                    try:
                        fcntl.flock(дескриптор, fcntl.LOCK_EX)
                        if терминальный:
                            снимок.write_bytes(запись.read_bytes())
                            разрешение.write_bytes(b"go")
                        os.write(готово_запись, b"R")
                        if os.read(отпустить_чтение, 1) != b"G":
                            os._exit(3)
                        fcntl.flock(дескриптор, fcntl.LOCK_UN)
                    finally:
                        os.close(дескриптор)
                    os._exit(0)
                except BaseException:
                    os._exit(4)
            os.close(готово_запись)
            готово_запись = None
            os.close(отпустить_чтение)
            отпустить_чтение = None
            if not терминальный:
                сам.assertTrue(select.select([готово_чтение], [], [], 5.0)[0])
                сам.assertEqual(os.read(готово_чтение, 1), b"R")
            код_ребёнка = (
                "import pathlib,sys,time\n"
                "старт,разрешение,конец=map(pathlib.Path,sys.argv[1:])\n"
                "with старт.open('ab') as поток:\n"
                "    поток.write(b'S')\n"
                "предел=time.monotonic()+5\n"
                "while not разрешение.exists():\n"
                "    if time.monotonic()>=предел: raise SystemExit(9)\n"
                "    time.sleep(0.01)\n"
                "конец.write_bytes(b'done')\n"
            )
            команда = [sys.executable, "-B", "-c", код_ребёнка,
                       str(старт), str(разрешение), str(конец)]
            штатный_popen = subprocess.Popen

            def в_тестовой_группе(*аргументы, **параметры):
                if аргументы and аргументы[0] == команда:
                    сам.assertIs(параметры.get("start_new_session"), True)
                    параметры["start_new_session"] = False
                return штатный_popen(*аргументы, **параметры)

            with mock.patch.object(модуль.tempfile, "gettempdir", return_value=str(каталог_замка)), \
                 mock.patch.object(модуль.subprocess, "Popen", side_effect=в_тестовой_группе):
                аргументы = (корень, Path(путь_запроса), "конкуренция", "корень",
                             идентификатор, 5.0, команда)
                if терминальный:
                    код = модуль._выполнить_ограниченный_запуск(
                        *аргументы, класс_проверки="адресная", тайм_аут_блокировки=0.5)
                    сам.assertTrue(select.select([готово_чтение], [], [], 5.0)[0])
                    сам.assertEqual(os.read(готово_чтение, 1), b"R")
                    сам.assertEqual(код, модуль.КОД_ОШИБКИ_ОБЁРТКИ)
                    сам.assertEqual(старт.read_bytes(), b"S")
                    сам.assertEqual(конец.read_bytes(), b"done")
                    сам.assertEqual(запись.read_bytes(), снимок.read_bytes())
                    сам.assertEqual(json.loads(запись.read_bytes())["состояние"], "выполняется")
                    сам.assertEqual(len(фикстура.записи()), 1)
                else:
                    with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, "истёк срок"):
                        модуль._выполнить_ограниченный_запуск(
                            *аргументы, класс_проверки="адресная", тайм_аут_блокировки=0.5)
                    сам.assertFalse(старт.exists())
                    сам.assertEqual(фикстура.записи(), [])
            os.write(отпустить_запись, b"G")
            _, статус = os.waitpid(процесс, 0)
            процесс = None
            сам.assertTrue(os.WIFEXITED(статус))
            сам.assertEqual(os.WEXITSTATUS(статус), 0)
        finally:
            for дескриптор in (готово_чтение, готово_запись, отпустить_чтение, отпустить_запись):
                if дескриптор is not None:
                    os.close(дескриптор)
            if процесс is not None and процесс > 0:
                try:
                    os.kill(процесс, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                os.waitpid(процесс, 0)
            фикстура.очистить()

