    def test_прерывание_передачи_fd_сообщает_неизвестный_исход(сам):
        модуль = загрузить_модуль_автоматизации()
        отмена = KeyboardInterrupt('после удаления из реестра')
        class Реестр(list):
            def remove(self, fd):
                super().remove(fd)
                raise отмена
        реестр = Реестр([41, 42])
        with mock.patch.object(модуль.signal, 'pthread_sigmask', return_value=set()), \
             mock.patch.object(модуль.os, 'close') as закрыть:
            with сам.assertRaises(KeyboardInterrupt) as отказ:
                модуль._отпустить_зарегистрированный_fd(реестр, 41)
            сам.assertIs(отказ.exception, отмена)
            сам.assertTrue(any('Неизвестен исход передачи FD' in заметка
                              for заметка in getattr(отказ.exception, '__notes__', ())))
            сам.assertEqual(реестр, [42])
            закрыть.assert_not_called()
            модуль._закрыть_удержанные_fd(реестр, отказ.exception, 'тест')
            закрыть.assert_called_once_with(42)

    def test_отмена_после_закрытия_компонента_закрывает_остальные_fd(сам):
        import stat
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            база = Path(временный).resolve()
            каталог = база / 'lock'; каталог.mkdir(mode=0o700)
            корень = база / 'repo'; корень.mkdir()
            закреплённый = os.open(каталог, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            try:
                данные = os.fstat(закреплённый)
                селектор = ('fum.test-lock-root.2', str(каталог), данные.st_dev, данные.st_ino,
                    данные.st_uid, stat.S_IMODE(данные.st_mode), 'fixture', str(корень))
                отмена = KeyboardInterrupt('после закрытия компонента')
                открытия, закрытия, восстановления = [], [], []
                исходный_open, исходный_close = os.open, os.close
                def открыть(*аргументы, **ключи):
                    fd = исходный_open(*аргументы, **ключи)
                    открытия.append(fd)
                    return fd
                def закрыть(fd):
                    закрытия.append(fd)
                    return исходный_close(fd)
                def маска(операция, _сигналы):
                    if операция == signal.SIG_SETMASK:
                        восстановления.append(True)
                        if len(восстановления) == 3: raise отмена
                    return set()
                with mock.patch.object(модуль.os, 'open', side_effect=открыть), \
                     mock.patch.object(модуль.os, 'close', side_effect=закрыть), \
                     mock.patch.object(модуль.signal, 'pthread_sigmask', side_effect=маска), \
                     mock.patch.object(модуль.fcntl, 'flock') as flock:
                    with сам.assertRaises(KeyboardInterrupt) as отказ:
                        with модуль._тестовый_замок_новой_сессии(
                            селектор, закреплённый, корень, 'fixture', срок_монотонный=time.monotonic()+3):
                            сам.fail('ожидалась отмена')
                    сам.assertIs(отказ.exception, отмена)
                    flock.assert_not_called()
                сам.assertEqual(len(открытия), 2)
                сам.assertCountEqual(закрытия, открытия)
                for fd in открытия:
                    with сам.assertRaises(OSError): os.fstat(fd)
                os.fstat(закреплённый)
            finally:
                os.close(закреплённый)

