    def test_eexist_и_маска_нового_замка_не_дают_fallback(сам):
        import stat
        модуль = загрузить_модуль_автоматизации()
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            база = Path(временный).resolve()
            каталог = база / 'lock'; каталог.mkdir(mode=0o700)
            корень = база / 'repo'; корень.mkdir()
            закреплённый = os.open(каталог, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            try:
                данные = os.fstat(закреплённый)
                селектор = ('fum.test-lock-root.2', str(каталог), данные.st_dev, данные.st_ino,
                    данные.st_uid, stat.S_IMODE(данные.st_mode), 'fixture', str(корень))
                ключ = hashlib.sha256(f'{корень}\0fixture'.encode()).hexdigest()
                путь = каталог / f'fum-check-runs-{ключ}.lock'
                fd = os.open(путь, os.O_CREAT | os.O_EXCL | os.O_RDWR, 0o600); os.close(fd)
                до = путь.stat()
                ошибка_маски = FileExistsError('ошибка маски')
                исходный_open = os.open
                открытия, попытки, восстановления = [], [], []
                def открыть(*аргументы, **ключи):
                    попытки.append(True)
                    fd = исходный_open(*аргументы, **ключи)
                    открытия.append(fd)
                    return fd
                def маска(операция, _сигналы):
                    if операция == signal.SIG_SETMASK:
                        восстановления.append(True)
                        if len(попытки) == len(каталог.parts)+1: raise ошибка_маски
                    return set()
                with mock.patch.object(модуль.os, 'open', side_effect=открыть), \
                     mock.patch.object(модуль.signal, 'pthread_sigmask', side_effect=маска), \
                     mock.patch.object(модуль.fcntl, 'flock') as flock:
                    with сам.assertRaises(BaseExceptionGroup) as отказ:
                        with модуль._тестовый_замок_новой_сессии(
                            селектор, закреплённый, корень, 'fixture', срок_монотонный=time.monotonic()+3):
                            сам.fail('ошибочная ветка открытия')
                    основная, вторичная = отказ.exception.exceptions
                    сам.assertIsInstance(основная.__cause__, FileExistsError)
                    сам.assertIs(вторичная, ошибка_маски)
                    сам.assertEqual(len(попытки), len(каталог.parts)+1)
                    flock.assert_not_called()
                for fd in открытия:
                    with сам.assertRaises(OSError): os.fstat(fd)
                после = путь.stat()
                сам.assertEqual((до.st_dev, до.st_ino), (после.st_dev, после.st_ino))
                os.fstat(закреплённый)
            finally:
                os.close(закреплённый)

