    def test_замена_корня_после_синтетического_fingerprint_до_active(сам):
        import stat
        модуль = загрузить_модуль_автоматизации()
        идентификатор = '00000000-0000-4000-8000-000000000024'
        with tempfile.TemporaryDirectory(dir='/tmp') as временный:
            база = Path(временный).resolve()
            корень = база / 'repo'
            каталог_сессии = корень / 'Журнал' / имя_сессии
            каталог_сессии.mkdir(parents=True)
            (каталог_сессии / 'запрос.md').write_text('# Запрос\n', encoding='utf-8')
            (каталог_сессии / 'отчёт.md').write_text(
                '# Отчёт\n\n' + открытый_маркер + '\nПроверок пока нет.\n' + конечный_маркер + '\n',
                encoding='utf-8')
            каталог_записей = каталог_сессии / 'материалы' / 'запуски-проверок'
            каталог = база / 'lock'
            прежний = база / 'held-lock'
            каталог.mkdir(mode=0o700)
            дескриптор = os.open(каталог, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            try:
                сведения = os.fstat(дескриптор)
                селектор = ('fum.test-lock-root.2', str(каталог), сведения.st_dev,
                    сведения.st_ino, сведения.st_uid, stat.S_IMODE(сведения.st_mode),
                    путь_запроса, str(корень))
                маркер = база / 'child'
                команда = [sys.executable, '-B', '-c',
                    'from pathlib import Path; import sys; Path(sys.argv[1]).write_text("ran")', str(маркер)]
                события = []
                перемещён = False
                создана_замена = False
                def синтетический_отпечаток(*аргументы):
                    nonlocal перемещён, создана_замена
                    каталог.rename(прежний)
                    перемещён = True
                    каталог.mkdir(mode=0o700)
                    создана_замена = True
                    замена = каталог.stat()
                    события.append((замена.st_dev, замена.st_ino))
                    return 'sha256:' + 'a' * 64
                try:
                    with mock.patch.object(модуль, 'вычислить_отпечаток_снимка', side_effect=синтетический_отпечаток), \
                         mock.patch.object(модуль, 'выполнить_чтение_репозитория', side_effect=AssertionError('Git запрещён')), \
                         mock.patch.object(модуль.subprocess, 'Popen', side_effect=AssertionError('процесс запрещён')) as popen, \
                         mock.patch.object(модуль.os, 'environ', object()):
                        with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'идентичность тестового каталога'):
                            модуль._выполнить_ограниченный_запуск(
                                корень, Path(путь_запроса), 'замена корня', 'корень', идентификатор,
                                5.0, команда, класс_проверки='адресная', тайм_аут_блокировки=5.0,
                                _тестовый_селектор=селектор, _тестовый_дескриптор=дескриптор)
                        popen.assert_not_called()
                    сам.assertEqual(len(события), 1)
                    сам.assertNotEqual(события[0], (сведения.st_dev, сведения.st_ino))
                    сам.assertFalse(маркер.exists())
                    сам.assertFalse(any(каталог_записей.glob(f'*_{идентификатор}.json')))
                finally:
                    try:
                        if создана_замена:
                            каталог.rmdir()
                    finally:
                        if перемещён:
                            прежний.rename(каталог)
                сам.assertEqual((каталог.stat().st_dev, каталог.stat().st_ino),
                                (сведения.st_dev, сведения.st_ino))
            finally:
                os.close(дескриптор)

