    def test_fork_не_разблокирует_унаследованный_legacy_lock(сам):
        import fcntl
        модуль = загрузить_модуль_автоматизации()
        временный = tempfile.TemporaryDirectory(dir='/tmp')
        # Автоочистка не должна удалить фикстуру при неизвестном исходе fork.
        временный._finalizer.detach()
        pid = None
        fork_начат = False
        собран = False
        второй_fd = None
        try:
            with mock.patch.object(модуль.tempfile, 'gettempdir', return_value=временный.name):
                try:
                    with модуль.межпроцессная_блокировка(Path('/tmp/fixture'), 'fork-session') as сверить:
                        fork_начат = True
                        pid = os.fork()
                        if pid == 0:
                            try:
                                сверить()
                            except модуль.ОшибкаОтчёта:
                                код_ребёнка = 0
                            except BaseException:
                                код_ребёнка = 2
                            else:
                                код_ребёнка = 1
                        else:
                            срок = time.monotonic() + 5.0
                            while True:
                                получен, статус = os.waitpid(pid, os.WNOHANG)
                                if получен == pid:
                                    собран = True
                                    break
                                if time.monotonic() >= срок:
                                    raise AssertionError('исход собственного ребёнка неизвестен')
                                time.sleep(0.01)
                            сам.assertTrue(os.WIFEXITED(статус))
                            сам.assertEqual(os.WEXITSTATUS(статус), 0)
                            путь, = Path(временный.name).iterdir()
                            второй_fd = os.open(путь, os.O_RDWR | os.O_NOFOLLOW)
                            with сам.assertRaises(BlockingIOError):
                                fcntl.flock(второй_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                            сверить()
                except BaseException:
                    if pid == 0:
                        os._exit(3)
                    raise
                if pid == 0:
                    os._exit(код_ребёнка)
                fcntl.flock(второй_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                fcntl.flock(второй_fd, fcntl.LOCK_UN)
        finally:
            первичная = sys.exception()
            ошибки_очистки = []
            try:
                if второй_fd is not None:
                    os.close(второй_fd)
            except BaseException as ошибка:
                ошибки_очистки.append(ошибка)
            if not fork_начат or собран:
                try:
                    временный.cleanup()
                except BaseException as ошибка:
                    ошибки_очистки.append(ошибка)
            if ошибки_очистки:
                raise BaseExceptionGroup('ошибки теста и очистки lock',
                                         ([первичная] if первичная is not None else []) + ошибки_очистки) from None

