    def test_ошибка_popen_не_доказывает_отсутствие_ребёнка(сам):
        модуль = загрузить_модуль_автоматизации()
        for номер, тип in enumerate((OSError, FileNotFoundError, PermissionError), start=60):
            with сам.subTest(ошибка=тип.__name__), tempfile.TemporaryDirectory(dir='/tmp') as замки:
                фикстура = ФикстураОтчётов()
                владелец = модуль._ТестовыйВладелецЗапуска()
                идентификатор = f'00000000-0000-4000-8000-{номер:012d}'
                причина = тип('неизвестная стадия Popen')
                try:
                    with mock.patch.object(модуль.tempfile, 'gettempdir', return_value=замки), \
                         mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64), \
                         mock.patch.object(модуль.subprocess, 'Popen', side_effect=причина) as запуск, \
                         mock.patch.object(модуль.os, 'kill') as сигнал, \
                         mock.patch.object(модуль.os, 'killpg') as группе:
                        with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'неизвест') as отказ:
                            модуль._выполнить_ограниченный_запуск(
                                фикстура.корень, Path(путь_запроса), 'ошибка Popen', 'корень',
                                идентификатор, 5.0, ['/bin/true'], класс_проверки='адресная',
                                тайм_аут_блокировки=1.0, _тестовый_владелец=владелец)
                        сам.assertIs(отказ.exception.__cause__, причина)
                        запуск.assert_called_once(); сигнал.assert_not_called(); группе.assert_not_called()
                    запись = фикстура.запись(идентификатор)
                    сам.assertEqual((запись['состояние'], запись['статус'], запись['код_завершения']),
                                    ('выполняется', None, None))
                    сам.assertEqual(владелец.состояние, 'неизвестно')
                finally:
                    фикстура.очистить()

