    def test_echild_после_waitid_оставляет_active(сам):
        import errno
        import types
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        владелец = модуль._ТестовыйВладелецЗапуска()
        идентификатор = '00000000-0000-4000-8000-000000000053'
        ребёнок = mock.Mock(pid=12345, returncode=None)
        ребёнок.wait.return_value = 0
        состояние = types.SimpleNamespace(si_pid=12345, si_code=os.CLD_EXITED, si_status=0)
        причина = ChildProcessError(errno.ECHILD, 'no child')
        try:
            with tempfile.TemporaryDirectory(dir='/tmp') as замки, \
                 mock.patch.object(модуль.tempfile, 'gettempdir', return_value=замки), \
                 mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64), \
                 mock.patch.object(модуль.subprocess, 'Popen', return_value=ребёнок), \
                 mock.patch.object(модуль.os, 'waitid', return_value=состояние), \
                 mock.patch.object(модуль.os, 'waitpid', side_effect=причина) as сбор, \
                 mock.patch.object(модуль.os, 'killpg') as группе:
                with сам.assertRaises(модуль.ОшибкаСбораЛидера) as отказ:
                    модуль._выполнить_ограниченный_запуск(
                        фикстура.корень, Path(путь_запроса), 'ECHILD после waitid', 'корень',
                        идентификатор, 1.0, ['/bin/true'], класс_проверки='адресная',
                        тайм_аут_блокировки=1.0, _тестовый_владелец=владелец)
                сам.assertIs(отказ.exception.__cause__, причина)
                сам.assertEqual(отказ.exception.наблюдённый_код, 0)
                сбор.assert_called_once_with(12345, os.WNOHANG)
                ребёнок.wait.assert_not_called(); группе.assert_not_called()
                сам.assertIsNone(ребёнок.returncode)
            сам.assertEqual(фикстура.запись(идентификатор)['состояние'], 'выполняется')
            сам.assertEqual(владелец.состояние, 'неизвестно')
        finally:
            фикстура.очистить()

