        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        владелец = модуль._ТестовыйВладелецЗапуска()
        второй_владелец = модуль._ТестовыйВладелецЗапуска()
        первый = '00000000-0000-4000-8000-000000000050'
        второй = '00000000-0000-4000-8000-000000000051'
        ребёнок = mock.Mock(pid=12345, returncode=None)
        ребёнок.wait.side_effect = subprocess.TimeoutExpired(['/bin/true'], 1.0)
        try:
            with tempfile.TemporaryDirectory(dir='/tmp') as замки, \
                 mock.patch.object(модуль.tempfile, 'gettempdir', return_value=замки), \
                 mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64), \
                 mock.patch.object(модуль.subprocess, 'Popen', return_value=ребёнок) as popen, \
                 mock.patch.object(модуль, '_кандидат_собрать_статус_лидера', side_effect=subprocess.TimeoutExpired(['/bin/true'], 1.0)), \
                 mock.patch.object(модуль.os, 'killpg', side_effect=AssertionError('сигнал')):
                with сам.assertRaises(модуль.ОшибкаОтчёта):
                    модуль._выполнить_ограниченный_запуск(
                        фикстура.корень, Path(путь_запроса), 'первый', 'корень', первый,
                        1.0, ['/bin/true'], класс_проверки='адресная', тайм_аут_блокировки=1.0, _тестовый_владелец=владелец)
                первый_popen = popen.call_count
                with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'выполня'):
                    модуль._выполнить_ограниченный_запуск(
                        фикстура.корень, Path(путь_запроса), 'второй', 'корень', второй,
                        1.0, ['/bin/true'], класс_проверки='адресная', тайм_аут_блокировки=1.0, _тестовый_владелец=второй_владелец)
                сам.assertEqual(popen.call_count, первый_popen)
            сам.assertEqual(len(фикстура.записи()), 1)
            сам.assertEqual(фикстура.запись(первый)['состояние'], 'выполняется')
            сам.assertEqual(владелец.состояние, 'неизвестно')
            сам.assertEqual(второй_владелец.состояние, 'неизвестно')
        finally:
            фикстура.очистить()

