    def test_отмена_popen_и_сбой_маски_сохраняются_как_обе_ошибки(сам):
        модуль = загрузить_модуль_автоматизации()
        отмены = (KeyboardInterrupt('interrupt'), SystemExit(7),
                  модуль.ПрерываниеОбёртки(signal.SIGTERM))
        for номер, отмена in enumerate(отмены, start=40):
            with сам.subTest(отмена=type(отмена).__name__), tempfile.TemporaryDirectory(dir='/tmp') as замки:
                фикстура = ФикстураОтчётов()
                владелец = модуль._ТестовыйВладелецЗапуска()
                идентификатор = f'00000000-0000-4000-8000-{номер:012d}'
                ошибка_маски = OSError('ошибка маски')
                восстановления, запускался = [], []
                def запуск(*_аргументы, **_ключи):
                    запускался.append(True)
                    raise отмена
                def маска(операция, _сигналы):
                    if операция == signal.SIG_SETMASK and запускался:
                        восстановления.append(True)
                        if len(восстановления) == 1: raise ошибка_маски
                    return set()
                try:
                    with mock.patch.object(модуль.tempfile, 'gettempdir', return_value=замки), \
                         mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64), \
                         mock.patch.object(модуль.subprocess, 'Popen', side_effect=запуск), \
                         mock.patch.object(модуль.signal, 'pthread_sigmask', side_effect=маска), \
                         mock.patch.object(модуль.os, 'killpg') as группе:
                        with сам.assertRaises(BaseExceptionGroup) as отказ:
                            модуль._выполнить_ограниченный_запуск(
                                фикстура.корень, Path(путь_запроса), 'отмена', 'корень',
                                идентификатор, 1.0, ['/bin/true'], класс_проверки='адресная',
                                тайм_аут_блокировки=1.0, _тестовый_владелец=владелец)
                        сам.assertEqual(отказ.exception.exceptions, (отмена, ошибка_маски))
                        сам.assertEqual(запускался, [True])
                        группе.assert_not_called()
                    сам.assertEqual(фикстура.запись(идентификатор)['состояние'], 'выполняется')
                    сам.assertEqual(владелец.состояние, 'неизвестно')
                finally:
                    фикстура.очистить()

    def test_реальный_отказ_exec_оставляет_active_без_подтверждения(сам):
        import stat
        модуль = загрузить_модуль_автоматизации()
        for вариант in ('нет-файла', 'нет-доступа'):
            with сам.subTest(вариант=вариант):
                фикстура = ФикстураОтчётов()
                идентификатор = '00000000-0000-4000-8000-000000000046'
                исполнитель = фикстура.корень.resolve() / 'исполнитель.bin'
                if вариант == 'нет-доступа':
                    исполнитель.write_bytes(b'not executable')
                    исполнитель.chmod(0o600)
                    сведения = исполнитель.lstat()
                    сам.assertTrue(stat.S_ISREG(сведения.st_mode))
                    сам.assertEqual(stat.S_IMODE(сведения.st_mode), 0o600)
                    сам.assertEqual(сведения.st_uid, os.geteuid())
                else:
                    сам.assertFalse(исполнитель.exists())
                команда = [str(исполнитель)]
                настоящий_popen = subprocess.Popen; попытки = []
                def запустить(*аргументы, **ключи):
                    if not аргументы or аргументы[0] != команда or попытки:
                        raise AssertionError('неожиданный или повторный запуск')
                    записи = фикстура.записи()
                    сам.assertEqual([запись['состояние'] for запись in записи], ['выполняется'])
                    попытки.append(True)
                    return настоящий_popen(*аргументы, **ключи)
                try:
                    with tempfile.TemporaryDirectory(dir='/tmp') as замки, \
                         mock.patch.object(модуль.tempfile, 'gettempdir', return_value=замки), \
                         mock.patch.object(модуль.subprocess, 'Popen', side_effect=запустить), \
                         mock.patch.object(модуль.os, 'kill', side_effect=AssertionError('неожиданный сигнал')), \
                         mock.patch.object(модуль.os, 'killpg', side_effect=AssertionError('неожиданный сигнал группе')), \
                         mock.patch.object(модуль, '_кандидат_собрать_статус_лидера', side_effect=AssertionError('неожиданный сбор')) as сбор, \
                         mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64):
                        with сам.assertRaisesRegex(модуль.ОшибкаОтчёта, 'неизвест') as отказ:
                            модуль._выполнить_ограниченный_запуск(
                                фикстура.корень, Path(путь_запроса), 'реальный отказ exec', 'корень',
                                идентификатор, 5.0, команда, класс_проверки='адресная', тайм_аут_блокировки=1.0)
                        сам.assertIsInstance(отказ.exception.__cause__, FileNotFoundError if вариант == 'нет-файла' else PermissionError)
                        сбор.assert_not_called()
                    запись = фикстура.запись(идентификатор)
                    сам.assertEqual((запись['состояние'], запись['статус'], запись['код_завершения']),
                                    ('выполняется', None, None))
                    сам.assertEqual(попытки, [True])
                    сам.assertFalse(any(путь.suffix == '.py' for путь in фикстура.корень.rglob('*')))
                finally:
                    фикстура.очистить()

    def test_реальный_eof_при_неизвестной_группе_оставляет_active(сам):
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        владелец = модуль._ТестовыйВладелецЗапуска()
        сам.владелец_реального_запуска = владелец
        сам.фикстура_реального_запуска = фикстура
        идентификатор = '00000000-0000-4000-8000-000000000047'
        команда = [sys.executable, '-I', '-S', '-B', '-c',
                   'import sys; raise SystemExit(0 if sys.stdin.buffer.read(1) == b"" else 7)']
        настоящий_popen = subprocess.Popen; замечено = []; дети = []
        сам.дети_реального_запуска = дети
        замки = tempfile.TemporaryDirectory(dir='/tmp')
        проверки_завершены = False
        def запустить(*аргументы, **ключи):
            if not аргументы or аргументы[0] != команда or замечено:
                raise AssertionError('неожиданный или повторный запуск')
            записи = фикстура.записи()
            сам.assertEqual([запись['состояние'] for запись in записи], ['выполняется'])
            сам.assertEqual(ключи['stdin'], subprocess.DEVNULL)
            сам.assertEqual(ключи['env'], {
                'PATH': os.defpath, 'GIT_OPTIONAL_LOCKS': '0', 'GIT_NO_LAZY_FETCH': '1',
                'GIT_NO_REPLACE_OBJECTS': '1', 'LC_ALL': 'C', 'FUM_CHECK_RUN_ID': идентификатор,
            })
            замечено.append(True)
            ребёнок = настоящий_popen(*аргументы, **ключи)
            дети.append(ребёнок)
            return ребёнок
        try:
            with mock.patch.object(модуль.tempfile, 'gettempdir', return_value=замки.name), \
                 mock.patch.object(модуль.subprocess, 'Popen', side_effect=запустить), \
                 mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64), \
                 mock.patch.object(модуль, 'группа_процессов_существует',
                                   side_effect=модуль.ОшибкаОтчёта('неизвестная группа')):
                with сам.assertRaises(модуль.ОшибкаНеподтверждённойГруппы) as ошибка:
                    модуль._выполнить_ограниченный_запуск(
                        фикстура.корень, Path(путь_запроса), 'реальный EOF', 'корень',
                        идентификатор, 5.0, команда, класс_проверки='адресная', тайм_аут_блокировки=1.0,
                        _тестовый_владелец=владелец)
                сам.assertEqual(ошибка.exception.код_лидера, 0)
                сам.assertIsInstance(ошибка.exception.__cause__, модуль.ОшибкаОтчёта)
                сам.assertIs(владелец.ошибка, ошибка.exception)
                сам.assertEqual(владелец.состояние, 'неизвестно')
                сам.assertIs(владелец.процесс, дети[0])
                сам.assertEqual((владелец.pid, владелец.код_лидера), (дети[0].pid, 0))
                сам.assertTrue(владелец.запись_вернула_успех)
            запись = фикстура.запись(идентификатор)
            сам.assertEqual((запись['состояние'], запись['статус'], запись['код_завершения']),
                            ('выполняется', None, None))
            сам.assertEqual(замечено, [True])
            сам.assertFalse(any(путь.suffix == '.py' for путь in фикстура.корень.rglob('*')))
            проверки_завершены = True
        finally:
            if проверки_завершены and len(дети) == 1 and type(дети[0].returncode) is int:
                замки.cleanup(); фикстура.очистить()
            else:
                замки._finalizer.detach(); фикстура.временный_каталог._finalizer.detach()

