    def test_очистка_сохраняет_первичную_и_все_свои_ошибки(сам):
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        идентификатор = '00000000-0000-4000-8000-000000000039'
        исходная = OSError('ошибка wait')
        ребёнок = mock.Mock(pid=12345)
        ребёнок.wait.side_effect = исходная
        ошибка_обработчика_1 = OSError('handler 1')
        ошибка_обработчика_2 = OSError('handler 2')
        ошибка_маски = OSError('mask final')
        маски, обработчики = [], []
        def маска(операция, _сигналы):
            маски.append(операция)
            if операция == signal.SIG_SETMASK and маски.count(signal.SIG_SETMASK) == 2:
                raise ошибка_маски
            return set()
        def обработчик(номер, функция):
            обработчики.append((номер, функция))
            if len(обработчики) == 3: raise ошибка_обработчика_1
            if len(обработчики) == 4: raise ошибка_обработчика_2
        try:
            with tempfile.TemporaryDirectory(dir='/tmp') as замки, \
                 mock.patch.object(модуль.tempfile, 'gettempdir', return_value=замки), \
                 mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64), \
                 mock.patch.object(модуль.subprocess, 'Popen', return_value=ребёнок), \
                 mock.patch.object(модуль, '_кандидат_собрать_статус_лидера', side_effect=исходная), \
                 mock.patch.object(модуль.signal, 'pthread_sigmask', side_effect=маска), \
                 mock.patch.object(модуль.signal, 'signal', side_effect=обработчик), \
                 mock.patch.object(модуль.os, 'killpg') as группе:
                with сам.assertRaises(BaseExceptionGroup) as отказ:
                    модуль._выполнить_ограниченный_запуск(
                        фикстура.корень, Path(путь_запроса), 'ошибки очистки', 'корень',
                        идентификатор, 1.0, ['/bin/true'], класс_проверки='адресная',
                        тайм_аут_блокировки=1.0)
                первичная, *ошибки = отказ.exception.exceptions
                сам.assertIsInstance(первичная, модуль.ОшибкаОтчёта)
                сам.assertIs(первичная.__cause__, исходная)
                сам.assertEqual(ошибки, [ошибка_обработчика_1, ошибка_обработчика_2, ошибка_маски])
                сам.assertEqual(len(обработчики), 4)
                группе.assert_not_called()
                сам.assertEqual(фикстура.запись(идентификатор)['состояние'], 'выполняется')
        finally:
            фикстура.очистить()

