    def test_закреплённая_команда_доходит_до_popen(сам):
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        идентификатор = '00000000-0000-4000-8000-000000000020'
        команда = ['/bin/true', 'исходный']
        исходное_разрешение = модуль.разрешить_сессию
        исходный_popen = subprocess.Popen
        запуск = mock.Mock(pid=12345)
        запуск.wait.return_value = 0
        вызовы = []
        def изменить_после_разрешения(*аргументы):
            результат = исходное_разрешение(*аргументы)
            команда[:] = ['/bin/false', '--источник-проверок']
            return результат
        def перехват(*аргументы, **параметры):
            if аргументы[0][0] == '/bin/true':
                вызовы.append((аргументы[0], параметры))
                return запуск
            if аргументы[0][0] == 'git':
                return исходный_popen(*аргументы, **параметры)
            raise AssertionError('неожиданный исполнитель')
        try:
            with mock.patch.object(модуль, 'разрешить_сессию', side_effect=изменить_после_разрешения), \
                 mock.patch.object(модуль.tempfile, 'gettempdir', return_value='/tmp'), \
                 mock.patch.object(модуль, 'вычислить_отпечаток_снимка', return_value='sha256:' + '0' * 64), \
                 mock.patch.object(модуль.os, 'kill', side_effect=AssertionError('сигнал')), \
                 mock.patch.object(модуль.os, 'killpg', side_effect=AssertionError('сигнал группе')), \
                 mock.patch.object(модуль, '_кандидат_собрать_статус_лидера', return_value=0), \
                 mock.patch.object(модуль.subprocess, 'Popen', side_effect=перехват):
                код = модуль._выполнить_ограниченный_запуск(
                    фикстура.корень, Path(путь_запроса), 'проверка команды',
                    'корень', идентификатор, 5.0, команда,
                    класс_проверки='адресная', тайм_аут_блокировки=5.0)
            сам.assertEqual(код, 0)
            сам.assertEqual(len(вызовы), 1)
            сам.assertEqual(вызовы[0][0], ['/bin/true', 'исходный'])
            сам.assertEqual(команда, ['/bin/false', '--источник-проверок'])
            сам.assertIs(вызовы[0][1]['start_new_session'], True)
            сам.assertEqual(фикстура.запись(идентификатор)['статус'], 'успешно')
        finally:
            фикстура.очистить()

    def test_адресный_запуск_получает_eof_вместо_stdin(сам):
        модуль = загрузить_модуль_автоматизации()
        фикстура = ФикстураОтчётов()
        идентификатор = "00000000-0000-4000-8000-000000000003"
        код_ребёнка = 'import sys; raise SystemExit(0 if sys.stdin.buffer.read(1) == b"" else 7)'
        команда = [sys.executable, "-B", "-c", код_ребёнка]
        исходный_popen = subprocess.Popen
        вызовы = []
        чтение = запись = None
        try:
            каталог_git = фикстура.корень / ".git"
            сам.assertTrue(каталог_git.is_dir())
            сам.assertFalse(каталог_git.is_symlink())
            сам.assertEqual(каталог_git.resolve().parent, фикстура.корень.resolve())
            чтение, запись = os.pipe()
            os.write(запись, b"X")

            def перехват(*аргументы, **параметры):
                if аргументы and аргументы[0] == команда:
                    вызовы.append(True)
                    сохранённый = os.dup(0)
                    try:
                        os.dup2(чтение, 0)
                        return исходный_popen(*аргументы, **параметры)
                    finally:
                        os.dup2(сохранённый, 0)
                        os.close(сохранённый)
                return исходный_popen(*аргументы, **параметры)

            with mock.patch.object(модуль.tempfile, "gettempdir", return_value=str(каталог_git)), \
                 mock.patch.object(модуль.subprocess, "Popen", side_effect=перехват):
                код = модуль._выполнить_ограниченный_запуск(
                    фикстура.корень, Path(путь_запроса), "проверка stdin",
                    "корень", идентификатор, 5.0, команда,
                    класс_проверки="адресная",
                    тайм_аут_блокировки=5.0,
                    _тестовый_владелец=модуль._ТестовыйВладелецЗапуска(),
                )
            сам.assertEqual(вызовы, [True])
            результат = фикстура.запись(идентификатор)
            сам.assertEqual(
                (код, результат["состояние"], результат["статус"], результат["код_завершения"]),
                (0, "завершён", "успешно", 0),
            )
        finally:
            if чтение is not None:
                os.close(чтение)
            if запись is not None:
                os.close(запись)
            фикстура.очистить()

