class ПроверкаОбменаКаналовGit(unittest.TestCase):
    """Отдельные pipe; процесс и дескрипторы принадлежат тесту."""

    def setUp(сам):
        сам.модуль = загрузить_модуль_автоматизации()
        сам.открытые = set()
        сам.закрытия = []
        сам.addCleanup(сам.закрыть_остаток)

    def закрыть_остаток(сам):
        for fd in tuple(сам.открытые):
            сам.открытые.remove(fd)
            os.close(fd)

    def закрыть(сам, fd):
        сам.открытые.remove(fd)
        сам.закрытия.append(fd)
        os.close(fd)

    def труба(сам):
        чтение, запись = os.pipe()
        сам.открытые.update((чтение, запись))
        return чтение, запись

    def test_три_канала_большие_данные_и_точный_кадр(сам):
        пары = [сам.труба() for _ in range(3)]
        for чтение, _ in пары:
            os.set_blocking(чтение, False)
        данные = (b'A' * 131072, b'B' * 131072, b'DONE\n')
        сбои = []
        def писать(fd, содержимое):
            try:
                позиция = 0
                while позиция < len(содержимое):
                    длина = os.write(fd, содержимое[позиция:])
                    if длина <= 0:
                        raise OSError('короткая запись')
                    позиция += длина
            except BaseException as ошибка:
                сбои.append(ошибка)
            finally:
                try:
                    os.close(fd)
                except BaseException as ошибка:
                    сбои.append(ошибка)
        потоки = []
        try:
            for (_, запись), содержимое in zip(пары, данные):
                поток = threading.Thread(target=писать, args=(запись, содержимое), daemon=True)
                поток.start()
                сам.открытые.remove(запись)
                потоки.append(поток)
            результат = сам.модуль._тестово_прочитать_три_канала(
                tuple(чтение for чтение, _ in пары), b'DONE\n', срок=time.monotonic() + 5,
                пределы=(131072, 131072), предел_суммы=262144)
            сам.assertEqual(результат, данные[:2])
        finally:
            первичная = sys.exception()
            for чтение, _ in пары:
                try:
                    сам.закрыть(чтение)
                except BaseException as ошибка:
                    сбои.append(ошибка)
            for _, запись in пары:
                if запись in сам.открытые:
                    try:
                        сам.закрыть(запись)
                    except BaseException as ошибка:
                        сбои.append(ошибка)
            for поток in потоки:
                поток.join(2)
            if any(поток.is_alive() for поток in потоки):
                raise AssertionError('неизвестно завершение потоков записи') from первичная
            if сбои:
                ошибка = AssertionError('неизвестен исход потоков или закрытий')
                ошибка.add_note(repr(сбои[0]))
                raise ошибка from первичная
        сам.assertFalse(any(поток.is_alive() for поток in потоки))
        сам.assertEqual(сбои, [])

    def test_три_канала_отклоняют_хвост_переполнение_и_срок(сам):
        for вывод, кадр, предел, открытый, причина in ((b'', b'DON\0\n', 0, False, 'неверный кадр'),
                                                      (b'', b'DONE\n\0', 0, False, 'превышен предел'),
                                                      (b'X', b'DONE\n', 0, False, 'превышен предел'),
                                                      (b'', b'DONE\n', 1, True, 'истёк срок')):
            with сам.subTest(вывод=вывод, кадр=кадр, открытый=открытый):
                пары = [сам.труба() for _ in range(3)]
                for чтение, _ in пары:
                    os.set_blocking(чтение, False)
                for (_, запись), содержимое in zip(пары, (вывод, b'', кадр)):
                    if содержимое:
                        os.write(запись, содержимое)
                    if not открытый or запись != пары[0][1]:
                        сам.закрыть(запись)
                with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, причина):
                    сам.модуль._тестово_прочитать_три_канала(
                        tuple(чтение for чтение, _ in пары), b'DONE\n',
                        срок=time.monotonic() + (0.1 if открытый else 2), пределы=(предел, 1), предел_суммы=2)
                for чтение, запись in пары:
                    сам.закрыть(чтение)
                    if запись in сам.открытые:
                        сам.закрыть(запись)

    def test_фактический_кадр_трёх_каналов_проверяет_статус(сам):
        run = '00112233-4455-4677-8899-aabbccddeeff'
        префикс = ('DONE ' + run + ' ').encode()
        варианты = ((b'0\n', True), (b'1792\n', True), (b'15\n', True),
                    (b'127\n', False), (b'65536\n', False), (b'01\n', False),
                    (b'0\n\0', False), (b'X' * 257, False))
        for окончание, допустимо in варианты:
            with сам.subTest(окончание=окончание):
                пары = [сам.труба() for _ in range(3)]
                for чтение, _ in пары:
                    os.set_blocking(чтение, False)
                frame = префикс + окончание
                for (_, запись), данные in zip(пары, (b'out', b'err', frame)):
                    os.write(запись, данные)
                    сам.закрыть(запись)
                аргументы = (tuple(чтение for чтение, _ in пары), run)
                параметры = dict(срок=time.monotonic() + 2, пределы=(3, 3), предел_суммы=6)
                if допустимо:
                    сам.assertEqual(сам.модуль._тестово_прочитать_три_канала_2(*аргументы, **параметры),
                                    (b'out', b'err', frame))
                else:
                    with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                        сам.модуль._тестово_прочитать_три_канала_2(*аргументы, **параметры)
                for чтение, _ in пары:
                    сам.закрыть(чтение)

    def test_только_кадр_группы_до_eof(сам):
        run = '00112233-4455-4677-8899-aabbccddeeff'
        чтение, запись = сам.труба()
        os.set_blocking(чтение, False)
        os.write(запись, b'Y')
        with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
            сам.модуль._тестово_прочитать_кадр_группы(чтение, 'неверный', срок=time.monotonic() + 2)
        сам.assertEqual(os.read(чтение, 1), b'Y')
        сам.закрыть(чтение)
        сам.закрыть(запись)
        for окончание, допустимо, держать in ((b'0\n', True, False), (b'1792\n', True, False),
                                               (b'15\n', True, False), (b'127\n', False, False),
                                               (b'0\n\0', False, False), (b'X' * 257, False, False),
                                               (b'0\n', False, True)):
            with сам.subTest(окончание=окончание, держать=держать):
                чтение, запись = сам.труба()
                os.set_blocking(чтение, False)
                frame = ('DONE ' + run + ' ').encode() + окончание
                os.write(запись, frame)
                if not держать:
                    сам.закрыть(запись)
                if допустимо:
                    сам.assertEqual(сам.модуль._тестово_прочитать_кадр_группы(
                        чтение, run, срок=time.monotonic() + 2), frame)
                else:
                    with сам.assertRaises(сам.модуль.ОшибкаОтчёта):
                        сам.модуль._тестово_прочитать_кадр_группы(
                            чтение, run, срок=time.monotonic() + (0.1 if держать else 2))
                сам.закрыть(чтение)
                if запись in сам.открытые:
                    сам.закрыть(запись)

    def фикстура(сам, данные=b'', stdout=b'', stderr=b'', *, пределы=(20, 20, 40), срок=None,
                закрыть_вход=None):
        вход_чтение, вход_запись = сам.труба()
        вывод_чтение, вывод_запись = сам.труба()
        ошибки_чтение, ошибки_запись = сам.труба()
        for fd in (вход_запись, вывод_чтение, ошибки_чтение):
            os.set_blocking(fd, False)
        if stdout: os.write(вывод_запись, stdout)
        if stderr: os.write(ошибки_запись, stderr)
        сам.закрыть(вывод_запись)
        сам.закрыть(ошибки_запись)
        объект = сам.модуль._ТестовыйОбменКаналовGit(
            вход_запись, вывод_чтение, ошибки_чтение, данные,
            сам.закрыть if закрыть_вход is None else закрыть_вход,
            срок=time.monotonic() + 3 if срок is None else срок,
            предел_вывода=пределы[0], предел_ошибок=пределы[1], предел_суммы=пределы[2])
        return объект, вход_чтение, вход_запись

    def test_пустой_вход_однократно_закрывается_и_выходы_читаются(сам):
        обмен, вход_чтение, вход_запись = сам.фикстура(stdout=b'out', stderr=b'err')
        сам.assertEqual(обмен.выполнить(), (b'out', b'err'))
        сам.assertEqual(os.read(вход_чтение, 1), b'')
        сам.assertEqual(сам.закрытия.count(вход_запись), 1)
        сам.assertEqual(обмен.закрытие_входа, 'callback вернулся')
        сам.assertEqual(обмен.состояние, 'готово')
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'уже использован'):
            обмен.выполнить()
        сам.assertEqual(сам.закрытия.count(вход_запись), 1)

    def test_частичные_записи_сохраняют_точные_байты(сам):
        обмен, вход_чтение, вход_запись = сам.фикстура(данные=b'abcdef')
        настоящий_write = os.write
        вызовы = []
        def частично(fd, данные):
            if fd == вход_запись:
                вызовы.append(len(данные))
                return настоящий_write(fd, данные[:2])
            return настоящий_write(fd, данные)
        with mock.patch.object(os, 'write', side_effect=частично):
            сам.assertEqual(обмен.выполнить(), (b'', b''))
        сам.assertEqual(os.read(вход_чтение, 100), b'abcdef')
        сам.assertEqual(обмен.передано, 6)
        сам.assertEqual(вызовы, [6, 4, 2])

    def test_ошибка_записи_после_эффекта_не_повторяется(сам):
        обмен, вход_чтение, вход_запись = сам.фикстура(данные=b'abcdef')
        настоящий_write = os.write
        вызовы = []
        def эффект_и_отказ(fd, данные):
            if fd == вход_запись:
                вызовы.append(fd)
                настоящий_write(fd, данные[:1])
                raise BlockingIOError('исход записи неизвестен')
            return настоящий_write(fd, данные)
        with mock.patch.object(os, 'write', side_effect=эффект_и_отказ):
            with сам.assertRaises(BlockingIOError):
                обмен.выполнить()
        сам.assertEqual(os.read(вход_чтение, 1), b'a')
        сам.assertEqual(обмен.передано, 0)
        сам.assertEqual(обмен.фаза, 'запись входа начата')
        сам.assertEqual(обмен.состояние, 'неизвестно')
        сам.assertEqual(вызовы, [вход_запись])
        with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'уже использован'):
            обмен.выполнить()
        сам.assertNotIn(вход_запись, сам.закрытия)

    def test_нулевая_запись_отказывает_без_повтора(сам):
        обмен, _, вход_запись = сам.фикстура(данные=b'a')
