    def test_повторное_событие_входа_не_повторяет_close(сам):
        обмен, вход_чтение, вход_запись = сам.фикстура(данные=b'a')
        настоящий = сам.модуль.selectors.DefaultSelector()
        class СелекторСПовтором:
            def __getattr__(сам, имя): return getattr(настоящий, имя)
            def select(сам, срок):
                события = настоящий.select(срок)
                вход = next((с for с in события if с[0].fd == вход_запись), None)
                return [вход, вход] if вход is not None else события
        with mock.patch.object(сам.модуль.selectors, 'DefaultSelector', return_value=СелекторСПовтором()):
            with сам.assertRaisesRegex(сам.модуль.ОшибкаОтчёта, 'повторная готовность'):
                обмен.выполнить()
        сам.assertEqual(os.read(вход_чтение, 1), b'a')
        сам.assertEqual(сам.закрытия.count(вход_запись), 1)
        сам.assertEqual(обмен.состояние, 'неизвестно')

    def test_вывод_до_чтения_входа_не_блокирует_обмен(сам):
        код = (
            "import os\n"
            "d=b'A'*131072\n"
            "while d:\n n=os.write(1,d[:16384]); d=d[n:]\n"
            "received=bytearray()\n"
            "while True:\n b=os.read(0,8192)\n if not b: break\n received.extend(b)\n"
            "if received!=b'B'*65536: raise SystemExit(8)\n"
            "os.write(2,b'received')\n"
        )
        процесс = subprocess.Popen([sys.executable, '-I', '-S', '-B', '-c', код], env={},
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0)
        for поток in (процесс.stdin, процесс.stdout, процесс.stderr):
            os.set_blocking(поток.fileno(), False)
        def закрыть_вход(fd):
            сам.assertEqual(fd, процесс.stdin.fileno())
            процесс.stdin.close()
        обмен = сам.модуль._ТестовыйОбменКаналовGit(
            процесс.stdin.fileno(), процесс.stdout.fileno(), процесс.stderr.fileno(), b'B' * 65536,
            закрыть_вход, срок=time.monotonic() + 8,
            предел_вывода=131072, предел_ошибок=8, предел_суммы=131080)
        stdout, stderr = обмен.выполнить()
        сам.assertEqual(stdout, b'A' * 131072)
        сам.assertEqual(stderr, b'received')
        сам.assertEqual(процесс.wait(timeout=3), 0)
        процесс.stdout.close()
        процесс.stderr.close()

    def создать_git_фикстуру(сам):
        import tempfile
        корень = Path(tempfile.mkdtemp(prefix='fum-batch-git-', dir='/private/tmp')).resolve()
        print('Сохранена Git-фикстура:', корень, file=sys.stderr)
        шаблон = корень / 'empty-template'
        шаблон.mkdir()
        среда = {'PATH': '/usr/bin:/bin', 'LC_ALL': 'C', 'GIT_OPTIONAL_LOCKS': '0',
            'GIT_NO_LAZY_FETCH': '1', 'GIT_NO_REPLACE_OBJECTS': '1', 'GIT_TERMINAL_PROMPT': '0',
            'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_GLOBAL': '/dev/null', 'GIT_ATTR_NOSYSTEM': '1'}
        гит = ['/usr/bin/git', '-C', str(корень), '-c', 'core.hooksPath=/dev/null',
               '-c', 'core.fsmonitor=false', '-c', 'protocol.allow=never']
        subprocess.run([*гит, 'init', '--quiet', '--object-format=sha1', '--template=' + str(шаблон)],
            env=среда, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            timeout=5, check=True)
        данные = b'fixture-content-' * 512
        oid = subprocess.run([*гит, 'hash-object', '-w', '--stdin'], env=среда, input=данные,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5, check=True).stdout.strip()
        сам.assertRegex(oid.decode('ascii'), '^[0-9a-f]{40}$')
        return корень, гит, среда, данные, oid

