    def test_движок_и_три_ограниченных_git_чтения_на_фикстуре(сам):
        import importlib.util
        корень, гит, среда, данные, oid = сам.создать_git_фикстуру()
        имя = 'имя*.txt'
        (корень / имя).write_bytes(данные)
        (корень / 'имя1.txt').write_bytes(b'different object\n')
        среда_коммита = dict(среда, GIT_AUTHOR_NAME='FUM Test', GIT_AUTHOR_EMAIL='fixture@example.invalid',
            GIT_COMMITTER_NAME='FUM Test', GIT_COMMITTER_EMAIL='fixture@example.invalid')
        for операция in (('--literal-pathspecs', 'add', '--', имя, 'имя1.txt'),
                         ('commit', '--quiet', '-m', 'Synthetic literal paths')):
            subprocess.run([*гит, *операция], env=среда_коммита, stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5, check=True)
        коммит = subprocess.run([*гит, 'rev-parse', 'HEAD'], env=среда, stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5, check=True).stdout.strip().decode('ascii')
        база = Path(сам.модуль.__file__).resolve().parents[2] / 'fum-svyaznostj-rabochej-sessii' / 'scripts'
        def загрузить(имя_модуля, путь):
            спецификация = importlib.util.spec_from_file_location(имя_модуля, путь)
            модуль = importlib.util.module_from_spec(спецификация)
            спецификация.loader.exec_module(модуль)
            return модуль
        двигатель = загрузить('fixture_bounded_engine', база / 'исполнение_принятого_кода.py')
        пуск = загрузить('fixture_bounded_pin', база / 'запуск_независимого_контура.py')
        исполняемый = Path('/usr/bin/git')
        метка = исполняемый.lstat()
        поля = (метка.st_dev, метка.st_ino, метка.st_mode, метка.st_uid, метка.st_gid,
                метка.st_nlink, метка.st_size, метка.st_mtime_ns, метка.st_ctime_ns)
        опора = ('fum.опора-исполнителя-git.1', str(исполняемый),
                 hashlib.sha256(исполняемый.read_bytes()).hexdigest(), поля, метка.st_size + 1)
        ожидаемые = ((('rev-parse', коммит + '^{commit}'), None, False),
                     (('ls-tree', '-z', коммит, '--', имя), None, True),
                     (('cat-file', '--batch'), oid + b'\n', False))
        владельцы = []
        осталось = 65536
        срок = time.monotonic() + 8
        def читатель(текущий_корень, *операция, вход=None, буквальные_пути=False):
            nonlocal осталось
            сам.assertEqual(текущий_корень, корень)
            сам.assertLess(len(владельцы), len(ожидаемые))
            сам.assertEqual((операция, вход, буквальные_пути), ожидаемые[len(владельцы)])
            путь = пуск._сверить_опору_гита(корень, опора)
            владелец = сам.модуль._ТестовыйВладелецПакетногоGit()
            владельцы.append(владелец)
            stdout, stderr, код = сам.модуль._тестовый_запустить_чтение_git(
                владелец, путь, корень, операция, вход=вход, буквальные_пути=буквальные_пути,
                срок=срок, предел_stdout=осталось, предел_stderr=0, предел_суммы=осталось)
            сам.assertEqual(код, 0)
            осталось -= len(stdout) + len(stderr)
            return stdout
        class ЗапрещённаяСреда(dict):
            def get(сам, ключ, default=None): raise AssertionError('чтение среды')
            def items(сам): raise AssertionError('чтение среды')
            def __iter__(сам): raise AssertionError('чтение среды')
            def __getitem__(сам, ключ): raise AssertionError('чтение среды')
        with mock.patch.object(os, 'environ', ЗапрещённаяСреда()):
            записи = двигатель.захватить_набор_с_читателем(корень, коммит, [имя], 'C', читать_гит=читатель)
        сам.assertEqual(set(записи), {str(корень / имя)})
        сам.assertEqual(записи[str(корень / имя)]['байты'], данные)
        сам.assertEqual(len(владельцы), 3)
        сам.assertTrue(all(в.состояние == 'лидер-собран' and в.код == 0 for в in владельцы))
        сам.assertGreater(осталось, 0)

