    def test_unknown_списка_git_не_теряет_владельца_и_не_повторяется(сам):
        from types import SimpleNamespace
        class Поток:
            def __init__(сам, fd): сам.fd, сам.closed = fd, False
            def fileno(сам): return сам.fd
            def close(сам): сам.closed = True
        селектор = 'a' * 40 + ':шаблоны'
        for причина in ('переполнение', 'срок'):
            with сам.subTest(причина=причина):
                путь = Path(сам.модуль.__file__)
                спецификация = importlib.util.spec_from_file_location('fixture_directory_unknown_' + причина, путь)
                отдельный = importlib.util.module_from_spec(спецификация)
                sys.modules[спецификация.name] = отдельный
                спецификация.loader.exec_module(отдельный)
                владелец = отдельный._ТестовыйВладелецПакетногоGit()
                процесс = SimpleNamespace(pid=12345, returncode=None,
                    stdin=Поток(101), stdout=Поток(102), stderr=Поток(103))
                def выполнить():
                    if причина == 'переполнение':
                        raise отдельный.ОшибкаПереполненияЧтения('переполнение')
                    raise отдельный.ОшибкаОтчёта('истёк срок обмена')
                общие = dict(каталоги=(('/private/tmp', селектор),), срок=time.monotonic() + 3,
                    предел_stdout=32, предел_stderr=0, предел_суммы=32)
                with mock.patch.object(subprocess, 'Popen', return_value=процесс) as вызов, \
                     mock.patch.object(os, 'set_blocking'), \
                     mock.patch.object(отдельный, '_ТестовыйОбменКаналовGit',
                                       return_value=SimpleNamespace(выполнить=выполнить)), \
                     mock.patch.object(отдельный, '_кандидат_собрать_статус_лидера',
                                       side_effect=AssertionError('сбор неизвестного')):
                    with сам.assertRaises(отдельный.ОшибкаОтчёта):
                        отдельный._тестовый_запустить_чтение_git(
                            владелец, '/usr/bin/git', '/private/tmp', ('ls-tree', '-z', селектор), **общие)
                    with сам.assertRaisesRegex(отдельный.ОшибкаОтчёта, 'неизвестный исход'):
                        отдельный._тестовый_запустить_чтение_git(
                            владелец, '/usr/bin/git', '/private/tmp', ('ls-tree', '-z', селектор), **общие)
                сам.assertEqual(вызов.call_count, 1)
                сам.assertEqual(владелец.состояние, 'неизвестно')
                сам.assertIs(владелец.процесс, процесс)
                сам.assertIsNone(владелец.код)
                сам.assertEqual(владелец.закрытие, ('не начато', 'не начато'))
                сам.assertIn(владелец, отдельный._тестовые_git_под_надзором)

