class ПроверкаЦелостностиАктивнойМетки(unittest.TestCase):
    """Адресная проверка одного процесса и доверенной синтетической области."""
    удержания = []
    назначенные_корни = None
    идентификатор = '00000000-0000-4000-8000-000000000001'

    def _начать(сам):
        м = загрузить_модуль_автоматизации()
        if сам.назначенные_корни is None:
            корень = Path(tempfile.mkdtemp(prefix='fum-active-root-', dir='/private/tmp')).resolve()
            (корень / 'Журнал' / 'сессия').mkdir(parents=True)
        else:
            корень, метки = сам.назначенные_корни.pop(0)
            корень = Path(корень)
            for путь, ожидаемая in zip((корень, корень / 'Журнал', корень / 'Журнал' / 'сессия'), метки):
                сведения = путь.lstat()
                сам.assertEqual((сведения.st_dev, сведения.st_ino, сведения.st_uid,
                                 сведения.st_mode & 0o7777), tuple(ожидаемая))
                сам.assertTrue(путь.is_dir())
            сам.assertEqual(корень.resolve(strict=True), корень)
        сессия = 'Журнал/сессия/запрос.md'
        опора = Path('/private/tmp').lstat()
        барьер = м._ТестовыйОдноразовыйБарьер((опора.st_dev, опора.st_ino, опора.st_uid,
                                               опора.st_mode & 0o7777))
        хозяин = м._ТестовыйВладелецЗапуска()
        сам.assertTrue(хозяин._блокировка.acquire(False))
        хозяин.состояние = 'занят'
        хозяин._поток_владельца = м._thread.get_ident()
        хозяин._объект_потока = м.threading.current_thread()
        хозяин._жизненный_барьер = барьер
        сам.удержания.append((м, барьер, хозяин))
        барьер.начать(хозяин, корень, сессия, сам.идентификатор)
        хозяин._фаза_реестра_запуска = 'зарегистрирован'
        м._тестовые_владельцы_запусков.add(хозяин)
        return м, корень, сессия, барьер, хозяин

    def _подменить_имя(сам, барьер, *, ссылка=False):
        каталог = барьер._дескриптор_резерва
        данные = b'ACTIVE ' + барьер._генерация + b'\n'
        os.link('ACTIVE', 'ACTIVE.original', src_dir_fd=каталог, dst_dir_fd=каталог,
                follow_symlinks=False)
        os.unlink('ACTIVE', dir_fd=каталог)
        if ссылка:
            os.symlink('ACTIVE.original', 'ACTIVE', dir_fd=каталог)
            return
        дескриптор = os.open('ACTIVE', os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW
                             | os.O_CLOEXEC, 0o600, dir_fd=каталог)
        учёт = {'дескриптор': дескриптор, 'фаза': 'открыт'}
        сам.удержания.append(учёт)
        учёт['фаза'] = 'запись начата'
        сам.assertEqual(os.write(дескриптор, данные), len(данные))
        учёт['фаза'] = 'закрытие начато'
        os.close(дескриптор)
        учёт['фаза'] = 'закрыт'

    def _изменить_байты(сам, барьер):
        дескриптор = os.open('ACTIVE', os.O_WRONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
                             dir_fd=барьер._дескриптор_резерва)
        учёт = {'дескриптор': дескриптор, 'фаза': 'открыт'}
        сам.удержания.append(учёт)
        учёт['фаза'] = 'запись начата'
        сам.assertEqual(os.pwrite(дескриптор, b'X', 0), 1)
        учёт['фаза'] = 'закрытие начато'
        os.close(дескриптор)
        учёт['фаза'] = 'закрыт'

    def _неизвестно(сам, м, барьер, хозяин, действие):
        with сам.assertRaises((м.ОшибкаОтчёта, OSError)) as отказ:
            действие()
        сам.assertEqual(барьер.состояние, 'неизвестно')
        сам.assertIs(барьер.ошибка, отказ.exception)
        первая_ошибка = барьер.ошибка
        with mock.patch.object(м.os, 'open', side_effect=AssertionError('повторное открытие')), \
             mock.patch.object(м.os, 'close', side_effect=AssertionError('повторное закрытие')):
            with сам.assertRaises(м.ОшибкаОтчёта):
                барьер.войти(хозяин)
        сам.assertIs(барьер.ошибка, первая_ошибка)

    def test_неизменённая_метка_допускает_вход_и_привязку(сам):
        м, корень, сессия, барьер, хозяин = сам._начать()
        барьер.войти(хозяин)
        барьер.сверить_привязку(хозяин, корень, сессия, сам.идентификатор)
        сам.assertEqual(барьер.состояние, 'активен')
        сам.assertIsNone(барьер.ошибка)

    def test_удалённая_метка_отказывает_до_снимка_и_запуска_процесса(сам):
        м, корень, сессия, барьер, хозяин = сам._начать()
        os.unlink('ACTIVE', dir_fd=барьер._дескриптор_резерва)
        with mock.patch.object(м._ТестовыйКонтейнерСнимка, 'открыть') as снимок, \
             mock.patch.object(м.subprocess, 'Popen') as запуск:
            сам._неизвестно(м, барьер, хозяин, lambda: м._выполнить_ограниченный_запуск_внутри(
                корень, Path(сессия), 'проверка', 'тест', сам.идентификатор, 1.0,
                ['/usr/bin/true'], класс_проверки='адресная', тайм_аут_блокировки=1.0,
                _владелец=хозяин, _тестовая_версия_6=True))
            снимок.assert_not_called()
            запуск.assert_not_called()

    def test_другой_индексный_узел_с_теми_же_байтами_отказывает(сам):
        м, _, _, барьер, хозяин = сам._начать()
        сам._подменить_имя(барьер)
        сам._неизвестно(м, барьер, хозяин, lambda: барьер.войти(хозяин))

    def test_символьная_ссылка_отказывает(сам):
        м, _, _, барьер, хозяин = сам._начать()
        сам._подменить_имя(барьер, ссылка=True)
        сам._неизвестно(м, барьер, хозяин, lambda: барьер.войти(хозяин))

    def test_изменённые_байты_отказывают_при_повторной_привязке(сам):
        м, корень, сессия, барьер, хозяин = сам._начать()
        барьер.войти(хозяин)
