        исходное, владелец, run = исходная._удержание, исходная._владелец, исходная._run
        image_fd = os.open('/Library/Developer/CommandLineTools/usr/bin/git', os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
