    def test_полномочие_собственного_git_однократно_и_связано_с_заявкой(сам):
        м = загрузить_модуль_автоматизации()
        временный = tempfile.TemporaryDirectory()
        сам.addCleanup(временный.cleanup)
        корень = Path(временный.name).resolve()
        fd = os.open(корень, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        сам.addCleanup(os.close, fd)
        владелец = м._ТестовыйВладелецЗапуска()
        заявка = м._ЗаявкаЗакрытогоПрофиляGit(fd, (), 0, 'запрос', time.monotonic() + 10)
        выдано = м._выдать_полномочие_собственного_git(корень, заявка, владелец, 'run', 'запрос')
        with mock.patch.object(м, '_ВладениеЗакрытымПрофилемGit') as адаптер:
            результат = выдано.принять(заявка, владелец, 'run', корень, 'запрос')
            сам.assertIs(результат, адаптер.return_value)
            адаптер.assert_called_once_with(заявка, владелец, 'run', корень, 'запрос')
            with сам.assertRaises(м.ОшибкаОтчёта):
                выдано.принять(заявка, владелец, 'run', корень, 'запрос')
        выдано = м._выдать_полномочие_собственного_git(корень, заявка, владелец, 'run', 'запрос')
        with mock.patch.object(м, '_ВладениеЗакрытымПрофилемGit') as адаптер:
            with сам.assertRaises(м.ОшибкаОтчёта):
                выдано.принять(заявка._replace(), владелец, 'run', корень, 'запрос')
            with сам.assertRaises(м.ОшибкаОтчёта):
                выдано.принять(заявка, владелец, 'run', корень, 'запрос')
            адаптер.assert_not_called()

