            запрос.write_bytes(b'fixture')
            (каталог / м.ИМЯ_ОТЧЁТА).write_bytes(b'fixture')
            срок = time.monotonic() + 10
            with м._тестово_удержать_связанный_профиль_git(рабочий, общий, 'work', срок=срок) as (_, удержание):
                with mock.patch.object(м, 'атомарно_записать_байты') as записать, \
                     mock.patch.object(м.subprocess, 'Popen') as запуск, \
                     mock.patch.object(м, '_выполнить_ограниченный_запуск_внутри') as внутри:
                    профиль = м._связать_профиль_git_с_сессией(удержание, run, рабочий, запрос)
                    сессия = запрос.relative_to(рабочий).as_posix()
